INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-1-u3-C1','math',4,1,'u3',2,'곱셈을 아는 계산으로 쪼개기 — 곱하는 수를 몇십과 몇으로 쪼개어 (세 자리 수) × (몇십)과 (세 자리 수) × (몇)의 합으로 구하기',ARRAY['4수01-04']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-1-u3-C2','math',4,1,'u3',2,'(세 자리 수) × (몇십) — (세 자리 수) × (몇)을 구한 뒤 10배 하기(곱하는 수가 10배면 곱도 10배)',ARRAY['4수01-04']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-1-u3-C3','math',4,1,'u3',3,'(세 자리 수) × (몇십몇) — 세로셈에서 일의 자리 곱과 십의 자리 곱(한 칸 밀어 쓰기)을 더하고, 줄마다 올림 처리하기',ARRAY['4수01-04']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-1-u3-C4','math',4,1,'u3',3,'곱의 어림과 점검 — 몇백 × 몇십으로 곱을 어림하고, 어림값과 견주어 계산 결과가 알맞은지 판단하기',ARRAY['4수01-08']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-1-u3-C5','math',4,1,'u3',4,'(세 자리 수) ÷ (몇십) — 똑같이 묶어 몫을 구하고(십 모형으로 보기), 나누어떨어지지 않으면 나누는 수보다 작은 나머지 구하기',ARRAY['4수01-07']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-1-u3-C6','math',4,1,'u3',4,'나눗셈 확인하기 — (나누는 수) × (몫) + (나머지) = (나누어지는 수)로 계산이 맞는지 확인하고, 어떤 수 구하기',ARRAY['4수01-07']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-1-u3-C7','math',4,1,'u3',5,'(두 자리 수) ÷ (몇십몇) — 몫을 어림하고 곱해서 확인하며, 곱이 크면 1 작게·남은 수가 크면 1 크게 고치기',ARRAY['4수01-07']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-1-u3-C8','math',4,1,'u3',6,'몫이 한 자리인 (세 자리 수) ÷ (몇십몇) — 나누어지는 수를 넘지 않으면서 가장 가까운 곱으로 몫을 찾고, 어림 방법이 여럿임을 알기',ARRAY['4수01-07']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-1-u3-C9','math',4,1,'u3',7,'몫이 두 자리인 (세 자리 수) ÷ (몇십몇) — 몇십 번을 먼저 덜어 몫의 십의 자리를 정하고, 남은 수로 일의 자리 몫 구하기',ARRAY['4수01-07']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M4-1-u3-C10','math',4,1,'u3',8,'생활 속 곱셈과 나눗셈 — 탄소 발자국처럼 여러 값을 더한 뒤 곱하고, 나눗셈의 몫과 나머지를 상황에 맞게 해석하기',ARRAY['4수01-04']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u3-X01','math',4,'u3',ARRAY['M4-1-u3-C2','M4-1-u3-C10']::text[],'(세 자리 수) × (몇십)에서 0을 붙이지 않거나 하나 더 붙인다(134 × 20 → 268·26800)','몇십은 몇의 10배') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u3-X02','math',4,'u3',ARRAY['M4-1-u3-C3']::text[],'십의 자리를 곱한 줄을 한 칸 밀어 쓰지 않고 일의 자리에 맞춘다','십의 자리 곱은 한 칸 밀기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u3-X03','math',4,'u3',ARRAY['M4-1-u3-C1','M4-1-u3-C3']::text[],'두 줄의 곱 가운데 하나를 빠뜨린다(몇십만 곱하거나 몇만 곱함)','두 곱을 모두 더하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u3-X04','math',4,'u3',ARRAY['M4-1-u3-C2','M4-1-u3-C3']::text[],'올림한 수를 윗자리에 더하지 않는다','올림은 윗자리에 더하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u3-X05','math',4,'u3',ARRAY['M4-1-u3-C3']::text[],'앞 줄에서 올림한 수를 다음 줄에도 다시 더한다','올림은 그 줄 안에서만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u3-X06','math',4,'u3',ARRAY['M4-1-u3-C1','M4-1-u3-C3']::text[],'곱하는 수를 쪼갤 때 몇십을 몇으로 보거나(24 = 2 + 4), 쪼갠 두 곱을 더하지 않고 곱한다','24 = 20 + 4, 두 곱은 더하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u3-X07','math',4,'u3',ARRAY['M4-1-u3-C5','M4-1-u3-C7','M4-1-u3-C8','M4-1-u3-C9','M4-1-u3-C10']::text[],'남은 수가 나누는 수와 같거나 큰데 몫을 그대로 둔다(몫이 1 작음)','나머지 < 나누는 수') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u3-X08','math',4,'u3',ARRAY['M4-1-u3-C5','M4-1-u3-C7','M4-1-u3-C8','M4-1-u3-C9','M4-1-u3-C10']::text[],'곱이 나누어지는 수보다 큰 몫을 그대로 쓴다(몫이 1 큼)','곱이 크면 몫을 1 작게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u3-X09','math',4,'u3',ARRAY['M4-1-u3-C5']::text[],'(세 자리 수) ÷ (몇십)에서 0을 지우고 나눈 뒤 나머지에 0을 되돌리지 않는다(597 ÷ 80 → 나머지 3)','나머지는 처음 수에서 빼서') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u3-X10','math',4,'u3',ARRAY['M4-1-u3-C6']::text[],'확인 식을 잘못 쓴다(나누는 수 × 몫 − 나머지, 나누어지는 수 × 나누는 수 …)','나누는 수 × 몫 + 나머지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u3-X11','math',4,'u3',ARRAY['M4-1-u3-C9']::text[],'몫의 일의 자리 0을 빠뜨린다(912 ÷ 18 = 50 … 12를 5 … 12로)','몫 자리에 0 쓰기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u3-X12','math',4,'u3',ARRAY['M4-1-u3-C8','M4-1-u3-C9']::text[],'몫의 자릿수를 잘못 판단한다(앞 두 자리가 나누는 수보다 작은데 몫을 두 자리로, 또는 반대로)','앞 두 자리와 나누는 수 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u3-X13','math',4,'u3',ARRAY['M4-1-u3-C5','M4-1-u3-C7','M4-1-u3-C8','M4-1-u3-C9','M4-1-u3-C10']::text[],'나머지를 상황에 맞게 처리하지 않는다(남은 것도 담아야 하는데 몫만 / 가득 찬 것만 세는데 몫 + 1)','남은 것을 어떻게 할지 묻기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u3-X14','math',4,'u3',ARRAY['M4-1-u3-C1','M4-1-u3-C2','M4-1-u3-C3','M4-1-u3-C4','M4-1-u3-C5','M4-1-u3-C6','M4-1-u3-C7','M4-1-u3-C8','M4-1-u3-C9','M4-1-u3-C10']::text[],'묻는 말을 거꾸로 읽는다 — 몫↔나머지, 큰↔작은, 맞는↔틀린','물음에 동그라미') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u3-X15','math',4,'u3',ARRAY['M4-1-u3-C1','M4-1-u3-C2','M4-1-u3-C5','M4-1-u3-C10']::text[],'곱해야 할 때 나누거나 더하고, 나누어야 할 때 곱하는 등 셈을 잘못 고른다','똑같이 여러 번이면 곱셈') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u3-X16','math',4,'u3',ARRAY['M4-1-u3-C3','M4-1-u3-C4']::text[],'어림한 수의 곱에서 0의 개수를 잘못 세어 값이 10배 어긋난다(600 × 50 = 3000)','0의 개수 세어 붙이기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u3-X17','math',4,'u3',ARRAY['M4-1-u3-C4','M4-1-u3-C7','M4-1-u3-C8']::text[],'어림을 계산 대신으로 여기거나, 어림값과 크게 다른 결과를 그대로 믿거나, 몫을 여러 번 고치는 것을 틀린 풀이로 여긴다','어림은 점검의 길잡이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M4-1-u3-X18','math',4,'u3',ARRAY['M4-1-u3-C10']::text[],'여러 단계 문제에서 한 단계를 빠뜨린다(반찬 하나만 곱하거나 합·차를 구하지 않음)','단계마다 식 쓰기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L02_basic#1','math',4,1,'u3','L02','g4_1_math_u3_L02_basic','lesson_basic','M4-1-u3-C2',1,'sa','auto','207 × 40은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-1-u3-C2","difficulty":1,"kind":"sa","stem":"207 × 40은 얼마인가요? 숫자로 쓰세요.","answer":["8280"],"explanation":["207 × 4 = 828 — 먼저 몇을 곱해요.","곱하는 수가 10배(4 → 40)라서 곱도 10배예요.","207 × 40 = 8280이에요."],"variant_rule":{"alt":[{"stem":"179 × 40은 얼마인가요? 숫자로 쓰세요.","answer":["7160"],"explanation":["179 × 4 = 716 — 먼저 몇을 곱해요.","곱하는 수가 10배(4 → 40)라서 곱도 10배예요.","179 × 40 = 7160이에요."],"asset":null},{"stem":"245 × 30은 얼마인가요? 숫자로 쓰세요.","answer":["7350"],"explanation":["245 × 3 = 735 — 먼저 몇을 곱해요.","곱하는 수가 10배(3 → 30)라서 곱도 10배예요.","245 × 30 = 7350이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L02_basic#2','math',4,1,'u3','L02','g4_1_math_u3_L02_basic','lesson_basic','M4-1-u3-C2',1,'sa','auto','216 × 3 = 648이에요. 이것을 보고 216 × 30의 값을 구하세요. 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-1-u3-C2","difficulty":1,"kind":"sa","stem":"216 × 3 = 648이에요. 이것을 보고 216 × 30의 값을 구하세요. 숫자로 쓰세요.","answer":["6480"],"explanation":["30은 3의 10배예요.","곱하는 수가 10배면 곱도 10배 — 648의 10배.","216 × 30 = 6480이에요."],"variant_rule":{"alt":[{"stem":"419 × 2 = 838이에요. 이것을 보고 419 × 20의 값을 구하세요. 숫자로 쓰세요.","answer":["8380"],"explanation":["20은 2의 10배예요.","곱하는 수가 10배면 곱도 10배 — 838의 10배.","419 × 20 = 8380이에요."],"asset":null},{"stem":"219 × 3 = 657이에요. 이것을 보고 219 × 30의 값을 구하세요. 숫자로 쓰세요.","answer":["6570"],"explanation":["30은 3의 10배예요.","곱하는 수가 10배면 곱도 10배 — 657의 10배.","219 × 30 = 6570이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L02_basic#3','math',4,1,'u3','L02','g4_1_math_u3_L02_basic','lesson_basic','M4-1-u3-C1',1,'sa','auto','641 × 13을 아는 계산으로 쪼갰어요. 641 × 13 = 641 × 10 + 641 × □에서 □ 안에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-1-u3-C1","difficulty":1,"kind":"sa","stem":"641 × 13을 아는 계산으로 쪼갰어요. 641 × 13 = 641 × 10 + 641 × □에서 □ 안에 알맞은 수를 쓰세요.","answer":["3"],"explanation":["13은 10과 3의 합이에요.","13번 더한 것 = 10번 더하고 3번 더 더한 것.","□ = 3이에요."],"asset":{"type":"expr_grid","rows":[["641 × 10","=","6410"],["641 × 3","=","1923"],["6410 + 1923","=","8333"]]},"variant_rule":{"alt":[{"stem":"555 × 34를 아는 계산으로 쪼갰어요. 555 × 34 = 555 × 30 + 555 × □에서 □ 안에 알맞은 수를 쓰세요.","answer":["4"],"explanation":["34는 30과 4의 합이에요.","34번 더한 것 = 30번 더하고 4번 더 더한 것.","□ = 4예요."],"asset":{"type":"expr_grid","rows":[["555 × 30","=","16650"],["555 × 4","=","2220"],["16650 + 2220","=","18870"]]}},{"stem":"173 × 58을 아는 계산으로 쪼갰어요. 173 × 58 = 173 × 50 + 173 × □에서 □ 안에 알맞은 수를 쓰세요.","answer":["8"],"explanation":["58은 50과 8의 합이에요.","58번 더한 것 = 50번 더하고 8번 더 더한 것.","□ = 8이에요."],"asset":{"type":"expr_grid","rows":[["173 × 50","=","8650"],["173 × 8","=","1384"],["8650 + 1384","=","10034"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L02_basic#4','math',4,1,'u3','L02','g4_1_math_u3_L02_basic','lesson_basic','M4-1-u3-C2',1,'sa','auto','인공 지능으로 물을 일주일에 283 L씩 30주 동안 아꼈어요. 아낀 물은 모두 몇 L인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-1-u3-C2","difficulty":1,"kind":"sa","stem":"인공 지능으로 물을 일주일에 283 L씩 30주 동안 아꼈어요. 아낀 물은 모두 몇 L인가요? 숫자로 쓰세요.","answer":["8490"],"explanation":["한 번에 283 L씩 30번 — 283 × 30으로 구해요.","곱하는 수가 10배(3 → 30)라서 곱도 10배예요.","모두 8490 L예요."],"variant_rule":{"alt":[{"stem":"줄넘기를 하루에 168번씩 30일 동안 했어요. 줄넘기를 모두 몇 번 했나요? 숫자로 쓰세요.","answer":["5040"],"explanation":["한 번에 168번씩 30번 — 168 × 30으로 구해요.","곱하는 수가 10배(3 → 30)라서 곱도 10배예요.","모두 5040번이에요."],"asset":null},{"stem":"딸기를 하루에 251 kg씩 30일 동안 거뒀어요. 거둔 딸기는 모두 몇 kg인가요? 숫자로 쓰세요.","answer":["7530"],"explanation":["한 번에 251 kg씩 30번 — 251 × 30으로 구해요.","곱하는 수가 10배(3 → 30)라서 곱도 10배예요.","모두 7530 kg예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L02_basic#5','math',4,1,'u3','L02','g4_1_math_u3_L02_basic','lesson_basic','M4-1-u3-C2',2,'mc','auto','(세 자리 수) × (몇십)을 계산하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['M4-1-u3-X06','M4-1-u3-X01','M4-1-u3-X15']::text[],true,'{"seq":5,"concept":"M4-1-u3-C2","difficulty":2,"kind":"mc","stem":"(세 자리 수) × (몇십)을 계산하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"(세 자리 수) × (몇)을 구한 뒤 10배 해요","correct":true},{"t":"(세 자리 수)에 10을 더한 뒤 곱해요","mis":"M4-1-u3-X06"},{"t":"(세 자리 수)의 각 자리 숫자에 0을 하나씩 붙여요","mis":"M4-1-u3-X01"},{"t":"(세 자리 수)를 10으로 나눈 뒤 곱해요","mis":"M4-1-u3-X15"}],"explanation":["몇십은 몇의 10배예요 — 20 = 2 × 10.","그래서 (세 자리 수) × (몇십) = (세 자리 수) × (몇)의 10배.","134 × 2 = 268이면 134 × 20 = 2680이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. (세 자리 수) × (몇십)을 계산하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"(세 자리 수) × (몇)을 구하고 그 곱에 0을 하나 붙여요","correct":true},{"t":"(세 자리 수) × (몇)에 0을 두 개 붙여요","mis":"M4-1-u3-X01"},{"t":"(세 자리 수)와 (몇십)을 더해요","mis":"M4-1-u3-X15"},{"t":"(세 자리 수) × (몇)을 그대로 답으로 써요","mis":"M4-1-u3-X01"}],"explanation":["몇십은 몇의 10배예요 — 20 = 2 × 10.","그래서 (세 자리 수) × (몇십) = (세 자리 수) × (몇)의 10배.","134 × 2 = 268이면 134 × 20 = 2680이에요."],"asset":null},{"stem":"이번에는 다른 수예요. (세 자리 수) × (몇십)을 계산하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"곱하는 수가 10배가 되면 곱도 10배가 돼요","correct":true},{"t":"곱하는 수가 10배가 되어도 곱은 그대로예요","mis":"M4-1-u3-X01"},{"t":"곱하는 수가 10배가 되면 곱은 100배가 돼요","mis":"M4-1-u3-X01"},{"t":"곱하는 수가 10배가 되면 곱은 10만큼 커져요","mis":"M4-1-u3-X06"}],"explanation":["몇십은 몇의 10배예요 — 20 = 2 × 10.","그래서 (세 자리 수) × (몇십) = (세 자리 수) × (몇)의 10배.","134 × 2 = 268이면 134 × 20 = 2680이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_c