INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L02_basic#6','math',4,1,'u3','L02','g4_1_math_u3_L02_basic','lesson_basic','M4-1-u3-C1',2,'sa','auto','141 × 20 = 2820, 141 × 4 = 564예요. 141 × 24는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M4-1-u3-C1","difficulty":2,"kind":"sa","stem":"141 × 20 = 2820, 141 × 4 = 564예요. 141 × 24는 얼마인가요? 숫자로 쓰세요.","answer":["3384"],"explanation":["24 = 20 + 4.","두 곱을 더해요 — 2820 + 564.","141 × 24 = 3384예요."],"variant_rule":{"alt":[{"stem":"168 × 20 = 3360, 168 × 7 = 1176이에요. 168 × 27은 얼마인가요? 숫자로 쓰세요.","answer":["4536"],"explanation":["27 = 20 + 7.","두 곱을 더해요 — 3360 + 1176.","168 × 27 = 4536이에요."],"asset":null},{"stem":"392 × 10 = 3920, 392 × 9 = 3528이에요. 392 × 19는 얼마인가요? 숫자로 쓰세요.","answer":["7448"],"explanation":["19 = 10 + 9.","두 곱을 더해요 — 3920 + 3528.","392 × 19 = 7448이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
