INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L02_basic#8','math',4,1,'u3','L02','g4_1_math_u3_L02_basic','lesson_basic','M4-1-u3-C2',2,'ox','auto','396 × 20은 396 × 2의 10배예요.',ARRAY['M4-1-u3-X01']::text[],true,'{"seq":8,"concept":"M4-1-u3-C2","difficulty":2,"kind":"ox","stem":"396 × 20은 396 × 2의 10배예요.","answer":"O","reason_options":[{"t":"20은 2의 10배라서","correct":true},{"t":"곱하는 수에 0이 있으면 곱은 100배가 되어서","mis":"M4-1-u3-X01"}],"mis":"M4-1-u3-X01","explanation":["396 × 2 = 792예요.","396 × 20 = 7920이에요 — 792의 10배.","그래서 맞아요."],"variant_rule":{"alt":[{"stem":"123 × 8 = 984이니까 123 × 80 = 98400이에요.","answer":"X","reason_options":[{"t":"0을 하나만 붙여야 해서","correct":true},{"t":"몇십을 곱하면 0을 두 개 붙여서","mis":"M4-1-u3-X01"}],"explanation":["80은 8의 10배예요.","곱도 10배 — 9840.","98400은 0을 하나 더 붙인 잘못이에요."],"asset":null},{"stem":"207 × 20을 계산하는데 자리마다 곱한 값의 일의 자리만 써서 4040이라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"올림한 수를 윗자리에 더해야 해서","correct":true},{"t":"자리마다 곱은 일의 자리만 쓰면 되어서","mis":"M4-1-u3-X04"}],"explanation":["207 × 2 = 414 — 올림이 있어요.","그 곱의 10배 — 4140.","4040은 올림을 버린 잘못이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
