INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L02_basic#10','math',4,1,'u3','L02','g4_1_math_u3_L02_basic','lesson_basic','M4-1-u3-C2',3,'error','auto','친구들이 (세 자리 수) × (몇십)을 계산했어요. 잘못 계산한 친구는 누구인가요?',ARRAY['M4-1-u3-X01','M4-1-u3-X14']::text[],true,'{"seq":10,"concept":"M4-1-u3-C2","difficulty":3,"kind":"error","stem":"친구들이 (세 자리 수) × (몇십)을 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"서준 — 132 × 60 = 792","correct":true,"mis_target":"M4-1-u3-X01"},{"t":"도윤 — 681 × 20 = 13620","mis":"M4-1-u3-X14"},{"t":"태오 — 153 × 40 = 6120","mis":"M4-1-u3-X14"}],"explanation":["132 × 6 = 792 — 이 곱의 10배가 답이에요.","132 × 60 = 7920이에요.","서준이 0을 붙이지 않았어요 — 10배를 잊었어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 친구들이 (세 자리 수) × (몇십)을 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"하린 — 136 × 20 = 272","correct":true,"mis_target":"M4-1-u3-X01"},{"t":"지유 — 522 × 40 = 20880","mis":"M4-1-u3-X14"},{"t":"은우 — 146 × 60 = 8760","mis":"M4-1-u3-X14"}],"explanation":["136 × 2 = 272 — 이 곱의 10배가 답이에요.","136 × 20 = 2720이에요.","하린이 0을 붙이지 않았어요 — 10배를 잊었어요."],"asset":null},{"stem":"이번에는 다른 수예요. 친구들이 (세 자리 수) × (몇십)을 계산했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"시아 — 166 × 60 = 996","correct":true,"mis_target":"M4-1-u3-X01"},{"t":"지유 — 412 × 30 = 12360","mis":"M4-1-u3-X14"},{"t":"태오 — 209 × 40 = 8360","mis":"M4-1-u3-X14"}],"explanation":["166 × 6 = 996 — 이 곱의 10배가 답이에요.","166 × 60 = 9960이에요.","시아가 0을 붙이지 않았어요 — 10배를 잊었어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L02_challenge#1','math',4,1,'u3','L02','g4_1_math_u3_L02_challenge','lesson_challenge','M4-1-u3-C2',2,'mc','auto','주스를 한 명이 553 mL씩 마셔요. 학생 80명이 마셔요. 주스는 모두 몇 mL 필요한가요?',ARRAY['M4-1-u3-X15','M4-1-u3-X01']::text[],true,'{"seq":1,"concept":"M4-1-u3-C2","difficulty":2,"kind":"mc","stem":"주스를 한 명이 553 mL씩 마셔요. 학생 80명이 마셔요. 주스는 모두 몇 mL 필요한가요?","options":[{"t":"44240 mL","correct":true},{"t":"633 mL","mis":"M4-1-u3-X15"},{"t":"4424 mL","mis":"M4-1-u3-X01"},{"t":"442400 mL","mis":"M4-1-u3-X01"}],"explanation":["한 번에 553 mL씩 80번 — 553 × 80으로 구해요.","곱하는 수가 10배(8 → 80)라서 곱도 10배예요.","모두 44240 mL예요."],"variant_rule":{"alt":[{"stem":"주스를 한 명이 841 mL씩 마셔요. 학생 20명이 마셔요. 주스는 모두 몇 mL 필요한가요?","options":[{"t":"16820 mL","correct":true},{"t":"861 mL","mis":"M4-1-u3-X15"},{"t":"1682 mL","mis":"M4-1-u3-X01"},{"t":"168200 mL","mis":"M4-1-u3-X01"}],"explanation":["한 번에 841 mL씩 20번 — 841 × 20으로 구해요.","곱하는 수가 10배(2 → 20)라서 곱도 10배예요.","모두 16820 mL예요."],"asset":null},{"stem":"모종 상자 하나에 모종이 495포기씩 들어 있어요. 상자가 30개 있어요. 모종은 모두 몇 포기인가요?","options":[{"t":"14850포기","correct":true},{"t":"525포기","mis":"M4-1-u3-X15"},{"t":"1485포기","mis":"M4-1-u3-X01"},{"t":"148500포기","mis":"M4-1-u3-X01"}],"explanation":["한 번에 495포기씩 30번 — 495 × 30으로 구해요.","곱하는 수가 10배(3 → 30)라서 곱도 10배예요.","모두 14850포기예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L02_challenge#2','math',4,1,'u3','L02','g4_1_math_u3_L02_challenge','lesson_challenge','M4-1-u3-C1',2,'mc','auto','478 × 96을 아는 계산으로 바르게 쪼갠 것은 어느 것인가요?',ARRAY['M4-1-u3-X06','M4-1-u3-X03']::text[],true,'{"seq":2,"concept":"M4-1-u3-C1","difficulty":2,"kind":"mc","stem":"478 × 96을 아는 계산으로 바르게 쪼갠 것은 어느 것인가요?","options":[{"t":"478 × 90 + 478 × 6","correct":true},{"t":"478 × 9 + 478 × 6","mis":"M4-1-u3-X06"},{"t":"478 × 90 × 478 × 6","mis":"M4-1-u3-X06"},{"t":"478 × 90","mis":"M4-1-u3-X03"}],"explanation":["96 = 90 + 6 — 십의 자리 9는 90을 나타내요.","96번 더한 것은 90번 더하고 6번 더 더한 것.","두 곱은 더해요 — 478 × 90 + 478 × 6."],"variant_rule":{"alt":[{"stem":"315 × 27을 아는 계산으로 바르게 쪼갠 것은 어느 것인가요?","options":[{"t":"315 × 20 + 315 × 7","correct":true},{"t":"315 × 2 + 315 × 7","mis":"M4-1-u3-X06"},{"t":"315 × 20 × 315 × 7","mis":"M4-1-u3-X06"},{"t":"315 × 20","mis":"M4-1-u3-X03"}],"explanation":["27 = 20 + 7 — 십의 자리 2는 20을 나타내요.","27번 더한 것은 20번 더하고 7번 더 더한 것.","두 곱은 더해요 — 315 × 20 + 315 × 7."],"asset":null},{"stem":"585 × 85를 아는 계산으로 바르게 쪼갠 것은 어느 것인가요?","options":[{"t":"585 × 80 + 585 × 5","correct":true},{"t":"585 × 8 + 585 × 5","mis":"M4-1-u3-X06"},{"t":"585 × 80 × 585 × 5","mis":"M4-1-u3-X06"},{"t":"585 × 80","mis":"M4-1-u3-X03"}],"explanation":["85 = 80 + 5 — 십의 자리 8은 80을 나타내요.","85번 더한 것은 80번 더하고 5번 더 더한 것.","두 곱은 더해요 — 585 × 80 + 585 × 5."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L02_challenge#3','math',4,1,'u3','L02','g4_1_math_u3_L02_challenge','lesson_challenge','M4-1-u3-C2',3,'sa','auto','□ × 20 = 6620에서 □ 안에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-1-u3-C2","difficulty":3,"kind":"sa","stem":"□ × 20 = 6620에서 □ 안에 알맞은 수를 쓰세요.","answer":["331"],"explanation":["□ × 20의 곱은 □ × 2의 10배예요.","662의 10배가 6620이니 □ × 2 = 662예요.","662 ÷ 2 = 331 — □ = 331이에요."],"variant_rule":{"alt":[{"stem":"□ × 30 = 7620에서 □ 안에 알맞은 수를 쓰세요.","answer":["254"],"explanation":["□ × 30의 곱은 □ × 3의 10배예요.","762의 10배가 7620이니 □ × 3 = 762예요.","762 ÷ 3 = 254 — □ = 254예요."],"asset":null},{"stem":"□ × 20 = 11820에서 □ 안에 알맞은 수를 쓰세요.","answer":["591"],"explanation":["□ × 20의 곱은 □ × 2의 10배예요.","1182의 10배가 11820이니 □ × 2 = 1182예요.","1182 ÷ 2 = 591 — □ = 591이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L02_challenge#4','math',4,1,'u3','L02','g4_1_math_u3_L02_challenge','lesson_challenge','M4-1-u3-C2',3,'sa','auto','136원짜리 물건을 80개 사려고 해요. 1000원짜리 지폐만 낸다면 적어도 몇 장을 내야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-1-u3-C2","difficulty":3,"kind":"sa","stem":"136원짜리 물건을 80개 사려고 해요. 1000원짜리 지폐만 낸다면 적어도 몇 장을 내야 하나요? 숫자로 쓰세요.","answer":["11"],"explanation":["물건값: 136 × 80 = 10880원.","1000원짜리 10장은 10000원으로 모자라요.","적어도 11장 내야 해요."],"variant_rule":{"alt":[{"stem":"454원짜리 물건을 50개 사려고 해요. 1000원짜리 지폐만 낸다면 적어도 몇 장을 내야 하나요? 숫자로 쓰세요.","answer":["23"],"explanation":["물건값: 454 × 50 = 22700원.","1000원짜리 22장은 22000원으로 모자라요.","적어도 23장 내야 해요."],"asset":null},{"stem":"502원짜리 물건을 40개 사려고 해요. 1000원짜리 지폐만 낸다면 적어도 몇 장을 내야 하나요? 숫자로 쓰세요.","answer":["21"],"explanation":["물건값: 502 × 40 = 20080원.","1000원짜리 20장은 20000원으로 모자라요.","적어도 21장 내야 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L02_challenge#5','math',4,1,'u3','L02','g4_1_math_u3_L02_challenge','lesson_challenge','M4-1-u3-C2',3,'sa','auto','사과를 한 상자에 194개씩 20상자, 배를 한 상자에 189개씩 20상자 거뒀어요. 거둔 사과와 배는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-1-u3-C2","difficulty":3,"kind":"sa","stem":"사과를 한 상자에 194개씩 20상자, 배를 한 상자에 189개씩 20상자 거뒀어요. 거둔 사과와 배는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["7660"],"explanation":["사과 194 × 20 = 3880개.","배 189 × 20 = 3780개.","3880 + 3780 = 7660 — 모두 7660개예요."],"variant_rule":{"alt":[{"stem":"사과를 한 상자에 175개씩 20상자, 배를 한 상자에 122개씩 30상자 거뒀어요. 거둔 사과와 배는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["7160"],"explanation":["사과 175 × 20 = 3500개.","배 122 × 30 = 3660개.","3500 + 3660 = 7160 — 모두 7160개예요."],"asset":null},{"stem":"사과를 한 상자에 186개씩 20상자, 배를 한 상자에 167개씩 20상자 거뒀어요. 거둔 사과와 배는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["7060"],"explanation":["사과 186 × 20 = 3720개.","배 167 × 20 = 3340개.","3720 + 3340 = 7060 — 모두 7060개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L02_challenge#6','math',4,1,'u3','L02','g4_1_math_u3_L02_challenge','lesson_challenge','M4-1-u3-C2',3,'mc','auto','수 카드 5, 8, 3, 6 중 세 장을 한 번씩 써서 세 자리 수를 만들고, 그 수에 60을 곱하려고 해요. 가장 큰 곱은 얼마인가요?',ARRAY['M4-1-u3-X14','M4-1-u3-X01']::text[],true,'{"seq":6,"concept":"M4-1-u3-C2","difficulty":3,"kind":"mc","stem":"수 카드 5, 8, 3, 6 중 세 장을 한 번씩 써서 세 자리 수를 만들고, 그 수에 60을 곱하려고 해요. 가장 큰 곱은 얼마인가요?","options":[{"t":"51900","correct":true},{"t":"51360","mis":"M4-1-u3-X14"},{"t":"41100","mis":"M4-1-u3-X14"},{"t":"5190","mis":"M4-1-u3-X01"}],"explanation":["곱하는 수가 정해져 있으니 세 자리 수가 가장 커야 해요.","큰 숫자부터 백·십·일의 자리에 — 865예요.","865 × 60 = 51900이에요."],"variant_rule":{"alt":[{"stem":"수 카드 4, 6, 7, 3 중 세 장을 한 번씩 써서 세 자리 수를 만들고, 그 수에 20을 곱하려고 해요. 가장 큰 곱은 얼마인가요?","options":[{"t":"15280","correct":true},{"t":"14920","mis":"M4-1-u3-X14"},{"t":"13480","mis":"M4-1-u3-X14"},{"t":"1528","mis":"M4-1-u3-X01"}],"explanation":["곱하는 수가 정해져 있으니 세 자리 수가 가장 커야 해요.","큰 숫자부터 백·십·일의 자리에 — 764예요.","764 × 20 = 15280이에요."],"asset":null},{"stem":"수 카드 4, 7, 1, 3 중 세 장을 한 번씩 써서 세 자리 수를 만들고, 그 수에 90을 곱하려고 해요. 가장 큰 곱은 얼마인가요?","options":[{"t":"66870","correct":true},{"t":"66060","mis":"M4-1-u3-X14"},{"t":"42570","mis":"M4-1-u3-X14"},{"t":"6687","mis":"M4-1-u3-X01"}],"explanation":["곱하는 수가 정해져 있으니 세 자리 수가 가장 커야 해요.","큰 숫자부터 백·십·일의 자리에 — 743이에요.","743 × 90 = 66870이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L02_challenge#7','math',4,1,'u3','L02','g4_1_math_u3_L02_challenge','lesson_challenge','M4-1-u3-C2',3,'ox','auto','574 × 30을 계산하는데 자리마다 곱한 값의 일의 자리만 써서 5120이라고 했어요. 바르게 계산했어요.',ARRAY['M4-1-u3-X04']::text[],true,'{"seq":7,"concept":"M4-1-u3-C2","difficulty":3,"kind":"ox","stem":"574 × 30을 계산하는데 자리마다 곱한 값의 일의 자리만 써서 5120이라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"올림한 수를 윗자리에 더해야 해서","correct":true},{"t":"자리마다 곱은 일의 자리만 쓰면 되어서","mis":"M4-1-u3-X04"}],"mis":"M4-1-u3-X04","explanation":["574 × 3 = 1722 — 올림이 있어요.","그 곱의 10배 — 17220.","5120은 올림을 버린 잘못이에요."],"variant_rule":{"alt":[{"stem":"802 × 70을 계산하는데 자리마다 곱한 값의 일의 자리만 써서 6040이라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"올림한 수를 윗자리에 더해야 해서","correct":true},{"t":"자리마다 곱은 일의 자리만 쓰면 되어서","mis":"M4-1-u3-X04"}],"explanation":["802 × 7 = 5614 — 올림이 있어요.","그 곱의 10배 — 56140.","6040은 올림을 버린 잘못이에요."],"asset":null},{"stem":"143 × 50을 계산하는데 자리마다 곱한 값의 일의 자리만 써서 5050이라고 했어요. 바르게 계산했어요.","answer":"X","reason_options":[{"t":"올림한 수를 윗자리에 더해야 해서","correct":true},{"t":"자리마다 곱은 일의 자리만 쓰면 되어서","mis":"M4-1-u3-X04"}],"explanation":["143 × 5 = 715 — 올림이 있어요.","그 곱의 10배 — 7150.","5050은 올림을 버린 잘못이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L02_challenge#8','math',4,1,'u3','L02','g4_1_math_u3_L02_challenge','lesson_challenge','M4-1-u3-C2',4,'essay','teacher','로봇이 하루에 채소를 186개씩 따요. 20일 동안 딴 채소는 몇 개인지 구하고, 186 × 2를 이용해 구하는 방법을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M4-1-u3-C2","difficulty":4,"kind":"essay","stem":"로봇이 하루에 채소를 186개씩 따요. 20일 동안 딴 채소는 몇 개인지 구하고, 186 × 2를 이용해 구하는 방법을 설명해 보세요.","answer_guide":{"answer":"예: 186 × 2 = 372이다. 20은 2의 10배이므로 186 × 20은 372의 10배인 3720이다. 20일 동안 딴 채소는 3720개이다.","scoring_points":["186 × 2 = 372를 구했는가","20이 2의 10배라서 곱도 10배라고 설명했는가","3720개라고 답했는가"]},"explanation":["186 × 2 = 372.","곱하는 수가 10배 → 곱도 10배.","3720개."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
