INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L03_basic#5','math',4,1,'u3','L03','g4_1_math_u3_L03_basic','lesson_basic','M4-1-u3-C3',2,'mc','auto','(세 자리 수) × (몇십몇)의 계산에 대해 바르게 말한 것은 어느 것인가요?',ARRAY['M4-1-u3-X06','M4-1-u3-X15','M4-1-u3-X03']::text[],true,'{"seq":5,"concept":"M4-1-u3-C3","difficulty":2,"kind":"mc","stem":"(세 자리 수) × (몇십몇)의 계산에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"(세 자리 수) × (몇십)과 (세 자리 수) × (몇)을 구해 더해요","correct":true},{"t":"각 자리 숫자끼리만 짝지어 곱해요","mis":"M4-1-u3-X06"},{"t":"두 수를 더한 뒤 10을 곱해요","mis":"M4-1-u3-X15"},{"t":"(세 자리 수) × (몇십)만 구하면 돼요","mis":"M4-1-u3-X03"}],"explanation":["152 × 24 = 152 × 20 + 152 × 4.","152 × 20 = 3040은 십의 자리를 곱한 값이라 한 칸 밀어 써요.","두 곱을 더하면 3040 + 608 = 3648이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. (세 자리 수) × (몇십몇)의 계산에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"십의 자리를 곱한 값은 한 칸 밀어 써요","correct":true},{"t":"두 줄을 모두 일의 자리에 맞추어 써요","mis":"M4-1-u3-X02"},{"t":"십의 자리를 곱한 값은 두 칸 밀어 써요","mis":"M4-1-u3-X02"},{"t":"십의 자리를 곱한 줄은 쓰지 않아요","mis":"M4-1-u3-X03"}],"explanation":["152 × 24 = 152 × 20 + 152 × 4.","152 × 20 = 3040은 십의 자리를 곱한 값이라 한 칸 밀어 써요.","두 곱을 더하면 3040 + 608 = 3648이에요."],"asset":null},{"stem":"이번에는 다른 수예요. (세 자리 수) × (몇십몇)의 계산에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"줄마다 올림한 수는 그 줄 안에서 더해요","correct":true},{"t":"올림한 수는 더하지 않고 버려요","mis":"M4-1-u3-X04"},{"t":"앞 줄의 올림을 다음 줄에도 다시 더해요","mis":"M4-1-u3-X05"},{"t":"올림한 수는 맨 마지막 합에만 더해요","mis":"M4-1-u3-X04"}],"explanation":["152 × 24 = 152 × 20 + 152 × 4.","152 × 20 = 3040은 십의 자리를 곱한 값이라 한 칸 밀어 써요.","두 곱을 더하면 3040 + 608 = 3648이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EX