INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L03_basic#9','math',4,1,'u3','L03','g4_1_math_u3_L03_basic','lesson_basic','M4-1-u3-C4',2,'mc','auto','도윤이 526 × 87을 계산해 7890이라고 했어요. 어림해 보면 어떤가요?',ARRAY['M4-1-u3-X17','M4-1-u3-X14']::text[],true,'{"seq":9,"concept":"M4-1-u3-C4","difficulty":2,"kind":"mc","stem":"도윤이 526 × 87을 계산해 7890이라고 했어요. 어림해 보면 어떤가요?","options":[{"t":"45000쯤인데 7890은 너무 작아요 — 잘못 계산했어요","correct":true},{"t":"어림값과 비슷하니 맞게 계산했어요","mis":"M4-1-u3-X17"},{"t":"어림으로는 맞았는지 알 수 없어요","mis":"M4-1-u3-X17"},{"t":"45000쯤인데 7890은 너무 커요 — 잘못 계산했어요","mis":"M4-1-u3-X14"}],"explanation":["526 × 87 — 약 500 × 90 = 45000.","7890은 어림값보다 훨씬 작아요.","바른 곱은 45762예요."],"variant_rule":{"alt":[{"stem":"도윤이 627 × 46을 계산해 6270이라고 했어요. 어림해 보면 어떤가요?","options":[{"t":"30000쯤인데 6270은 너무 작아요 — 잘못 계산했어요","correct":true},{"t":"어림값과 비슷하니 맞게 계산했어요","mis":"M4-1-u3-X17"},{"t":"어림으로는 맞았는지 알 수 없어요","mis":"M4-1-u3-X17"},{"t":"30000쯤인데 6270은 너무 커요 — 잘못 계산했어요","mis":"M4-1-u3-X14"}],"explanation":["627 × 46 — 약 600 × 50 = 30000.","6270은 어림값보다 훨씬 작아요.","바른 곱은 28842예요."],"asset":null},{"stem":"하린이 845 × 64를 계산해 50700이라고 했어요. 어림해 보면 어떤가요?","options":[{"t":"48000쯤인데 50700은 너무 작아요 — 잘못 계산했어요","correct":true},{"t":"어림값과 비슷하니 맞게 계산했어요","mis":"M4-1-u3-X17"},{"t":"어림으로는 맞았는지 알 수 없어요","mis":"M4-1-u3-X17"},{"t":"48000쯤인데 50700은 너무 커요 — 잘못 계산했어요","mis":"M4-1-u3-X14"}],"explanation":["845 × 64 — 약 800 × 60 = 48000.","50700은 어림값보다 훨씬 작아요.","바른 곱은 54080이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L03_basic#10','math',4,1,'u3','L03','g4_1_math_u3_L03_basic','lesson_basic','M4-1-u3-C3',3,'sa','auto','은우가 321 × 19를 이렇게 계산해 3210이라고 했어요. 바르게 계산하면 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M4-1-u3-C3","difficulty":3,"kind":"sa","stem":"은우가 321 × 19를 이렇게 계산해 3210이라고 했어요. 바르게 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["6099"],"explanation":["은우 — 넷째 줄을 한 칸 밀어 쓰지 않았어요.","321 × 9 = 2889, 321 × 10 = 3210.","2889 + 3210 = 6099예요."],"asset":{"type":"expr_grid","rows":[["","","","3","2","1"],["×","","","","1","9"],["","","2","8","8","9"],["","","","3","2","1"],["","","3","2","1","0"]]},"variant_rule":{"alt":[{"stem":"건우가 294 × 27을 이렇게 계산해 2646이라고 했어요. 바르게 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["7938"],"explanation":["건우 — 넷째 줄을 한 칸 밀어 쓰지 않았어요.","294 × 7 = 2058, 294 × 20 = 5880.","2058 + 5880 = 7938이에요."],"asset":{"type":"expr_grid","rows":[["","","","2","9","4"],["×","","","","2","7"],["","","2","0","5","8"],["","","","5","8","8"],["","","2","6","4","6"]]}},{"stem":"건우가 641 × 13을 이렇게 계산해 2564라고 했어요. 바르게 계산하면 얼마인가요? 숫자로 쓰세요.","answer":["8333"],"explanation":["건우 — 넷째 줄을 한 칸 밀어 쓰지 않았어요.","641 × 3 = 1923, 641 × 10 = 6410.","1923 + 6410 = 8333이에요."],"asset":{"type":"expr_grid","rows":[["","","","6","4","1"],["×","","","","1","3"],["","","1","9","2","3"],["","","","6","4","1"],["","","2","5","6","4"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L03_challenge#1','math',4,1,'u3','L03','g4_1_math_u3_L03_challenge','lesson_challenge','M4-1-u3-C3',2,'mc','auto','스마트 팜 로봇이 하루에 채소를 454개씩 따요. 27일 동안 땄어요. 로봇이 딴 채소는 모두 몇 개인가요?',ARRAY['M4-1-u3-X15','M4-1-u3-X02','M4-1-u3-X03']::text[],true,'{"seq":1,"concept":"M4-1-u3-C3","difficulty":2,"kind":"mc","stem":"스마트 팜 로봇이 하루에 채소를 454개씩 따요. 27일 동안 땄어요. 로봇이 딴 채소는 모두 몇 개인가요?","options":[{"t":"12258개","correct":true},{"t":"481개","mis":"M4-1-u3-X15"},{"t":"4086개","mis":"M4-1-u3-X02"},{"t":"9080개","mis":"M4-1-u3-X03"}],"explanation":["한 번에 454개씩 27번 — 454 × 27로 구해요.","454 × 20 = 9080, 454 × 7 = 3178.","모두 12258개예요."],"variant_rule":{"alt":[{"stem":"딸기를 하루에 606 kg씩 29일 동안 거뒀어요. 거둔 딸기는 모두 몇 kg인가요?","options":[{"t":"17574 kg","correct":true},{"t":"635 kg","mis":"M4-1-u3-X15"},{"t":"6666 kg","mis":"M4-1-u3-X02"},{"t":"12120 kg","mis":"M4-1-u3-X03"}],"explanation":["한 번에 606 kg씩 29번 — 606 × 29로 구해요.","606 × 20 = 12120, 606 × 9 = 5454.","모두 17574 kg예요."],"asset":null},{"stem":"인공 지능으로 물을 일주일에 425 L씩 35주 동안 아꼈어요. 아낀 물은 모두 몇 L인가요?","options":[{"t":"14875 L","correct":true},{"t":"460 L","mis":"M4-1-u3-X15"},{"t":"3400 L","mis":"M4-1-u3-X02"},{"t":"12750 L","mis":"M4-1-u3-X03"}],"explanation":["한 번에 425 L씩 35번 — 425 × 35로 구해요.","425 × 30 = 12750, 425 × 5 = 2125.","모두 14875 L예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L03_challenge#2','math',4,1,'u3','L03','g4_1_math_u3_L03_challenge','lesson_challenge','M4-1-u3-C3',2,'ox','auto','308 × 14를 세로셈으로 계산할 때 308 × 1의 곱은 한 칸 밀어 써요.',ARRAY['M4-1-u3-X02']::text[],true,'{"seq":2,"concept":"M4-1-u3-C3","difficulty":2,"kind":"ox","stem":"308 × 14를 세로셈으로 계산할 때 308 × 1의 곱은 한 칸 밀어 써요.","answer":"O","reason_options":[{"t":"십의 자리 1이 10을 나타내서","correct":true},{"t":"곱한 줄은 모두 일의 자리에 맞추어 써서","mis":"M4-1-u3-X02"}],"mis":"M4-1-u3-X02","explanation":["308 × 1 = 308이에요.","실제로는 308 × 10 = 3080 — 그래서 한 칸 밀어요.","맞아요."],"asset":{"type":"expr_grid","rows":[["","","","3","0","8"],["×","","","","1","4"],["","","1","2","3","2"],["","","3","0","8",""],["","","4","3","1","2"]]},"variant_rule":{"alt":[{"stem":"161 × 46 = 161 × 6 + 161 × 4 = 1610이에요.","answer":"X","reason_options":[{"t":"십의 자리 4가 40을 나타내서","correct":true},{"t":"쪼갠 두 곱을 더하면 언제나 맞아서","mis":"M4-1-u3-X06"}],"explanation":["46 = 40 + 6 — 십의 자리 4는 40을 나타내요.","바르게: 161 × 40 + 161 × 6 = 7406이에요.","그래서 틀렸어요."],"asset":null},{"stem":"344 × 25를 세로셈으로 계산할 때 344 × 2의 곱은 한 칸 밀어 써요.","answer":"O","reason_options":[{"t":"십의 자리 2가 20을 나타내서","correct":true},{"t":"곱한 줄은 모두 일의 자리에 맞추어 써서","mis":"M4-1-u3-X02"}],"explanation":["344 × 2 = 688이에요.","실제로는 344 × 20 = 6880 — 그래서 한 칸 밀어요.","맞아요."],"asset":{"type":"expr_grid","rows":[["","","","3","4","4"],["×","","","","2","5"],["","","1","7","2","0"],["","","6","8","8",""],["","","8","6","0","0"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L03_challenge#3','math',4,1,'u3','L03','g4_1_math_u3_L03_challenge','lesson_challenge','M4-1-u3-C3',3,'error','auto','태오가 345 × 16을 이렇게 계산해 4290이라고 했어요. 무엇이 잘못됐나요?',ARRAY['M4-1-u3-X04','M4-1-u3-X02','M4-1-u3-X06']::text[],true,'{"seq":3,"concept":"M4-1-u3-C3","difficulty":3,"kind":"error","stem":"태오가 345 × 16을 이렇게 계산해 4290이라고 했어요. 무엇이 잘못됐나요?","options":[{"t":"올림한 수를 윗자리에 더하지 않았어요","correct":true,"mis_target":"M4-1-u3-X04"},{"t":"345 × 10의 값을 한 칸 밀지 않고 써서 자리가 어긋났어요","mis":"M4-1-u3-X02"},{"t":"16을 10과 6으로 쪼개서 잘못됐어요","mis":"M4-1-u3-X06"}],"explanation":["345 × 6 = 2070, 345 × 10 = 3450.","2070 + 3450 = 5520이에요.","태오 — 올림한 수를 윗자리에 더하지 않았어요."],"asset":{"type":"expr_grid","rows":[["","","","3","4","5"],["×","","","","1","6"],["","","","8","4","0"],["","","3","4","5",""],["","","4","2","9","0"]]},"variant_rule":{"alt":[{"stem":"태오가 188 × 29를 이렇게 계산해 2068이라고 했어요. 무엇이 잘못됐나요?","options":[{"t":"188 × 20의 값을 한 칸 밀지 않고 써서 자리가 어긋났어요","correct":true,"mis_target":"M4-1-u3-X02"},{"t":"셋째 줄에서 올림한 수를 넷째 줄에도 다시 더했어요","mis":"M4-1-u3-X05"},{"t":"29를 20과 9로 쪼개서 잘못됐어요","mis":"M4-1-u3-X06"}],"explanation":["188 × 9 = 1692, 188 × 20 = 3760.","1692 + 3760 = 5452예요.","태오 — 188 × 20의 값을 한 칸 밀지 않고 써서 자리가 어긋났어요."],"asset":{"type":"expr_grid","rows":[["","","","1","8","8"],["×","","","","2","9"],["","","1","6","9","2"],["","","","3","7","6"],["","","2","0","6","8"]]}},{"stem":"태오가 248 × 18을 이렇게 계산해 3104라고 했어요. 무엇이 잘못됐나요?","options":[{"t":"올림한 수를 윗자리에 더하지 않았어요","correct":true,"mis_target":"M4-1-u3-X04"},{"t":"248 × 10의 값을 한 칸 밀지 않고 써서 자리가 어긋났어요","mis":"M4-1-u3-X02"},{"t":"18을 10과 8로 쪼개서 잘못됐어요","mis":"M4-1-u3-X06"}],"explanation":["248 × 8 = 1984, 248 × 10 = 2480.","1984 + 2480 = 4464예요.","태오 — 올림한 수를 윗자리에 더하지 않았어요."],"asset":{"type":"expr_grid","rows":[["","","","2","4","8"],["×","","","","1","8