INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L03_challenge#4','math',4,1,'u3','L03','g4_1_math_u3_L03_challenge','lesson_challenge','M4-1-u3-C3',3,'mc','auto','786 × 62를 어림하면 곱은 어느 사이에 있나요?',ARRAY['M4-1-u3-X16','M4-1-u3-X14']::text[],true,'{"seq":4,"concept":"M4-1-u3-C3","difficulty":3,"kind":"mc","stem":"786 × 62를 어림하면 곱은 어느 사이에 있나요?","options":[{"t":"42000보다 크고 56000보다 작아요","correct":true},{"t":"4200보다 크고 5600보다 작아요","mis":"M4-1-u3-X16"},{"t":"420000보다 크고 560000보다 작아요","mis":"M4-1-u3-X16"},{"t":"42000보다 작아요","mis":"M4-1-u3-X14"}],"explanation":["786은 700과 800 사이, 62는 60과 70 사이예요.","700 × 60 = 42000, 800 × 70 = 56000이에요.","실제 곱 48732는 그 사이에 있어요."],"variant_rule":{"alt":[{"stem":"829 × 34를 어림하면 곱은 어느 사이에 있나요?","options":[{"t":"24000보다 크고 36000보다 작아요","correct":true},{"t":"2400보다 크고 3600보다 작아요","mis":"M4-1-u3-X16"},{"t":"240000보다 크고 360000보다 작아요","mis":"M4-1-u3-X16"},{"t":"24000보다 작아요","mis":"M4-1-u3-X14"}],"explanation":["829는 800과 900 사이, 34는 30과 40 사이예요.","800 × 30 = 24000, 900 × 40 = 36000이에요.","실제 곱 28186은 그 사이에 있어요."],"asset":null},{"stem":"639 × 75를 어림하면 곱은 어느 사이에 있나요?","options":[{"t":"42000보다 크고 56000보다 작아요","correct":true},{"t":"4200보다 크고 5600보다 작아요","mis":"M4-1-u3-X16"},{"t":"420000보다 크고 560000보다 작아요","mis":"M4-1-u3-X16"},{"t":"42000보다 작아요","mis":"M4-1-u3-X14"}],"explanation":["639는 600과 700 사이, 75는 70과 80 사이예요.","600 × 70 = 42000, 700 × 80 = 56000이에요.","실제 곱 47925는 그 사이에 있어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
