INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L03_challenge#8','math',4,1,'u3','L03','g4_1_math_u3_L03_challenge','lesson_challenge','M4-1-u3-C3',4,'essay','teacher','152 × 24를 세로셈으로 계산하는 방법을 두 줄의 곱(부분곱)을 써서 설명하고, 답을 구해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M4-1-u3-C3","difficulty":4,"kind":"essay","stem":"152 × 24를 세로셈으로 계산하는 방법을 두 줄의 곱(부분곱)을 써서 설명하고, 답을 구해 보세요.","answer_guide":{"answer":"예: 먼저 152 × 4 = 608을 쓴다. 다음 152 × 2 = 304를 쓰는데, 십의 자리 2를 곱한 것이므로 한 칸 밀어 써서 3040을 나타낸다. 두 줄을 더하면 608 + 3040 = 3648이다.","scoring_points":["152 × 4 = 608을 구했는가","152 × 20 = 3040을 한 칸 밀어 쓴다고 설명했는가","3648을 구했는가"]},"explanation":["152 × 4 = 608.","152 × 20 = 3040(한 칸 밀기).","608 + 3040 = 3648."],"asset":{"type":"expr_grid","rows":[["","","","1","5","2"],["×","","","","2","4"],["","","","6","0","8"],["","","3","0","4",""],["","","3","6","4","8"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L03_challenge#9','math',4,1,'u3','L03','g4_1_math_u3_L03_challenge','lesson_challenge','M4-1-u3-C4',4,'mc','auto','가 반은 31명이 한 명에 173 mL씩, 나 반은 29명이 한 명에 193 mL씩 우유를 마셨어요. 어느 반이 몇 mL 더 많이 마셨나요?',ARRAY['M4-1-u3-X14','M4-1-u3-X18','M4-1-u3-X15']::text[],true,'{"seq":9,"concept":"M4-1-u3-C4","difficulty":4,"kind":"mc","stem":"가 반은 31명이 한 명에 173 mL씩, 나 반은 29명이 한 명에 193 mL씩 우유를 마셨어요. 어느 반이 몇 mL 더 많이 마셨나요?","options":[{"t":"나 반, 234 mL","correct":true},{"t":"가 반, 234 mL","mis":"M4-1-u3-X14"},{"t":"나 반, 620 mL","mis":"M4-1-u3-X18"},{"t":"나 반, 10960 mL","mis":"M4-1-u3-X15"}],"explanation":["가 반 173 × 31 = 5363 mL.","나 반 193 × 29 = 5597 mL.","나 반이 5597 − 5363 = 234 mL 더 마셨어요."],"variant_rule":{"alt":[{"stem":"가 반은 25명이 한 명에 165 mL씩, 나 반은 23명이 한 명에 205 mL씩 우유를 마셨어요. 어느 반이 몇 mL 더 많이 마셨나요?","options":[{"t":"나 반, 590 mL","correct":true},{"t":"가 반, 590 mL","mis":"M4-1-u3-X14"},{"t":"나 반, 1000 mL","mis":"M4-1-u3-X18"},{"t":"나 반, 8840 mL","mis":"M4-1-u3-X15"}],"explanation":["가 반 165 × 25 = 4125 mL.","나 반 205 × 23 = 4715 mL.","나 반이 4715 − 4125 = 590 mL 더 마셨어요."],"asset":null},{"stem":"가 반은 32명이 한 명에 259 mL씩, 나 반은 30명이 한 명에 279 mL씩 우유를 마셨어요. 어느 반이 몇 mL 더 많이 마셨나요?","options":[{"t":"나 반, 82 mL","correct":true},{"t":"가 반, 82 mL","mis":"M4-1-u3-X14"},{"t":"나 반, 640 mL","mis":"M4-1-u3-X18"},{"t":"나 반, 16658 mL","mis":"M4-1-u3-X15"}],"explanation":["가 반 259 × 32 = 8288 mL.","나 반 279 × 30 = 8370 mL.","나 반이 8370 − 8288 = 82 mL 더 마셨어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
