INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L04_basic#1','math',4,1,'u3','L04','g4_1_math_u3_L04_basic','lesson_basic','M4-1-u3-C5',1,'sa','auto','270 ÷ 30의 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-1-u3-C5","difficulty":1,"kind":"sa","stem":"270 ÷ 30의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["270 ÷ 30 — 270은 십 모형 27개, 30은 십 모형 3개로 보면 27 ÷ 3과 같아요.","30 × 9 = 270 — 남는 것이 없어요.","270 ÷ 30 = 9예요."],"asset":{"type":"ldiv","a":270,"b":30,"upto":0},"variant_rule":{"alt":[{"stem":"450 ÷ 50의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["450 ÷ 50 — 450은 십 모형 45개, 50은 십 모형 5개로 보면 45 ÷ 5와 같아요.","50 × 9 = 450 — 남는 것이 없어요.","450 ÷ 50 = 9예요."],"asset":{"type":"ldiv","a":450,"b":50,"upto":0}},{"stem":"720 ÷ 90의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["720 ÷ 90 — 720은 십 모형 72개, 90은 십 모형 9개로 보면 72 ÷ 9와 같아요.","90 × 8 = 720 — 남는 것이 없어요.","720 ÷ 90 = 8이에요."],"asset":{"type":"ldiv","a":720,"b":90,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
