INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L04_basic#3','math',4,1,'u3','L04','g4_1_math_u3_L04_basic','lesson_basic','M4-1-u3-C5',1,'mc','auto','나눗셈의 나머지에 대해 바르게 말한 것은 어느 것인가요?',ARRAY['M4-1-u3-X07','M4-1-u3-X14']::text[],true,'{"seq":3,"concept":"M4-1-u3-C5","difficulty":1,"kind":"mc","stem":"나눗셈의 나머지에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"나누는 수보다 작아야 해요","correct":true},{"t":"나누는 수보다 커야 해요","mis":"M4-1-u3-X07"},{"t":"몫보다 작아야 해요","mis":"M4-1-u3-X14"},{"t":"언제나 0이어야 해요","mis":"M4-1-u3-X07"}],"explanation":["248 ÷ 40 — 40 × 6 = 240, 남는 수 8.","8은 40보다 작아서 더 나눌 수 없어요.","나머지는 언제나 나누는 수보다 작아요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 나눗셈의 나머지에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"나누는 수와 같거나 크면 몫을 1 크게 해야 해요","correct":true},{"t":"나누는 수와 같거나 커도 그대로 두어요","mis":"M4-1-u3-X07"},{"t":"나누는 수와 같거나 크면 몫을 1 작게 해요","mis":"M4-1-u3-X08"},{"t":"나머지가 크면 나누는 수를 바꾸어요","mis":"M4-1-u3-X15"}],"explanation":["248 ÷ 40 — 40 × 6 = 240, 남는 수 8.","8은 40보다 작아서 더 나눌 수 없어요.","나머지는 언제나 나누는 수보다 작아요."],"asset":null},{"stem":"이번에는 다른 수예요. 나눗셈의 나머지에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"남는 수가 없으면 나머지는 0이에요","correct":true},{"t":"남는 수가 없으면 나머지는 나누는 수예요","mis":"M4-1-u3-X07"},{"t":"남는 수가 없으면 몫이 0이에요","mis":"M4-1-u3-X14"},{"t":"나머지는 언제나 1보다 커요","mis":"M4-1-u3-X07"}],"explanation":["248 ÷ 40 — 40 × 6 = 240, 남는 수 8.","8은 40보다 작아서 더 나눌 수 없어요.","나머지는 언제나 나누는 수보다 작아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L04_basic#4','math',4,1,'u3','L04','g4_1_math_u3_L04_basic','lesson_basic','M4-1-u3-C5',1,'mc','auto','240 ÷ 60의 몫을 구할 때 이용할 수 있는 나눗셈은 어느 것인가요?',ARRAY['M4-1-u3-X01','M4-1-u3-X15']::text[],true,'{"seq":4,"concept":"M4-1-u3-C5","difficulty":1,"kind":"mc","stem":"240 ÷ 60의 몫을 구할 때 이용할 수 있는 나눗셈은 어느 것인가요?","options":[{"t":"24 ÷ 6","correct":true},{"t":"240 ÷ 6","mis":"M4-1-u3-X01"},{"t":"24 ÷ 60","mis":"M4-1-u3-X01"},{"t":"24 × 6","mis":"M4-1-u3-X15"}],"explanation":["240은 십 모형 24개, 60은 십 모형 6개로 볼 수 있어요.","24개를 6개씩 묶으면 4묶음.","그래서 몫은 24 ÷ 6의 몫 4와 같아요."],"variant_rule":{"alt":[{"stem":"720 ÷ 80의 몫을 구할 때 이용할 수 있는 나눗셈은 어느 것인가요?","options":[{"t":"72 ÷ 8","correct":true},{"t":"720 ÷ 8","mis":"M4-1-u3-X01"},{"t":"72 ÷ 80","mis":"M4-1-u3-X01"},{"t":"72 × 8","mis":"M4-1-u3-X15"}],"explanation":["720은 십 모형 72개, 80은 십 모형 8개로 볼 수 있어요.","72개를 8개씩 묶으면 9묶음.","그래서 몫은 72 ÷ 8의 몫 9와 같아요."],"asset":null},{"stem":"180 ÷ 60의 몫을 구할 때 이용할 수 있는 나눗셈은 어느 것인가요?","options":[{"t":"18 ÷ 6","correct":true},{"t":"180 ÷ 6","mis":"M4-1-u3-X01"},{"t":"18 ÷ 60","mis":"M4-1-u3-X01"},{"t":"18 × 6","mis":"M4-1-u3-X15"}],"explanation":["180은 십 모형 18개, 60은 십 모형 6개로 볼 수 있어요.","18개를 6개씩 묶으면 3묶음.","그래서 몫은 18 ÷ 6의 몫 3과 같아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
