INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L04_basic#8','math',4,1,'u3','L04','g4_1_math_u3_L04_basic','lesson_basic','M4-1-u3-C5',2,'sa','auto','162 ÷ 20의 세로셈이에요. ?에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M4-1-u3-C5","difficulty":2,"kind":"sa","stem":"162 ÷ 20의 세로셈이에요. ?에 알맞은 수를 쓰세요.","answer":["8"],"explanation":["?는 몫의 일의 자리예요.","162 ÷ 20 — 160은 십 모형 16개, 20은 십 모형 2개로 보면 16 ÷ 2와 같아요.","?는 8이에요."],"asset":{"type":"ldiv","a":162,"b":20,"hide":[["q",2]]},"variant_rule":{"alt":[{"stem":"393 ÷ 80의 세로셈이에요. ?에 알맞은 수를 쓰세요.","answer":["73"],"explanation":["?는 나머지예요.","393 ÷ 80 — 390은 십 모형 39개, 80은 십 모형 8개로 보면 39 ÷ 8과 같아요.","?는 73이에요."],"asset":{"type":"ldiv","a":393,"b":80,"hide":["rem"]}},{"stem":"281 ÷ 90의 세로셈이에요. ?에 알맞은 수를 쓰세요.","answer":["270"],"explanation":["?는 나누는 수와 몫을 곱한 값이에요.","281 ÷ 90 — 280은 십 모형 28개, 90은 십 모형 9개로 보면 28 ÷ 9와 같아요.","?는 270이에요."],"asset":{"type":"ldiv","a":281,"b":90,"hide":[["r",0]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L04_basic#9','math',4,1,'u3','L04','g4_1_math_u3_L04_basic','lesson_basic','M4-1-u3-C5',2,'sa','auto','방울토마토 102 kg을 한 상자에 40 kg씩 담으려고 해요. 가득 채운 상자는 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-1-u3-C5","difficulty":2,"kind":"sa","stem":"방울토마토 102 kg을 한 상자에 40 kg씩 담으려고 해요. 가득 채운 상자는 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["102 ÷ 40을 계산해요.","102 − 80 = 22 — 22는 40보다 작아요.","몫 2 — 2개예요."],"variant_rule":{"alt":[{"stem":"색종이 812장을 90장씩 묶으려고 해요. 몇 묶음이 되나요? 숫자로 쓰세요.","answer":["9"],"explanation":["812 ÷ 90을 계산해요.","812 − 810 = 2 — 2는 90보다 작아요.","몫 9 — 9묶음이에요."],"asset":null},{"stem":"방울토마토 249 kg을 한 상자에 30 kg씩 담으려고 해요. 가득 채운 상자는 몇 개인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["249 ÷ 30을 계산해요.","249 − 240 = 9 — 9는 30보다 작아요.","몫 8 — 8개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L04_basic#10','math',4,1,'u3','L04','g4_1_math_u3_L04_basic','lesson_basic','M4-1-u3-C5',3,'error','auto','친구들이 나눗셈을 했어요. 잘못 계산한 친구는 누구인가요?',ARRAY['M4-1-u3-X09','M4-1-u3-X14']::text[],true,'{"seq":10,"concept":"M4-1-u3-C5","difficulty":3,"kind":"error","stem":"친구들이 나눗셈을 했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"도윤 — 296 ÷ 60 = 4 … 5","correct":true,"mis_target":"M4-1-u3-X09"},{"t":"서준 — 541 ÷ 70 = 7 … 51","mis":"M4-1-u3-X14"},{"t":"하린 — 223 ÷ 30 = 7 … 13","mis":"M4-1-u3-X14"}],"explanation":["296 ÷ 60 — 60 × 4 = 240.","296 − 240 = 56이에요 — 나머지예요.","도윤이 0을 지우고 29 ÷ 6을 계산해 나머지를 5로 썼어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 친구들이 나눗셈을 했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"하린 — 227 ÷ 70 = 3 … 1","correct":true,"mis_target":"M4-1-u3-X09"},{"t":"건우 — 132 ÷ 30 = 4 … 12","mis":"M4-1-u3-X14"},{"t":"서준 — 291 ÷ 50 = 5 … 41","mis":"M4-1-u3-X14"}],"explanation":["227 ÷ 70 — 70 × 3 = 210.","227 − 210 = 17이에요 — 나머지예요.","하린이 0을 지우고 22 ÷ 7을 계산해 나머지를 1로 썼어요."],"asset":null},{"stem":"이번에는 다른 수예요. 친구들이 나눗셈을 했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"태오 — 131 ÷ 60 = 2 … 1","correct":true,"mis_target":"M4-1-u3-X09"},{"t":"건우 — 566 ÷ 70 = 8 … 6","mis":"M4-1-u3-X14"},{"t":"서준 — 235 ÷ 40 = 5 … 35","mis":"M4-1-u3-X14"}],"explanation":["131 ÷ 60 — 60 × 2 = 120.","131 − 120 = 11이에요 — 나머지예요.","태오가 0을 지우고 13 ÷ 6을 계산해 나머지를 1로 썼어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L04_challenge#1','math',4,1,'u3','L04','g4_1_math_u3_L04_challenge','lesson_challenge','M4-1-u3-C5',2,'mc','auto','방울토마토 159 kg을 한 상자에 50 kg씩 담으려고 해요. 상자에 담고 남는 방울토마토는 몇 kg인가요?',ARRAY['M4-1-u3-X14','M4-1-u3-X07','M4-1-u3-X15']::text[],true,'{"seq":1,"concept":"M4-1-u3-C5","difficulty":2,"kind":"mc","stem":"방울토마토 159 kg을 한 상자에 50 kg씩 담으려고 해요. 상자에 담고 남는 방울토마토는 몇 kg인가요?","options":[{"t":"9 kg","correct":true},{"t":"3 kg","mis":"M4-1-u3-X14"},{"t":"59 kg","mis":"M4-1-u3-X07"},{"t":"12 kg","mis":"M4-1-u3-X15"}],"explanation":["159 ÷ 50을 계산해요.","159 − 150 = 9 — 9는 50보다 작아요.","나머지 9 — 9 kg 남아요."],"variant_rule":{"alt":[{"stem":"방울토마토 349 kg을 한 상자에 50 kg씩 담으려고 해요. 상자에 담고 남는 방울토마토는 몇 kg인가요?","options":[{"t":"49 kg","correct":true},{"t":"6 kg","mis":"M4-1-u3-X14"},{"t":"99 kg","mis":"M4-1-u3-X07"},{"t":"4 kg","mis":"M4-1-u3-X09"}],"explanation":["349 ÷ 50을 계산해요.","349 − 300 = 49 — 49는 50보다 작아요.","나머지 49 — 49 kg 남아요."],"asset":null},{"stem":"구슬 263개를 한 봉지에 50개씩 담으려고 해요. 담고 남는 구슬은 몇 개인가요?","options":[{"t":"13개","correct":true},{"t":"5개","mis":"M4-1-u3-X14"},{"t":"63개","mis":"M4-1-u3-X07"},{"t":"1개","mis":"M4-1-u3-X09"}],"explanation":["263 ÷ 50을 계산해요.","263 − 250 = 13 — 13은 50보다 작아요.","나머지 13 — 13개 남아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L04_challenge#2','math',4,1,'u3','L04','g4_1_math_u3_L04_challenge','lesson_challenge','M4-1-u3-C6',2,'sa','auto','어떤 수를 70으로 나누었더니 몫이 8, 나머지가 13이 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-1-u3-C6","difficulty":2,"kind":"sa","stem":"어떤 수를 70으로 나누었더니 몫이 8, 나머지가 13이 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["573"],"explanation":["나누어지는 수 = (나누는 수) × (몫) + (나머지).","70 × 8 = 560.","560 + 13 = 573 — 어떤 수는 573이에요."],"asset":{"type":"expr_grid","rows":[["70 × 8","=","560"],["560 + 13","=",null]]},"variant_rule":{"alt":[{"stem":"어떤 수를 60으로 나누었더니 몫이 7, 나머지가 17이 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["437"],"explanation":["나누어지는 수 = (나누는 수) × (몫) + (나머지).","60 × 7 = 420.","420 + 17 = 437 — 어떤 수는 437이에요."],"asset":{"type":"expr_grid","rows":[["60 × 7","=","420"],["420 + 17","=",null]]}},{"stem":"어떤 수를 40으로 나누었더니 몫이 3, 나머지가 19가 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["139"],"explanation":["나누어지는 수 = (나누는 수) × (몫) + (나머지).","40 × 3 = 120.","120 + 19 = 139 — 어떤 수는 139예요."],"asset":{"type":"expr_grid","rows":[["40 × 3","=","120"],["120 + 19","=",null]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L04_challenge#3','math',4,1,'u3','L04','g4_1_math_u3_L04_challenge','lesson_challenge','M4-1-u3-C5',3,'sa','auto','어떤 수를 40으로 나누었더니 몫이 9였어요. 나머지가 될 수 있는 수 가운데 가장 큰 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-1-u3-C5","difficulty":3,"kind":"sa","stem":"어떤 수를 40으로 나누었더니 몫이 9였어요. 나머지가 될 수 있는 수 가운데 가장 큰 수는 얼마인가요? 숫자로 쓰세요.","answer":["39"],"explanation":["나머지는 나누는 수 40보다 작아야 해요.","40이 되면 한 번 더 나눌 수 있어요.","가장 큰 나머지는 39예요."],"variant_rule":{"alt":[{"stem":"어떤 수를 70으로 나누었더니 몫이 8이었어요. 나머지가 될 수 있는 수 가운데 가장 큰 수는 얼마인가요? 숫자로 쓰세요.","answer":["69"],"explanation":["나머지는 나누는 수 70보다 작아야 해요.","70이 되면 한 번 더 나눌 수 있어요.","가장 큰 나머지는 69예요."],"asset":null},{"stem":"어떤 수를 70으로 나누었더니 몫이 7이었어요. 나머지가 될 수 있는 수 가운데 가장 큰 수는 얼마인가요? 숫자로 쓰세요.","answer":["69"],"explanation":["나머지는 나누는 수 70보다 작아야 해요.","70이 되면 한 번 더 나눌 수 있어요.","가장 큰 나머지는 69예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L04_challenge#4','math',4,1,'u3','L04','g4_1_math_u3_L04_challenge','lesson_challenge','M4-1-u3-C6',3,'mc','auto','141 ÷ 50을 계산했어요. 확인하는 식으로 보아 바르게 계산한 친구는 누구인가요?',ARRAY['M4-1-u3-X07','M4-1-u3-X08','M4-1-u3-X10']::text[],true,'{"seq":4,"concept":"M4-1-u3-C6","difficulty":3,"kind":"mc","stem":"141 ÷ 50을 계산했어요. 확인하는 식으로 보아 바르게 계산한 친구는 누구인가요?","options":[{"t":"도윤 — 2 … 41","correct":true},{"t":"서준 — 1 … 91","mis":"M4-1-u3-X07"},{"t":"하린 — 3 … 41","mis":"M4-1-u3-X08"},{"t":"은우 — 2 … 42","mis":"M4-1-u3-X10"}],"explanation":["(나누는 수) × (몫) + (나머지) = (나누어지는 수)여야 해요.","50 × 2 + 41 = 141이에요.","도윤 — 나머지 41이 50보다 작고 확인 식도 맞아요."],"asset":{"type":"expr_grid","rows":[["50 × 2","=","100"],["100 + 41","=",null]]},"variant_rule":{"alt":[{"stem":"535 ÷ 90을 계산했어요. 확인하는 식으로 보아 바르게 계산한 친구는 누구인가요?","options":[{"t":"하린 — 5 … 85","correct":true},{"t":"건우 — 4 … 175","mis":"M4-1-u3-X07"},{"t":"서준 — 6 … 85","mis":"M4-1-u3-X08"},{"t":"은우 — 5 … 86","mis":"M4-1-u3-X10"}],"explanation":["(나누는 수) × (몫) + (나머지) = (나누어지는 수)여야 해요.","90 × 5 + 85 = 535예요.","하린 — 나머지 85가 90보다 작고 확인 식도 맞아요."],"asset":{"type":"expr_grid","rows":[["90 × 5","=","450"],["450 + 85","=",null]]}},{"stem":"166 ÷ 60을 계산했어요. 확인하는 식으로 보아 바르게 계산한 친구는 누구인가요?","options":[{"t":"지유 — 2 … 46","correct":true},{"t":"시아 — 1 … 106","mis":"M4-1-u3-X07"},{"t":"은우 — 3 … 46","mis":"M4-1-u3-X08"},{"t":"도윤 — 2 … 47","mis":"M4-1-u3-X10"}],"explanation":["(나누는 수) × (몫) + (나머지) = (나누어지는 수)여야 해요.","60 × 2 + 46 = 166이에요.","지유 — 나머지 46이 60보다 작고 확인 식도 맞아요."],"asset":{"type":"expr_grid","rows":[["60 × 2","=","120"],["120 + 46","=",null]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L04_challenge#5','math',4,1,'u3','L04','g4_1_math_u3_L04_challenge','lesson_challenge','M4-1-u3-C5',3,'mc','auto','책 186쪽을 하루에 40쪽씩 읽으려고 해요. 책을 다 읽으려면 적어도 며칠이 걸리나요?',ARRAY['M4-1-u3-X13','M4-1-u3-X14','M4-1-u3-X15']::text[],true,'{"seq":5,"concept":"M4-1-u3-C5","difficulty":3,"kind":"mc","stem":"책 186쪽을 하루에 40쪽씩 읽으려고 해요. 책을 다 읽으려면 적어도 며칠이 걸리나요?","options":[{"t":"5일","correct":true},{"t":"4일","mis":"M4-1-u3-X13"},{"t":"26일","mis":"M4-1-u3-X14"},{"t":"30일","mis":"M4-1-u3-X15"}],"explanation":["186 ÷ 40 = 4 … 26.","남은 26도 읽어야 하니 하나 더 — 4 + 1 = 5.","답은 5일이에요."],"variant_rule":{"alt":[{"stem":"책 358쪽을 하루에 40쪽씩 읽으려고 해요. 책을 다 읽으려면 적어도 며칠이 걸리나요?","options":[{"t":"9일","correct":true},{"t":"8일","mis":"M4-1-u3-X13"},{"t":"38일","mis":"M4-1-u3-X14"},{"t":"46일","mis":"M4-1-u3-X15"}],"explanation":["358 ÷ 40 = 8 … 38.","남은 38도 읽어야 하니 하나 더 — 8 + 1 = 9.","답은 9일이에요."],"asset":null},{"stem":"학생 145명이 한 대에 30명씩 타는 버스를 타려고 해요. 모두 타려면 버스는 적어도 몇 대 필요한가요?","options":[{"t":"5대","correct":true},{"t":"4대","mis":"M4-1-u3-X13"},{"t":"25대","mis":"M4-1-u3-X14"},{"t":"29대","mis":"M4-1-u3-X15"}],"explanation":["145 ÷ 30 = 4 … 25.","남은 25도 태워야 하니 하나 더 — 4 + 1 = 5.","답은 5대예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L04_challenge#6','math',4,1,'u3','L04','g4_1_math_u3_L04_challenge','lesson_challenge','M4-1-u3-C5',3,'error','auto','친구들이 나눗셈을 했어요. 잘못 계산한 친구는 누구인가요?',ARRAY['M4-1-u3-X09','M4-1-u3-X14']::text[],true,'{"seq":6,"concept":"M4-1-u3-C5","difficulty":3,"kind":"error","stem":"친구들이 나눗셈을 했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"건우 — 271 ÷ 30 = 9 … 0","correct":true,"mis_target":"M4-1-u3-X09"},{"t":"은우 — 373 ÷ 80 = 4 … 53","mis":"M4-1-u3-X14"},{"t":"하린 — 507 ÷ 60 = 8 … 27","mis":"M4-1-u3-X14"}],"explanation":["271 ÷ 30 — 30 × 9 = 270.","271 − 270 = 1이에요 — 나머지예요.","건우가 0을 지우고 27 ÷ 3을 계산해 나머지를 0으로 썼어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 친구들이 나눗셈을 했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"시아 — 608 ÷ 80 = 7 … 4","correct":true,"mis_target":"M4-1-u3-X09"},{"t":"서준 — 239 ÷ 90 = 2 … 59","mis":"M4-1-u3-X14"},{"t":"하린 — 283 ÷ 40 = 7 … 3","mis":"M4-1-u3-X14"}],"explanation":["608 ÷ 80 — 80 × 7 = 560.","608 − 560 = 48이에요 — 나머지예요.","시아가 0을 지우고 60 ÷ 8을 계산해 나머지를 4로 썼어요."],"asset":null},{"stem":"이번에는 다른 수예요. 친구들이 나눗셈을 했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"은우 — 284 ÷ 70 = 4 … 0","correct":true,"mis_target":"M4-1-u3-X09"},{"t":"서준 — 129 ÷ 50 = 2 … 29","mis":"M4-1-u3-X14"},{"t":"하린 — 411 ÷ 80 = 5 … 11","mis":"M4-1-u3-X14"}],"explanation":["284 ÷ 70 — 70 × 4 = 280.","284 − 280 = 4예요 — 나머지예요.","은우가 0을 지우고 28 ÷ 7을 계산해 나머지를 0으로 썼어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L04_challenge#7','math',4,1,'u3','L04','g4_1_math_u3_L04_challenge','lesson_challenge','M4-1-u3-C6',3,'sa','auto','4□7 ÷ 50 = 9 … 37에서 □ 안에 알맞은 숫자를 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M4-1-u3-C6","difficulty":3,"kind":"sa","stem":"4□7 ÷ 50 = 9 … 37에서 □ 안에 알맞은 숫자를 쓰세요.","answer":["8"],"explanation":["나누어지는 수 = 50 × 9 + 37.","450 + 37 = 487이에요.","□ = 8이에요."],"asset":{"type":"expr_grid","rows":[["50 × 9","=","450"],["450 + 37","=",null]]},"variant_rule":{"alt":[{"stem":"1□2 ÷ 20 = 6 … 2에서 □ 안에 알맞은 숫자를 쓰세요.","answer":["2"],"explanation":["나누어지는 수 = 20 × 6 + 2.","120 + 2 = 122예요.","□ = 2예요."],"asset":{"type":"expr_grid","rows":[["20 × 6","=","120"],["120 + 2","=",null]]}},{"stem":"3□6 ÷ 60 = 5 … 46에서 □ 안에 알맞은 숫자를 쓰세요.","answer":["4"],"explanation":["나누어지는 수 = 60 × 5 + 46.","300 + 46 = 346이에요.","□ = 4예요."],"asset":{"type":"expr_grid","rows":[["60 × 5","=","300"],["300 + 46","=",null]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L04_challenge#8','math',4,1,'u3','L04','g4_1_math_u3_L04_challenge','lesson_challenge','M4-1-u3-C5',4,'essay','teacher','방울토마토 467 kg을 한 상자에 70 kg씩 담아요. 가득 채운 상자는 몇 개이고 몇 kg이 남는지 구하고, 바르게 계산했는지 확인하는 방법을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M4-1-u3-C5","difficulty":4,"kind":"essay","stem":"방울토마토 467 kg을 한 상자에 70 kg씩 담아요. 가득 채운 상자는 몇 개이고 몇 kg이 남는지 구하고, 바르게 계산했는지 확인하는 방법을 설명해 보세요.","answer_guide":{"answer":"예: 70 × 6 = 420, 70 × 7 = 490이므로 467을 넘지 않는 가장 큰 곱은 420이다. 467 − 420 = 47이므로 상자 6개를 채우고 47 kg이 남는다. 70 × 6 + 47 = 467이 되므로 바르게 계산했다.","scoring_points":["몫 6을 구했는가","나머지 47을 구하고 70보다 작음을 확인했는가","70 × 6 + 47 = 467로 확인했는가"]},"explanation":["70 × 6 = 420 ≤ 467 < 490.","467 − 420 = 47.","70 × 6 + 47 = 467."],"asset":{"type":"ldiv","a":467,"b":70,"upto":0}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L04_challenge#9','math',4,1,'u3','L04','g4_1_math_u3_L04_challenge','lesson_challenge','M4-1-u3-C6',4,'sa','auto','□17 ÷ 80 = 7 … 57에서 □ 안에 알맞은 숫자를 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-1-u3-C6","difficulty":4,"kind":"sa","stem":"□17 ÷ 80 = 7 … 57에서 □ 안에 알맞은 숫자를 쓰세요.","answer":["6"],"explanation":["나누어지는 수 = 80 × 7 + 57.","560 + 57 = 617이에요.","□ = 6이에요."],"asset":{"type":"expr_grid","rows":[["80 × 7","=","560"],["560 + 57","=",null]]},"variant_rule":{"alt":[{"stem":"□37 ÷ 20 = 6 … 17에서 □ 안에 알맞은 숫자를 쓰세요.","answer":["1"],"explanation":["나누어지는 수 = 20 × 6 + 17.","120 + 17 = 137이에요.","□ = 1이에요."],"asset":{"type":"expr_grid","rows":[["20 × 6","=","120"],["120 + 17","=",null]]}},{"stem":"3□2 ÷ 90 = 3 … 82에서 □ 안에 알맞은 숫자를 쓰세요.","answer":["5"],"explanation":["나누어지는 수 = 90 × 3 + 82.","270 + 82 = 352예요.","□ = 5예요."],"asset":{"type":"expr_grid","rows":[["90 × 3","=","270"],["270 + 82","=",null]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L04_challenge#10','math',4,1,'u3','L04','g4_1_math_u3_L04_challenge','lesson_challenge','M4-1-u3-C5',4,'mc','auto','달걀 163개를 한 판에 40개씩 담으려고 해요. 가득 채운 판은 몇 판인가요?',ARRAY['M4-1-u3-X13','M4-1-u3-X14','M4-1-u3-X15']::text[],true,'{"seq":10,"concept":"M4-1-u3-C5","difficulty":4,"kind":"mc","stem":"달걀 163개를 한 판에 40개씩 담으려고 해요. 가득 채운 판은 몇 판인가요?","options":[{"t":"4판","correct":true},{"t":"5판","mis":"M4-1-u3-X13"},{"t":"3판","mis":"M4-1-u3-X14"},{"t":"7판","mis":"M4-1-u3-X15"}],"explanation":["163 ÷ 40 = 4 … 3.","남은 3은 하나를 다 채우지 못해요.","답은 4판이에요."],"variant_rule":{"alt":[{"stem":"리본 499 cm로 70 cm짜리 머리끈을 만들려고 해요. 머리끈을 몇 개까지 만들 수 있나요?","options":[{"t":"7개","correct":true},{"t":"8개","mis":"M4-1-u3-X13"},{"t":"9개","mis":"M4-1-u3-X14"},{"t":"16개","mis":"M4-1-u3-X15"}],"explanation":["499 ÷ 70 = 7 … 9.","남은 9는 하나를 다 채우지 못해요.","답은 7개예요."],"asset":null},{"stem":"달걀 606개를 한 판에 90개씩 담으려고 해요. 가득 채운 판은 몇 판인가요?","options":[{"t":"6판","correct":true},{"t":"7판","mis":"M4-1-u3-X13"},{"t":"66판","mis":"M4-1-u3-X14"},{"t":"72판","mis":"M4-1-u3-X15"}],"explanation":["606 ÷ 90 = 6 … 66.","남은 66은 하나를 다 채우지 못해요.","답은 6판이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L05_basic#1','math',4,1,'u3','L05','g4_1_math_u3_L05_basic','lesson_basic','M4-1-u3-C7',1,'sa','auto','76 ÷ 19의 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-1-u3-C7","difficulty":1,"kind":"sa","stem":"76 ÷ 19의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["19 × 4 = 76, 19 × 5 = 95 — 76을 넘지 않으면서 가장 가까운 곱을 찾아요.","19 × 4 = 76 — 남는 것이 없어요.","76 ÷ 19 = 4예요."],"asset":{"type":"ldiv","a":76,"b":19,"upto":0},"variant_rule":{"alt":[{"stem":"52 ÷ 26의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["26 × 2 = 52, 26 × 3 = 78 — 52를 넘지 않으면서 가장 가까운 곱을 찾아요.","26 × 2 = 52 — 남는 것이 없어요.","52 ÷ 26 = 2예요."],"asset":{"type":"ldiv","a":52,"b":26,"upto":0}},{"stem":"76 ÷ 38의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["38 × 2 = 76, 38 × 3 = 114 — 76을 넘지 않으면서 가장 가까운 곱을 찾아요.","38 × 2 = 76 — 남는 것이 없어요.","76 ÷ 38 = 2예요."],"asset":{"type":"ldiv","a":76,"b":38,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L05_basic#2','math',4,1,'u3','L05','g4_1_math_u3_L05_basic','lesson_basic','M4-1-u3-C7',1,'sa','auto','57 ÷ 19의 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-1-u3-C7","difficulty":1,"kind":"sa","stem":"57 ÷ 19의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["19 × 3 = 57, 19 × 4 = 76 — 57을 넘지 않으면서 가장 가까운 곱을 찾아요.","19 × 3 = 57 — 남는 것이 없어요.","57 ÷ 19 = 3이에요."],"asset":{"type":"ldiv","a":57,"b":19,"upto":0},"variant_rule":{"alt":[{"stem":"69 ÷ 23의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["23 × 3 = 69, 23 × 4 = 92 — 69를 넘지 않으면서 가장 가까운 곱을 찾아요.","23 × 3 = 69 — 남는 것이 없어요.","69 ÷ 23 = 3이에요."],"asset":{"type":"ldiv","a":69,"b":23,"upto":0}},{"stem":"84 ÷ 28의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["28 × 3 = 84, 28 × 4 = 112 — 84를 넘지 않으면서 가장 가까운 곱을 찾아요.","28 × 3 = 84 — 남는 것이 없어요.","84 ÷ 28 = 3이에요."],"asset":{"type":"ldiv","a":84,"b":28,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L05_basic#3','math',4,1,'u3','L05','g4_1_math_u3_L05_basic','lesson_basic','M4-1-u3-C7',1,'mc','auto','몫을 6으로 어림했는데 곱한 값이 나누어지는 수보다 컸어요. 어떻게 해야 하나요?',ARRAY['M4-1-u3-X08','M4-1-u3-X15']::text[],true,'{"seq":3,"concept":"M4-1-u3-C7","difficulty":1,"kind":"mc","stem":"몫을 6으로 어림했는데 곱한 값이 나누어지는 수보다 컸어요. 어떻게 해야 하나요?","options":[{"t":"몫을 1 작게 해서 다시 곱해 봐요","correct":true},{"t":"몫을 1 크게 해서 다시 곱해 봐요","mis":"M4-1-u3-X08"},{"t":"나누는 수를 1 작게 바꿔요","mis":"M4-1-u3-X15"},{"t":"그냥 그 몫으로 두어요","mis":"M4-1-u3-X08"}],"explanation":["어림한 몫은 예상일 뿐이에요.","곱이 크면 몫을 1 작게, 남은 수가 나누는 수보다 크거나 같으면 1 크게.","곱해서 확인하며 알맞은 몫을 찾아요."],"variant_rule":{"alt":[{"stem":"몫을 5로 어림해 빼 보니 남은 수가 나누는 수보다 컸어요. 어떻게 해야 하나요?","options":[{"t":"몫을 1 크게 해서 다시 곱해 봐요","correct":true},{"t":"몫을 1 작게 해서 다시 곱해 봐요","mis":"M4-1-u3-X07"},{"t":"남은 수를 나머지로 그대로 써요","mis":"M4-1-u3-X07"},{"t":"나누어지는 수를 바꾸어요","mis":"M4-1-u3-X15"}],"explanation":["어림한 몫은 예상일 뿐이에요.","곱이 크면 몫을 1 작게, 남은 수가 나누는 수보다 크거나 같으면 1 크게.","곱해서 확인하며 알맞은 몫을 찾아요."],"asset":null},{"stem":"어림한 몫으로 곱해 보았더니 맞지 않아 여러 번 고쳤어요. 이것은 어떤가요?","options":[{"t":"여러 번 곱해 보는 것은 몫을 찾아가는 방법이에요","correct":true},{"t":"한 번에 맞히지 못하면 틀린 풀이예요","mis":"M4-1-u3-X17"},{"t":"어림은 하지 않는 것이 좋아요","mis":"M4-1-u3-X17"},{"t":"처음 어림한 몫을 그대로 써야 해요","mis":"M4-1-u3-X08"}],"explanation":["어림한 몫은 예상일 뿐이에요.","곱이 크면 몫을 1 작게, 남은 수가 나누는 수보다 크거나 같으면 1 크게.","곱해서 확인하며 알맞은 몫을 찾아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L05_basic#4','math',4,1,'u3','L05','g4_1_math_u3_L05_basic','lesson_basic','M4-1-u3-C7',1,'sa','auto','98 ÷ 15에서 15는 약 20, 98은 약 100으로 어림하면 몫은 얼마쯤일까요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-1-u3-C7","difficulty":1,"kind":"sa","stem":"98 ÷ 15에서 15는 약 20, 98은 약 100으로 어림하면 몫은 얼마쯤일까요? 숫자로 쓰세요.","answer":["5"],"explanation":["100 ÷ 20으로 어림해요.","20 × 5 = 100이에요.","몫은 5쯤 — 실제 몫은 곱해서 확인해요(98 ÷ 15의 몫은 6)."],"variant_rule":{"alt":[{"stem":"87 ÷ 29에서 29는 약 30, 87은 약 90으로 어림하면 몫은 얼마쯤일까요? 숫자로 쓰세요.","answer":["3"],"explanation":["90 ÷ 30으로 어림해요.","30 × 3 = 90이에요.","몫은 3쯤 — 실제 몫은 곱해서 확인해요(87 ÷ 29의 몫은 3)."],"asset":null},{"stem":"61 ÷ 26에서 26은 약 30, 61은 약 60으로 어림하면 몫은 얼마쯤일까요? 숫자로 쓰세요.","answer":["2"],"explanation":["60 ÷ 30으로 어림해요.","30 × 2 = 60이에요.","몫은 2쯤 — 실제 몫은 곱해서 확인해요(61 ÷ 26의 몫은 2)."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L05_basic#5','math',4,1,'u3','L05','g4_1_math_u3_L05_basic','lesson_basic','M4-1-u3-C7',2,'sa','auto','76 ÷ 27의 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-1-u3-C7","difficulty":2,"kind":"sa","stem":"76 ÷ 27의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["27 × 2 = 54, 27 × 3 = 81 — 76을 넘지 않으면서 가장 가까운 곱을 찾아요.","76 − 54 = 22 — 22는 27보다 작아요.","76 ÷ 27 = 2 … 22예요."],"asset":{"type":"ldiv","a":76,"b":27,"upto":0},"variant_rule":{"alt":[{"stem":"44 ÷ 19의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["19 × 2 = 38, 19 × 3 = 57 — 44를 넘지 않으면서 가장 가까운 곱을 찾아요.","44 − 38 = 6 — 6은 19보다 작아요.","44 ÷ 19 = 2 … 6이에요."],"asset":{"type":"ldiv","a":44,"b":19,"upto":0}},{"stem":"61 ÷ 19의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["19 × 3 = 57, 19 × 4 = 76 — 61을 넘지 않으면서 가장 가까운 곱을 찾아요.","61 − 57 = 4 — 4는 19보다 작아요.","61 ÷ 19 = 3 … 4예요."],"asset":{"type":"ldiv","a":61,"b":19,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L05_basic#6','math',4,1,'u3','L05','g4_1_math_u3_L05_basic','lesson_basic','M4-1-u3-C7',2,'mc','auto','86 ÷ 32를 계산하여 몫과 나머지를 바르게 구한 것은 어느 것인가요?',ARRAY['M4-1-u3-X07','M4-1-u3-X08','M4-1-u3-X14']::text[],true,'{"seq":6,"concept":"M4-1-u3-C7","difficulty":2,"kind":"mc","stem":"86 ÷ 32를 계산하여 몫과 나머지를 바르게 구한 것은 어느 것인가요?","options":[{"t":"몫 2, 나머지 22","correct":true},{"t":"몫 1, 나머지 54","mis":"M4-1-u3-X07"},{"t":"몫 3, 나머지 없음","mis":"M4-1-u3-X08"},{"t":"몫 22, 나머지 2","mis":"M4-1-u3-X14"}],"explanation":["32 × 2 = 64, 32 × 3 = 96 — 86을 넘지 않으면서 가장 가까운 곱을 찾아요.","86 − 64 = 22 — 22는 32보다 작아요.","86 ÷ 32 = 2 … 22예요."],"asset":{"type":"ldiv","a":86,"b":32,"upto":0},"variant_rule":{"alt":[{"stem":"79 ÷ 28을 계산하여 몫과 나머지를 바르게 구한 것은 어느 것인가요?","options":[{"t":"몫 2, 나머지 23","correct":true},{"t":"몫 1, 나머지 51","mis":"M4-1-u3-X07"},{"t":"몫 3, 나머지 없음","mis":"M4-1-u3-X08"},{"t":"몫 23, 나머지 2","mis":"M4-1-u3-X14"}],"explanation":["28 × 2 = 56, 28 × 3 = 84 — 79를 넘지 않으면서 가장 가까운 곱을 찾아요.","79 − 56 = 23 — 23은 28보다 작아요.","79 ÷ 28 = 2 … 23이에요."],"asset":{"type":"ldiv","a":79,"b":28,"upto":0}},{"stem":"54 ÷ 11을 계산하여 몫과 나머지를 바르게 구한 것은 어느 것인가요?","options":[{"t":"몫 4, 나머지 10","correct":true},{"t":"몫 3, 나머지 21","mis":"M4-1-u3-X07"},{"t":"몫 5, 나머지 없음","mis":"M4-1-u3-X08"},{"t":"몫 10, 나머지 4","mis":"M4-1-u3-X14"}],"explanation":["11 × 4 = 44, 11 × 5 = 55 — 54를 넘지 않으면서 가장 가까운 곱을 찾아요.","54 − 44 = 10 — 10은 11보다 작아요.","54 ÷ 11 = 4 … 10이에요."],"asset":{"type":"ldiv","a":54,"b":11,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L05_basic#7','math',4,1,'u3','L05','g4_1_math_u3_L05_basic','lesson_basic','M4-1-u3-C7',2,'sa','auto','64 ÷ 21의 몫을 4로 어림했더니 21 × 4 = 84가 64보다 커요. 알맞은 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M4-1-u3-C7","difficulty":2,"kind":"sa","stem":"64 ÷ 21의 몫을 4로 어림했더니 21 × 4 = 84가 64보다 커요. 알맞은 몫은 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["곱 84가 64보다 커서 4는 너무 큰 몫이에요.","몫을 1 작게: 21 × 3 = 63.","알맞은 몫은 3이에요."],"variant_rule":{"alt":[{"stem":"68 ÷ 15의 몫을 5로 어림했더니 15 × 5 = 75가 68보다 커요. 알맞은 몫은 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["곱 75가 68보다 커서 5는 너무 큰 몫이에요.","몫을 1 작게: 15 × 4 = 60.","알맞은 몫은 4예요."],"asset":null},{"stem":"85 ÷ 13의 몫을 7로 어림했더니 13 × 7 = 91이 85보다 커요. 알맞은 몫은 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["곱 91이 85보다 커서 7은 너무 큰 몫이에요.","몫을 1 작게: 13 × 6 = 78.","알맞은 몫은 6이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L05_basic#8','math',4,1,'u3','L05','g4_1_math_u3_L05_basic','lesson_basic','M4-1-u3-C7',2,'sa','auto','64 ÷ 13의 세로셈이에요. ?에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M4-1-u3-C7","difficulty":2,"kind":"sa","stem":"64 ÷ 13의 세로셈이에요. ?에 알맞은 수를 쓰세요.","answer":["4"],"explanation":["?는 몫의 일의 자리예요.","13 × 4 = 52, 13 × 5 = 65 — 64를 넘지 않으면서 가장 가까운 곱을 찾아요.","?는 4예요."],"asset":{"type":"ldiv","a":64,"b":13,"hide":[["q",1]]},"variant_rule":{"alt":[{"stem":"42 ÷ 16의 세로셈이에요. ?에 알맞은 수를 쓰세요.","answer":["10"],"explanation":["?는 나머지예요.","16 × 2 = 32, 16 × 3 = 48 — 42를 넘지 않으면서 가장 가까운 곱을 찾아요.","?는 10이에요."],"asset":{"type":"ldiv","a":42,"b":16,"hide":["rem"]}},{"stem":"75 ÷ 27의 세로셈이에요. ?에 알맞은 수를 쓰세요.","answer":["54"],"explanation":["?는 나누는 수와 몫을 곱한 값이에요.","27 × 2 = 54, 27 × 3 = 81 — 75를 넘지 않으면서 가장 가까운 곱을 찾아요.","?는 54예요."],"asset":{"type":"ldiv","a":75,"b":27,"hide":[["r",0]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L05_basic#9','math',4,1,'u3','L05','g4_1_math_u3_L05_basic','lesson_basic','M4-1-u3-C7',2,'sa','auto','69 ÷ 17의 나머지는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-1-u3-C7","difficulty":2,"kind":"sa","stem":"69 ÷ 17의 나머지는 얼마인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["17 × 4 = 68, 17 × 5 = 85 — 69를 넘지 않으면서 가장 가까운 곱을 찾아요.","69 − 68 = 1 — 1은 17보다 작아요.","69 ÷ 17 = 4 … 1이에요."],"asset":{"type":"ldiv","a":69,"b":17,"upto":0},"variant_rule":{"alt":[{"stem":"54 ÷ 12의 나머지는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["12 × 4 = 48, 12 × 5 = 60 — 54를 넘지 않으면서 가장 가까운 곱을 찾아요.","54 − 48 = 6 — 6은 12보다 작아요.","54 ÷ 12 = 4 … 6이에요."],"asset":{"type":"ldiv","a":54,"b":12,"upto":0}},{"stem":"66 ÷ 19의 나머지는 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["19 × 3 = 57, 19 × 4 = 76 — 66을 넘지 않으면서 가장 가까운 곱을 찾아요.","66 − 57 = 9 — 9는 19보다 작아요.","66 ÷ 19 = 3 … 9예요."],"asset":{"type":"ldiv","a":66,"b":19,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L05_basic#10','math',4,1,'u3','L05','g4_1_math_u3_L05_basic','lesson_basic','M4-1-u3-C7',3,'error','auto','지유가 58 ÷ 12 = 3 … 22라고 계산했어요. 무엇이 잘못됐나요?',ARRAY['M4-1-u3-X07','M4-1-u3-X08']::text[],true,'{"seq":10,"concept":"M4-1-u3-C7","difficulty":3,"kind":"error","stem":"지유가 58 ÷ 12 = 3 … 22라고 계산했어요. 무엇이 잘못됐나요?","options":[{"t":"남은 22가 12보다 커요 — 몫을 1 크게 해야 해요","correct":true,"mis_target":"M4-1-u3-X07"},{"t":"남은 22가 12보다 커요 — 몫을 1 작게 해야 해요","mis":"M4-1-u3-X08"},{"t":"나머지는 나누는 수보다 커도 괜찮아요","mis":"M4-1-u3-X07"}],"explanation":["12 × 3 = 36, 58 − 36 = 22.","남은 수가 나누는 수보다 작아야 해요.","바르게: 58 ÷ 12 = 4 … 10이에요."],"variant_rule":{"alt":[{"stem":"시아가 69 ÷ 12 = 4 … 21이라고 계산했어요. 무엇이 잘못됐나요?","options":[{"t":"남은 21이 12보다 커요 — 몫을 1 크게 해야 해요","correct":true,"mis_target":"M4-1-u3-X07"},{"t":"남은 21이 12보다 커요 — 몫을 1 작게 해야 해요","mis":"M4-1-u3-X08"},{"t":"나머지는 나누는 수보다 커도 괜찮아요","mis":"M4-1-u3-X07"}],"explanation":["12 × 4 = 48, 69 − 48 = 21.","남은 수가 나누는 수보다 작아야 해요.","바르게: 69 ÷ 12 = 5 … 9예요."],"asset":null},{"stem":"도윤이 71 ÷ 16 = 3 … 23이라고 계산했어요. 무엇이 잘못됐나요?","options":[{"t":"남은 23이 16보다 커요 — 몫을 1 크게 해야 해요","correct":true,"mis_target":"M4-1-u3-X07"},{"t":"남은 23이 16보다 커요 — 몫을 1 작게 해야 해요","mis":"M4-1-u3-X08"},{"t":"나머지는 나누는 수보다 커도 괜찮아요","mis":"M4-1-u3-X07"}],"explanation":["16 × 3 = 48, 71 − 48 = 23.","남은 수가 나누는 수보다 작아야 해요.","바르게: 71 ÷ 16 = 4 … 7이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L05_challenge#1','math',4,1,'u3','L05','g4_1_math_u3_L05_challenge','lesson_challenge','M4-1-u3-C7',2,'sa','auto','달걀 75개를 한 판에 35개씩 담으려고 해요. 가득 채운 판은 몇 판인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-1-u3-C7","difficulty":2,"kind":"sa","stem":"달걀 75개를 한 판에 35개씩 담으려고 해요. 가득 채운 판은 몇 판인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["75 ÷ 35를 계산해요.","75 − 70 = 5 — 5는 35보다 작아요.","몫 2 — 2판이에요."],"variant_rule":{"alt":[{"stem":"달걀 91개를 한 판에 39개씩 담으려고 해요. 가득 채운 판은 몇 판인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["91 ÷ 39를 계산해요.","91 − 78 = 13 — 13은 39보다 작아요.","몫 2 — 2판이에요."],"asset":null},{"stem":"색종이 80장을 32장씩 묶으려고 해요. 몇 묶음이 되나요? 숫자로 쓰세요.","answer":["2"],"explanation":["80 ÷ 32를 계산해요.","80 − 64 = 16 — 16은 32보다 작아요.","몫 2 — 2묶음이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L05_challenge#2','math',4,1,'u3','L05','g4_1_math_u3_L05_challenge','lesson_challenge','M4-1-u3-C7',2,'sa','auto','71 ÷ 11의 몫을 5로 어림해 11 × 5 = 55를 빼니 16이 남았어요. 알맞은 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-1-u3-C7","difficulty":2,"kind":"sa","stem":"71 ÷ 11의 몫을 5로 어림해 11 × 5 = 55를 빼니 16이 남았어요. 알맞은 몫은 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["남은 16이 나누는 수 11보다 커요.","한 번 더 나눌 수 있으니 몫을 1 크게: 6.","알맞은 몫은 6이에요."],"variant_rule":{"alt":[{"stem":"56 ÷ 13의 몫을 3으로 어림해 13 × 3 = 39를 빼니 17이 남았어요. 알맞은 몫은 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["남은 17이 나누는 수 13보다 커요.","한 번 더 나눌 수 있으니 몫을 1 크게: 4.","알맞은 몫은 4예요."],"asset":null},{"stem":"89 ÷ 12의 몫을 6으로 어림해 12 × 6 = 72를 빼니 17이 남았어요. 알맞은 몫은 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["남은 17이 나누는 수 12보다 커요.","한 번 더 나눌 수 있으니 몫을 1 크게: 7.","알맞은 몫은 7이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L05_challenge#3','math',4,1,'u3','L05','g4_1_math_u3_L05_challenge','lesson_challenge','M4-1-u3-C7',3,'error','auto','시아가 77 ÷ 12의 몫을 7로 정하고 다음 계산을 이어 가려고 해요. 무엇이 잘못됐나요?',ARRAY['M4-1-u3-X08','M4-1-u3-X07','M4-1-u3-X15']::text[],true,'{"seq":3,"concept":"M4-1-u3-C7","difficulty":3,"kind":"error","stem":"시아가 77 ÷ 12의 몫을 7로 정하고 다음 계산을 이어 가려고 해요. 무엇이 잘못됐나요?","options":[{"t":"12 × 7 = 84가 77보다 커요 — 몫을 1 작게 해야 해요","correct":true,"mis_target":"M4-1-u3-X08"},{"t":"12 × 7 = 84가 77보다 커요 — 몫을 1 크게 해야 해요","mis":"M4-1-u3-X07"},{"t":"곱이 크면 나누어지는 수를 바꾸어야 해요","mis":"M4-1-u3-X15"}],"explanation":["12 × 7 = 84.","84는 77보다 커서 뺄 수 없어요.","바르게: 77 ÷ 12 = 6 … 5예요."],"variant_rule":{"alt":[{"stem":"건우가 98 ÷ 24의 몫을 5로 정하고 다음 계산을 이어 가려고 해요. 무엇이 잘못됐나요?","options":[{"t":"24 × 5 = 120이 98보다 커요 — 몫을 1 작게 해야 해요","correct":true,"mis_target":"M4-1-u3-X08"},{"t":"24 × 5 = 120이 98보다 커요 — 몫을 1 크게 해야 해요","mis":"M4-1-u3-X07"},{"t":"곱이 크면 나누어지는 수를 바꾸어야 해요","mis":"M4-1-u3-X15"}],"explanation":["24 × 5 = 120.","120은 98보다 커서 뺄 수 없어요.","바르게: 98 ÷ 24 = 4 … 2예요."],"asset":null},{"stem":"시아가 80 ÷ 29의 몫을 3으로 정하고 다음 계산을 이어 가려고 해요. 무엇이 잘못됐나요?","options":[{"t":"29 × 3 = 87이 80보다 커요 — 몫을 1 작게 해야 해요","correct":true,"mis_target":"M4-1-u3-X08"},{"t":"29 × 3 = 87이 80보다 커요 — 몫을 1 크게 해야 해요","mis":"M4-1-u3-X07"},{"t":"곱이 크면 나누어지는 수를 바꾸어야 해요","mis":"M4-1-u3-X15"}],"explanation":["29 × 3 = 87.","87은 80보다 커서 뺄 수 없어요.","바르게: 80 ÷ 29 = 2 … 22예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L05_challenge#4','math',4,1,'u3','L05','g4_1_math_u3_L05_challenge','lesson_challenge','M4-1-u3-C7',3,'sa','auto','어떤 수를 16으로 나누었더니 몫이 3, 나머지가 8이 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-1-u3-C7","difficulty":3,"kind":"sa","stem":"어떤 수를 16으로 나누었더니 몫이 3, 나머지가 8이 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["56"],"explanation":["나누어지는 수 = (나누는 수) × (몫) + (나머지).","16 × 3 = 48.","48 + 8 = 56 — 어떤 수는 56이에요."],"asset":{"type":"expr_grid","rows":[["16 × 3","=","48"],["48 + 8","=",null]]},"variant_rule":{"alt":[{"stem":"어떤 수를 24로 나누었더니 몫이 3, 나머지가 22가 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["94"],"explanation":["나누어지는 수 = (나누는 수) × (몫) + (나머지).","24 × 3 = 72.","72 + 22 = 94 — 어떤 수는 94예요."],"asset":{"type":"expr_grid","rows":[["24 × 3","=","72"],["72 + 22","=",null]]}},{"stem":"어떤 수를 18로 나누었더니 몫이 4, 나머지가 11이 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["83"],"explanation":["나누어지는 수 = (나누는 수) × (몫) + (나머지).","18 × 4 = 72.","72 + 11 = 83 — 어떤 수는 83이에요."],"asset":{"type":"expr_grid","rows":[["18 × 4","=","72"],["72 + 11","=",null]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L05_challenge#5','math',4,1,'u3','L05','g4_1_math_u3_L05_challenge','lesson_challenge','M4-1-u3-C7',3,'sa','auto','어떤 수를 24로 나누었더니 몫이 3이었어요. 나머지가 될 수 있는 수 가운데 가장 큰 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-1-u3-C7","difficulty":3,"kind":"sa","stem":"어떤 수를 24로 나누었더니 몫이 3이었어요. 나머지가 될 수 있는 수 가운데 가장 큰 수는 얼마인가요? 숫자로 쓰세요.","answer":["23"],"explanation":["나머지는 나누는 수 24보다 작아야 해요.","24가 되면 한 번 더 나눌 수 있어요.","가장 큰 나머지는 23이에요."],"variant_rule":{"alt":[{"stem":"어떤 수를 13으로 나누었더니 몫이 2였어요. 나머지가 될 수 있는 수 가운데 가장 큰 수는 얼마인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["나머지는 나누는 수 13보다 작아야 해요.","13이 되면 한 번 더 나눌 수 있어요.","가장 큰 나머지는 12예요."],"asset":null},{"stem":"어떤 수를 24로 나누었더니 몫이 2였어요. 나머지가 될 수 있는 수 가운데 가장 큰 수는 얼마인가요? 숫자로 쓰세요.","answer":["23"],"explanation":["나머지는 나누는 수 24보다 작아야 해요.","24가 되면 한 번 더 나눌 수 있어요.","가장 큰 나머지는 23이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L05_challenge#6','math',4,1,'u3','L05','g4_1_math_u3_L05_challenge','lesson_challenge','M4-1-u3-C7',3,'mc','auto','몫의 크기를 비교하여 ○ 안에 알맞은 것을 고르세요. 88 ÷ 18 ○ 55 ÷ 26',ARRAY['M4-1-u3-X14','M4-1-u3-X12','M4-1-u3-X15']::text[],true,'{"seq":6,"concept":"M4-1-u3-C7","difficulty":3,"kind":"mc","stem":"몫의 크기를 비교하여 ○ 안에 알맞은 것을 고르세요. 88 ÷ 18 ○ 55 ÷ 26","options":[{"t":">","correct":true},{"t":"<","mis":"M4-1-u3-X14"},{"t":"=","mis":"M4-1-u3-X12"},{"t":"알 수 없어요","mis":"M4-1-u3-X15"}],"explanation":["88 ÷ 18의 몫은 4예요.","55 ÷ 26의 몫은 2예요.","4 > 2예요."],"variant_rule":{"alt":[{"stem":"몫의 크기를 비교하여 ○ 안에 알맞은 것을 고르세요. 84 ÷ 18 ○ 70 ÷ 19","options":[{"t":">","correct":true},{"t":"<","mis":"M4-1-u3-X14"},{"t":"=","mis":"M4-1-u3-X12"},{"t":"알 수 없어요","mis":"M4-1-u3-X15"}],"explanation":["84 ÷ 18의 몫은 4예요.","70 ÷ 19의 몫은 3이에요.","4 > 3이에요."],"asset":null},{"stem":"몫의 크기를 비교하여 ○ 안에 알맞은 것을 고르세요. 94 ÷ 12 ○ 76 ÷ 34","options":[{"t":">","correct":true},{"t":"<","mis":"M4-1-u3-X14"},{"t":"=","mis":"M4-1-u3-X12"},{"t":"알 수 없어요","mis":"M4-1-u3-X15"}],"explanation":["94 ÷ 12의 몫은 7이에요.","76 ÷ 34의 몫은 2예요.","7 > 2예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L05_challenge#7','math',4,1,'u3','L05','g4_1_math_u3_L05_challenge','lesson_challenge','M4-1-u3-C7',3,'mc','auto','책 99쪽을 하루에 48쪽씩 읽으려고 해요. 책을 다 읽으려면 적어도 며칠이 걸리나요?',ARRAY['M4-1-u3-X13','M4-1-u3-X15']::text[],true,'{"seq":7,"concept":"M4-1-u3-C7","difficulty":3,"kind":"mc","stem":"책 99쪽을 하루에 48쪽씩 읽으려고 해요. 책을 다 읽으려면 적어도 며칠이 걸리나요?","options":[{"t":"3일","correct":true},{"t":"2일","mis":"M4-1-u3-X13"},{"t":"5일","mis":"M4-1-u3-X15"},{"t":"51일","mis":"M4-1-u3-X15"}],"explanation":["99 ÷ 48 = 2 … 3.","남은 3도 읽어야 하니 하나 더 — 2 + 1 = 3.","답은 3일이에요."],"variant_rule":{"alt":[{"stem":"사과 53개를 한 상자에 19개씩 남김없이 모두 담으려고 해요. 상자는 적어도 몇 개 필요한가요?","options":[{"t":"3개","correct":true},{"t":"2개","mis":"M4-1-u3-X13"},{"t":"15개","mis":"M4-1-u3-X14"},{"t":"17개","mis":"M4-1-u3-X15"}],"explanation":["53 ÷ 19 = 2 … 15.","남은 15도 담아야 하니 하나 더 — 2 + 1 = 3.","답은 3개예요."],"asset":null},{"stem":"학생 58명이 한 대에 18명씩 타는 버스를 타려고 해요. 모두 타려면 버스는 적어도 몇 대 필요한가요?","options":[{"t":"4대","correct":true},{"t":"3대","mis":"M4-1-u3-X13"},{"t":"7대","mis":"M4-1-u3-X15"},{"t":"40대","mis":"M4-1-u3-X15"}],"explanation":["58 ÷ 18 = 3 … 4.","남은 4도 태워야 하니 하나 더 — 3 + 1 = 4.","답은 4대예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L05_challenge#8','math',4,1,'u3','L05','g4_1_math_u3_L05_challenge','lesson_challenge','M4-1-u3-C7',4,'essay','teacher','97 ÷ 23의 몫을 어림하고, 어림한 몫이 맞지 않을 때 어떻게 고쳐서 알맞은 몫을 찾는지 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M4-1-u3-C7","difficulty":4,"kind":"essay","stem":"97 ÷ 23의 몫을 어림하고, 어림한 몫이 맞지 않을 때 어떻게 고쳐서 알맞은 몫을 찾는지 설명해 보세요.","answer_guide":{"answer":"예: 23을 20으로, 97을 100으로 보면 몫은 5쯤이다. 23 × 5 = 115는 97보다 크므로 몫을 1 작게 하여 4로 한다. 23 × 4 = 92, 97 − 92 = 5이므로 97 ÷ 23 = 4 … 5이다.","scoring_points":["몫을 어림했는가","곱이 크면 몫을 1 작게 한다고 설명했는가","4 … 5를 구했는가"]},"explanation":["23 → 20, 97 → 100, 몫 5쯤.","23 × 5 = 115 > 97 → 4.","23 × 4 = 92, 나머지 5."],"asset":{"type":"ldiv","a":97,"b":23,"upto":0}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L05_challenge#9','math',4,1,'u3','L05','g4_1_math_u3_L05_challenge','lesson_challenge','M4-1-u3-C7',4,'sa','auto','□8 ÷ 15 = 6 … 8에서 □ 안에 알맞은 숫자를 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-1-u3-C7","difficulty":4,"kind":"sa","stem":"□8 ÷ 15 = 6 … 8에서 □ 안에 알맞은 숫자를 쓰세요.","answer":["9"],"explanation":["나누어지는 수 = 15 × 6 + 8.","90 + 8 = 98이에요.","□ = 9예요."],"asset":{"type":"expr_grid","rows":[["15 × 6","=","90"],["90 + 8","=",null]]},"variant_rule":{"alt":[{"stem":"6□ ÷ 28 = 2 … 6에서 □ 안에 알맞은 숫자를 쓰세요.","answer":["2"],"explanation":["나누어지는 수 = 28 × 2 + 6.","56 + 6 = 62예요.","□ = 2예요."],"asset":{"type":"expr_grid","rows":[["28 × 2","=","56"],["56 + 6","=",null]]}},{"stem":"8□ ÷ 37 = 2 … 14에서 □ 안에 알맞은 숫자를 쓰세요.","answer":["8"],"explanation":["나누어지는 수 = 37 × 2 + 14.","74 + 14 = 88이에요.","□ = 8이에요."],"asset":{"type":"expr_grid","rows":[["37 × 2","=","74"],["74 + 14","=",null]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L05_challenge#10','math',4,1,'u3','L05','g4_1_math_u3_L05_challenge','lesson_challenge','M4-1-u3-C7',4,'mc','auto','63 ÷ 12에서 하린이는 몫을 5, 은우는 6으로 어림했어요. 바르게 말한 것은 어느 것인가요?',ARRAY['M4-1-u3-X17','M4-1-u3-X08','M4-1-u3-X15']::text[],true,'{"seq":10,"concept":"M4-1-u3-C7","difficulty":4,"kind":"mc","stem":"63 ÷ 12에서 하린이는 몫을 5, 은우는 6으로 어림했어요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"둘 다 괜찮아요 — 곱해서 확인하면 몫은 5예요","correct":true},{"t":"어림한 몫이 다르니 둘 다 틀렸어요","mis":"M4-1-u3-X17"},{"t":"더 큰 6이 언제나 맞아요","mis":"M4-1-u3-X08"},{"t":"몫은 두 어림의 합 11이에요","mis":"M4-1-u3-X15"}],"explanation":["어림하는 방법은 여러 가지예요.","12 × 5 = 60, 12 × 6 = 72.","63을 넘지 않는 가장 큰 곱 — 몫 5예요."],"variant_rule":{"alt":[{"stem":"53 ÷ 18에서 하린이는 몫을 2, 은우는 3으로 어림했어요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"둘 다 괜찮아요 — 곱해서 확인하면 몫은 2예요","correct":true},{"t":"어림한 몫이 다르니 둘 다 틀렸어요","mis":"M4-1-u3-X17"},{"t":"더 큰 3이 언제나 맞아요","mis":"M4-1-u3-X08"},{"t":"몫은 두 어림의 합 5예요","mis":"M4-1-u3-X15"}],"explanation":["어림하는 방법은 여러 가지예요.","18 × 2 = 36, 18 × 3 = 54.","53을 넘지 않는 가장 큰 곱 — 몫 2예요."],"asset":null},{"stem":"99 ÷ 19에서 하린이는 몫을 5, 은우는 6으로 어림했어요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"둘 다 괜찮아요 — 곱해서 확인하면 몫은 5예요","correct":true},{"t":"어림한 몫이 다르니 둘 다 틀렸어요","mis":"M4-1-u3-X17"},{"t":"더 큰 6이 언제나 맞아요","mis":"M4-1-u3-X08"},{"t":"몫은 두 어림의 합 11이에요","mis":"M4-1-u3-X15"}],"explanation":["어림하는 방법은 여러 가지예요.","19 × 5 = 95, 19 × 6 = 114.","99를 넘지 않는 가장 큰 곱 — 몫 5예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L06_basic#1','math',4,1,'u3','L06','g4_1_math_u3_L06_basic','lesson_basic','M4-1-u3-C8',1,'sa','auto','255 ÷ 51의 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-1-u3-C8","difficulty":1,"kind":"sa","stem":"255 ÷ 51의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["51 × 5 = 255, 51 × 6 = 306 — 255를 넘지 않으면서 가장 가까운 곱을 찾아요.","51 × 5 = 255 — 남는 것이 없어요.","255 ÷ 51 = 5예요."],"asset":{"type":"ldiv","a":255,"b":51,"upto":0},"variant_rule":{"alt":[{"stem":"144 ÷ 72의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["72 × 2 = 144, 72 × 3 = 216 — 144를 넘지 않으면서 가장 가까운 곱을 찾아요.","72 × 2 = 144 — 남는 것이 없어요.","144 ÷ 72 = 2예요."],"asset":{"type":"ldiv","a":144,"b":72,"upto":0}},{"stem":"711 ÷ 79의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["79 × 9 = 711, 79 × 10 = 790 — 711을 넘지 않으면서 가장 가까운 곱을 찾아요.","79 × 9 = 711 — 남는 것이 없어요.","711 ÷ 79 = 9예요."],"asset":{"type":"ldiv","a":711,"b":79,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L06_basic#2','math',4,1,'u3','L06','g4_1_math_u3_L06_basic','lesson_basic','M4-1-u3-C8',1,'sa','auto','527 ÷ 69의 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-1-u3-C8","difficulty":1,"kind":"sa","stem":"527 ÷ 69의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["69 × 7 = 483, 69 × 8 = 552 — 527을 넘지 않으면서 가장 가까운 곱을 찾아요.","527 − 483 = 44 — 44는 69보다 작아요.","527 ÷ 69 = 7 … 44예요."],"asset":{"type":"ldiv","a":527,"b":69,"upto":0},"variant_rule":{"alt":[{"stem":"148 ÷ 36의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["36 × 4 = 144, 36 × 5 = 180 — 148을 넘지 않으면서 가장 가까운 곱을 찾아요.","148 − 144 = 4 — 4는 36보다 작아요.","148 ÷ 36 = 4 … 4예요."],"asset":{"type":"ldiv","a":148,"b":36,"upto":0}},{"stem":"509 ÷ 97의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["97 × 5 = 485, 97 × 6 = 582 — 509를 넘지 않으면서 가장 가까운 곱을 찾아요.","509 − 485 = 24 — 24는 97보다 작아요.","509 ÷ 97 = 5 … 24예요."],"asset":{"type":"ldiv","a":509,"b":97,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L06_basic#3','math',4,1,'u3','L06','g4_1_math_u3_L06_basic','lesson_basic','M4-1-u3-C8',1,'mc','auto','친구들이 어림한 몫이 서로 달랐어요. 어떻게 해야 하나요?',ARRAY['M4-1-u3-X17','M4-1-u3-X08']::text[],true,'{"seq":3,"concept":"M4-1-u3-C8","difficulty":1,"kind":"mc","stem":"친구들이 어림한 몫이 서로 달랐어요. 어떻게 해야 하나요?","options":[{"t":"어느 방법으로 어림했든 곱셈으로 확인해 알맞은 몫을 찾으면 돼요","correct":true},{"t":"어림한 몫이 다르면 둘 다 틀린 거예요","mis":"M4-1-u3-X17"},{"t":"언제나 더 큰 쪽으로 어림해야 해요","mis":"M4-1-u3-X08"},{"t":"어림은 하지 않는 것이 좋아요","mis":"M4-1-u3-X17"}],"explanation":["어림하는 방법은 여러 가지예요.","96 × 4 = 384, 96 × 5 = 480.","478을 넘지 않는 가장 큰 곱 — 몫 4예요."],"variant_rule":{"alt":[{"stem":"434 ÷ 63에서 하린이는 몫을 6, 은우는 7로 어림했어요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"둘 다 괜찮아요 — 곱해서 확인하면 몫은 6이에요","correct":true},{"t":"어림한 몫이 다르니 둘 다 틀렸어요","mis":"M4-1-u3-X17"},{"t":"더 큰 7이 언제나 맞아요","mis":"M4-1-u3-X08"},{"t":"몫은 두 어림의 합 13이에요","mis":"M4-1-u3-X15"}],"explanation":["어림하는 방법은 여러 가지예요.","63 × 6 = 378, 63 × 7 = 441.","434를 넘지 않는 가장 큰 곱 — 몫 6이에요."],"asset":null},{"stem":"437 ÷ 71에서 하린이는 몫을 6, 은우는 7로 어림했어요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"둘 다 괜찮아요 — 곱해서 확인하면 몫은 6이에요","correct":true},{"t":"어림한 몫이 다르니 둘 다 틀렸어요","mis":"M4-1-u3-X17"},{"t":"더 큰 7이 언제나 맞아요","mis":"M4-1-u3-X08"},{"t":"몫은 두 어림의 합 13이에요","mis":"M4-1-u3-X15"}],"explanation":["어림하는 방법은 여러 가지예요.","71 × 6 = 426, 71 × 7 = 497.","437을 넘지 않는 가장 큰 곱 — 몫 6이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L06_basic#4','math',4,1,'u3','L06','g4_1_math_u3_L06_basic','lesson_basic','M4-1-u3-C8',1,'mc','auto','891 ÷ 23의 몫은 몇 자리 수인가요?',ARRAY['M4-1-u3-X12','M4-1-u3-X14']::text[],true,'{"seq":4,"concept":"M4-1-u3-C8","difficulty":1,"kind":"mc","stem":"891 ÷ 23의 몫은 몇 자리 수인가요?","options":[{"t":"두 자리 수","correct":true},{"t":"한 자리 수","mis":"M4-1-u3-X12"},{"t":"세 자리 수","mis":"M4-1-u3-X12"},{"t":"몫이 없어요","mis":"M4-1-u3-X14"}],"explanation":["나누어지는 수의 앞 두 자리 89와 나누는 수 23을 견주어요.","89 ≥ 23 — 몫이 십의 자리부터 나와요.","몫 38 — 두 자리 수예요."],"variant_rule":{"alt":[{"stem":"945 ÷ 47의 몫은 몇 자리 수인가요?","options":[{"t":"두 자리 수","correct":true},{"t":"한 자리 수","mis":"M4-1-u3-X12"},{"t":"세 자리 수","mis":"M4-1-u3-X12"},{"t":"몫이 없어요","mis":"M4-1-u3-X14"}],"explanation":["나누어지는 수의 앞 두 자리 94와 나누는 수 47을 견주어요.","94 ≥ 47 — 몫이 십의 자리부터 나와요.","몫 20 — 두 자리 수예요."],"asset":null},{"stem":"593 ÷ 29의 몫은 몇 자리 수인가요?","options":[{"t":"두 자리 수","correct":true},{"t":"한 자리 수","mis":"M4-1-u3-X12"},{"t":"세 자리 수","mis":"M4-1-u3-X12"},{"t":"몫이 없어요","mis":"M4-1-u3-X14"}],"explanation":["나누어지는 수의 앞 두 자리 59와 나누는 수 29를 견주어요.","59 ≥ 29 — 몫이 십의 자리부터 나와요.","몫 20 — 두 자리 수예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L06_basic#5','math',4,1,'u3','L06','g4_1_math_u3_L06_basic','lesson_basic','M4-1-u3-C8',2,'sa','auto','287 ÷ 87의 나머지는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-1-u3-C8","difficulty":2,"kind":"sa","stem":"287 ÷ 87의 나머지는 얼마인가요? 숫자로 쓰세요.","answer":["26"],"explanation":["87 × 3 = 261, 87 × 4 = 348 — 287을 넘지 않으면서 가장 가까운 곱을 찾아요.","287 − 261 = 26 — 26은 87보다 작아요.","287 ÷ 87 = 3 … 26이에요."],"asset":{"type":"ldiv","a":287,"b":87,"upto":0},"variant_rule":{"alt":[{"stem":"118 ÷ 32의 나머지는 얼마인가요? 숫자로 쓰세요.","answer":["22"],"explanation":["32 × 3 = 96, 32 × 4 = 128 — 118을 넘지 않으면서 가장 가까운 곱을 찾아요.","118 − 96 = 22 — 22는 32보다 작아요.","118 ÷ 32 = 3 … 22예요."],"asset":{"type":"ldiv","a":118,"b":32,"upto":0}},{"stem":"139 ÷ 18의 나머지는 얼마인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["18 × 7 = 126, 18 × 8 = 144 — 139를 넘지 않으면서 가장 가까운 곱을 찾아요.","139 − 126 = 13 — 13은 18보다 작아요.","139 ÷ 18 = 7 … 13이에요."],"asset":{"type":"ldiv","a":139,"b":18,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L06_basic#6','math',4,1,'u3','L06','g4_1_math_u3_L06_basic','lesson_basic','M4-1-u3-C8',2,'mc','auto','248 ÷ 94를 계산하여 몫과 나머지를 바르게 구한 것은 어느 것인가요?',ARRAY['M4-1-u3-X07','M4-1-u3-X08','M4-1-u3-X14']::text[],true,'{"seq":6,"concept":"M4-1-u3-C8","difficulty":2,"kind":"mc","stem":"248 ÷ 94를 계산하여 몫과 나머지를 바르게 구한 것은 어느 것인가요?","options":[{"t":"몫 2, 나머지 60","correct":true},{"t":"몫 1, 나머지 154","mis":"M4-1-u3-X07"},{"t":"몫 3, 나머지 없음","mis":"M4-1-u3-X08"},{"t":"몫 60, 나머지 2","mis":"M4-1-u3-X14"}],"explanation":["94 × 2 = 188, 94 × 3 = 282 — 248을 넘지 않으면서 가장 가까운 곱을 찾아요.","248 − 188 = 60 — 60은 94보다 작아요.","248 ÷ 94 = 2 … 60이에요."],"asset":{"type":"ldiv","a":248,"b":94,"upto":0},"variant_rule":{"alt":[{"stem":"354 ÷ 58을 계산하여 몫과 나머지를 바르게 구한 것은 어느 것인가요?","options":[{"t":"몫 6, 나머지 6","correct":true},{"t":"몫 5, 나머지 64","mis":"M4-1-u3-X07"},{"t":"몫 7, 나머지 없음","mis":"M4-1-u3-X08"},{"t":"몫 6, 나머지 7","mis":"M4-1-u3-X14"}],"explanation":["58 × 6 = 348, 58 × 7 = 406 — 354를 넘지 않으면서 가장 가까운 곱을 찾아요.","354 − 348 = 6 — 6은 58보다 작아요.","354 ÷ 58 = 6 … 6이에요."],"asset":{"type":"ldiv","a":354,"b":58,"upto":0}},{"stem":"560 ÷ 87을 계산하여 몫과 나머지를 바르게 구한 것은 어느 것인가요?","options":[{"t":"몫 6, 나머지 38","correct":true},{"t":"몫 5, 나머지 125","mis":"M4-1-u3-X07"},{"t":"몫 7, 나머지 없음","mis":"M4-1-u3-X08"},{"t":"몫 38, 나머지 6","mis":"M4-1-u3-X14"}],"explanation":["87 × 6 = 522, 87 × 7 = 609 — 560을 넘지 않으면서 가장 가까운 곱을 찾아요.","560 − 522 = 38 — 38은 87보다 작아요.","560 ÷ 87 = 6 … 38이에요."],"asset":{"type":"ldiv","a":560,"b":87,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L06_basic#7','math',4,1,'u3','L06','g4_1_math_u3_L06_basic','lesson_basic','M4-1-u3-C8',2,'sa','auto','178 ÷ 25의 몫을 8로 어림했더니 25 × 8 = 200이 178보다 커요. 알맞은 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M4-1-u3-C8","difficulty":2,"kind":"sa","stem":"178 ÷ 25의 몫을 8로 어림했더니 25 × 8 = 200이 178보다 커요. 알맞은 몫은 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["곱 200이 178보다 커서 8은 너무 큰 몫이에요.","몫을 1 작게: 25 × 7 = 175.","알맞은 몫은 7이에요."],"variant_rule":{"alt":[{"stem":"453 ÷ 68의 몫을 7로 어림했더니 68 × 7 = 476이 453보다 커요. 알맞은 몫은 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["곱 476이 453보다 커서 7은 너무 큰 몫이에요.","몫을 1 작게: 68 × 6 = 408.","알맞은 몫은 6이에요."],"asset":null},{"stem":"157 ÷ 41의 몫을 2로 어림해 41 × 2 = 82를 빼니 75가 남았어요. 알맞은 몫은 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["남은 75가 나누는 수 41보다 커요.","한 번 더 나눌 수 있으니 몫을 1 크게: 3.","알맞은 몫은 3이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L06_basic#8','math',4,1,'u3','L06','g4_1_math_u3_L06_basic','lesson_basic','M4-1-u3-C8',2,'sa','auto','118 ÷ 17의 세로셈이에요. ?에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M4-1-u3-C8","difficulty":2,"kind":"sa","stem":"118 ÷ 17의 세로셈이에요. ?에 알맞은 수를 쓰세요.","answer":["6"],"explanation":["?는 몫의 일의 자리예요.","17 × 6 = 102, 17 × 7 = 119 — 118을 넘지 않으면서 가장 가까운 곱을 찾아요.","?는 6이에요."],"asset":{"type":"ldiv","a":118,"b":17,"hide":[["q",2]]},"variant_rule":{"alt":[{"stem":"366 ÷ 57의 세로셈이에요. ?에 알맞은 수를 쓰세요.","answer":["24"],"explanation":["?는 나머지예요.","57 × 6 = 342, 57 × 7 = 399 — 366을 넘지 않으면서 가장 가까운 곱을 찾아요.","?는 24예요."],"asset":{"type":"ldiv","a":366,"b":57,"hide":["rem"]}},{"stem":"113 ÷ 13의 세로셈이에요. ?에 알맞은 수를 쓰세요.","answer":["8"],"explanation":["?는 몫의 일의 자리예요.","13 × 8 = 104, 13 × 9 = 117 — 113을 넘지 않으면서 가장 가까운 곱을 찾아요.","?는 8이에요."],"asset":{"type":"ldiv","a":113,"b":13,"hide":[["q",2]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L06_basic#9','math',4,1,'u3','L06','g4_1_math_u3_L06_basic','lesson_basic','M4-1-u3-C8',2,'sa','auto','색종이 155장을 42장씩 묶으려고 해요. 몇 묶음이 되나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-1-u3-C8","difficulty":2,"kind":"sa","stem":"색종이 155장을 42장씩 묶으려고 해요. 몇 묶음이 되나요? 숫자로 쓰세요.","answer":["3"],"explanation":["155 ÷ 42를 계산해요.","155 − 126 = 29 — 29는 42보다 작아요.","몫 3 — 3묶음이에요."],"variant_rule":{"alt":[{"stem":"색종이 105장을 16장씩 묶으려고 해요. 몇 묶음이 되나요? 숫자로 쓰세요.","answer":["6"],"explanation":["105 ÷ 16을 계산해요.","105 − 96 = 9 — 9는 16보다 작아요.","몫 6 — 6묶음이에요."],"asset":null},{"stem":"화분 391개를 학교 48곳에 똑같이 나누어 기부하려고 해요. 한 학교에 몇 개씩 줄 수 있나요? 숫자로 쓰세요.","answer":["8"],"explanation":["391 ÷ 48을 계산해요.","391 − 384 = 7 — 7은 48보다 작아요.","몫 8 — 8개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L06_basic#10','math',4,1,'u3','L06','g4_1_math_u3_L06_basic','lesson_basic','M4-1-u3-C8',3,'error','auto','도윤이 764 ÷ 91 = 7 … 127이라고 계산했어요. 무엇이 잘못됐나요?',ARRAY['M4-1-u3-X07','M4-1-u3-X08']::text[],true,'{"seq":10,"concept":"M4-1-u3-C8","difficulty":3,"kind":"error","stem":"도윤이 764 ÷ 91 = 7 … 127이라고 계산했어요. 무엇이 잘못됐나요?","options":[{"t":"남은 127이 91보다 커요 — 몫을 1 크게 해야 해요","correct":true,"mis_target":"M4-1-u3-X07"},{"t":"남은 127이 91보다 커요 — 몫을 1 작게 해야 해요","mis":"M4-1-u3-X08"},{"t":"나머지는 나누는 수보다 커도 괜찮아요","mis":"M4-1-u3-X07"}],"explanation":["91 × 7 = 637, 764 − 637 = 127.","남은 수가 나누는 수보다 작아야 해요.","바르게: 764 ÷ 91 = 8 … 36이에요."],"variant_rule":{"alt":[{"stem":"은우가 714 ÷ 87 = 7 … 105라고 계산했어요. 무엇이 잘못됐나요?","options":[{"t":"남은 105가 87보다 커요 — 몫을 1 크게 해야 해요","correct":true,"mis_target":"M4-1-u3-X07"},{"t":"남은 105가 87보다 커요 — 몫을 1 작게 해야 해요","mis":"M4-1-u3-X08"},{"t":"나머지는 나누는 수보다 커도 괜찮아요","mis":"M4-1-u3-X07"}],"explanation":["87 × 7 = 609, 714 − 609 = 105.","남은 수가 나누는 수보다 작아야 해요.","바르게: 714 ÷ 87 = 8 … 18이에요."],"asset":null},{"stem":"서준이 321 ÷ 36 = 7 … 69라고 계산했어요. 무엇이 잘못됐나요?","options":[{"t":"남은 69가 36보다 커요 — 몫을 1 크게 해야 해요","correct":true,"mis_target":"M4-1-u3-X07"},{"t":"남은 69가 36보다 커요 — 몫을 1 작게 해야 해요","mis":"M4-1-u3-X08"},{"t":"나머지는 나누는 수보다 커도 괜찮아요","mis":"M4-1-u3-X07"}],"explanation":["36 × 7 = 252, 321 − 252 = 69.","남은 수가 나누는 수보다 작아야 해요.","바르게: 321 ÷ 36 = 8 … 33이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L06_challenge#1','math',4,1,'u3','L06','g4_1_math_u3_L06_challenge','lesson_challenge','M4-1-u3-C8',2,'mc','auto','104 ÷ 18 = 5 … 14가 맞는지 확인하는 식은 어느 것인가요?',ARRAY['M4-1-u3-X10','M4-1-u3-X15']::text[],true,'{"seq":1,"concept":"M4-1-u3-C8","difficulty":2,"kind":"mc","stem":"104 ÷ 18 = 5 … 14가 맞는지 확인하는 식은 어느 것인가요?","options":[{"t":"18 × 5 + 14 = 104","correct":true},{"t":"18 × 5 − 14 = 76","mis":"M4-1-u3-X10"},{"t":"104 × 18 + 14","mis":"M4-1-u3-X10"},{"t":"18 + 5 + 14 = 37","mis":"M4-1-u3-X15"}],"explanation":["확인은 (나누는 수) × (몫) + (나머지).","18 × 5 = 90, 90 + 14 = 104예요.","나누어지는 수 104와 같으니 바르게 계산했어요."],"asset":{"type":"expr_grid","rows":[["18 × 5","=","90"],["90 + 14","=","104"]]},"variant_rule":{"alt":[{"stem":"322 ÷ 43 = 7 … 21이 맞는지 확인하는 식은 어느 것인가요?","options":[{"t":"43 × 7 + 21 = 322","correct":true},{"t":"43 × 7 − 21 = 280","mis":"M4-1-u3-X10"},{"t":"322 × 43 + 21","mis":"M4-1-u3-X10"},{"t":"43 + 7 + 21 = 71","mis":"M4-1-u3-X15"}],"explanation":["확인은 (나누는 수) × (몫) + (나머지).","43 × 7 = 301, 301 + 21 = 322예요.","나누어지는 수 322와 같으니 바르게 계산했어요."],"asset":{"type":"expr_grid","rows":[["43 × 7","=","301"],["301 + 21","=","322"]]}},{"stem":"437 ÷ 61 = 7 … 10이 맞는지 확인하는 식은 어느 것인가요?","options":[{"t":"61 × 7 + 10 = 437","correct":true},{"t":"61 × 7 − 10 = 417","mis":"M4-1-u3-X10"},{"t":"437 × 61 + 10","mis":"M4-1-u3-X10"},{"t":"61 + 7 + 10 = 78","mis":"M4-1-u3-X15"}],"explanation":["확인은 (나누는 수) × (몫) + (나머지).","61 × 7 = 427, 427 + 10 = 437이에요.","나누어지는 수 437과 같으니 바르게 계산했어요."],"asset":{"type":"expr_grid","rows":[["61 × 7","=","427"],["427 + 10","=","437"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_cod