INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L06_challenge#2','math',4,1,'u3','L06','g4_1_math_u3_L06_challenge','lesson_challenge','M4-1-u3-C8',2,'mc','auto','619 ÷ 77에서 하린이는 몫을 8, 은우는 9로 어림했어요. 바르게 말한 것은 어느 것인가요?',ARRAY['M4-1-u3-X17','M4-1-u3-X08','M4-1-u3-X15']::text[],true,'{"seq":2,"concept":"M4-1-u3-C8","difficulty":2,"kind":"mc","stem":"619 ÷ 77에서 하린이는 몫을 8, 은우는 9로 어림했어요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"둘 다 괜찮아요 — 곱해서 확인하면 몫은 8이에요","correct":true},{"t":"어림한 몫이 다르니 둘 다 틀렸어요","mis":"M4-1-u3-X17"},{"t":"더 큰 9가 언제나 맞아요","mis":"M4-1-u3-X08"},{"t":"몫은 두 어림의 합 17이에요","mis":"M4-1-u3-X15"}],"explanation":["어림하는 방법은 여러 가지예요.","77 × 8 = 616, 77 × 9 = 693.","619를 넘지 않는 가장 큰 곱 — 몫 8이에요."],"variant_rule":{"alt":[{"stem":"419 ÷ 94에서 하린이는 몫을 4, 은우는 5로 어림했어요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"둘 다 괜찮아요 — 곱해서 확인하면 몫은 4예요","correct":true},{"t":"어림한 몫이 다르니 둘 다 틀렸어요","mis":"M4-1-u3-X17"},{"t":"더 큰 5가 언제나 맞아요","mis":"M4-1-u3-X08"},{"t":"몫은 두 어림의 합 9예요","mis":"M4-1-u3-X15"}],"explanation":["어림하는 방법은 여러 가지예요.","94 × 4 = 376, 94 × 5 = 470.","419를 넘지 않는 가장 큰 곱 — 몫 4예요."],"asset":null},{"stem":"512 ÷ 86에서 하린이는 몫을 5, 은우는 6으로 어림했어요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"둘 다 괜찮아요 — 곱해서 확인하면 몫은 5예요","correct":true},{"t":"어림한 몫이 다르니 둘 다 틀렸어요","mis":"M4-1-u3-X17"},{"t":"더 큰 6이 언제나 맞아요","mis":"M4-1-u3-X08"},{"t":"몫은 두 어림의 합 11이에요","mis":"M4-1-u3-X15"}],"explanation":["어림하는 방법은 여러 가지예요.","86 × 5 = 430, 86 × 6 = 516.","512를 넘지 않는 가장 큰 곱 — 몫 5예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L06_challenge#3','math',4,1,'u3','L06','g4_1_math_u3_L06_challenge','lesson_challenge','M4-1-u3-C8',3,'mc','auto','434 ÷ 54를 계산했어요. 확인하는 식으로 보아 바르게 계산한 친구는 누구인가요?',ARRAY['M4-1-u3-X07','M4-1-u3-X08','M4-1-u3-X10']::text[],true,'{"seq":3,"concept":"M4-1-u3-C8","difficulty":3,"kind":"mc","stem":"434 ÷ 54를 계산했어요. 확인하는 식으로 보아 바르게 계산한 친구는 누구인가요?","options":[{"t":"태오 — 8 … 2","correct":true},{"t":"지유 — 7 … 56","mis":"M4-1-u3-X07"},{"t":"시아 — 9 … 2","mis":"M4-1-u3-X08"},{"t":"건우 — 8 … 3","mis":"M4-1-u3-X10"}],"explanation":["(나누는 수) × (몫) + (나머지) = (나누어지는 수)여야 해요.","54 × 8 + 2 = 434예요.","태오 — 나머지 2가 54보다 작고 확인 식도 맞아요."],"asset":{"type":"expr_grid","rows":[["54 × 8","=","432"],["432 + 2","=",null]]},"variant_rule":{"alt":[{"stem":"199 ÷ 92를 계산했어요. 확인하는 식으로 보아 바르게 계산한 친구는 누구인가요?","options":[{"t":"은우 — 2 … 15","correct":true},{"t":"태오 — 1 … 107","mis":"M4-1-u3-X07"},{"t":"시아 — 3 … 15","mis":"M4-1-u3-X08"},{"t":"도윤 — 2 … 16","mis":"M4-1-u3-X10"}],"explanation":["(나누는 수) × (몫) + (나머지) = (나누어지는 수)여야 해요.","92 × 2 + 15 = 199예요.","은우 — 나머지 15가 92보다 작고 확인 식도 맞아요."],"asset":{"type":"expr_grid","rows":[["92 × 2","=","184"],["184 + 15","=",null]]}},{"stem":"174 ÷ 19를 계산했어요. 확인하는 식으로 보아 바르게 계산한 친구는 누구인가요?","options":[{"t":"하린 — 9 … 3","correct":true},{"t":"도윤 — 8 … 22","mis":"M4-1-u3-X07"},{"t":"시아 — 10 … 3","mis":"M4-1-u3-X08"},{"t":"태오 — 9 … 4","mis":"M4-1-u3-X10"}],"explanation":["(나누는 수) × (몫) + (나머지) = (나누어지는 수)여야 해요.","19 × 9 + 3 = 174예요.","하린 — 나머지 3이 19보다 작고 확인 식도 맞아요."],"asset":{"type":"expr_grid","rows":[["19 × 9","=","171"],["171 + 3","=",null]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes