INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L06_challenge#4','math',4,1,'u3','L06','g4_1_math_u3_L06_challenge','lesson_challenge','M4-1-u3-C8',3,'mc','auto','책 776쪽을 하루에 93쪽씩 읽으려고 해요. 책을 다 읽으려면 적어도 며칠이 걸리나요?',ARRAY['M4-1-u3-X13','M4-1-u3-X14','M4-1-u3-X15']::text[],true,'{"seq":4,"concept":"M4-1-u3-C8","difficulty":3,"kind":"mc","stem":"책 776쪽을 하루에 93쪽씩 읽으려고 해요. 책을 다 읽으려면 적어도 며칠이 걸리나요?","options":[{"t":"9일","correct":true},{"t":"8일","mis":"M4-1-u3-X13"},{"t":"32일","mis":"M4-1-u3-X14"},{"t":"40일","mis":"M4-1-u3-X15"}],"explanation":["776 ÷ 93 = 8 … 32.","남은 32도 읽어야 하니 하나 더 — 8 + 1 = 9.","답은 9일이에요."],"variant_rule":{"alt":[{"stem":"학생 631명이 한 대에 94명씩 타는 버스를 타려고 해요. 모두 타려면 버스는 적어도 몇 대 필요한가요?","options":[{"t":"7대","correct":true},{"t":"6대","mis":"M4-1-u3-X13"},{"t":"67대","mis":"M4-1-u3-X14"},{"t":"73대","mis":"M4-1-u3-X15"}],"explanation":["631 ÷ 94 = 6 … 67.","남은 67도 태워야 하니 하나 더 — 6 + 1 = 7.","답은 7대예요."],"asset":null},{"stem":"학생 286명이 한 대에 78명씩 타는 버스를 타려고 해요. 모두 타려면 버스는 적어도 몇 대 필요한가요?","options":[{"t":"4대","correct":true},{"t":"3대","mis":"M4-1-u3-X13"},{"t":"52대","mis":"M4-1-u3-X14"},{"t":"55대","mis":"M4-1-u3-X15"}],"explanation":["286 ÷ 78 = 3 … 52.","남은 52도 태워야 하니 하나 더 — 3 + 1 = 4.","답은 4대예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
