INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L06_challenge#6','math',4,1,'u3','L06','g4_1_math_u3_L06_challenge','lesson_challenge','M4-1-u3-C8',3,'mc','auto','몫의 크기를 비교하여 ○ 안에 알맞은 것을 고르세요. 498 ÷ 79 ○ 867 ÷ 97',ARRAY['M4-1-u3-X14','M4-1-u3-X12','M4-1-u3-X15']::text[],true,'{"seq":6,"concept":"M4-1-u3-C8","difficulty":3,"kind":"mc","stem":"몫의 크기를 비교하여 ○ 안에 알맞은 것을 고르세요. 498 ÷ 79 ○ 867 ÷ 97","options":[{"t":"<","correct":true},{"t":">","mis":"M4-1-u3-X14"},{"t":"=","mis":"M4-1-u3-X12"},{"t":"알 수 없어요","mis":"M4-1-u3-X15"}],"explanation":["498 ÷ 79의 몫은 6이에요.","867 ÷ 97의 몫은 8이에요.","6 < 8이에요."],"variant_rule":{"alt":[{"stem":"몫의 크기를 비교하여 ○ 안에 알맞은 것을 고르세요. 210 ÷ 81 ○ 413 ÷ 43","options":[{"t":"<","correct":true},{"t":">","mis":"M4-1-u3-X14"},{"t":"=","mis":"M4-1-u3-X12"},{"t":"알 수 없어요","mis":"M4-1-u3-X15"}],"explanation":["210 ÷ 81의 몫은 2예요.","413 ÷ 43의 몫은 9예요.","2 < 9예요."],"asset":null},{"stem":"몫의 크기를 비교하여 ○ 안에 알맞은 것을 고르세요. 635 ÷ 74 ○ 111 ÷ 34","options":[{"t":">","correct":true},{"t":"<","mis":"M4-1-u3-X14"},{"t":"=","mis":"M4-1-u3-X12"},{"t":"알 수 없어요","mis":"M4-1-u3-X15"}],"explanation":["635 ÷ 74의 몫은 8이에요.","111 ÷ 34의 몫은 3이에요.","8 > 3이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L06_challenge#7','math',4,1,'u3','L06','g4_1_math_u3_L06_challenge','lesson_challenge','M4-1-u3-C8',3,'error','auto','시아가 400 ÷ 81의 몫을 5로 정하고 다음 계산을 이어 가려고 해요. 무엇이 잘못됐나요?',ARRAY['M4-1-u3-X08','M4-1-u3-X07','M4-1-u3-X15']::text[],true,'{"seq":7,"concept":"M4-1-u3-C8","difficulty":3,"kind":"error","stem":"시아가 400 ÷ 81의 몫을 5로 정하고 다음 계산을 이어 가려고 해요. 무엇이 잘못됐나요?","options":[{"t":"81 × 5 = 405가 400보다 커요 — 몫을 1 작게 해야 해요","correct":true,"mis_target":"M4-1-u3-X08"},{"t":"81 × 5 = 405가 400보다 커요 — 몫을 1 크게 해야 해요","mis":"M4-1-u3-X07"},{"t":"곱이 크면 나누어지는 수를 바꾸어야 해요","mis":"M4-1-u3-X15"}],"explanation":["81 × 5 = 405.","405는 400보다 커서 뺄 수 없어요.","바르게: 400 ÷ 81 = 4 … 76이에요."],"variant_rule":{"alt":[{"stem":"시아가 267 ÷ 35의 몫을 8로 정하고 다음 계산을 이어 가려고 해요. 무엇이 잘못됐나요?","options":[{"t":"35 × 8 = 280이 267보다 커요 — 몫을 1 작게 해야 해요","correct":true,"mis_target":"M4-1-u3-X08"},{"t":"35 × 8 = 280이 267보다 커요 — 몫을 1 크게 해야 해요","mis":"M4-1-u3-X07"},{"t":"곱이 크면 나누어지는 수를 바꾸어야 해요","mis":"M4-1-u3-X15"}],"explanation":["35 × 8 = 280.","280은 267보다 커서 뺄 수 없어요.","바르게: 267 ÷ 35 = 7 … 22예요."],"asset":null},{"stem":"건우가 428 ÷ 47의 몫을 10으로 정하고 다음 계산을 이어 가려고 해요. 무엇이 잘못됐나요?","options":[{"t":"47 × 10 = 470이 428보다 커요 — 몫을 1 작게 해야 해요","correct":true,"mis_target":"M4-1-u3-X08"},{"t":"47 × 10 = 470이 428보다 커요 — 몫을 1 크게 해야 해요","mis":"M4-1-u3-X07"},{"t":"곱이 크면 나누어지는 수를 바꾸어야 해요","mis":"M4-1-u3-X15"}],"explanation":["47 × 10 = 470.","470은 428보다 커서 뺄 수 없어요.","바르게: 428 ÷ 47 = 9 … 5예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L06_challenge#8','math',4,1,'u3','L06','g4_1_math_u3_L06_challenge','lesson_challenge','M4-1-u3-C8',4,'essay','teacher','306 ÷ 41의 몫과 나머지를 구하고, 몫을 어떻게 정했는지 곱셈을 이용해 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M4-1-u3-C8","difficulty":4,"kind":"essay","stem":"306 ÷ 41의 몫과 나머지를 구하고, 몫을 어떻게 정했는지 곱셈을 이용해 설명해 보세요.","answer_guide":{"answer":"예: 41 × 7 = 287, 41 × 8 = 328이다. 306을 넘지 않으면서 가장 가까운 곱은 287이므로 몫은 7이다. 306 − 287 = 19이고 19는 41보다 작으므로 306 ÷ 41 = 7 … 19이다.","scoring_points":["41 × 7과 41 × 8을 견주었는가","넘지 않는 가장 큰 곱으로 몫 7을 정했는가","나머지 19를 구했는가"]},"explanation":["41 × 7 = 287, 41 × 8 = 328.","306을 넘지 않는 가장 큰 곱 287 → 몫 7.","306 − 287 = 19."],"asset":{"type":"ldiv","a":306,"b":41,"upto":0}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L06_challenge#9','math',4,1,'u3','L06','g4_1_math_u3_L06_challenge','lesson_challenge','M4-1-u3-C8',4,'sa','auto','어떤 수를 85로 나누었더니 몫이 7, 나머지가 2가 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-1-u3-C8","difficulty":4,"kind":"sa","stem":"어떤 수를 85로 나누었더니 몫이 7, 나머지가 2가 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["597"],"explanation":["나누어지는 수 = (나누는 수) × (몫) + (나머지).","85 × 7 = 595.","595 + 2 = 597 — 어떤 수는 597이에요."],"asset":{"type":"expr_grid","rows":[["85 × 7","=","595"],["595 + 2","=",null]]},"variant_rule":{"alt":[{"stem":"어떤 수를 85로 나누었더니 몫이 9, 나머지가 14가 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["779"],"explanation":["나누어지는 수 = (나누는 수) × (몫) + (나머지).","85 × 9 = 765.","765 + 14 = 779 — 어떤 수는 779예요."],"asset":{"type":"expr_grid","rows":[["85 × 9","=","765"],["765 + 14","=",null]]}},{"stem":"어떤 수를 62로 나누었더니 몫이 5, 나머지가 9가 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["319"],"explanation":["나누어지는 수 = (나누는 수) × (몫) + (나머지).","62 × 5 = 310.","310 + 9 = 319 — 어떤 수는 319예요."],"asset":{"type":"expr_grid","rows":[["62 × 5","=","310"],["310 + 9","=",null]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L06_challenge#10','math',4,1,'u3','L06','g4_1_math_u3_L06_challenge','lesson_challenge','M4-1-u3-C8',4,'mc','auto','달걀 565개를 한 판에 57개씩 담으려고 해요. 가득 채운 판은 몇 판인가요?',ARRAY['M4-1-u3-X13','M4-1-u3-X14','M4-1-u3-X15']::text[],true,'{"seq":10,"concept":"M4-1-u3-C8","difficulty":4,"kind":"mc","stem":"달걀 565개를 한 판에 57개씩 담으려고 해요. 가득 채운 판은 몇 판인가요?","options":[{"t":"9판","correct":true},{"t":"10판","mis":"M4-1-u3-X13"},{"t":"52판","mis":"M4-1-u3-X14"},{"t":"61판","mis":"M4-1-u3-X15"}],"explanation":["565 ÷ 57 = 9 … 52.","남은 52는 하나를 다 채우지 못해요.","답은 9판이에요."],"variant_rule":{"alt":[{"stem":"리본 185 cm로 47 cm짜리 머리끈을 만들려고 해요. 머리끈을 몇 개까지 만들 수 있나요?","options":[{"t":"3개","correct":true},{"t":"4개","mis":"M4-1-u3-X13"},{"t":"44개","mis":"M4-1-u3-X14"},{"t":"47개","mis":"M4-1-u3-X15"}],"explanation":["185 ÷ 47 = 3 … 44.","남은 44는 하나를 다 채우지 못해요.","답은 3개예요."],"asset":null},{"stem":"달걀 285개를 한 판에 84개씩 담으려고 해요. 가득 채운 판은 몇 판인가요?","options":[{"t":"3판","correct":true},{"t":"4판","mis":"M4-1-u3-X13"},{"t":"33판","mis":"M4-1-u3-X14"},{"t":"36판","mis":"M4-1-u3-X15"}],"explanation":["285 ÷ 84 = 3 … 33.","남은 33은 하나를 다 채우지 못해요.","답은 3판이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L07_basic#1','math',4,1,'u3','L07','g4_1_math_u3_L07_basic','lesson_basic','M4-1-u3-C9',1,'sa','auto','528 ÷ 24의 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-1-u3-C9","difficulty":1,"kind":"sa","stem":"528 ÷ 24의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["22"],"explanation":["먼저 몇십 번: 24 × 20 = 480 → 48이 남아요.","24 × 22 = 528 — 남는 것이 없어요.","528 ÷ 24 = 22예요."],"asset":{"type":"ldiv","a":528,"b":24,"upto":0},"variant_rule":{"alt":[{"stem":"462 ÷ 21의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["22"],"explanation":["먼저 몇십 번: 21 × 20 = 420 → 42가 남아요.","21 × 22 = 462 — 남는 것이 없어요.","462 ÷ 21 = 22예요."],"asset":{"type":"ldiv","a":462,"b":21,"upto":0}},{"stem":"336 ÷ 24의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["먼저 몇십 번: 24 × 10 = 240 → 96이 남아요.","24 × 14 = 336 — 남는 것이 없어요.","336 ÷ 24 = 14예요."],"asset":{"type":"ldiv","a":336,"b":24,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L07_basic#2','math',4,1,'u3','L07','g4_1_math_u3_L07_basic','lesson_basic','M4-1-u3-C9',1,'sa','auto','941 ÷ 25에서 몫의 십의 자리를 정하려고 해요. 25 × 30 = 750은 941보다 작고, 25 × 40 = 1000은 941보다 커요. 먼저 몇십 번 나눌 수 있나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-1-u3-C9","difficulty":1,"kind":"sa","stem":"941 ÷ 25에서 몫의 십의 자리를 정하려고 해요. 25 × 30 = 750은 941보다 작고, 25 × 40 = 1000은 941보다 커요. 먼저 몇십 번 나눌 수 있나요? 숫자로 쓰세요.","answer":["30"],"explanation":["30번은 941을 넘지 않아요.","40번은 941을 넘어요.","먼저 30번 — 몫의 십의 자리는 3이에요."],"variant_rule":{"alt":[{"stem":"410 ÷ 36에서 몫의 십의 자리를 정하려고 해요. 36 × 10 = 360은 410보다 작고, 36 × 20 = 720은 410보다 커요. 먼저 몇십 번 나눌 수 있나요? 숫자로 쓰세요.","answer":["10"],"explanation":["10번은 410을 넘지 않아요.","20번은 410을 넘어요.","먼저 10번 — 몫의 십의 자리는 1이에요."],"asset":null},{"stem":"880 ÷ 14에서 몫의 십의 자리를 정하려고 해요. 14 × 60 = 840은 880보다 작고, 14 × 70 = 980은 880보다 커요. 먼저 몇십 번 나눌 수 있나요? 숫자로 쓰세요.","answer":["60"],"explanation":["60번은 880을 넘지 않아요.","70번은 880을 넘어요.","먼저 60번 — 몫의 십의 자리는 6이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L07_basic#3','math',4,1,'u3','L07','g4_1_math_u3_L07_basic','lesson_basic','M4-1-u3-C9',1,'mc','auto','859 ÷ 31의 몫은 몇 자리 수인가요?',ARRAY['M4-1-u3-X12','M4-1-u3-X14']::text[],true,'{"seq":3,"concept":"M4-1-u3-C9","difficulty":1,"kind":"mc","stem":"859 ÷ 31의 몫은 몇 자리 수인가요?","options":[{"t":"두 자리 수","correct":true},{"t":"한 자리 수","mis":"M4-1-u3-X12"},{"t":"세 자리 수","mis":"M4-1-u3-X12"},{"t":"몫이 없어요","mis":"M4-1-u3-X14"}],"explanation":["나누어지는 수의 앞 두 자리 85와 나누는 수 31을 견주어요.","85 ≥ 31 — 몫이 십의 자리부터 나와요.","몫 27 — 두 자리 수예요."],"variant_rule":{"alt":[{"stem":"856 ÷ 18의 몫은 몇 자리 수인가요?","options":[{"t":"두 자리 수","correct":true},{"t":"한 자리 수","mis":"M4-1-u3-X12"},{"t":"세 자리 수","mis":"M4-1-u3-X12"},{"t":"몫이 없어요","mis":"M4-1-u3-X14"}],"explanation":["나누어지는 수의 앞 두 자리 85와 나누는 수 18을 견주어요.","85 ≥ 18 — 몫이 십의 자리부터 나와요.","몫 47 — 두 자리 수예요."],"asset":null},{"stem":"580 ÷ 25의 몫은 몇 자리 수인가요?","options":[{"t":"두 자리 수","correct":true},{"t":"한 자리 수","mis":"M4-1-u3-X12"},{"t":"세 자리 수","mis":"M4-1-u3-X12"},{"t":"몫이 없어요","mis":"M4-1-u3-X14"}],"explanation":["나누어지는 수의 앞 두 자리 58과 나누는 수 25를 견주어요.","58 ≥ 25 — 몫이 십의 자리부터 나와요.","몫 23 — 두 자리 수예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L07_basic#4','math',4,1,'u3','L07','g4_1_math_u3_L07_basic','lesson_basic','M4-1-u3-C9',1,'sa','auto','877 ÷ 23의 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-1-u3-C9","difficulty":1,"kind":"sa","stem":"877 ÷ 23의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["38"],"explanation":["먼저 몇십 번: 23 × 30 = 690 → 187이 남아요.","877 − 874 = 3 — 3은 23보다 작아요.","877 ÷ 23 = 38 … 3이에요."],"asset":{"type":"ldiv","a":877,"b":23,"upto":0},"variant_rule":{"alt":[{"stem":"975 ÷ 19의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["51"],"explanation":["먼저 몇십 번: 19 × 50 = 950 → 25가 남아요.","975 − 969 = 6 — 6은 19보다 작아요.","975 ÷ 19 = 51 … 6이에요."],"asset":{"type":"ldiv","a":975,"b":19,"upto":0}},{"stem":"592 ÷ 31의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["19"],"explanation":["먼저 몇십 번: 31 × 10 = 310 → 282가 남아요.","592 − 589 = 3 — 3은 31보다 작아요.","592 ÷ 31 = 19 … 3이에요."],"asset":{"type":"ldiv","a":592,"b":31,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L07_basic#5','math',4,1,'u3','L07','g4_1_math_u3_L07_basic','lesson_basic','M4-1-u3-C9',2,'sa','auto','733 ÷ 17에서 먼저 17 × 40 = 680을 뺐어요. 남은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-1-u3-C9","difficulty":2,"kind":"sa","stem":"733 ÷ 17에서 먼저 17 × 40 = 680을 뺐어요. 남은 수는 얼마인가요? 숫자로 쓰세요.","answer":["53"],"explanation":["733 − 680 = 53이에요.","남은 53에 17이 3번 더 들어가요.","그래서 몫은 40 + 3 = 43이에요."],"asset":{"type":"ldiv","a":733,"b":17,"upto":1},"variant_rule":{"alt":[{"stem":"564 ÷ 36에서 먼저 36 × 10 = 360을 뺐어요. 남은 수는 얼마인가요? 숫자로 쓰세요.","answer":["204"],"explanation":["564 − 360 = 204예요.","남은 204에 36이 5번 더 들어가요.","그래서 몫은 10 + 5 = 15예요."],"asset":{"type":"ldiv","a":564,"b":36,"upto":1}},{"stem":"486 ÷ 25에서 먼저 25 × 10 = 250을 뺐어요. 남은 수는 얼마인가요? 숫자로 쓰세요.","answer":["236"],"explanation":["486 − 250 = 236이에요.","남은 236에 25가 9번 더 들어가요.","그래서 몫은 10 + 9 = 19예요."],"asset":{"type":"ldiv","a":486,"b":25,"upto":1}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L07_basic#6','math',4,1,'u3','L07','g4_1_math_u3_L07_basic','lesson_basic','M4-1-u3-C9',2,'mc','auto','892 ÷ 35를 계산하여 몫과 나머지를 바르게 구한 것은 어느 것인가요?',ARRAY['M4-1-u3-X07','M4-1-u3-X08','M4-1-u3-X14']::text[],true,'{"seq":6,"concept":"M4-1-u3-C9","difficulty":2,"kind":"mc","stem":"892 ÷ 35를 계산하여 몫과 나머지를 바르게 구한 것은 어느 것인가요?","options":[{"t":"몫 25, 나머지 17","correct":true},{"t":"몫 24, 나머지 52","mis":"M4-1-u3-X07"},{"t":"몫 26, 나머지 없음","mis":"M4-1-u3-X08"},{"t":"몫 17, 나머지 25","mis":"M4-1-u3-X14"}],"explanation":["먼저 몇십 번: 35 × 20 = 700 → 192가 남아요.","892 − 875 = 17 — 17은 35보다 작아요.","892 ÷ 35 = 25 … 17이에요."],"asset":{"type":"ldiv","a":892,"b":35,"upto":0},"variant_rule":{"alt":[{"stem":"883 ÷ 39를 계산하여 몫과 나머지를 바르게 구한 것은 어느 것인가요?","options":[{"t":"몫 22, 나머지 25","correct":true},{"t":"몫 21, 나머지 64","mis":"M4-1-u3-X07"},{"t":"몫 23, 나머지 없음","mis":"M4-1-u3-X08"},{"t":"몫 25, 나머지 22","mis":"M4-1-u3-X14"}],"explanation":["먼저 몇십 번: 39 × 20 = 780 → 103이 남아요.","883 − 858 = 25 — 25는 39보다 작아요.","883 ÷ 39 = 22 … 25예요."],"asset":{"type":"ldiv","a":883,"b":39,"upto":0}},{"stem":"330 ÷ 14를 계산하여 몫과 나머지를 바르게 구한 것은 어느 것인가요?","options":[{"t":"몫 23, 나머지 8","correct":true},{"t":"몫 22, 나머지 22","mis":"M4-1-u3-X07"},{"t":"몫 24, 나머지 없음","mis":"M4-1-u3-X08"},{"t":"몫 8, 나머지 23","mis":"M4-1-u3-X14"}],"explanation":["먼저 몇십 번: 14 × 20 = 280 → 50이 남아요.","330 − 322 = 8 — 8은 14보다 작아요.","330 ÷ 14 = 23 … 8이에요."],"asset":{"type":"ldiv","a":330,"b":14,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
