INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L07_basic#8','math',4,1,'u3','L07','g4_1_math_u3_L07_basic','lesson_basic','M4-1-u3-C9',2,'sa','auto','646 ÷ 11의 나머지는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M4-1-u3-C9","difficulty":2,"kind":"sa","stem":"646 ÷ 11의 나머지는 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["먼저 몇십 번: 11 × 50 = 550 → 96이 남아요.","646 − 638 = 8 — 8은 11보다 작아요.","646 ÷ 11 = 58 … 8이에요."],"asset":{"type":"ldiv","a":646,"b":11,"upto":0},"variant_rule":{"alt":[{"stem":"933 ÷ 31의 나머지는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["먼저 몇십 번: 31 × 30 = 930 → 3이 남아요.","933 − 930 = 3 — 3은 31보다 작아요.","933 ÷ 31 = 30 … 3이에요."],"asset":{"type":"ldiv","a":933,"b":31,"upto":0}},{"stem":"671 ÷ 19의 나머지는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["먼저 몇십 번: 19 × 30 = 570 → 101이 남아요.","671 − 665 = 6 — 6은 19보다 작아요.","671 ÷ 19 = 35 … 6이에요."],"asset":{"type":"ldiv","a":671,"b":19,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L07_basic#9','math',4,1,'u3','L07','g4_1_math_u3_L07_basic','lesson_basic','M4-1-u3-C9',2,'sa','auto','사료 699 kg을 소 한 마리에게 18 kg씩 주려고 해요. 몇 마리에게 줄 수 있나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-1-u3-C9","difficulty":2,"kind":"sa","stem":"사료 699 kg을 소 한 마리에게 18 kg씩 주려고 해요. 몇 마리에게 줄 수 있나요? 숫자로 쓰세요.","answer":["38"],"explanation":["699 ÷ 18을 계산해요.","699 − 684 = 15 — 15는 18보다 작아요.","몫 38 — 38마리예요."],"variant_rule":{"alt":[{"stem":"사료 801 kg을 소 한 마리에게 26 kg씩 주려고 해요. 몇 마리에게 줄 수 있나요? 숫자로 쓰세요.","answer":["30"],"explanation":["801 ÷ 26을 계산해요.","801 − 780 = 21 — 21은 26보다 작아요.","몫 30 — 30마리예요."],"asset":null},{"stem":"구슬 933개를 한 봉지에 26개씩 담으려고 해요. 가득 찬 봉지는 몇 개인가요? 숫자로 쓰세요.","answer":["35"],"explanation":["933 ÷ 26을 계산해요.","933 − 910 = 23 — 23은 26보다 작아요.","몫 35 — 35개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L07_basic#10','math',4,1,'u3','L07','g4_1_math_u3_L07_basic','lesson_basic','M4-1-u3-C9',3,'error','auto','지유가 137 ÷ 13 = 1 … 7이라고 계산했어요. 무엇이 잘못됐나요?',ARRAY['M4-1-u3-X11','M4-1-u3-X07','M4-1-u3-X08']::text[],true,'{"seq":10,"concept":"M4-1-u3-C9","difficulty":3,"kind":"error","stem":"지유가 137 ÷ 13 = 1 … 7이라고 계산했어요. 무엇이 잘못됐나요?","options":[{"t":"몫의 일의 자리에 0을 쓰지 않았어요","correct":true,"mis_target":"M4-1-u3-X11"},{"t":"나머지가 나누는 수보다 커요","mis":"M4-1-u3-X07"},{"t":"몫을 1 크게 해야 해요","mis":"M4-1-u3-X08"}],"explanation":["13 × 10 = 130 — 몫의 십의 자리 1.","남은 7이 13보다 작아 일의 자리 몫은 0.","바르게: 137 ÷ 13 = 10 … 7이에요."],"asset":{"type":"ldiv","a":137,"b":13},"variant_rule":{"alt":[{"stem":"태오가 860 ÷ 17 = 5 … 10이라고 계산했어요. 무엇이 잘못됐나요?","options":[{"t":"몫의 일의 자리에 0을 쓰지 않았어요","correct":true,"mis_target":"M4-1-u3-X11"},{"t":"나머지가 나누는 수보다 커요","mis":"M4-1-u3-X07"},{"t":"몫을 1 크게 해야 해요","mis":"M4-1-u3-X08"}],"explanation":["17 × 50 = 850 — 몫의 십의 자리 5.","남은 10이 17보다 작아 일의 자리 몫은 0.","바르게: 860 ÷ 17 = 50 … 10이에요."],"asset":{"type":"ldiv","a":860,"b":17}},{"stem":"건우가 730 ÷ 24 = 3 … 10이라고 계산했어요. 무엇이 잘못됐나요?","options":[{"t":"몫의 일의 자리에 0을 쓰지 않았어요","correct":true,"mis_target":"M4-1-u3-X11"},{"t":"나머지가 나누는 수보다 커요","mis":"M4-1-u3-X07"},{"t":"몫을 1 크게 해야 해요","mis":"M4-1-u3-X08"}],"explanation":["24 × 30 = 720 — 몫의 십의 자리 3.","남은 10이 24보다 작아 일의 자리 몫은 0.","바르게: 730 ÷ 24 = 30 … 10이에요."],"asset":{"type":"ldiv","a":730,"b":24}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L07_challenge#1','math',4,1,'u3','L07','g4_1_math_u3_L07_challenge','lesson_challenge','M4-1-u3-C9',2,'mc','auto','217 ÷ 15 = 14 … 7이 맞는지 확인하는 식은 어느 것인가요?',ARRAY['M4-1-u3-X10','M4-1-u3-X15']::text[],true,'{"seq":1,"concept":"M4-1-u3-C9","difficulty":2,"kind":"mc","stem":"217 ÷ 15 = 14 … 7이 맞는지 확인하는 식은 어느 것인가요?","options":[{"t":"15 × 14 + 7 = 217","correct":true},{"t":"15 × 14 − 7 = 203","mis":"M4-1-u3-X10"},{"t":"217 × 15 + 7","mis":"M4-1-u3-X10"},{"t":"15 + 14 + 7 = 36","mis":"M4-1-u3-X15"}],"explanation":["확인은 (나누는 수) × (몫) + (나머지).","15 × 14 = 210, 210 + 7 = 217이에요.","나누어지는 수 217과 같으니 바르게 계산했어요."],"asset":{"type":"expr_grid","rows":[["15 × 14","=","210"],["210 + 7","=","217"]]},"variant_rule":{"alt":[{"stem":"965 ÷ 18 = 53 … 11이 맞는지 확인하는 식은 어느 것인가요?","options":[{"t":"18 × 53 + 11 = 965","correct":true},{"t":"18 × 53 − 11 = 943","mis":"M4-1-u3-X10"},{"t":"965 × 18 + 11","mis":"M4-1-u3-X10"},{"t":"18 + 53 + 11 = 82","mis":"M4-1-u3-X15"}],"explanation":["확인은 (나누는 수) × (몫) + (나머지).","18 × 53 = 954, 954 + 11 = 965예요.","나누어지는 수 965와 같으니 바르게 계산했어요."],"asset":{"type":"expr_grid","rows":[["18 × 53","=","954"],["954 + 11","=","965"]]}},{"stem":"443 ÷ 14 = 31 … 9가 맞는지 확인하는 식은 어느 것인가요?","options":[{"t":"14 × 31 + 9 = 443","correct":true},{"t":"14 × 31 − 9 = 425","mis":"M4-1-u3-X10"},{"t":"443 × 14 + 9","mis":"M4-1-u3-X10"},{"t":"14 + 31 + 9 = 54","mis":"M4-1-u3-X15"}],"explanation":["확인은 (나누는 수) × (몫) + (나머지).","14 × 31 = 434, 434 + 9 = 443이에요.","나누어지는 수 443과 같으니 바르게 계산했어요."],"asset":{"type":"expr_grid","rows":[["14 × 31","=","434"],["434 + 9","=","443"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconc