INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L07_challenge#2','math',4,1,'u3','L07','g4_1_math_u3_L07_challenge','lesson_challenge','M4-1-u3-C9',2,'sa','auto','598 ÷ 16에서 몫의 십의 자리를 정하려고 해요. 16 × 30 = 480은 598보다 작고, 16 × 40 = 640은 598보다 커요. 먼저 몇십 번 나눌 수 있나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-1-u3-C9","difficulty":2,"kind":"sa","stem":"598 ÷ 16에서 몫의 십의 자리를 정하려고 해요. 16 × 30 = 480은 598보다 작고, 16 × 40 = 640은 598보다 커요. 먼저 몇십 번 나눌 수 있나요? 숫자로 쓰세요.","answer":["30"],"explanation":["30번은 598을 넘지 않아요.","40번은 598을 넘어요.","먼저 30번 — 몫의 십의 자리는 3이에요."],"variant_rule":{"alt":[{"stem":"569 ÷ 26에서 몫의 십의 자리를 정하려고 해요. 26 × 20 = 520은 569보다 작고, 26 × 30 = 780은 569보다 커요. 먼저 몇십 번 나눌 수 있나요? 숫자로 쓰세요.","answer":["20"],"explanation":["20번은 569를 넘지 않아요.","30번은 569를 넘어요.","먼저 20번 — 몫의 십의 자리는 2예요."],"asset":null},{"stem":"712 ÷ 11에서 몫의 십의 자리를 정하려고 해요. 11 × 60 = 660은 712보다 작고, 11 × 70 = 770은 712보다 커요. 먼저 몇십 번 나눌 수 있나요? 숫자로 쓰세요.","answer":["60"],"explanation":["60번은 712를 넘지 않아요.","70번은 712를 넘어요.","먼저 60번 — 몫의 십의 자리는 6이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
