INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L07_challenge#5','math',4,1,'u3','L07','g4_1_math_u3_L07_challenge','lesson_challenge','M4-1-u3-C9',3,'mc','auto','491 ÷ 12를 계산했어요. 확인하는 식으로 보아 바르게 계산한 친구는 누구인가요?',ARRAY['M4-1-u3-X07','M4-1-u3-X08','M4-1-u3-X10']::text[],true,'{"seq":5,"concept":"M4-1-u3-C9","difficulty":3,"kind":"mc","stem":"491 ÷ 12를 계산했어요. 확인하는 식으로 보아 바르게 계산한 친구는 누구인가요?","options":[{"t":"서준 — 40 … 11","correct":true},{"t":"하린 — 39 … 23","mis":"M4-1-u3-X07"},{"t":"은우 — 41 … 11","mis":"M4-1-u3-X08"},{"t":"건우 — 40 … 10","mis":"M4-1-u3-X10"}],"explanation":["(나누는 수) × (몫) + (나머지) = (나누어지는 수)여야 해요.","12 × 40 + 11 = 491이에요.","서준 — 나머지 11이 12보다 작고 확인 식도 맞아요."],"asset":{"type":"expr_grid","rows":[["12 × 40","=","480"],["480 + 11","=",null]]},"variant_rule":{"alt":[{"stem":"814 ÷ 19를 계산했어요. 확인하는 식으로 보아 바르게 계산한 친구는 누구인가요?","options":[{"t":"하린 — 42 … 16","correct":true},{"t":"건우 — 41 … 35","mis":"M4-1-u3-X07"},{"t":"시아 — 43 … 16","mis":"M4-1-u3-X08"},{"t":"태오 — 42 … 17","mis":"M4-1-u3-X10"}],"explanation":["(나누는 수) × (몫) + (나머지) = (나누어지는 수)여야 해요.","19 × 42 + 16 = 814예요.","하린 — 나머지 16이 19보다 작고 확인 식도 맞아요."],"asset":{"type":"expr_grid","rows":[["19 × 42","=","798"],["798 + 16","=",null]]}},{"stem":"134 ÷ 11을 계산했어요. 확인하는 식으로 보아 바르게 계산한 친구는 누구인가요?","options":[{"t":"건우 — 12 … 2","correct":true},{"t":"지유 — 11 … 13","mis":"M4-1-u3-X07"},{"t":"은우 — 13 … 2","mis":"M4-1-u3-X08"},{"t":"태오 — 12 … 3","mis":"M4-1-u3-X10"}],"explanation":["(나누는 수) × (몫) + (나머지) = (나누어지는 수)여야 해요.","11 × 12 + 2 = 134예요.","건우 — 나머지 2가 11보다 작고 확인 식도 맞아요."],"asset":{"type":"expr_grid","rows":[["11 × 12","=","132"],["132 + 2","=",null]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLU