INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L07_challenge#6','math',4,1,'u3','L07','g4_1_math_u3_L07_challenge','lesson_challenge','M4-1-u3-C9',3,'mc','auto','사과 618개를 한 상자에 11개씩 남김없이 모두 담으려고 해요. 상자는 적어도 몇 개 필요한가요?',ARRAY['M4-1-u3-X13','M4-1-u3-X14','M4-1-u3-X15']::text[],true,'{"seq":6,"concept":"M4-1-u3-C9","difficulty":3,"kind":"mc","stem":"사과 618개를 한 상자에 11개씩 남김없이 모두 담으려고 해요. 상자는 적어도 몇 개 필요한가요?","options":[{"t":"57개","correct":true},{"t":"56개","mis":"M4-1-u3-X13"},{"t":"2개","mis":"M4-1-u3-X14"},{"t":"58개","mis":"M4-1-u3-X15"}],"explanation":["618 ÷ 11 = 56 … 2.","남은 2도 담아야 하니 하나 더 — 56 + 1 = 57.","답은 57개예요."],"variant_rule":{"alt":[{"stem":"학생 171명이 한 대에 12명씩 타는 버스를 타려고 해요. 모두 타려면 버스는 적어도 몇 대 필요한가요?","options":[{"t":"15대","correct":true},{"t":"14대","mis":"M4-1-u3-X13"},{"t":"3대","mis":"M4-1-u3-X14"},{"t":"17대","mis":"M4-1-u3-X15"}],"explanation":["171 ÷ 12 = 14 … 3.","남은 3도 태워야 하니 하나 더 — 14 + 1 = 15.","답은 15대예요."],"asset":null},{"stem":"학생 544명이 한 대에 44명씩 타는 버스를 타려고 해요. 모두 타려면 버스는 적어도 몇 대 필요한가요?","options":[{"t":"13대","correct":true},{"t":"12대","mis":"M4-1-u3-X13"},{"t":"16대","mis":"M4-1-u3-X14"},{"t":"28대","mis":"M4-1-u3-X15"}],"explanation":["544 ÷ 44 = 12 … 16.","남은 16도 태워야 하니 하나 더 — 12 + 1 = 13.","답은 13대예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L07_challenge#7','math',4,1,'u3','L07','g4_1_math_u3_L07_challenge','lesson_challenge','M4-1-u3-C9',3,'sa','auto','2□2 ÷ 14 = 15 … 2에서 □ 안에 알맞은 숫자를 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M4-1-u3-C9","difficulty":3,"kind":"sa","stem":"2□2 ÷ 14 = 15 … 2에서 □ 안에 알맞은 숫자를 쓰세요.","answer":["1"],"explanation":["나누어지는 수 = 14 × 15 + 2.","210 + 2 = 212예요.","□ = 1이에요."],"asset":{"type":"expr_grid","rows":[["14 × 15","=","210"],["210 + 2","=",null]]},"variant_rule":{"alt":[{"stem":"54□ ÷ 23 = 23 … 20에서 □ 안에 알맞은 숫자를 쓰세요.","answer":["9"],"explanation":["나누어지는 수 = 23 × 23 + 20.","529 + 20 = 549예요.","□ = 9예요."],"asset":{"type":"expr_grid","rows":[["23 × 23","=","529"],["529 + 20","=",null]]}},{"stem":"□16 ÷ 12 = 34 … 8에서 □ 안에 알맞은 숫자를 쓰세요.","answer":["4"],"explanation":["나누어지는 수 = 12 × 34 + 8.","408 + 8 = 416이에요.","□ = 4예요."],"asset":{"type":"expr_grid","rows":[["12 × 34","=","408"],["408 + 8","=",null]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L07_challenge#8','math',4,1,'u3','L07','g4_1_math_u3_L07_challenge','lesson_challenge','M4-1-u3-C9',4,'essay','teacher','675 ÷ 28의 몫과 나머지를 구하려고 해요. 몇십 번을 먼저 덜어 내는 방법으로 풀이 과정을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M4-1-u3-C9","difficulty":4,"kind":"essay","stem":"675 ÷ 28의 몫과 나머지를 구하려고 해요. 몇십 번을 먼저 덜어 내는 방법으로 풀이 과정을 설명해 보세요.","answer_guide":{"answer":"예: 28 × 20 = 560은 675보다 작고 28 × 30 = 840은 크므로 먼저 20번 덜어 낸다. 675 − 560 = 115가 남고, 28 × 4 = 112이므로 4번 더 덜어 낸다. 115 − 112 = 3이므로 675 ÷ 28 = 24 … 3이다.","scoring_points":["28 × 20 = 560을 먼저 덜어 냈는가","남은 115에서 28 × 4 = 112를 덜어 냈는가","24 … 3을 구했는가"]},"explanation":["28 × 20 = 560 → 115 남음.","28 × 4 = 112 → 3 남음.","몫 24, 나머지 3."],"asset":{"type":"ldiv","a":675,"b":28,"upto":0}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L07_challenge#9','math',4,1,'u3','L07','g4_1_math_u3_L07_challenge','lesson_challenge','M4-1-u3-C9',4,'sa','auto','어떤 수를 21로 나누었더니 몫이 24, 나머지가 8이 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-1-u3-C9","difficulty":4,"kind":"sa","stem":"어떤 수를 21로 나누었더니 몫이 24, 나머지가 8이 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["512"],"explanation":["나누어지는 수 = (나누는 수) × (몫) + (나머지).","21 × 24 = 504.","504 + 8 = 512 — 어떤 수는 512예요."],"asset":{"type":"expr_grid","rows":[["21 × 24","=","504"],["504 + 8","=",null]]},"variant_rule":{"alt":[{"stem":"어떤 수를 27로 나누었더니 몫이 22, 나머지가 8이 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["602"],"explanation":["나누어지는 수 = (나누는 수) × (몫) + (나머지).","27 × 22 = 594.","594 + 8 = 602 — 어떤 수는 602예요."],"asset":{"type":"expr_grid","rows":[["27 × 22","=","594"],["594 + 8","=",null]]}},{"stem":"어떤 수를 27로 나누었더니 몫이 15, 나머지가 5가 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["410"],"explanation":["나누어지는 수 = (나누는 수) × (몫) + (나머지).","27 × 15 = 405.","405 + 5 = 410 — 어떤 수는 410이에요."],"asset":{"type":"expr_grid","rows":[["27 × 15","=","405"],["405 + 5","=",null]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L07_challenge#10','math',4,1,'u3','L07','g4_1_math_u3_L07_challenge','lesson_challenge','M4-1-u3-C9',4,'mc','auto','끈 873 cm를 11 cm씩 잘라 리본을 만들려고 해요. 자르고 남는 끈은 몇 cm인가요?',ARRAY['M4-1-u3-X14','M4-1-u3-X07','M4-1-u3-X15']::text[],true,'{"seq":10,"concept":"M4-1-u3-C9","difficulty":4,"kind":"mc","stem":"끈 873 cm를 11 cm씩 잘라 리본을 만들려고 해요. 자르고 남는 끈은 몇 cm인가요?","options":[{"t":"4 cm","correct":true},{"t":"79 cm","mis":"M4-1-u3-X14"},{"t":"15 cm","mis":"M4-1-u3-X07"},{"t":"83 cm","mis":"M4-1-u3-X15"}],"explanation":["873 ÷ 11을 계산해요.","873 − 869 = 4 — 4는 11보다 작아요.","나머지 4 — 4 cm 남아요."],"variant_rule":{"alt":[{"stem":"끈 580 cm를 12 cm씩 잘라 리본을 만들려고 해요. 자르고 남는 끈은 몇 cm인가요?","options":[{"t":"4 cm","correct":true},{"t":"48 cm","mis":"M4-1-u3-X14"},{"t":"16 cm","mis":"M4-1-u3-X07"},{"t":"52 cm","mis":"M4-1-u3-X15"}],"explanation":["580 ÷ 12를 계산해요.","580 − 576 = 4 — 4는 12보다 작아요.","나머지 4 — 4 cm 남아요."],"asset":null},{"stem":"사료 185 kg을 소 한 마리에게 15 kg씩 주려고 해요. 주고 남는 사료는 몇 kg인가요?","options":[{"t":"5 kg","correct":true},{"t":"12 kg","mis":"M4-1-u3-X14"},{"t":"20 kg","mis":"M4-1-u3-X07"},{"t":"17 kg","mis":"M4-1-u3-X15"}],"explanation":["185 ÷ 15를 계산해요.","185 − 180 = 5 — 5는 15보다 작아요.","나머지 5 — 5 kg 남아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L08_basic#1','math',4,1,'u3','L08','g4_1_math_u3_L08_basic','lesson_basic','M4-1-u3-C10',1,'sa','auto','반찬 한 사람 몫의 탄소 발자국이에요 — 콩나물무침 58 g, 깍두기 58 g, 미역국 92 g. 세 반찬의 탄소 발자국을 모두 더하면 몇 g인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-1-u3-C10","difficulty":1,"kind":"sa","stem":"반찬 한 사람 몫의 탄소 발자국이에요 — 콩나물무침 58 g, 깍두기 58 g, 미역국 92 g. 세 반찬의 탄소 발자국을 모두 더하면 몇 g인가요? 숫자로 쓰세요.","answer":["208"],"explanation":["세 값을 차례로 더해요.","58 + 58 + 92 = 208.","한 사람 몫은 208 g이에요."],"variant_rule":{"alt":[{"stem":"반찬 한 사람 몫의 탄소 발자국이에요 — 달걀말이 118 g, 불고기 460 g, 닭볶음 312 g. 세 반찬의 탄소 발자국을 모두 더하면 몇 g인가요? 숫자로 쓰세요.","answer":["890"],"explanation":["세 값을 차례로 더해요.","118 + 460 + 312 = 890.","한 사람 몫은 890 g이에요."],"asset":null},{"stem":"반찬 한 사람 몫의 탄소 발자국이에요 — 깍두기 58 g, 닭볶음 312 g, 고등어조림 245 g. 세 반찬의 탄소 발자국을 모두 더하면 몇 g인가요? 숫자로 쓰세요.","answer":["615"],"explanation":["세 값을 차례로 더해요.","58 + 312 + 245 = 615.","한 사람 몫은 615 g이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L08_basic#2','math',4,1,'u3','L08','g4_1_math_u3_L08_basic','lesson_basic','M4-1-u3-C10',1,'sa','auto','빈 병 한 개를 돌려주면 50원을 받아요. 350원을 받았다면 돌려준 빈 병은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-1-u3-C10","difficulty":1,"kind":"sa","stem":"빈 병 한 개를 돌려주면 50원을 받아요. 350원을 받았다면 돌려준 빈 병은 몇 개인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["받은 돈 ÷ 한 개에 받는 돈.","350 ÷ 50 = 7이에요.","빈 병 7개를 돌려줬어요."],"asset":{"type":"ldiv","a":350,"b":50,"upto":0},"variant_rule":{"alt":[{"stem":"빈 병 한 개를 돌려주면 80원을 받아요. 1520원을 받았다면 돌려준 빈 병은 몇 개인가요? 숫자로 쓰세요.","answer":["19"],"explanation":["받은 돈 ÷ 한 개에 받는 돈.","1520 ÷ 80 = 19예요.","빈 병 19개를 돌려줬어요."],"asset":{"type":"ldiv","a":1520,"b":80,"upto":0}},{"stem":"빈 병 한 개를 돌려주면 70원을 받아요. 630원을 받았다면 돌려준 빈 병은 몇 개인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["받은 돈 ÷ 한 개에 받는 돈.","630 ÷ 70 = 9예요.","빈 병 9개를 돌려줬어요."],"asset":{"type":"ldiv","a":630,"b":70,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L08_basic#3','math',4,1,'u3','L08','g4_1_math_u3_L08_basic','lesson_basic','M4-1-u3-C10',1,'mc','auto','반찬 한 사람 몫의 탄소 발자국과 사람 수를 알 때 모두의 탄소 발자국을 구하는 식은 어느 것인가요?',ARRAY['M4-1-u3-X15']::text[],true,'{"seq":3,"concept":"M4-1-u3-C10","difficulty":1,"kind":"mc","stem":"반찬 한 사람 몫의 탄소 발자국과 사람 수를 알 때 모두의 탄소 발자국을 구하는 식은 어느 것인가요?","options":[{"t":"(한 사람 몫) × (사람 수)","correct":true},{"t":"(한 사람 몫) ÷ (사람 수)","mis":"M4-1-u3-X15"},{"t":"(한 사람 몫) + (사람 수)","mis":"M4-1-u3-X15"},{"t":"(사람 수) − (한 사람 몫)","mis":"M4-1-u3-X15"}],"explanation":["똑같은 양이 여러 번이면 곱셈.","전체를 똑같이 나누거나 몇 번 들어가는지 찾으면 나눗셈.","알맞은 식은 (한 사람 몫) × (사람 수)."],"variant_rule":{"alt":[{"stem":"빈 병 한 개에 받는 돈과 받은 돈을 알 때 돌려준 빈 병의 수를 구하는 식은 어느 것인가요?","options":[{"t":"(받은 돈) ÷ (한 개에 받는 돈)","correct":true},{"t":"(받은 돈) × (한 개에 받는 돈)","mis":"M4-1-u3-X15"},{"t":"(한 개에 받는 돈) ÷ (받은 돈)","mis":"M4-1-u3-X14"},{"t":"(받은 돈) − (한 개에 받는 돈)","mis":"M4-1-u3-X15"}],"explanation":["똑같은 양이 여러 번이면 곱셈.","전체를 똑같이 나누거나 몇 번 들어가는지 찾으면 나눗셈.","알맞은 식은 (받은 돈) ÷ (한 개에 받는 돈)."],"asset":null},{"stem":"하루에 줄인 탄소 발자국과 날수를 알 때 모두 줄인 양을 구하는 식은 어느 것인가요?","options":[{"t":"(하루에 줄인 양) × (날수)","correct":true},{"t":"(하루에 줄인 양) ÷ (날수)","mis":"M4-1-u3-X15"},{"t":"(날수) ÷ (하루에 줄인 양)","mis":"M4-1-u3-X14"},{"t":"(하루에 줄인 양) + (날수)","mis":"M4-1-u3-X15"}],"explanation":["똑같은 양이 여러 번이면 곱셈.","전체를 똑같이 나누거나 몇 번 들어가는지 찾으면 나눗셈.","알맞은 식은 (하루에 줄인 양) × (날수)."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L08_basic#4','math',4,1,'u3','L08','g4_1_math_u3_L08_basic','lesson_basic','M4-1-u3-C10',1,'sa','auto','학교에서 쓰지 않는 전기를 꺼서 하루에 탄소 발자국을 129 g씩 줄였어요. 30일 동안 줄인 탄소 발자국은 모두 몇 g인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-1-u3-C10","difficulty":1,"kind":"sa","stem":"학교에서 쓰지 않는 전기를 꺼서 하루에 탄소 발자국을 129 g씩 줄였어요. 30일 동안 줄인 탄소 발자국은 모두 몇 g인가요? 숫자로 쓰세요.","answer":["3870"],"explanation":["하루 129 g씩 30일 — 129 × 30.","곱하는 수가 10배(3 → 30)라서 곱도 10배예요.","모두 3870 g 줄였어요."],"variant_rule":{"alt":[{"stem":"학교에서 쓰지 않는 전기를 꺼서 하루에 탄소 발자국을 181 g씩 줄였어요. 40일 동안 줄인 탄소 발자국은 모두 몇 g인가요? 숫자로 쓰세요.","answer":["7240"],"explanation":["하루 181 g씩 40일 — 181 × 40.","곱하는 수가 10배(4 → 40)라서 곱도 10배예요.","모두 7240 g 줄였어요."],"asset":null},{"stem":"학교에서 쓰지 않는 전기를 꺼서 하루에 탄소 발자국을 364 g씩 줄였어요. 20일 동안 줄인 탄소 발자국은 모두 몇 g인가요? 숫자로 쓰세요.","answer":["7280"],"explanation":["하루 364 g씩 20일 — 364 × 20.","곱하는 수가 10배(2 → 20)라서 곱도 10배예요.","모두 7280 g 줄였어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L08_basic#5','math',4,1,'u3','L08','g4_1_math_u3_L08_basic','lesson_basic','M4-1-u3-C10',2,'mc','auto','불고기·두부조림·달걀말이가 한 사람 몫이에요(460 g, 104 g, 118 g). 우리 반 22명이 모두 먹으면 탄소 발자국은 모두 몇 g인가요?',ARRAY['M4-1-u3-X18','M4-1-u3-X15','M4-1-u3-X02']::text[],true,'{"seq":5,"concept":"M4-1-u3-C10","difficulty":2,"kind":"mc","stem":"불고기·두부조림·달걀말이가 한 사람 몫이에요(460 g, 104 g, 118 g). 우리 반 22명이 모두 먹으면 탄소 발자국은 모두 몇 g인가요?","options":[{"t":"15004 g","correct":true},{"t":"10120 g","mis":"M4-1-u3-X18"},{"t":"704 g","mis":"M4-1-u3-X15"},{"t":"2728 g","mis":"M4-1-u3-X02"}],"explanation":["한 사람 몫: 460 + 104 + 118 = 682 g.","22명이니 682 × 22.","682 × 22 = 15004 — 15004 g이에요."],"variant_rule":{"alt":[{"stem":"깍두기·잡곡밥·닭볶음이 한 사람 몫이에요(58 g, 136 g, 312 g). 우리 반 22명이 모두 먹으면 탄소 발자국은 모두 몇 g인가요?","options":[{"t":"11132 g","correct":true},{"t":"1276 g","mis":"M4-1-u3-X18"},{"t":"528 g","mis":"M4-1-u3-X15"},{"t":"2024 g","mis":"M4-1-u3-X02"}],"explanation":["한 사람 몫: 58 + 136 + 312 = 506 g.","22명이니 506 × 22.","506 × 22 = 11132 — 11132 g이에요."],"asset":null},{"stem":"미역국·달걀말이·잡곡밥이 한 사람 몫이에요(92 g, 118 g, 136 g). 우리 반 22명이 모두 먹으면 탄소 발자국은 모두 몇 g인가요?","options":[{"t":"7612 g","correct":true},{"t":"2024 g","mis":"M4-1-u3-X18"},{"t":"368 g","mis":"M4-1-u3-X15"},{"t":"1384 g","mis":"M4-1-u3-X02"}],"explanation":["한 사람 몫: 92 + 118 + 136 = 346 g.","22명이니 346 × 22.","346 × 22 = 7612 — 7612 g이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L08_basic#6','math',4,1,'u3','L08','g4_1_math_u3_L08_basic','lesson_basic','M4-1-u3-C10',2,'mc','auto','재활용 종이 112장으로 장바구니 한 개에 12장씩 써서 장바구니를 만들려고 해요. 장바구니를 몇 개까지 만들 수 있고, 종이는 몇 장 남나요?',ARRAY['M4-1-u3-X13','M4-1-u3-X14','M4-1-u3-X07']::text[],true,'{"seq":6,"concept":"M4-1-u3-C10","difficulty":2,"kind":"mc","stem":"재활용 종이 112장으로 장바구니 한 개에 12장씩 써서 장바구니를 만들려고 해요. 장바구니를 몇 개까지 만들 수 있고, 종이는 몇 장 남나요?","options":[{"t":"9개, 4장","correct":true},{"t":"10개, 0장","mis":"M4-1-u3-X13"},{"t":"4개, 9장","mis":"M4-1-u3-X14"},{"t":"8개, 16장","mis":"M4-1-u3-X07"}],"explanation":["112 ÷ 12를 계산해요.","112 − 108 = 4 — 4는 12보다 작아요.","9개를 만들고 4장이 남아요."],"asset":{"type":"ldiv","a":112,"b":12,"upto":0},"variant_rule":{"alt":[{"stem":"재활용 종이 145장으로 장바구니 한 개에 18장씩 써서 장바구니를 만들려고 해요. 장바구니를 몇 개까지 만들 수 있고, 종이는 몇 장 남나요?","options":[{"t":"8개, 1장","correct":true},{"t":"9개, 0장","mis":"M4-1-u3-X13"},{"t":"1개, 8장","mis":"M4-1-u3-X14"},{"t":"7개, 19장","mis":"M4-1-u3-X07"}],"explanation":["145 ÷ 18을 계산해요.","145 − 144 = 1 — 1은 18보다 작아요.","8개를 만들고 1장이 남아요."],"asset":{"type":"ldiv","a":145,"b":18,"upto":0}},{"stem":"재활용 종이 364장으로 장바구니 한 개에 92장씩 써서 장바구니를 만들려고 해요. 장바구니를 몇 개까지 만들 수 있고, 종이는 몇 장 남나요?","options":[{"t":"3개, 88장","correct":true},{"t":"4개, 0장","mis":"M4-1-u3-X13"},{"t":"88개, 3장","mis":"M4-1-u3-X14"},{"t":"2개, 180장","mis":"M4-1-u3-X07"}],"explanation":["364 ÷ 92를 계산해요.","364 − 276 = 88 — 88은 92보다 작아요.","3개를 만들고 88장이 남아요."],"asset":{"type":"ldiv","a":364,"b":92,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L08_basic#7','math',4,1,'u3','L08','g4_1_math_u3_L08_basic','lesson_basic','M4-1-u3-C10',2,'ox','auto','반찬 수가 적을수록 탄소 발자국은 언제나 작아요.',ARRAY['M4-1-u3-X18']::text[],true,'{"seq":7,"concept":"M4-1-u3-C10","difficulty":2,"kind":"ox","stem":"반찬 수가 적을수록 탄소 발자국은 언제나 작아요.","answer":"X","reason_options":[{"t":"무엇을 고르느냐에 따라 달라져서","correct":true},{"t":"반찬이 적으면 언제나 줄어서","mis":"M4-1-u3-X18"}],"mis":"M4-1-u3-X18","explanation":["고기 반찬 하나가 채소 반찬 셋보다 클 수 있어요.","곱셈과 나눗셈으로 견주면 차이가 보여요.","그래서 틀렸어요."],"variant_rule":{"alt":[{"stem":"같은 반찬이라도 먹는 사람이 많아지면 모두의 탄소 발자국은 커져요.","answer":"O","reason_options":[{"t":"한 사람 몫에 사람 수를 곱하니까","correct":true},{"t":"사람이 많아지면 한 사람 몫이 나누어져 작아지니까","mis":"M4-1-u3-X15"}],"explanation":["모두의 양 = 한 사람 몫 × 사람 수.","곱셈과 나눗셈으로 견주면 차이가 보여요.","그래서 맞아요."],"asset":null},{"stem":"먹을 만큼만 담아 남기지 않으면 탄소 발자국을 줄일 수 있어요.","answer":"O","reason_options":[{"t":"버려지는 음식에도 탄소 발자국이 있어서","correct":true},{"t":"남긴 음식은 탄소 발자국과 상관없어서","mis":"M4-1-u3-X18"}],"explanation":["만들고 옮긴 음식이 버려지면 그만큼 헛되이 남아요.","곱셈과 나눗셈으로 견주면 차이가 보여요.","그래서 맞아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L08_basic#8','math',4,1,'u3','L08','g4_1_math_u3_L08_basic','lesson_basic','M4-1-u3-C10',2,'mc','auto','학생 498명이 한 대에 79명씩 타는 버스를 타려고 해요. 모두 타려면 버스는 적어도 몇 대 필요한가요?',ARRAY['M4-1-u3-X13','M4-1-u3-X14','M4-1-u3-X15']::text[],true,'{"seq":8,"concept":"M4-1-u3-C10","difficulty":2,"kind":"mc","stem":"학생 498명이 한 대에 79명씩 타는 버스를 타려고 해요. 모두 타려면 버스는 적어도 몇 대 필요한가요?","options":[{"t":"7대","correct":true},{"t":"6대","mis":"M4-1-u3-X13"},{"t":"24대","mis":"M4-1-u3-X14"},{"t":"30대","mis":"M4-1-u3-X15"}],"explanation":["498 ÷ 79 = 6 … 24.","남은 24도 태워야 하니 하나 더 — 6 + 1 = 7.","답은 7대예요."],"variant_rule":{"alt":[{"stem":"책 473쪽을 하루에 52쪽씩 읽으려고 해요. 책을 다 읽으려면 적어도 며칠이 걸리나요?","options":[{"t":"10일","correct":true},{"t":"9일","mis":"M4-1-u3-X13"},{"t":"5일","mis":"M4-1-u3-X14"},{"t":"14일","mis":"M4-1-u3-X15"}],"explanation":["473 ÷ 52 = 9 … 5.","남은 5도 읽어야 하니 하나 더 — 9 + 1 = 10.","답은 10일이에요."],"asset":null},{"stem":"사과 356개를 한 상자에 58개씩 남김없이 모두 담으려고 해요. 상자는 적어도 몇 개 필요한가요?","options":[{"t":"7개","correct":true},{"t":"6개","mis":"M4-1-u3-X13"},{"t":"8개","mis":"M4-1-u3-X14"},{"t":"14개","mis":"M4-1-u3-X15"}],"explanation":["356 ÷ 58 = 6 … 8.","남은 8도 담아야 하니 하나 더 — 6 + 1 = 7.","답은 7개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L08_basic#9','math',4,1,'u3','L08','g4_1_math_u3_L08_basic','lesson_basic','M4-1-u3-C10',2,'mc','auto','학교에서 쓰지 않는 전기를 꺼서 하루에 탄소 발자국을 953 g씩 줄였어요. 17일 동안 줄인 탄소 발자국은 모두 몇 g인가요?',ARRAY['M4-1-u3-X15','M4-1-u3-X02','M4-1-u3-X03']::text[],true,'{"seq":9,"concept":"M4-1-u3-C10","difficulty":2,"kind":"mc","stem":"학교에서 쓰지 않는 전기를 꺼서 하루에 탄소 발자국을 953 g씩 줄였어요. 17일 동안 줄인 탄소 발자국은 모두 몇 g인가요?","options":[{"t":"16201 g","correct":true},{"t":"970 g","mis":"M4-1-u3-X15"},{"t":"7624 g","mis":"M4-1-u3-X02"},{"t":"9530 g","mis":"M4-1-u3-X03"}],"explanation":["하루 953 g씩 17일 — 953 × 17.","953 × 10 = 9530, 953 × 7 = 6671.","모두 16201 g 줄였어요."],"variant_rule":{"alt":[{"stem":"학교에서 쓰지 않는 전기를 꺼서 하루에 탄소 발자국을 706 g씩 줄였어요. 85일 동안 줄인 탄소 발자국은 모두 몇 g인가요?","options":[{"t":"60010 g","correct":true},{"t":"791 g","mis":"M4-1-u3-X15"},{"t":"9178 g","mis":"M4-1-u3-X02"},{"t":"56480 g","mis":"M4-1-u3-X03"}],"explanation":["하루 706 g씩 85일 — 706 × 85.","706 × 80 = 56480, 706 × 5 = 3530.","모두 60010 g 줄였어요."],"asset":null},{"stem":"학교에서 쓰지 않는 전기를 꺼서 하루에 탄소 발자국을 472 g씩 줄였어요. 86일 동안 줄인 탄소 발자국은 모두 몇 g인가요?","options":[{"t":"40592 g","correct":true},{"t":"558 g","mis":"M4-1-u3-X15"},{"t":"6608 g","mis":"M4-1-u3-X02"},{"t":"37760 g","mis":"M4-1-u3-X03"}],"explanation":["하루 472 g씩 86일 — 472 × 86.","472 × 80 = 37760, 472 × 6 = 2832.","모두 40592 g 줄였어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L08_basic#10','math',4,1,'u3','L08','g4_1_math_u3_L08_basic','lesson_basic','M4-1-u3-C10',3,'mc','auto','오늘 반찬은 한 사람에 598 g, 내일 반찬은 한 사람에 348 g이에요. 25명이 먹을 때 내일은 오늘보다 탄소 발자국이 몇 g 줄어드나요?',ARRAY['M4-1-u3-X18','M4-1-u3-X15']::text[],true,'{"seq":10,"concept":"M4-1-u3-C10","difficulty":3,"kind":"mc","stem":"오늘 반찬은 한 사람에 598 g, 내일 반찬은 한 사람에 348 g이에요. 25명이 먹을 때 내일은 오늘보다 탄소 발자국이 몇 g 줄어드나요?","options":[{"t":"6250 g","correct":true},{"t":"250 g","mis":"M4-1-u3-X18"},{"t":"23650 g","mis":"M4-1-u3-X15"},{"t":"8700 g","mis":"M4-1-u3-X18"}],"explanation":["오늘 598 × 25 = 14950 g.","내일 348 × 25 = 8700 g.","14950 − 8700 = 6250 g 줄어요."],"variant_rule":{"alt":[{"stem":"오늘 반찬은 한 사람에 644 g, 내일 반찬은 한 사람에 361 g이에요. 21명이 먹을 때 내일은 오늘보다 탄소 발자국이 몇 g 줄어드나요?","options":[{"t":"5943 g","correct":true},{"t":"283 g","mis":"M4-1-u3-X18"},{"t":"21105 g","mis":"M4-1-u3-X15"},{"t":"7581 g","mis":"M4-1-u3-X18"}],"explanation":["오늘 644 × 21 = 13524 g.","내일 361 × 21 = 7581 g.","13524 − 7581 = 5943 g 줄어요."],"asset":null},{"stem":"오늘 반찬은 한 사람에 662 g, 내일 반찬은 한 사람에 350 g이에요. 28명이 먹을 때 내일은 오늘보다 탄소 발자국이 몇 g 줄어드나요?","options":[{"t":"8736 g","correct":true},{"t":"312 g","mis":"M4-1-u3-X18"},{"t":"28336 g","mis":"M4-1-u3-X15"},{"t":"9800 g","mis":"M4-1-u3-X18"}],"explanation":["오늘 662 × 28 = 18536 g.","내일 350 × 28 = 9800 g.","18536 − 9800 = 8736 g 줄어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L08_challenge#1','math',4,1,'u3','L08','g4_1_math_u3_L08_challenge','lesson_challenge','M4-1-u3-C10',2,'mc','auto','닭볶음·콩나물무침·잡곡밥이 한 사람 몫이에요(312 g, 58 g, 136 g). 우리 반 27명이 모두 먹으면 탄소 발자국은 모두 몇 g인가요?',ARRAY['M4-1-u3-X18','M4-1-u3-X15','M4-1-u3-X02']::text[],true,'{"seq":1,"concept":"M4-1-u3-C10","difficulty":2,"kind":"mc","stem":"닭볶음·콩나물무침·잡곡밥이 한 사람 몫이에요(312 g, 58 g, 136 g). 우리 반 27명이 모두 먹으면 탄소 발자국은 모두 몇 g인가요?","options":[{"t":"13662 g","correct":true},{"t":"8424 g","mis":"M4-1-u3-X18"},{"t":"533 g","mis":"M4-1-u3-X15"},{"t":"4554 g","mis":"M4-1-u3-X02"}],"explanation":["한 사람 몫: 312 + 58 + 136 = 506 g.","27명이니 506 × 27.","506 × 27 = 13662 — 13662 g이에요."],"variant_rule":{"alt":[{"stem":"불고기·달걀말이·깍두기가 한 사람 몫이에요(460 g, 118 g, 58 g). 우리 반 28명이 모두 먹으면 탄소 발자국은 모두 몇 g인가요?","options":[{"t":"17808 g","correct":true},{"t":"12880 g","mis":"M4-1-u3-X18"},{"t":"664 g","mis":"M4-1-u3-X15"},{"t":"6360 g","mis":"M4-1-u3-X02"}],"explanation":["한 사람 몫: 460 + 118 + 58 = 636 g.","28명이니 636 × 28.","636 × 28 = 17808 — 17808 g이에요."],"asset":null},{"stem":"고등어조림·닭볶음·불고기가 한 사람 몫이에요(245 g, 312 g, 460 g). 우리 반 24명이 모두 먹으면 탄소 발자국은 모두 몇 g인가요?","options":[{"t":"24408 g","correct":true},{"t":"5880 g","mis":"M4-1-u3-X18"},{"t":"1041 g","mis":"M4-1-u3-X15"},{"t":"6102 g","mis":"M4-1-u3-X02"}],"explanation":["한 사람 몫: 245 + 312 + 460 = 1017 g.","24명이니 1017 × 24.","1017 × 24 = 24408 — 24408 g이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L08_challenge#2','math',4,1,'u3','L08','g4_1_math_u3_L08_challenge','lesson_challenge','M4-1-u3-C10',2,'sa','auto','빈 병 한 개를 돌려주면 20원을 받아요. 520원을 받았다면 돌려준 빈 병은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-1-u3-C10","difficulty":2,"kind":"sa","stem":"빈 병 한 개를 돌려주면 20원을 받아요. 520원을 받았다면 돌려준 빈 병은 몇 개인가요? 숫자로 쓰세요.","answer":["26"],"explanation":["받은 돈 ÷ 한 개에 받는 돈.","520 ÷ 20 = 26이에요.","빈 병 26개를 돌려줬어요."],"asset":{"type":"ldiv","a":520,"b":20,"upto":0},"variant_rule":{"alt":[{"stem":"빈 병 한 개를 돌려주면 70원을 받아요. 1890원을 받았다면 돌려준 빈 병은 몇 개인가요? 숫자로 쓰세요.","answer":["27"],"explanation":["받은 돈 ÷ 한 개에 받는 돈.","1890 ÷ 70 = 27이에요.","빈 병 27개를 돌려줬어요."],"asset":{"type":"ldiv","a":1890,"b":70,"upto":0}},{"stem":"빈 병 한 개를 돌려주면 50원을 받아요. 2050원을 받았다면 돌려준 빈 병은 몇 개인가요? 숫자로 쓰세요.","answer":["41"],"explanation":["받은 돈 ÷ 한 개에 받는 돈.","2050 ÷ 50 = 41이에요.","빈 병 41개를 돌려줬어요."],"asset":{"type":"ldiv","a":2050,"b":50,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L08_challenge#3','math',4,1,'u3','L08','g4_1_math_u3_L08_challenge','lesson_challenge','M4-1-u3-C10',3,'mc','auto','오늘 반찬은 한 사람에 631 g, 내일 반찬은 한 사람에 418 g이에요. 22명이 먹을 때 내일은 오늘보다 탄소 발자국이 몇 g 줄어드나요?',ARRAY['M4-1-u3-X18','M4-1-u3-X15']::text[],true,'{"seq":3,"concept":"M4-1-u3-C10","difficulty":3,"kind":"mc","stem":"오늘 반찬은 한 사람에 631 g, 내일 반찬은 한 사람에 418 g이에요. 22명이 먹을 때 내일은 오늘보다 탄소 발자국이 몇 g 줄어드나요?","options":[{"t":"4686 g","correct":true},{"t":"213 g","mis":"M4-1-u3-X18"},{"t":"23078 g","mis":"M4-1-u3-X15"},{"t":"9196 g","mis":"M4-1-u3-X18"}],"explanation":["오늘 631 × 22 = 13882 g.","내일 418 × 22 = 9196 g.","13882 − 9196 = 4686 g 줄어요."],"variant_rule":{"alt":[{"stem":"오늘 반찬은 한 사람에 667 g, 내일 반찬은 한 사람에 388 g이에요. 27명이 먹을 때 내일은 오늘보다 탄소 발자국이 몇 g 줄어드나요?","options":[{"t":"7533 g","correct":true},{"t":"279 g","mis":"M4-1-u3-X18"},{"t":"28485 g","mis":"M4-1-u3-X15"},{"t":"10476 g","mis":"M4-1-u3-X18"}],"explanation":["오늘 667 × 27 = 18009 g.","내일 388 × 27 = 10476 g.","18009 − 10476 = 7533 g 줄어요."],"asset":null},{"stem":"오늘 반찬은 한 사람에 632 g, 내일 반찬은 한 사람에 348 g이에요. 27명이 먹을 때 내일은 오늘보다 탄소 발자국이 몇 g 줄어드나요?","options":[{"t":"7668 g","correct":true},{"t":"284 g","mis":"M4-1-u3-X18"},{"t":"26460 g","mis":"M4-1-u3-X15"},{"t":"9396 g","mis":"M4-1-u3-X18"}],"explanation":["오늘 632 × 27 = 17064 g.","내일 348 × 27 = 9396 g.","17064 − 9396 = 7668 g 줄어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L08_challenge#4','math',4,1,'u3','L08','g4_1_math_u3_L08_challenge','lesson_challenge','M4-1-u3-C10',3,'mc','auto','재활용 종이 923장으로 장바구니 한 개에 15장씩 써서 장바구니를 만들려고 해요. 장바구니를 몇 개까지 만들 수 있고, 종이는 몇 장 남나요?',ARRAY['M4-1-u3-X13','M4-1-u3-X14','M4-1-u3-X07']::text[],true,'{"seq":4,"concept":"M4-1-u3-C10","difficulty":3,"kind":"mc","stem":"재활용 종이 923장으로 장바구니 한 개에 15장씩 써서 장바구니를 만들려고 해요. 장바구니를 몇 개까지 만들 수 있고, 종이는 몇 장 남나요?","options":[{"t":"61개, 8장","correct":true},{"t":"62개, 0장","mis":"M4-1-u3-X13"},{"t":"8개, 61장","mis":"M4-1-u3-X14"},{"t":"60개, 23장","mis":"M4-1-u3-X07"}],"explanation":["923 ÷ 15를 계산해요.","923 − 915 = 8 — 8은 15보다 작아요.","61개를 만들고 8장이 남아요."],"asset":{"type":"ldiv","a":923,"b":15,"upto":0},"variant_rule":{"alt":[{"stem":"재활용 종이 500장으로 장바구니 한 개에 43장씩 써서 장바구니를 만들려고 해요. 장바구니를 몇 개까지 만들 수 있고, 종이는 몇 장 남나요?","options":[{"t":"11개, 27장","correct":true},{"t":"12개, 0장","mis":"M4-1-u3-X13"},{"t":"27개, 11장","mis":"M4-1-u3-X14"},{"t":"10개, 70장","mis":"M4-1-u3-X07"}],"explanation":["500 ÷ 43을 계산해요.","500 − 473 = 27 — 27은 43보다 작아요.","11개를 만들고 27장이 남아요."],"asset":{"type":"ldiv","a":500,"b":43,"upto":0}},{"stem":"재활용 종이 691장으로 장바구니 한 개에 32장씩 써서 장바구니를 만들려고 해요. 장바구니를 몇 개까지 만들 수 있고, 종이는 몇 장 남나요?","options":[{"t":"21개, 19장","correct":true},{"t":"22개, 0장","mis":"M4-1-u3-X13"},{"t":"19개, 21장","mis":"M4-1-u3-X14"},{"t":"20개, 51장","mis":"M4-1-u3-X07"}],"explanation":["691 ÷ 32를 계산해요.","691 − 672 = 19 — 19는 32보다 작아요.","21개를 만들고 19장이 남아요."],"asset":{"type":"ldiv","a":691,"b":32,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L08_challenge#5','math',4,1,'u3','L08','g4_1_math_u3_L08_challenge','lesson_challenge','M4-1-u3-C10',3,'mc','auto','리본 999 cm로 48 cm짜리 머리끈을 만들려고 해요. 머리끈을 몇 개까지 만들 수 있나요?',ARRAY['M4-1-u3-X13','M4-1-u3-X14','M4-1-u3-X15']::text[],true,'{"seq":5,"concept":"M4-1-u3-C10","difficulty":3,"kind":"mc","stem":"리본 999 cm로 48 cm짜리 머리끈을 만들려고 해요. 머리끈을 몇 개까지 만들 수 있나요?","options":[{"t":"20개","correct":true},{"t":"21개","mis":"M4-1-u3-X13"},{"t":"39개","mis":"M4-1-u3-X14"},{"t":"59개","mis":"M4-1-u3-X15"}],"explanation":["999 ÷ 48 = 20 … 39.","남은 39는 하나를 다 채우지 못해요.","답은 20개예요."],"variant_rule":{"alt":[{"stem":"리본 496 cm로 11 cm짜리 머리끈을 만들려고 해요. 머리끈을 몇 개까지 만들 수 있나요?","options":[{"t":"45개","correct":true},{"t":"46개","mis":"M4-1-u3-X13"},{"t":"1개","mis":"M4-1-u3-X14"},{"t":"485개","mis":"M4-1-u3-X15"}],"explanation":["496 ÷ 11 = 45 … 1.","남은 1은 하나를 다 채우지 못해요.","답은 45개예요."],"asset":null},{"stem":"리본 424 cm로 13 cm짜리 머리끈을 만들려고 해요. 머리끈을 몇 개까지 만들 수 있나요?","options":[{"t":"32개","correct":true},{"t":"33개","mis":"M4-1-u3-X13"},{"t":"8개","mis":"M4-1-u3-X14"},{"t":"40개","mis":"M4-1-u3-X15"}],"explanation":["424 ÷ 13 = 32 … 8.","남은 8은 하나를 다 채우지 못해요.","답은 32개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L08_challenge#6','math',4,1,'u3','L08','g4_1_math_u3_L08_challenge','lesson_challenge','M4-1-u3-C10',3,'sa','auto','방울토마토 833 kg을 한 상자에 22 kg씩 담으려고 해요. 가득 채운 상자는 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M4-1-u3-C10","difficulty":3,"kind":"sa","stem":"방울토마토 833 kg을 한 상자에 22 kg씩 담으려고 해요. 가득 채운 상자는 몇 개인가요? 숫자로 쓰세요.","answer":["37"],"explanation":["833 ÷ 22를 계산해요.","833 − 814 = 19 — 19는 22보다 작아요.","몫 37 — 37개예요."],"variant_rule":{"alt":[{"stem":"구슬 635개를 한 봉지에 15개씩 담으려고 해요. 가득 찬 봉지는 몇 개인가요? 숫자로 쓰세요.","answer":["42"],"explanation":["635 ÷ 15를 계산해요.","635 − 630 = 5 — 5는 15보다 작아요.","몫 42 — 42개예요."],"asset":null},{"stem":"방울토마토 624 kg을 한 상자에 27 kg씩 담으려고 해요. 가득 채운 상자는 몇 개인가요? 숫자로 쓰세요.","answer":["23"],"explanation":["624 ÷ 27을 계산해요.","624 − 621 = 3 — 3은 27보다 작아요.","몫 23 — 23개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L08_challenge#7','math',4,1,'u3','L08','g4_1_math_u3_L08_challenge','lesson_challenge','M4-1-u3-C10',3,'mc','auto','책 688쪽을 하루에 15쪽씩 읽으려고 해요. 책을 다 읽으려면 적어도 며칠이 걸리나요?',ARRAY['M4-1-u3-X13','M4-1-u3-X14','M4-1-u3-X15']::text[],true,'{"seq":7,"concept":"M4-1-u3-C10","difficulty":3,"kind":"mc","stem":"책 688쪽을 하루에 15쪽씩 읽으려고 해요. 책을 다 읽으려면 적어도 며칠이 걸리나요?","options":[{"t":"46일","correct":true},{"t":"45일","mis":"M4-1-u3-X13"},{"t":"13일","mis":"M4-1-u3-X14"},{"t":"58일","mis":"M4-1-u3-X15"}],"explanation":["688 ÷ 15 = 45 … 13.","남은 13도 읽어야 하니 하나 더 — 45 + 1 = 46.","답은 46일이에요."],"variant_rule":{"alt":[{"stem":"책 490쪽을 하루에 12쪽씩 읽으려고 해요. 책을 다 읽으려면 적어도 며칠이 걸리나요?","options":[{"t":"41일","correct":true},{"t":"40일","mis":"M4-1-u3-X13"},{"t":"10일","mis":"M4-1-u3-X14"},{"t":"50일","mis":"M4-1-u3-X15"}],"explanation":["490 ÷ 12 = 40 … 10.","남은 10도 읽어야 하니 하나 더 — 40 + 1 = 41.","답은 41일이에요."],"asset":null},{"stem":"학생 639명이 한 대에 29명씩 타는 버스를 타려고 해요. 모두 타려면 버스는 적어도 몇 대 필요한가요?","options":[{"t":"23대","correct":true},{"t":"22대","mis":"M4-1-u3-X13"},{"t":"1대","mis":"M4-1-u3-X14"},{"t":"610대","mis":"M4-1-u3-X15"}],"explanation":["639 ÷ 29 = 22 … 1.","남은 1도 태워야 하니 하나 더 — 22 + 1 = 23.","답은 23대예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L08_challenge#8','math',4,1,'u3','L08','g4_1_math_u3_L08_challenge','lesson_challenge','M4-1-u3-C10',4,'essay','teacher','오늘 반찬(잡곡밥 136 g·불고기 460 g·배추김치 76 g)과 내가 고른 반찬(깍두기 58 g·고등어조림 245 g·콩나물무침 58 g)의 한 사람 몫 탄소 발자국을 각각 구하고, 25명이 먹을 때 얼마나 줄어드는지 풀이 과정과 함께 써 보세요.','{}'::text[],false,'{"seq":8,"concept":"M4-1-u3-C10","difficulty":4,"kind":"essay","stem":"오늘 반찬(잡곡밥 136 g·불고기 460 g·배추김치 76 g)과 내가 고른 반찬(깍두기 58 g·고등어조림 245 g·콩나물무침 58 g)의 한 사람 몫 탄소 발자국을 각각 구하고, 25명이 먹을 때 얼마나 줄어드는지 풀이 과정과 함께 써 보세요.","answer_guide":{"answer":"예: 오늘 반찬은 136 + 460 + 76 = 672 g, 내가 고른 반찬은 58 + 245 + 58 = 361 g이다. 25명이면 672 × 25 = 16800 g, 361 × 25 = 9025 g이다. 16800 − 9025 = 7775이므로 7775 g 줄어든다.","scoring_points":["672 g과 361 g을 구했는가","16800 g과 9025 g을 구했는가","7775 g 줄어든다고 답했는가"]},"explanation":["672 g · 361 g.","672 × 25 = 16800, 361 × 25 = 9025.","16800 − 9025 = 7775 g."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L08_challenge#9','math',4,1,'u3','L08','g4_1_math_u3_L08_challenge','lesson_challenge','M4-1-u3-C10',4,'mc','auto','오늘 반찬은 한 사람에 715 g, 내일 반찬은 한 사람에 372 g이에요. 26명이 먹을 때 내일은 오늘보다 탄소 발자국이 몇 g 줄어드나요?',ARRAY['M4-1-u3-X18','M4-1-u3-X15']::text[],true,'{"seq":9,"concept":"M4-1-u3-C10","difficulty":4,"kind":"mc","stem":"오늘 반찬은 한 사람에 715 g, 내일 반찬은 한 사람에 372 g이에요. 26명이 먹을 때 내일은 오늘보다 탄소 발자국이 몇 g 줄어드나요?","options":[{"t":"8918 g","correct":true},{"t":"343 g","mis":"M4-1-u3-X18"},{"t":"28262 g","mis":"M4-1-u3-X15"},{"t":"9672 g","mis":"M4-1-u3-X18"}],"explanation":["오늘 715 × 26 = 18590 g.","내일 372 × 26 = 9672 g.","18590 − 9672 = 8918 g 줄어요."],"variant_rule":{"alt":[{"stem":"오늘 반찬은 한 사람에 606 g, 내일 반찬은 한 사람에 451 g이에요. 25명이 먹을 때 내일은 오늘보다 탄소 발자국이 몇 g 줄어드나요?","options":[{"t":"3875 g","correct":true},{"t":"155 g","mis":"M4-1-u3-X18"},{"t":"26425 g","mis":"M4-1-u3-X15"},{"t":"11275 g","mis":"M4-1-u3-X18"}],"explanation":["오늘 606 × 25 = 15150 g.","내일 451 × 25 = 11275 g.","15150 − 11275 = 3875 g 줄어요."],"asset":null},{"stem":"오늘 반찬은 한 사람에 567 g, 내일 반찬은 한 사람에 421 g이에요. 25명이 먹을 때 내일은 오늘보다 탄소 발자국이 몇 g 줄어드나요?","options":[{"t":"3650 g","correct":true},{"t":"146 g","mis":"M4-1-u3-X18"},{"t":"24700 g","mis":"M4-1-u3-X15"},{"t":"10525 g","mis":"M4-1-u3-X18"}],"explanation":["오늘 567 × 25 = 14175 g.","내일 421 × 25 = 10525 g.","14175 − 10525 = 3650 g 줄어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_L08_challenge#10','math',4,1,'u3','L08','g4_1_math_u3_L08_challenge','lesson_challenge','M4-1-u3-C10',4,'mc','auto','배추김치·콩나물무침·잡곡밥이 한 사람 몫이에요(76 g, 58 g, 136 g). 우리 반 34명이 모두 먹으면 탄소 발자국은 모두 몇 g인가요?',ARRAY['M4-1-u3-X18','M4-1-u3-X15','M4-1-u3-X02']::text[],true,'{"seq":10,"concept":"M4-1-u3-C10","difficulty":4,"kind":"mc","stem":"배추김치·콩나물무침·잡곡밥이 한 사람 몫이에요(76 g, 58 g, 136 g). 우리 반 34명이 모두 먹으면 탄소 발자국은 모두 몇 g인가요?","options":[{"t":"9180 g","correct":true},{"t":"2584 g","mis":"M4-1-u3-X18"},{"t":"304 g","mis":"M4-1-u3-X15"},{"t":"1890 g","mis":"M4-1-u3-X02"}],"explanation":["한 사람 몫: 76 + 58 + 136 = 270 g.","34명이니 270 × 34.","270 × 34 = 9180 — 9180 g이에요."],"variant_rule":{"alt":[{"stem":"닭볶음·불고기·고등어조림이 한 사람 몫이에요(312 g, 460 g, 245 g). 우리 반 26명이 모두 먹으면 탄소 발자국은 모두 몇 g인가요?","options":[{"t":"26442 g","correct":true},{"t":"8112 g","mis":"M4-1-u3-X18"},{"t":"1043 g","mis":"M4-1-u3-X15"},{"t":"8136 g","mis":"M4-1-u3-X02"}],"explanation":["한 사람 몫: 312 + 460 + 245 = 1017 g.","26명이니 1017 × 26.","1017 × 26 = 26442 — 26442 g이에요."],"asset":null},{"stem":"고등어조림·두부조림·깍두기가 한 사람 몫이에요(245 g, 104 g, 58 g). 우리 반 28명이 모두 먹으면 탄소 발자국은 모두 몇 g인가요?","options":[{"t":"11396 g","correct":true},{"t":"6860 g","mis":"M4-1-u3-X18"},{"t":"435 g","mis":"M4-1-u3-X15"},{"t":"4070 g","mis":"M4-1-u3-X02"}],"explanation":["한 사람 몫: 245 + 104 + 58 = 407 g.","28명이니 407 × 28.","407 × 28 = 11396 — 11396 g이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_a#1','math',4,1,'u3','','g4_1_math_u3_review_a','unit_review','M4-1-u3-C2',1,'sa','auto','159 × 30은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-1-u3-C2","difficulty":1,"kind":"sa","stem":"159 × 30은 얼마인가요? 숫자로 쓰세요.","answer":["4770"],"explanation":["159 × 3 = 477 — 먼저 몇을 곱해요.","곱하는 수가 10배(3 → 30)라서 곱도 10배예요.","159 × 30 = 4770이에요."],"variant_rule":{"alt":[{"stem":"138 × 20은 얼마인가요? 숫자로 쓰세요.","answer":["2760"],"explanation":["138 × 2 = 276 — 먼저 몇을 곱해요.","곱하는 수가 10배(2 → 20)라서 곱도 10배예요.","138 × 20 = 2760이에요."],"asset":null},{"stem":"116 × 30은 얼마인가요? 숫자로 쓰세요.","answer":["3480"],"explanation":["116 × 3 = 348 — 먼저 몇을 곱해요.","곱하는 수가 10배(3 → 30)라서 곱도 10배예요.","116 × 30 = 3480이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_a#2','math',4,1,'u3','','g4_1_math_u3_review_a','unit_review','M4-1-u3-C1',1,'sa','auto','286 × 98을 아는 계산으로 쪼갰어요. 286 × 98 = 286 × 90 + 286 × □에서 □ 안에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-1-u3-C1","difficulty":1,"kind":"sa","stem":"286 × 98을 아는 계산으로 쪼갰어요. 286 × 98 = 286 × 90 + 286 × □에서 □ 안에 알맞은 수를 쓰세요.","answer":["8"],"explanation":["98은 90과 8의 합이에요.","98번 더한 것 = 90번 더하고 8번 더 더한 것.","□ = 8이에요."],"asset":{"type":"expr_grid","rows":[["286 × 90","=","25740"],["286 × 8","=","2288"],["25740 + 2288","=","28028"]]},"variant_rule":{"alt":[{"stem":"825 × 19를 아는 계산으로 쪼갰어요. 825 × 19 = 825 × 10 + 825 × □에서 □ 안에 알맞은 수를 쓰세요.","answer":["9"],"explanation":["19는 10과 9의 합이에요.","19번 더한 것 = 10번 더하고 9번 더 더한 것.","□ = 9예요."],"asset":{"type":"expr_grid","rows":[["825 × 10","=","8250"],["825 × 9","=","7425"],["8250 + 7425","=","15675"]]}},{"stem":"986 × 72를 아는 계산으로 쪼갰어요. 986 × 72 = 986 × 70 + 986 × □에서 □ 안에 알맞은 수를 쓰세요.","answer":["2"],"explanation":["72는 70과 2의 합이에요.","72번 더한 것 = 70번 더하고 2번 더 더한 것.","□ = 2예요."],"asset":{"type":"expr_grid","rows":[["986 × 70","=","69020"],["986 × 2","=","1972"],["69020 + 1972","=","70992"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_a#3','math',4,1,'u3','','g4_1_math_u3_review_a','unit_review','M4-1-u3-C3',1,'sa','auto','168 × 54의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-1-u3-C3","difficulty":1,"kind":"sa","stem":"168 × 54의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["2"],"explanation":["일의 자리 4를 먼저 곱하고, 십의 자리 5를 곱한 값은 한 칸 밀어 써요.","셋째 줄은 168 × 4 = 672예요.","?는 일의 자리 숫자 2예요."],"asset":{"type":"expr_grid","rows":[["","","","1","6","8"],["×","","","","5","4"],["","","","6","7",null],["","","8","4","0",""],["","","9","0","7","2"]]},"variant_rule":{"alt":[{"stem":"241 × 29의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["1"],"explanation":["일의 자리 9를 먼저 곱하고, 십의 자리 2를 곱한 값은 한 칸 밀어 써요.","셋째 줄은 241 × 9 = 2169예요.","?는 백의 자리 숫자 1이에요."],"asset":{"type":"expr_grid","rows":[["","","","2","4","1"],["×","","","","2","9"],["","","2",null,"6","9"],["","","4","8","2",""],["","","6","9","8","9"]]}},{"stem":"249 × 34의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["6"],"explanation":["일의 자리 4를 먼저 곱하고, 십의 자리 3을 곱한 값은 한 칸 밀어 써요.","셋째 줄은 249 × 4 = 996이에요.","?는 일의 자리 숫자 6이에요."],"asset":{"type":"expr_grid","rows":[["","","","2","4","9"],["×","","","","3","4"],["","","","9","9",null],["","","7","4","7",""],["","","8","4","6","6"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_a#4','math',4,1,'u3','','g4_1_math_u3_review_a','unit_review','M4-1-u3-C5',1,'sa','auto','223 ÷ 80의 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-1-u3-C5","difficulty":1,"kind":"sa","stem":"223 ÷ 80의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["223 ÷ 80 — 220은 십 모형 22개, 80은 십 모형 8개로 보면 22 ÷ 8과 같아요.","223 − 160 = 63 — 63은 80보다 작아요.","223 ÷ 80 = 2 … 63이에요."],"asset":{"type":"ldiv","a":223,"b":80,"upto":0},"variant_rule":{"alt":[{"stem":"208 ÷ 80의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["208 ÷ 80 — 200은 십 모형 20개, 80은 십 모형 8개로 보면 20 ÷ 8과 같아요.","208 − 160 = 48 — 48은 80보다 작아요.","208 ÷ 80 = 2 … 48이에요."],"asset":{"type":"ldiv","a":208,"b":80,"upto":0}},{"stem":"476 ÷ 70의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["476 ÷ 70 — 470은 십 모형 47개, 70은 십 모형 7개로 보면 47 ÷ 7과 같아요.","476 − 420 = 56 — 56은 70보다 작아요.","476 ÷ 70 = 6 … 56이에요."],"asset":{"type":"ldiv","a":476,"b":70,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_a#5','math',4,1,'u3','','g4_1_math_u3_review_a','unit_review','M4-1-u3-C7',1,'sa','auto','35 ÷ 15의 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-1-u3-C7","difficulty":1,"kind":"sa","stem":"35 ÷ 15의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["15 × 2 = 30, 15 × 3 = 45 — 35를 넘지 않으면서 가장 가까운 곱을 찾아요.","35 − 30 = 5 — 5는 15보다 작아요.","35 ÷ 15 = 2 … 5예요."],"asset":{"type":"ldiv","a":35,"b":15,"upto":0},"variant_rule":{"alt":[{"stem":"60 ÷ 18의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["18 × 3 = 54, 18 × 4 = 72 — 60을 넘지 않으면서 가장 가까운 곱을 찾아요.","60 − 54 = 6 — 6은 18보다 작아요.","60 ÷ 18 = 3 … 6이에요."],"asset":{"type":"ldiv","a":60,"b":18,"upto":0}},{"stem":"50 ÷ 15의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["15 × 3 = 45, 15 × 4 = 60 — 50을 넘지 않으면서 가장 가까운 곱을 찾아요.","50 − 45 = 5 — 5는 15보다 작아요.","50 ÷ 15 = 3 … 5예요."],"asset":{"type":"ldiv","a":50,"b":15,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_a#6','math',4,1,'u3','','g4_1_math_u3_review_a','unit_review','M4-1-u3-C8',1,'sa','auto','115 ÷ 32의 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M4-1-u3-C8","difficulty":1,"kind":"sa","stem":"115 ÷ 32의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["32 × 3 = 96, 32 × 4 = 128 — 115를 넘지 않으면서 가장 가까운 곱을 찾아요.","115 − 96 = 19 — 19는 32보다 작아요.","115 ÷ 32 = 3 … 19예요."],"asset":{"type":"ldiv","a":115,"b":32,"upto":0},"variant_rule":{"alt":[{"stem":"295 ÷ 82의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["82 × 3 = 246, 82 × 4 = 328 — 295를 넘지 않으면서 가장 가까운 곱을 찾아요.","295 − 246 = 49 — 49는 82보다 작아요.","295 ÷ 82 = 3 … 49예요."],"asset":{"type":"ldiv","a":295,"b":82,"upto":0}},{"stem":"284 ÷ 97의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["97 × 2 = 194, 97 × 3 = 291 — 284를 넘지 않으면서 가장 가까운 곱을 찾아요.","284 − 194 = 90 — 90은 97보다 작아요.","284 ÷ 97 = 2 … 90이에요."],"asset":{"type":"ldiv","a":284,"b":97,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_a#7','math',4,1,'u3','','g4_1_math_u3_review_a','unit_review','M4-1-u3-C9',1,'sa','auto','309 ÷ 25의 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M4-1-u3-C9","difficulty":1,"kind":"sa","stem":"309 ÷ 25의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["먼저 몇십 번: 25 × 10 = 250 → 59가 남아요.","309 − 300 = 9 — 9는 25보다 작아요.","309 ÷ 25 = 12 … 9예요."],"asset":{"type":"ldiv","a":309,"b":25,"upto":0},"variant_rule":{"alt":[{"stem":"949 ÷ 34의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["27"],"explanation":["먼저 몇십 번: 34 × 20 = 680 → 269가 남아요.","949 − 918 = 31 — 31은 34보다 작아요.","949 ÷ 34 = 27 … 31이에요."],"asset":{"type":"ldiv","a":949,"b":34,"upto":0}},{"stem":"875 ÷ 34의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["먼저 몇십 번: 34 × 20 = 680 → 195가 남아요.","875 − 850 = 25 — 25는 34보다 작아요.","875 ÷ 34 = 25 … 25예요."],"asset":{"type":"ldiv","a":875,"b":34,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_a#8','math',4,1,'u3','','g4_1_math_u3_review_a','unit_review','M4-1-u3-C10',1,'sa','auto','반찬 한 사람 몫의 탄소 발자국이에요 — 달걀말이 118 g, 두부조림 104 g, 배추김치 76 g. 세 반찬의 탄소 발자국을 모두 더하면 몇 g인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M4-1-u3-C10","difficulty":1,"kind":"sa","stem":"반찬 한 사람 몫의 탄소 발자국이에요 — 달걀말이 118 g, 두부조림 104 g, 배추김치 76 g. 세 반찬의 탄소 발자국을 모두 더하면 몇 g인가요? 숫자로 쓰세요.","answer":["298"],"explanation":["세 값을 차례로 더해요.","118 + 104 + 76 = 298.","한 사람 몫은 298 g이에요."],"variant_rule":{"alt":[{"stem":"반찬 한 사람 몫의 탄소 발자국이에요 — 잡곡밥 136 g, 깍두기 58 g, 두부조림 104 g. 세 반찬의 탄소 발자국을 모두 더하면 몇 g인가요? 숫자로 쓰세요.","answer":["298"],"explanation":["세 값을 차례로 더해요.","136 + 58 + 104 = 298.","한 사람 몫은 298 g이에요."],"asset":null},{"stem":"반찬 한 사람 몫의 탄소 발자국이에요 — 콩나물무침 58 g, 깍두기 58 g, 고등어조림 245 g. 세 반찬의 탄소 발자국을 모두 더하면 몇 g인가요? 숫자로 쓰세요.","answer":["361"],"explanation":["세 값을 차례로 더해요.","58 + 58 + 245 = 361.","한 사람 몫은 361 g이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_a#9','math',4,1,'u3','','g4_1_math_u3_review_a','unit_review','M4-1-u3-C3',2,'mc','auto','131 × 98은 얼마인가요?',ARRAY['M4-1-u3-X02','M4-1-u3-X03']::text[],true,'{"seq":9,"concept":"M4-1-u3-C3","difficulty":2,"kind":"mc","stem":"131 × 98은 얼마인가요?","options":[{"t":"12838","correct":true},{"t":"2227","mis":"M4-1-u3-X02"},{"t":"11790","mis":"M4-1-u3-X03"},{"t":"1048","mis":"M4-1-u3-X03"}],"explanation":["98을 90과 8로 쪼개요.","131 × 90 = 11790, 131 × 8 = 1048.","11790 + 1048 = 12838이에요."],"variant_rule":{"alt":[{"stem":"886 × 32는 얼마인가요?","options":[{"t":"28352","correct":true},{"t":"4430","mis":"M4-1-u3-X02"},{"t":"26580","mis":"M4-1-u3-X03"},{"t":"1772","mis":"M4-1-u3-X03"}],"explanation":["32를 30과 2로 쪼개요.","886 × 30 = 26580, 886 × 2 = 1772.","26580 + 1772 = 28352예요."],"asset":null},{"stem":"962 × 53은 얼마인가요?","options":[{"t":"50986","correct":true},{"t":"7696","mis":"M4-1-u3-X02"},{"t":"48100","mis":"M4-1-u3-X03"},{"t":"2886","mis":"M4-1-u3-X03"}],"explanation":["53을 50과 3으로 쪼개요.","962 × 50 = 48100, 962 × 3 = 2886.","48100 + 2886 = 50986이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_a#10','math',4,1,'u3','','g4_1_math_u3_review_a','unit_review','M4-1-u3-C4',2,'mc','auto','384 × 53을 몇백과 몇십으로 어림하면 약 얼마인가요?',ARRAY['M4-1-u3-X16','M4-1-u3-X15']::text[],true,'{"seq":10,"concept":"M4-1-u3-C4","difficulty":2,"kind":"mc","stem":"384 × 53을 몇백과 몇십으로 어림하면 약 얼마인가요?","options":[{"t":"약 20000","correct":true},{"t":"약 200000","mis":"M4-1-u3-X16"},{"t":"약 2000","mis":"M4-1-u3-X16"},{"t":"약 450","mis":"M4-1-u3-X15"}],"explanation":["384는 약 400, 53은 약 50이에요.","400 × 50 = 20000이에요 — 0의 개수를 세어 붙여요.","실제 곱 20352는 어림값 20000에 가까워요."],"variant_rule":{"alt":[{"stem":"712 × 56을 몇백과 몇십으로 어림하면 약 얼마인가요?","options":[{"t":"약 42000","correct":true},{"t":"약 420000","mis":"M4-1-u3-X16"},{"t":"약 4200","mis":"M4-1-u3-X16"},{"t":"약 760","mis":"M4-1-u3-X15"}],"explanation":["712는 약 700, 56은 약 60이에요.","700 × 60 = 42000이에요 — 0의 개수를 세어 붙여요.","실제 곱 39872는 어림값 42000에 가까워요."],"asset":null},{"stem":"555 × 34를 몇백과 몇십으로 어림하면 약 얼마인가요?","options":[{"t":"약 18000","correct":true},{"t":"약 180000","mis":"M4-1-u3-X16"},{"t":"약 1800","mis":"M4-1-u3-X16"},{"t":"약 630","mis":"M4-1-u3-X15"}],"explanation":["555는 약 600, 34는 약 30이에요.","600 × 30 = 18000이에요 — 0의 개수를 세어 붙여요.","실제 곱 18870은 어림값 18000에 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_a#11','math',4,1,'u3','','g4_1_math_u3_review_a','unit_review','M4-1-u3-C6',2,'mc','auto','189 ÷ 83 = 2 … 23이 맞는지 확인하는 식은 어느 것인가요?',ARRAY['M4-1-u3-X10','M4-1-u3-X15']::text[],true,'{"seq":11,"concept":"M4-1-u3-C6","difficulty":2,"kind":"mc","stem":"189 ÷ 83 = 2 … 23이 맞는지 확인하는 식은 어느 것인가요?","options":[{"t":"83 × 2 + 23 = 189","correct":true},{"t":"83 × 2 − 23 = 143","mis":"M4-1-u3-X10"},{"t":"189 × 83 + 23","mis":"M4-1-u3-X10"},{"t":"83 + 2 + 23 = 108","mis":"M4-1-u3-X15"}],"explanation":["확인은 (나누는 수) × (몫) + (나머지).","83 × 2 = 166, 166 + 23 = 189예요.","나누어지는 수 189와 같으니 바르게 계산했어요."],"asset":{"type":"expr_grid","rows":[["83 × 2","=","166"],["166 + 23","=","189"]]},"variant_rule":{"alt":[{"stem":"118 ÷ 43 = 2 … 32가 맞는지 확인하는 식은 어느 것인가요?","options":[{"t":"43 × 2 + 32 = 118","correct":true},{"t":"43 × 2 − 32 = 54","mis":"M4-1-u3-X10"},{"t":"118 × 43 + 32","mis":"M4-1-u3-X10"},{"t":"43 + 2 + 32 = 77","mis":"M4-1-u3-X15"}],"explanation":["확인은 (나누는 수) × (몫) + (나머지).","43 × 2 = 86, 86 + 32 = 118이에요.","나누어지는 수 118과 같으니 바르게 계산했어요."],"asset":{"type":"expr_grid","rows":[["43 × 2","=","86"],["86 + 32","=","118"]]}},{"stem":"144 ÷ 43 = 3 … 15가 맞는지 확인하는 식은 어느 것인가요?","options":[{"t":"43 × 3 + 15 = 144","correct":true},{"t":"43 × 3 − 15 = 114","mis":"M4-1-u3-X10"},{"t":"144 × 43 + 15","mis":"M4-1-u3-X10"},{"t":"43 + 3 + 15 = 61","mis":"M4-1-u3-X15"}],"explanation":["확인은 (나누는 수) × (몫) + (나머지).","43 × 3 = 129, 129 + 15 = 144예요.","나누어지는 수 144와 같으니 바르게 계산했어요."],"asset":{"type":"expr_grid","rows":[["43 × 3","=","129"],["129 + 15","=","144"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant