INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_a#12','math',4,1,'u3','','g4_1_math_u3_review_a','unit_review','M4-1-u3-C5',2,'mc','auto','123 ÷ 50을 계산하여 몫과 나머지를 바르게 구한 것은 어느 것인가요?',ARRAY['M4-1-u3-X07','M4-1-u3-X08','M4-1-u3-X09']::text[],true,'{"seq":12,"concept":"M4-1-u3-C5","difficulty":2,"kind":"mc","stem":"123 ÷ 50을 계산하여 몫과 나머지를 바르게 구한 것은 어느 것인가요?","options":[{"t":"몫 2, 나머지 23","correct":true},{"t":"몫 1, 나머지 73","mis":"M4-1-u3-X07"},{"t":"몫 3, 나머지 없음","mis":"M4-1-u3-X08"},{"t":"몫 2, 나머지 2","mis":"M4-1-u3-X09"}],"explanation":["123 ÷ 50 — 120은 십 모형 12개, 50은 십 모형 5개로 보면 12 ÷ 5와 같아요.","123 − 100 = 23 — 23은 50보다 작아요.","123 ÷ 50 = 2 … 23이에요."],"asset":{"type":"ldiv","a":123,"b":50,"upto":0},"variant_rule":{"alt":[{"stem":"228 ÷ 40을 계산하여 몫과 나머지를 바르게 구한 것은 어느 것인가요?","options":[{"t":"몫 5, 나머지 28","correct":true},{"t":"몫 4, 나머지 68","mis":"M4-1-u3-X07"},{"t":"몫 6, 나머지 없음","mis":"M4-1-u3-X08"},{"t":"몫 5, 나머지 2","mis":"M4-1-u3-X09"}],"explanation":["228 ÷ 40 — 220은 십 모형 22개, 40은 십 모형 4개로 보면 22 ÷ 4와 같아요.","228 − 200 = 28 — 28은 40보다 작아요.","228 ÷ 40 = 5 … 28이에요."],"asset":{"type":"ldiv","a":228,"b":40,"upto":0}},{"stem":"462 ÷ 50을 계산하여 몫과 나머지를 바르게 구한 것은 어느 것인가요?","options":[{"t":"몫 9, 나머지 12","correct":true},{"t":"몫 8, 나머지 62","mis":"M4-1-u3-X07"},{"t":"몫 10, 나머지 없음","mis":"M4-1-u3-X08"},{"t":"몫 9, 나머지 1","mis":"M4-1-u3-X09"}],"explanation":["462 ÷ 50 — 460은 십 모형 46개, 50은 십 모형 5개로 보면 46 ÷ 5와 같아요.","462 − 450 = 12 — 12는 50보다 작아요.","462 ÷ 50 = 9 … 12예요."],"asset":{"type":"ldiv","a":462,"b":50,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_a#13','math',4,1,'u3','','g4_1_math_u3_review_a','unit_review','M4-1-u3-C7',2,'sa','auto','78 ÷ 14의 몫을 4로 어림해 14 × 4 = 56을 빼니 22가 남았어요. 알맞은 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":13,"concept":"M4-1-u3-C7","difficulty":2,"kind":"sa","stem":"78 ÷ 14의 몫을 4로 어림해 14 × 4 = 56을 빼니 22가 남았어요. 알맞은 몫은 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["남은 22가 나누는 수 14보다 커요.","한 번 더 나눌 수 있으니 몫을 1 크게: 5.","알맞은 몫은 5예요."],"variant_rule":{"alt":[{"stem":"90 ÷ 22의 몫을 5로 어림했더니 22 × 5 = 110이 90보다 커요. 알맞은 몫은 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["곱 110이 90보다 커서 5는 너무 큰 몫이에요.","몫을 1 작게: 22 × 4 = 88.","알맞은 몫은 4예요."],"asset":null},{"stem":"92 ÷ 36의 몫을 3으로 어림했더니 36 × 3 = 108이 92보다 커요. 알맞은 몫은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["곱 108이 92보다 커서 3은 너무 큰 몫이에요.","몫을 1 작게: 36 × 2 = 72.","알맞은 몫은 2예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_a#14','math',4,1,'u3','','g4_1_math_u3_review_a','unit_review','M4-1-u3-C8',2,'mc','auto','172 ÷ 61을 계산하여 몫과 나머지를 바르게 구한 것은 어느 것인가요?',ARRAY['M4-1-u3-X07','M4-1-u3-X08','M4-1-u3-X14']::text[],true,'{"seq":14,"concept":"M4-1-u3-C8","difficulty":2,"kind":"mc","stem":"172 ÷ 61을 계산하여 몫과 나머지를 바르게 구한 것은 어느 것인가요?","options":[{"t":"몫 2, 나머지 50","correct":true},{"t":"몫 1, 나머지 111","mis":"M4-1-u3-X07"},{"t":"몫 3, 나머지 없음","mis":"M4-1-u3-X08"},{"t":"몫 50, 나머지 2","mis":"M4-1-u3-X14"}],"explanation":["61 × 2 = 122, 61 × 3 = 183 — 172를 넘지 않으면서 가장 가까운 곱을 찾아요.","172 − 122 = 50 — 50은 61보다 작아요.","172 ÷ 61 = 2 … 50이에요."],"asset":{"type":"ldiv","a":172,"b":61,"upto":0},"variant_rule":{"alt":[{"stem":"348 ÷ 67을 계산하여 몫과 나머지를 바르게 구한 것은 어느 것인가요?","options":[{"t":"몫 5, 나머지 13","correct":true},{"t":"몫 4, 나머지 80","mis":"M4-1-u3-X07"},{"t":"몫 6, 나머지 없음","mis":"M4-1-u3-X08"},{"t":"몫 13, 나머지 5","mis":"M4-1-u3-X14"}],"explanation":["67 × 5 = 335, 67 × 6 = 402 — 348을 넘지 않으면서 가장 가까운 곱을 찾아요.","348 − 335 = 13 — 13은 67보다 작아요.","348 ÷ 67 = 5 … 13이에요."],"asset":{"type":"ldiv","a":348,"b":67,"upto":0}},{"stem":"473 ÷ 49를 계산하여 몫과 나머지를 바르게 구한 것은 어느 것인가요?","options":[{"t":"몫 9, 나머지 32","correct":true},{"t":"몫 8, 나머지 81","mis":"M4-1-u3-X07"},{"t":"몫 10, 나머지 없음","mis":"M4-1-u3-X08"},{"t":"몫 32, 나머지 9","mis":"M4-1-u3-X14"}],"explanation":["49 × 9 = 441, 49 × 10 = 490 — 473을 넘지 않으면서 가장 가까운 곱을 찾아요.","473 − 441 = 32 — 32는 49보다 작아요.","473 ÷ 49 = 9 … 32예요."],"asset":{"type":"ldiv","a":473,"b":49,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_a#15','math',4,1,'u3','','g4_1_math_u3_review_a','unit_review','M4-1-u3-C9',2,'sa','auto','290 ÷ 11에서 먼저 11 × 20 = 220을 뺐어요. 남은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":15,"concept":"M4-1-u3-C9","difficulty":2,"kind":"sa","stem":"290 ÷ 11에서 먼저 11 × 20 = 220을 뺐어요. 남은 수는 얼마인가요? 숫자로 쓰세요.","answer":["70"],"explanation":["290 − 220 = 70이에요.","남은 70에 11이 6번 더 들어가요.","그래서 몫은 20 + 6 = 26이에요."],"asset":{"type":"ldiv","a":290,"b":11,"upto":1},"variant_rule":{"alt":[{"stem":"442 ÷ 14에서 먼저 14 × 30 = 420을 뺐어요. 남은 수는 얼마인가요? 숫자로 쓰세요.","answer":["22"],"explanation":["442 − 420 = 22예요.","남은 22에 14가 1번 더 들어가요.","그래서 몫은 30 + 1 = 31이에요."],"asset":{"type":"ldiv","a":442,"b":14,"upto":1}},{"stem":"255 ÷ 12에서 먼저 12 × 20 = 240을 뺐어요. 남은 수는 얼마인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["255 − 240 = 15예요.","남은 15에 12가 1번 더 들어가요.","그래서 몫은 20 + 1 = 21이에요."],"asset":{"type":"ldiv","a":255,"b":12,"upto":1}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_a#16','math',4,1,'u3','','g4_1_math_u3_review_a','unit_review','M4-1-u3-C10',2,'sa','auto','빈 병 한 개를 돌려주면 40원을 받아요. 640원을 받았다면 돌려준 빈 병은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":16,"concept":"M4-1-u3-C10","difficulty":2,"kind":"sa","stem":"빈 병 한 개를 돌려주면 40원을 받아요. 640원을 받았다면 돌려준 빈 병은 몇 개인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["받은 돈 ÷ 한 개에 받는 돈.","640 ÷ 40 = 16이에요.","빈 병 16개를 돌려줬어요."],"asset":{"type":"ldiv","a":640,"b":40,"upto":0},"variant_rule":{"alt":[{"stem":"빈 병 한 개를 돌려주면 70원을 받아요. 2100원을 받았다면 돌려준 빈 병은 몇 개인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["받은 돈 ÷ 한 개에 받는 돈.","2100 ÷ 70 = 30이에요.","빈 병 30개를 돌려줬어요."],"asset":{"type":"ldiv","a":2100,"b":70,"upto":0}},{"stem":"빈 병 한 개를 돌려주면 20원을 받아요. 260원을 받았다면 돌려준 빈 병은 몇 개인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["받은 돈 ÷ 한 개에 받는 돈.","260 ÷ 20 = 13이에요.","빈 병 13개를 돌려줬어요."],"asset":{"type":"ldiv","a":260,"b":20,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_a#17','math',4,1,'u3','','g4_1_math_u3_review_a','unit_review','M4-1-u3-C3',3,'mc','auto','하린이 367 × 37을 이렇게 계산해 13619라고 했어요. 바르게 계산하면 얼마인가요?',ARRAY['M4-1-u3-X05','M4-1-u3-X02','M4-1-u3-X03']::text[],true,'{"seq":17,"concept":"M4-1-u3-C3","difficulty":3,"kind":"mc","stem":"하린이 367 × 37을 이렇게 계산해 13619라고 했어요. 바르게 계산하면 얼마인가요?","options":[{"t":"13579","correct":true},{"t":"13619","mis":"M4-1-u3-X05"},{"t":"3670","mis":"M4-1-u3-X02"},{"t":"11010","mis":"M4-1-u3-X03"}],"explanation":["하린 — 셋째 줄의 올림을 넷째 줄에 다시 더했어요.","367 × 7 = 2569, 367 × 30 = 11010.","2569 + 11010 = 13579예요."],"asset":{"type":"expr_grid","rows":[["","","","3","6","7"],["×","","","","3","7"],["","","2","5","6","9"],["","1","1","0","5",""],["","1","3","6","1","9"]]},"variant_rule":{"alt":[{"stem":"건우가 615 × 57을 이렇게 계산해 7380이라고 했어요. 바르게 계산하면 얼마인가요?","options":[{"t":"35055","correct":true},{"t":"7380","mis":"M4-1-u3-X02"},{"t":"30750","mis":"M4-1-u3-X03"},{"t":"4305","mis":"M4-1-u3-X03"}],"explanation":["건우 — 넷째 줄을 한 칸 밀어 쓰지 않았어요.","615 × 7 = 4305, 615 × 50 = 30750.","4305 + 30750 = 35055예요."],"asset":{"type":"expr_grid","rows":[["","","","6","1","5"],["×","","","","5","7"],["","","4","3","0","5"],["","","3","0","7","5"],["","","7","3","8","0"]]}},{"stem":"지유가 357 × 38을 이렇게 계산해 13616이라고 했어요. 바르게 계산하면 얼마인가요?","options":[{"t":"13566","correct":true},{"t":"13616","mis":"M4-1-u3-X05"},{"t":"3927","mis":"M4-1-u3-X02"},{"t":"10710","mis":"M4-1-u3-X03"}],"explanation":["지유 — 셋째 줄의 올림을 넷째 줄에 다시 더했어요.","357 × 8 = 2856, 357 × 30 = 10710.","2856 + 10710 = 13566이에요."],"asset":{"type":"expr_grid","rows":[["","","","3","5","7"],["×","","","","3","8"],["","","2","8","5","6"],["","1","0","7","6",""],["","1","3","6","1","6"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficu