INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_a#18','math',4,1,'u3','','g4_1_math_u3_review_a','unit_review','M4-1-u3-C4',3,'mc','auto','도윤이 557 × 78을 계산해 8355라고 했어요. 어림해 보면 어떤가요?',ARRAY['M4-1-u3-X17','M4-1-u3-X14']::text[],true,'{"seq":18,"concept":"M4-1-u3-C4","difficulty":3,"kind":"mc","stem":"도윤이 557 × 78을 계산해 8355라고 했어요. 어림해 보면 어떤가요?","options":[{"t":"48000쯤인데 8355는 너무 작아요 — 잘못 계산했어요","correct":true},{"t":"어림값과 비슷하니 맞게 계산했어요","mis":"M4-1-u3-X17"},{"t":"어림으로는 맞았는지 알 수 없어요","mis":"M4-1-u3-X17"},{"t":"48000쯤인데 8355는 너무 커요 — 잘못 계산했어요","mis":"M4-1-u3-X14"}],"explanation":["557 × 78 — 약 600 × 80 = 48000.","8355는 어림값보다 훨씬 작아요.","바른 곱은 43446이에요."],"variant_rule":{"alt":[{"stem":"하린이 595 × 18을 계산해 5950이라고 했어요. 어림해 보면 어떤가요?","options":[{"t":"12000쯤인데 5950은 너무 작아요 — 잘못 계산했어요","correct":true},{"t":"어림값과 비슷하니 맞게 계산했어요","mis":"M4-1-u3-X17"},{"t":"어림으로는 맞았는지 알 수 없어요","mis":"M4-1-u3-X17"},{"t":"12000쯤인데 5950은 너무 커요 — 잘못 계산했어요","mis":"M4-1-u3-X14"}],"explanation":["595 × 18 — 약 600 × 20 = 12000.","5950은 어림값보다 훨씬 작아요.","바른 곱은 10710이에요."],"asset":null},{"stem":"하린이 742 × 42를 계산해 29680이라고 했어요. 어림해 보면 어떤가요?","options":[{"t":"28000쯤인데 29680은 너무 작아요 — 잘못 계산했어요","correct":true},{"t":"어림값과 비슷하니 맞게 계산했어요","mis":"M4-1-u3-X17"},{"t":"어림으로는 맞았는지 알 수 없어요","mis":"M4-1-u3-X17"},{"t":"28000쯤인데 29680은 너무 커요 — 잘못 계산했어요","mis":"M4-1-u3-X14"}],"explanation":["742 × 42 — 약 700 × 40 = 28000.","29680은 어림값보다 훨씬 작아요.","바른 곱은 31164예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_a#19','math',4,1,'u3','','g4_1_math_u3_review_a','unit_review','M4-1-u3-C5',3,'error','auto','친구들이 나눗셈을 했어요. 잘못 계산한 친구는 누구인가요?',ARRAY['M4-1-u3-X09','M4-1-u3-X14']::text[],true,'{"seq":19,"concept":"M4-1-u3-C5","difficulty":3,"kind":"error","stem":"친구들이 나눗셈을 했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"서준 — 842 ÷ 90 = 9 … 3","correct":true,"mis_target":"M4-1-u3-X09"},{"t":"은우 — 246 ÷ 50 = 4 … 46","mis":"M4-1-u3-X14"},{"t":"하린 — 316 ÷ 50 = 6 … 16","mis":"M4-1-u3-X14"}],"explanation":["842 ÷ 90 — 90 × 9 = 810.","842 − 810 = 32예요 — 나머지예요.","서준이 0을 지우고 84 ÷ 9를 계산해 나머지를 3으로 썼어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 친구들이 나눗셈을 했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"하린 — 431 ÷ 70 = 6 … 1","correct":true,"mis_target":"M4-1-u3-X09"},{"t":"도윤 — 188 ÷ 20 = 9 … 8","mis":"M4-1-u3-X14"},{"t":"시아 — 212 ÷ 80 = 2 … 52","mis":"M4-1-u3-X14"}],"explanation":["431 ÷ 70 — 70 × 6 = 420.","431 − 420 = 11이에요 — 나머지예요.","하린이 0을 지우고 43 ÷ 7을 계산해 나머지를 1로 썼어요."],"asset":null},{"stem":"이번에는 다른 수예요. 친구들이 나눗셈을 했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"지유 — 127 ÷ 50 = 2 … 2","correct":true,"mis_target":"M4-1-u3-X09"},{"t":"서준 — 218 ÷ 40 = 5 … 18","mis":"M4-1-u3-X14"},{"t":"건우 — 155 ÷ 30 = 5 … 5","mis":"M4-1-u3-X14"}],"explanation":["127 ÷ 50 — 50 × 2 = 100.","127 − 100 = 27이에요 — 나머지예요.","지유가 0을 지우고 12 ÷ 5를 계산해 나머지를 2로 썼어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_a#20','math',4,1,'u3','','g4_1_math_u3_review_a','unit_review','M4-1-u3-C9',3,'error','auto','하린이 451 ÷ 15 = 3 … 1이라고 계산했어요. 무엇이 잘못됐나요?',ARRAY['M4-1-u3-X11','M4-1-u3-X07','M4-1-u3-X08']::text[],true,'{"seq":20,"concept":"M4-1-u3-C9","difficulty":3,"kind":"error","stem":"하린이 451 ÷ 15 = 3 … 1이라고 계산했어요. 무엇이 잘못됐나요?","options":[{"t":"몫의 일의 자리에 0을 쓰지 않았어요","correct":true,"mis_target":"M4-1-u3-X11"},{"t":"나머지가 나누는 수보다 커요","mis":"M4-1-u3-X07"},{"t":"몫을 1 크게 해야 해요","mis":"M4-1-u3-X08"}],"explanation":["15 × 30 = 450 — 몫의 십의 자리 3.","남은 1이 15보다 작아 일의 자리 몫은 0.","바르게: 451 ÷ 15 = 30 … 1이에요."],"asset":{"type":"ldiv","a":451,"b":15},"variant_rule":{"alt":[{"stem":"서준이 255 ÷ 24 = 1 … 15라고 계산했어요. 무엇이 잘못됐나요?","options":[{"t":"몫의 일의 자리에 0을 쓰지 않았어요","correct":true,"mis_target":"M4-1-u3-X11"},{"t":"나머지가 나누는 수보다 커요","mis":"M4-1-u3-X07"},{"t":"몫을 1 크게 해야 해요","mis":"M4-1-u3-X08"}],"explanation":["24 × 10 = 240 — 몫의 십의 자리 1.","남은 15가 24보다 작아 일의 자리 몫은 0.","바르게: 255 ÷ 24 = 10 … 15예요."],"asset":{"type":"ldiv","a":255,"b":24}},{"stem":"서준이 263 ÷ 13 = 2 … 3이라고 계산했어요. 무엇이 잘못됐나요?","options":[{"t":"몫의 일의 자리에 0을 쓰지 않았어요","correct":true,"mis_target":"M4-1-u3-X11"},{"t":"나머지가 나누는 수보다 커요","mis":"M4-1-u3-X07"},{"t":"몫을 1 크게 해야 해요","mis":"M4-1-u3-X08"}],"explanation":["13 × 20 = 260 — 몫의 십의 자리 2.","남은 3이 13보다 작아 일의 자리 몫은 0.","바르게: 263 ÷ 13 = 20 … 3이에요."],"asset":{"type":"ldiv","a":263,"b":13}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_a#21','math',4,1,'u3','','g4_1_math_u3_review_a','unit_review','M4-1-u3-C10',3,'mc','auto','돈 422원으로 54원짜리 지우개를 사려고 해요. 지우개를 몇 개까지 살 수 있나요?',ARRAY['M4-1-u3-X13','M4-1-u3-X14','M4-1-u3-X15']::text[],true,'{"seq":21,"concept":"M4-1-u3-C10","difficulty":3,"kind":"mc","stem":"돈 422원으로 54원짜리 지우개를 사려고 해요. 지우개를 몇 개까지 살 수 있나요?","options":[{"t":"7개","correct":true},{"t":"8개","mis":"M4-1-u3-X13"},{"t":"44개","mis":"M4-1-u3-X14"},{"t":"51개","mis":"M4-1-u3-X15"}],"explanation":["422 ÷ 54 = 7 … 44.","남은 44는 하나를 다 채우지 못해요.","답은 7개예요."],"variant_rule":{"alt":[{"stem":"리본 201 cm로 75 cm짜리 머리끈을 만들려고 해요. 머리끈을 몇 개까지 만들 수 있나요?","options":[{"t":"2개","correct":true},{"t":"3개","mis":"M4-1-u3-X13"},{"t":"51개","mis":"M4-1-u3-X14"},{"t":"53개","mis":"M4-1-u3-X15"}],"explanation":["201 ÷ 75 = 2 … 51.","남은 51은 하나를 다 채우지 못해요.","답은 2개예요."],"asset":null},{"stem":"사과 460개를 한 상자에 89개씩 남김없이 모두 담으려고 해요. 상자는 적어도 몇 개 필요한가요?","options":[{"t":"6개","correct":true},{"t":"5개","mis":"M4-1-u3-X13"},{"t":"15개","mis":"M4-1-u3-X14"},{"t":"20개","mis":"M4-1-u3-X15"}],"explanation":["460 ÷ 89 = 5 … 15.","남은 15도 담아야 하니 하나 더 — 5 + 1 = 6.","답은 6개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_a#22','math',4,1,'u3','','g4_1_math_u3_review_a','unit_review','M4-1-u3-C6',3,'sa','auto','어떤 수를 34로 나누었더니 몫이 8, 나머지가 2가 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":22,"concept":"M4-1-u3-C6","difficulty":3,"kind":"sa","stem":"어떤 수를 34로 나누었더니 몫이 8, 나머지가 2가 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["274"],"explanation":["나누어지는 수 = (나누는 수) × (몫) + (나머지).","34 × 8 = 272.","272 + 2 = 274 — 어떤 수는 274예요."],"asset":{"type":"expr_grid","rows":[["34 × 8","=","272"],["272 + 2","=",null]]},"variant_rule":{"alt":[{"stem":"어떤 수를 76으로 나누었더니 몫이 4, 나머지가 19가 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["323"],"explanation":["나누어지는 수 = (나누는 수) × (몫) + (나머지).","76 × 4 = 304.","304 + 19 = 323 — 어떤 수는 323이에요."],"asset":{"type":"expr_grid","rows":[["76 × 4","=","304"],["304 + 19","=",null]]}},{"stem":"어떤 수를 76으로 나누었더니 몫이 6, 나머지가 13이 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["469"],"explanation":["나누어지는 수 = (나누는 수) × (몫) + (나머지).","76 × 6 = 456.","456 + 13 = 469 — 어떤 수는 469예요."],"asset":{"type":"expr_grid","rows":[["76 × 6","=","456"],["456 + 13","=",null]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_a#23','math',4,1,'u3','','g4_1_math_u3_review_a','unit_review','M4-1-u3-C3',4,'mc','auto','수 카드 3, 5, 1, 8, 9를 한 번씩 모두 써서 (세 자리 수) × (두 자리 수)를 만들려고 해요. 가장 큰 곱은 얼마인가요?',ARRAY['M4-1-u3-X14','M4-1-u3-X16']::text[],true,'{"seq":23,"concept":"M4-1-u3-C3","difficulty":4,"kind":"mc","stem":"수 카드 3, 5, 1, 8, 9를 한 번씩 모두 써서 (세 자리 수) × (두 자리 수)를 만들려고 해요. 가장 큰 곱은 얼마인가요?","options":[{"t":"79143","correct":true},{"t":"30535","mis":"M4-1-u3-X14"},{"t":"78933","mis":"M4-1-u3-X14"},{"t":"7914","mis":"M4-1-u3-X16"}],"explanation":["가장 큰 두 숫자를 두 수의 맨 앞(백의 자리·십의 자리)에 나누어 놓아요.","여러 가지로 놓아 곱을 견주면 851 × 93이 가장 커요.","851 × 93 = 79143이에요."],"variant_rule":{"alt":[{"stem":"수 카드 2, 1, 3, 5, 8을 한 번씩 모두 써서 (세 자리 수) × (두 자리 수)를 만들려고 해요. 가장 큰 곱은 얼마인가요?","options":[{"t":"43542","correct":true},{"t":"17913","mis":"M4-1-u3-X14"},{"t":"43212","mis":"M4-1-u3-X14"},{"t":"4354","mis":"M4-1-u3-X16"}],"explanation":["가장 큰 두 숫자를 두 수의 맨 앞(백의 자리·십의 자리)에 나누어 놓아요.","여러 가지로 놓아 곱을 견주면 531 × 82가 가장 커요.","531 × 82 = 43542예요."],"asset":null},{"stem":"수 카드 4, 3, 2, 6, 8을 한 번씩 모두 써서 (세 자리 수) × (두 자리 수)를 만들려고 해요. 가장 큰 곱은 얼마인가요?","options":[{"t":"53286","correct":true},{"t":"27648","mis":"M4-1-u3-X14"},{"t":"53046","mis":"M4-1-u3-X14"},{"t":"5328","mis":"M4-1-u3-X16"}],"explanation":["가장 큰 두 숫자를 두 수의 맨 앞(백의 자리·십의 자리)에 나누어 놓아요.","여러 가지로 놓아 곱을 견주면 642 × 83이 가장 커요.","642 × 83 = 53286이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_a#24','math',4,1,'u3','','g4_1_math_u3_review_a','unit_review','M4-1-u3-C10',4,'mc','auto','오늘 반찬은 한 사람에 637 g, 내일 반찬은 한 사람에 356 g이에요. 29명이 먹을 때 내일은 오늘보다 탄소 발자국이 몇 g 줄어드나요?',ARRAY['M4-1-u3-X18','M4-1-u3-X15']::text[],true,'{"seq":24,"concept":"M4-1-u3-C10","difficulty":4,"kind":"mc","stem":"오늘 반찬은 한 사람에 637 g, 내일 반찬은 한 사람에 356 g이에요. 29명이 먹을 때 내일은 오늘보다 탄소 발자국이 몇 g 줄어드나요?","options":[{"t":"8149 g","correct":true},{"t":"281 g","mis":"M4-1-u3-X18"},{"t":"28797 g","mis":"M4-1-u3-X15"},{"t":"10324 g","mis":"M4-1-u3-X18"}],"explanation":["오늘 637 × 29 = 18473 g.","내일 356 × 29 = 10324 g.","18473 − 10324 = 8149 g 줄어요."],"variant_rule":{"alt":[{"stem":"오늘 반찬은 한 사람에 608 g, 내일 반찬은 한 사람에 329 g이에요. 28명이 먹을 때 내일은 오늘보다 탄소 발자국이 몇 g 줄어드나요?","options":[{"t":"7812 g","correct":true},{"t":"279 g","mis":"M4-1-u3-X18"},{"t":"26236 g","mis":"M4-1-u3-X15"},{"t":"9212 g","mis":"M4-1-u3-X18"}],"explanation":["오늘 608 × 28 = 17024 g.","내일 329 × 28 = 9212 g.","17024 − 9212 = 7812 g 줄어요."],"asset":null},{"stem":"오늘 반찬은 한 사람에 584 g, 내일 반찬은 한 사람에 309 g이에요. 30명이 먹을 때 내일은 오늘보다 탄소 발자국이 몇 g 줄어드나요?","options":[{"t":"8250 g","correct":true},{"t":"275 g","mis":"M4-1-u3-X18"},{"t":"26790 g","mis":"M4-1-u3-X15"},{"t":"9270 g","mis":"M4-1-u3-X18"}],"explanation":["오늘 584 × 30 = 17520 g.","내일 309 × 30 = 9270 g.","17520 − 9270 = 8250 g 줄어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_a#25','math',4,1,'u3','','g4_1_math_u3_review_a','unit_review','M4-1-u3-C3',4,'essay','teacher','친구가 405 × 34를 계산하며 405 × 3 = 1215를 한 칸 밀지 않고 써서 1620 + 1215 = 2835라고 했어요. 무엇이 잘못됐는지 쓰고 바르게 계산해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M4-1-u3-C3","difficulty":4,"kind":"essay","stem":"친구가 405 × 34를 계산하며 405 × 3 = 1215를 한 칸 밀지 않고 써서 1620 + 1215 = 2835라고 했어요. 무엇이 잘못됐는지 쓰고 바르게 계산해 보세요.","answer_guide":{"answer":"예: 405 × 3은 십의 자리 3을 곱한 것이라 실제로는 405 × 30 = 12150이므로 한 칸 밀어 써야 한다. 405 × 4 = 1620, 405 × 30 = 12150, 1620 + 12150 = 13770이다.","scoring_points":["한 칸 밀어 쓰지 않은 것을 찾았는가","405 × 30 = 12150을 구했는가","13770을 구했는가"]},"explanation":["405 × 4 = 1620.","405 × 30 = 12150(한 칸 밀기).","1620 + 12150 = 13770."],"asset":{"type":"expr_grid","rows":[["","","","4","0","5"],["×","","","","3","4"],["","","1","6","2","0"],["","","1","2","1","5"],["","","2","8","3","5"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_b#1','math',4,1,'u3','','g4_1_math_u3_review_b','unit_review','M4-1-u3-C2',1,'sa','auto','138 × 30은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-1-u3-C2","difficulty":1,"kind":"sa","stem":"138 × 30은 얼마인가요? 숫자로 쓰세요.","answer":["4140"],"explanation":["138 × 3 = 414 — 먼저 몇을 곱해요.","곱하는 수가 10배(3 → 30)라서 곱도 10배예요.","138 × 30 = 4140이에요."],"variant_rule":{"alt":[{"stem":"202 × 40은 얼마인가요? 숫자로 쓰세요.","answer":["8080"],"explanation":["202 × 4 = 808 — 먼저 몇을 곱해요.","곱하는 수가 10배(4 → 40)라서 곱도 10배예요.","202 × 40 = 8080이에요."],"asset":null},{"stem":"153 × 40은 얼마인가요? 숫자로 쓰세요.","answer":["6120"],"explanation":["153 × 4 = 612 — 먼저 몇을 곱해요.","곱하는 수가 10배(4 → 40)라서 곱도 10배예요.","153 × 40 = 6120이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_b#2','math',4,1,'u3','','g4_1_math_u3_review_b','unit_review','M4-1-u3-C1',1,'sa','auto','398 × 25를 아는 계산으로 쪼갰어요. 398 × 25 = 398 × 20 + 398 × □에서 □ 안에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-1-u3-C1","difficulty":1,"kind":"sa","stem":"398 × 25를 아는 계산으로 쪼갰어요. 398 × 25 = 398 × 20 + 398 × □에서 □ 안에 알맞은 수를 쓰세요.","answer":["5"],"explanation":["25는 20과 5의 합이에요.","25번 더한 것 = 20번 더하고 5번 더 더한 것.","□ = 5예요."],"asset":{"type":"expr_grid","rows":[["398 × 20","=","7960"],["398 × 5","=","1990"],["7960 + 1990","=","9950"]]},"variant_rule":{"alt":[{"stem":"232 × 27을 아는 계산으로 쪼갰어요. 232 × 27 = 232 × 20 + 232 × □에서 □ 안에 알맞은 수를 쓰세요.","answer":["7"],"explanation":["27은 20과 7의 합이에요.","27번 더한 것 = 20번 더하고 7번 더 더한 것.","□ = 7이에요."],"asset":{"type":"expr_grid","rows":[["232 × 20","=","4640"],["232 × 7","=","1624"],["4640 + 1624","=","6264"]]}},{"stem":"887 × 45를 아는 계산으로 쪼갰어요. 887 × 45 = 887 × 40 + 887 × □에서 □ 안에 알맞은 수를 쓰세요.","answer":["5"],"explanation":["45는 40과 5의 합이에요.","45번 더한 것 = 40번 더하고 5번 더 더한 것.","□ = 5예요."],"asset":{"type":"expr_grid","rows":[["887 × 40","=","35480"],["887 × 5","=","4435"],["35480 + 4435","=","39915"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_b#3','math',4,1,'u3','','g4_1_math_u3_review_b','unit_review','M4-1-u3-C3',1,'sa','auto','312 × 18의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-1-u3-C3","difficulty":1,"kind":"sa","stem":"312 × 18의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["1"],"explanation":["일의 자리 8을 먼저 곱하고, 십의 자리 1을 곱한 값은 한 칸 밀어 써요.","넷째 줄은 312 × 1 = 312 — 한 칸 밀어 써서 3120을 나타내요.","?는 백의 자리 숫자 1이에요."],"asset":{"type":"expr_grid","rows":[["","","","3","1","2"],["×","","","","1","8"],["","","2","4","9","6"],["","","3",null,"2",""],["","","5","6","1","6"]]},"variant_rule":{"alt":[{"stem":"314 × 13의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["4"],"explanation":["일의 자리 3을 먼저 곱하고, 십의 자리 1을 곱한 값은 한 칸 밀어 써요.","넷째 줄은 314 × 1 = 314 — 한 칸 밀어 써서 3140을 나타내요.","?는 십의 자리 숫자 4예요."],"asset":{"type":"expr_grid","rows":[["","","","3","1","4"],["×","","","","1","3"],["","","","9","4","2"],["","","3","1",null,""],["","","4","0","8","2"]]}},{"stem":"162 × 25의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["8"],"explanation":["일의 자리 5를 먼저 곱하고, 십의 자리 2를 곱한 값은 한 칸 밀어 써요.","셋째 줄은 162 × 5 = 810이에요.","?는 백의 자리 숫자 8이에요."],"asset":{"type":"expr_grid","rows":[["","","","1","6","2"],["×","","","","2","5"],["","","",null,"1","0"],["","","3","2","4",""],["","","4","0","5","0"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_b#4','math',4,1,'u3','','g4_1_math_u3_review_b','unit_review','M4-1-u3-C5',1,'sa','auto','399 ÷ 50의 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-1-u3-C5","difficulty":1,"kind":"sa","stem":"399 ÷ 50의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["399 ÷ 50 — 390은 십 모형 39개, 50은 십 모형 5개로 보면 39 ÷ 5와 같아요.","399 − 350 = 49 — 49는 50보다 작아요.","399 ÷ 50 = 7 … 49예요."],"asset":{"type":"ldiv","a":399,"b":50,"upto":0},"variant_rule":{"alt":[{"stem":"199 ÷ 20의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["199 ÷ 20 — 190은 십 모형 19개, 20은 십 모형 2개로 보면 19 ÷ 2와 같아요.","199 − 180 = 19 — 19는 20보다 작아요.","199 ÷ 20 = 9 … 19예요."],"asset":{"type":"ldiv","a":199,"b":20,"upto":0}},{"stem":"574 ÷ 60의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["574 ÷ 60 — 570은 십 모형 57개, 60은 십 모형 6개로 보면 57 ÷ 6과 같아요.","574 − 540 = 34 — 34는 60보다 작아요.","574 ÷ 60 = 9 … 34예요."],"asset":{"type":"ldiv","a":574,"b":60,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_b#5','math',4,1,'u3','','g4_1_math_u3_review_b','unit_review','M4-1-u3-C7',1,'sa','auto','61 ÷ 16의 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-1-u3-C7","difficulty":1,"kind":"sa","stem":"61 ÷ 16의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["16 × 3 = 48, 16 × 4 = 64 — 61을 넘지 않으면서 가장 가까운 곱을 찾아요.","61 − 48 = 13 — 13은 16보다 작아요.","61 ÷ 16 = 3 … 13이에요."],"asset":{"type":"ldiv","a":61,"b":16,"upto":0},"variant_rule":{"alt":[{"stem":"75 ÷ 14의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["14 × 5 = 70, 14 × 6 = 84 — 75를 넘지 않으면서 가장 가까운 곱을 찾아요.","75 − 70 = 5 — 5는 14보다 작아요.","75 ÷ 14 = 5 … 5예요."],"asset":{"type":"ldiv","a":75,"b":14,"upto":0}},{"stem":"66 ÷ 24의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["24 × 2 = 48, 24 × 3 = 72 — 66을 넘지 않으면서 가장 가까운 곱을 찾아요.","66 − 48 = 18 — 18은 24보다 작아요.","66 ÷ 24 = 2 … 18이에요."],"asset":{"type":"ldiv","a":66,"b":24,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_b#6','math',4,1,'u3','','g4_1_math_u3_review_b','unit_review','M4-1-u3-C8',1,'sa','auto','263 ÷ 33의 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M4-1-u3-C8","difficulty":1,"kind":"sa","stem":"263 ÷ 33의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["33 × 7 = 231, 33 × 8 = 264 — 263을 넘지 않으면서 가장 가까운 곱을 찾아요.","263 − 231 = 32 — 32는 33보다 작아요.","263 ÷ 33 = 7 … 32예요."],"asset":{"type":"ldiv","a":263,"b":33,"upto":0},"variant_rule":{"alt":[{"stem":"607 ÷ 78의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["78 × 7 = 546, 78 × 8 = 624 — 607을 넘지 않으면서 가장 가까운 곱을 찾아요.","607 − 546 = 61 — 61은 78보다 작아요.","607 ÷ 78 = 7 … 61이에요."],"asset":{"type":"ldiv","a":607,"b":78,"upto":0}},{"stem":"229 ÷ 24의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["24 × 9 = 216, 24 × 10 = 240 — 229를 넘지 않으면서 가장 가까운 곱을 찾아요.","229 − 216 = 13 — 13은 24보다 작아요.","229 ÷ 24 = 9 … 13이에요."],"asset":{"type":"ldiv","a":229,"b":24,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_b#7','math',4,1,'u3','','g4_1_math_u3_review_b','unit_review','M4-1-u3-C9',1,'sa','auto','542 ÷ 21의 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M4-1-u3-C9","difficulty":1,"kind":"sa","stem":"542 ÷ 21의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["먼저 몇십 번: 21 × 20 = 420 → 122가 남아요.","542 − 525 = 17 — 17은 21보다 작아요.","542 ÷ 21 = 25 … 17이에요."],"asset":{"type":"ldiv","a":542,"b":21,"upto":0},"variant_rule":{"alt":[{"stem":"507 ÷ 23의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["22"],"explanation":["먼저 몇십 번: 23 × 20 = 460 → 47이 남아요.","507 − 506 = 1 — 1은 23보다 작아요.","507 ÷ 23 = 22 … 1이에요."],"asset":{"type":"ldiv","a":507,"b":23,"upto":0}},{"stem":"614 ÷ 11의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["55"],"explanation":["먼저 몇십 번: 11 × 50 = 550 → 64가 남아요.","614 − 605 = 9 — 9는 11보다 작아요.","614 ÷ 11 = 55 … 9예요."],"asset":{"type":"ldiv","a":614,"b":11,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_b#8','math',4,1,'u3','','g4_1_math_u3_review_b','unit_review','M4-1-u3-C10',1,'sa','auto','반찬 한 사람 몫의 탄소 발자국이에요 — 닭볶음 312 g, 잡곡밥 136 g, 고등어조림 245 g. 세 반찬의 탄소 발자국을 모두 더하면 몇 g인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M4-1-u3-C10","difficulty":1,"kind":"sa","stem":"반찬 한 사람 몫의 탄소 발자국이에요 — 닭볶음 312 g, 잡곡밥 136 g, 고등어조림 245 g. 세 반찬의 탄소 발자국을 모두 더하면 몇 g인가요? 숫자로 쓰세요.","answer":["693"],"explanation":["세 값을 차례로 더해요.","312 + 136 + 245 = 693.","한 사람 몫은 693 g이에요."],"variant_rule":{"alt":[{"stem":"반찬 한 사람 몫의 탄소 발자국이에요 — 달걀말이 118 g, 닭볶음 312 g, 고등어조림 245 g. 세 반찬의 탄소 발자국을 모두 더하면 몇 g인가요? 숫자로 쓰세요.","answer":["675"],"explanation":["세 값을 차례로 더해요.","118 + 312 + 245 = 675.","한 사람 몫은 675 g이에요."],"asset":null},{"stem":"반찬 한 사람 몫의 탄소 발자국이에요 — 미역국 92 g, 잡곡밥 136 g, 배추김치 76 g. 세 반찬의 탄소 발자국을 모두 더하면 몇 g인가요? 숫자로 쓰세요.","answer":["304"],"explanation":["세 값을 차례로 더해요.","92 + 136 + 76 = 304.","한 사람 몫은 304 g이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_b#9','math',4,1,'u3','','g4_1_math_u3_review_b','unit_review','M4-1-u3-C3',2,'mc','auto','596 × 89는 얼마인가요?',ARRAY['M4-1-u3-X02','M4-1-u3-X03']::text[],true,'{"seq":9,"concept":"M4-1-u3-C3","difficulty":2,"kind":"mc","stem":"596 × 89는 얼마인가요?","options":[{"t":"53044","correct":true},{"t":"10132","mis":"M4-1-u3-X02"},{"t":"47680","mis":"M4-1-u3-X03"},{"t":"5364","mis":"M4-1-u3-X03"}],"explanation":["89를 80과 9로 쪼개요.","596 × 80 = 47680, 596 × 9 = 5364.","47680 + 5364 = 53044예요."],"variant_rule":{"alt":[{"stem":"543 × 35는 얼마인가요?","options":[{"t":"19005","correct":true},{"t":"4344","mis":"M4-1-u3-X02"},{"t":"16290","mis":"M4-1-u3-X03"},{"t":"2715","mis":"M4-1-u3-X03"}],"explanation":["35를 30과 5로 쪼개요.","543 × 30 = 16290, 543 × 5 = 2715.","16290 + 2715 = 19005예요."],"asset":null},{"stem":"966 × 18은 얼마인가요?","options":[{"t":"17388","correct":true},{"t":"8694","mis":"M4-1-u3-X02"},{"t":"9660","mis":"M4-1-u3-X03"},{"t":"7728","mis":"M4-1-u3-X03"}],"explanation":["18을 10과 8로 쪼개요.","966 × 10 = 9660, 966 × 8 = 7728.","9660 + 7728 = 17388이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_b#10','math',4,1,'u3','','g4_1_math_u3_review_b','unit_review','M4-1-u3-C4',2,'mc','auto','856 × 18을 몇백과 몇십으로 어림하면 약 얼마인가요?',ARRAY['M4-1-u3-X16','M4-1-u3-X15']::text[],true,'{"seq":10,"concept":"M4-1-u3-C4","difficulty":2,"kind":"mc","stem":"856 × 18을 몇백과 몇십으로 어림하면 약 얼마인가요?","options":[{"t":"약 18000","correct":true},{"t":"약 180000","mis":"M4-1-u3-X16"},{"t":"약 1800","mis":"M4-1-u3-X16"},{"t":"약 920","mis":"M4-1-u3-X15"}],"explanation":["856은 약 900, 18은 약 20이에요.","900 × 20 = 18000이에요 — 0의 개수를 세어 붙여요.","실제 곱 15408은 어림값 18000에 가까워요."],"variant_rule":{"alt":[{"stem":"651 × 69를 몇백과 몇십으로 어림하면 약 얼마인가요?","options":[{"t":"약 49000","correct":true},{"t":"약 490000","mis":"M4-1-u3-X16"},{"t":"약 4900","mis":"M4-1-u3-X16"},{"t":"약 770","mis":"M4-1-u3-X15"}],"explanation":["651은 약 700, 69는 약 70이에요.","700 × 70 = 49000이에요 — 0의 개수를 세어 붙여요.","실제 곱 44919는 어림값 49000에 가까워요."],"asset":null},{"stem":"663 × 49를 몇백과 몇십으로 어림하면 약 얼마인가요?","options":[{"t":"약 35000","correct":true},{"t":"약 350000","mis":"M4-1-u3-X16"},{"t":"약 3500","mis":"M4-1-u3-X16"},{"t":"약 750","mis":"M4-1-u3-X15"}],"explanation":["663은 약 700, 49는 약 50이에요.","700 × 50 = 35000이에요 — 0의 개수를 세어 붙여요.","실제 곱 32487은 어림값 35000에 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_b#11','math',4,1,'u3','','g4_1_math_u3_review_b','unit_review','M4-1-u3-C6',2,'mc','auto','342 ÷ 53 = 6 … 24가 맞는지 확인하는 식은 어느 것인가요?',ARRAY['M4-1-u3-X10','M4-1-u3-X15']::text[],true,'{"seq":11,"concept":"M4-1-u3-C6","difficulty":2,"kind":"mc","stem":"342 ÷ 53 = 6 … 24가 맞는지 확인하는 식은 어느 것인가요?","options":[{"t":"53 × 6 + 24 = 342","correct":true},{"t":"53 × 6 − 24 = 294","mis":"M4-1-u3-X10"},{"t":"342 × 53 + 24","mis":"M4-1-u3-X10"},{"t":"53 + 6 + 24 = 83","mis":"M4-1-u3-X15"}],"explanation":["확인은 (나누는 수) × (몫) + (나머지).","53 × 6 = 318, 318 + 24 = 342예요.","나누어지는 수 342와 같으니 바르게 계산했어요."],"asset":{"type":"expr_grid","rows":[["53 × 6","=","318"],["318 + 24","=","342"]]},"variant_rule":{"alt":[{"stem":"390 ÷ 46 = 8 … 22가 맞는지 확인하는 식은 어느 것인가요?","options":[{"t":"46 × 8 + 22 = 390","correct":true},{"t":"46 × 8 − 22 = 346","mis":"M4-1-u3-X10"},{"t":"390 × 46 + 22","mis":"M4-1-u3-X10"},{"t":"46 + 8 + 22 = 76","mis":"M4-1-u3-X15"}],"explanation":["확인은 (나누는 수) × (몫) + (나머지).","46 × 8 = 368, 368 + 22 = 390이에요.","나누어지는 수 390과 같으니 바르게 계산했어요."],"asset":{"type":"expr_grid","rows":[["46 × 8","=","368"],["368 + 22","=","390"]]}},{"stem":"565 ÷ 64 = 8 … 53이 맞는지 확인하는 식은 어느 것인가요?","options":[{"t":"64 × 8 + 53 = 565","correct":true},{"t":"64 × 8 − 53 = 459","mis":"M4-1-u3-X10"},{"t":"565 × 64 + 53","mis":"M4-1-u3-X10"},{"t":"64 + 8 + 53 = 125","mis":"M4-1-u3-X15"}],"explanation":["확인은 (나누는 수) × (몫) + (나머지).","64 × 8 = 512, 512 + 53 = 565예요.","나누어지는 수 565와 같으니 바르게 계산했어요."],"asset":{"type":"expr_grid","rows":[["64 × 8","=","512"],["512 + 53","=","565"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_b#12','math',4,1,'u3','','g4_1_math_u3_review_b','unit_review','M4-1-u3-C5',2,'mc','auto','501 ÷ 60을 계산하여 몫과 나머지를 바르게 구한 것은 어느 것인가요?',ARRAY['M4-1-u3-X07','M4-1-u3-X08','M4-1-u3-X09']::text[],true,'{"seq":12,"concept":"M4-1-u3-C5","difficulty":2,"kind":"mc","stem":"501 ÷ 60을 계산하여 몫과 나머지를 바르게 구한 것은 어느 것인가요?","options":[{"t":"몫 8, 나머지 21","correct":true},{"t":"몫 7, 나머지 81","mis":"M4-1-u3-X07"},{"t":"몫 9, 나머지 없음","mis":"M4-1-u3-X08"},{"t":"몫 8, 나머지 2","mis":"M4-1-u3-X09"}],"explanation":["501 ÷ 60 — 500은 십 모형 50개, 60은 십 모형 6개로 보면 50 ÷ 6과 같아요.","501 − 480 = 21 — 21은 60보다 작아요.","501 ÷ 60 = 8 … 21이에요."],"asset":{"type":"ldiv","a":501,"b":60,"upto":0},"variant_rule":{"alt":[{"stem":"557 ÷ 80을 계산하여 몫과 나머지를 바르게 구한 것은 어느 것인가요?","options":[{"t":"몫 6, 나머지 77","correct":true},{"t":"몫 5, 나머지 157","mis":"M4-1-u3-X07"},{"t":"몫 7, 나머지 없음","mis":"M4-1-u3-X08"},{"t":"몫 6, 나머지 7","mis":"M4-1-u3-X09"}],"explanation":["557 ÷ 80 — 550은 십 모형 55개, 80은 십 모형 8개로 보면 55 ÷ 8과 같아요.","557 − 480 = 77 — 77은 80보다 작아요.","557 ÷ 80 = 6 … 77이에요."],"asset":{"type":"ldiv","a":557,"b":80,"upto":0}},{"stem":"372 ÷ 60을 계산하여 몫과 나머지를 바르게 구한 것은 어느 것인가요?","options":[{"t":"몫 6, 나머지 12","correct":true},{"t":"몫 5, 나머지 72","mis":"M4-1-u3-X07"},{"t":"몫 7, 나머지 없음","mis":"M4-1-u3-X08"},{"t":"몫 6, 나머지 1","mis":"M4-1-u3-X09"}],"explanation":["372 ÷ 60 — 370은 십 모형 37개, 60은 십 모형 6개로 보면 37 ÷ 6과 같아요.","372 − 360 = 12 — 12는 60보다 작아요.","372 ÷ 60 = 6 … 12예요."],"asset":{"type":"ldiv","a":372,"b":60,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_b#13','math',4,1,'u3','','g4_1_math_u3_review_b','unit_review','M4-1-u3-C7',2,'sa','auto','68 ÷ 19의 몫을 2로 어림해 19 × 2 = 38을 빼니 30이 남았어요. 알맞은 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":13,"concept":"M4-1-u3-C7","difficulty":2,"kind":"sa","stem":"68 ÷ 19의 몫을 2로 어림해 19 × 2 = 38을 빼니 30이 남았어요. 알맞은 몫은 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["남은 30이 나누는 수 19보다 커요.","한 번 더 나눌 수 있으니 몫을 1 크게: 3.","알맞은 몫은 3이에요."],"variant_rule":{"alt":[{"stem":"55 ÷ 19의 몫을 3으로 어림했더니 19 × 3 = 57이 55보다 커요. 알맞은 몫은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["곱 57이 55보다 커서 3은 너무 큰 몫이에요.","몫을 1 작게: 19 × 2 = 38.","알맞은 몫은 2예요."],"asset":null},{"stem":"35 ÷ 17의 몫을 3으로 어림했더니 17 × 3 = 51이 35보다 커요. 알맞은 몫은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["곱 51이 35보다 커서 3은 너무 큰 몫이에요.","몫을 1 작게: 17 × 2 = 34.","알맞은 몫은 2예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_b#14','math',4,1,'u3','','g4_1_math_u3_review_b','unit_review','M4-1-u3-C8',2,'mc','auto','363 ÷ 78을 계산하여 몫과 나머지를 바르게 구한 것은 어느 것인가요?',ARRAY['M4-1-u3-X07','M4-1-u3-X08','M4-1-u3-X14']::text[],true,'{"seq":14,"concept":"M4-1-u3-C8","difficulty":2,"kind":"mc","stem":"363 ÷ 78을 계산하여 몫과 나머지를 바르게 구한 것은 어느 것인가요?","options":[{"t":"몫 4, 나머지 51","correct":true},{"t":"몫 3, 나머지 129","mis":"M4-1-u3-X07"},{"t":"몫 5, 나머지 없음","mis":"M4-1-u3-X08"},{"t":"몫 51, 나머지 4","mis":"M4-1-u3-X14"}],"explanation":["78 × 4 = 312, 78 × 5 = 390 — 363을 넘지 않으면서 가장 가까운 곱을 찾아요.","363 − 312 = 51 — 51은 78보다 작아요.","363 ÷ 78 = 4 … 51이에요."],"asset":{"type":"ldiv","a":363,"b":78,"upto":0},"variant_rule":{"alt":[{"stem":"557 ÷ 72를 계산하여 몫과 나머지를 바르게 구한 것은 어느 것인가요?","options":[{"t":"몫 7, 나머지 53","correct":true},{"t":"몫 6, 나머지 125","mis":"M4-1-u3-X07"},{"t":"몫 8, 나머지 없음","mis":"M4-1-u3-X08"},{"t":"몫 53, 나머지 7","mis":"M4-1-u3-X14"}],"explanation":["72 × 7 = 504, 72 × 8 = 576 — 557을 넘지 않으면서 가장 가까운 곱을 찾아요.","557 − 504 = 53 — 53은 72보다 작아요.","557 ÷ 72 = 7 … 53이에요."],"asset":{"type":"ldiv","a":557,"b":72,"upto":0}},{"stem":"305 ÷ 91을 계산하여 몫과 나머지를 바르게 구한 것은 어느 것인가요?","options":[{"t":"몫 3, 나머지 32","correct":true},{"t":"몫 2, 나머지 123","mis":"M4-1-u3-X07"},{"t":"몫 4, 나머지 없음","mis":"M4-1-u3-X08"},{"t":"몫 32, 나머지 3","mis":"M4-1-u3-X14"}],"explanation":["91 × 3 = 273, 91 × 4 = 364 — 305를 넘지 않으면서 가장 가까운 곱을 찾아요.","305 − 273 = 32 — 32는 91보다 작아요.","305 ÷ 91 = 3 … 32예요."],"asset":{"type":"ldiv","a":305,"b":91,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_b#15','math',4,1,'u3','','g4_1_math_u3_review_b','unit_review','M4-1-u3-C9',2,'sa','auto','889 ÷ 17에서 먼저 17 × 50 = 850을 뺐어요. 남은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":15,"concept":"M4-1-u3-C9","difficulty":2,"kind":"sa","stem":"889 ÷ 17에서 먼저 17 × 50 = 850을 뺐어요. 남은 수는 얼마인가요? 숫자로 쓰세요.","answer":["39"],"explanation":["889 − 850 = 39예요.","남은 39에 17이 2번 더 들어가요.","그래서 몫은 50 + 2 = 52예요."],"asset":{"type":"ldiv","a":889,"b":17,"upto":1},"variant_rule":{"alt":[{"stem":"242 ÷ 19에서 먼저 19 × 10 = 190을 뺐어요. 남은 수는 얼마인가요? 숫자로 쓰세요.","answer":["52"],"explanation":["242 − 190 = 52예요.","남은 52에 19가 2번 더 들어가요.","그래서 몫은 10 + 2 = 12예요."],"asset":{"type":"ldiv","a":242,"b":19,"upto":1}},{"stem":"725 ÷ 27에서 먼저 27 × 20 = 540을 뺐어요. 남은 수는 얼마인가요? 숫자로 쓰세요.","answer":["185"],"explanation":["725 − 540 = 185예요.","남은 185에 27이 6번 더 들어가요.","그래서 몫은 20 + 6 = 26이에요."],"asset":{"type":"ldiv","a":725,"b":27,"upto":1}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_b#16','math',4,1,'u3','','g4_1_math_u3_review_b','unit_review','M4-1-u3-C10',2,'sa','auto','빈 병 한 개를 돌려주면 80원을 받아요. 2880원을 받았다면 돌려준 빈 병은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":16,"concept":"M4-1-u3-C10","difficulty":2,"kind":"sa","stem":"빈 병 한 개를 돌려주면 80원을 받아요. 2880원을 받았다면 돌려준 빈 병은 몇 개인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["받은 돈 ÷ 한 개에 받는 돈.","2880 ÷ 80 = 36이에요.","빈 병 36개를 돌려줬어요."],"asset":{"type":"ldiv","a":2880,"b":80,"upto":0},"variant_rule":{"alt":[{"stem":"빈 병 한 개를 돌려주면 90원을 받아요. 2520원을 받았다면 돌려준 빈 병은 몇 개인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["받은 돈 ÷ 한 개에 받는 돈.","2520 ÷ 90 = 28이에요.","빈 병 28개를 돌려줬어요."],"asset":{"type":"ldiv","a":2520,"b":90,"upto":0}},{"stem":"빈 병 한 개를 돌려주면 90원을 받아요. 1800원을 받았다면 돌려준 빈 병은 몇 개인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["받은 돈 ÷ 한 개에 받는 돈.","1800 ÷ 90 = 20이에요.","빈 병 20개를 돌려줬어요."],"asset":{"type":"ldiv","a":1800,"b":90,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_b#17','math',4,1,'u3','','g4_1_math_u3_review_b','unit_review','M4-1-u3-C3',3,'mc','auto','지유가 786 × 93을 이렇게 계산해 3388이라고 했어요. 바르게 계산하면 얼마인가요?',ARRAY['M4-1-u3-X04','M4-1-u3-X02','M4-1-u3-X03']::text[],true,'{"seq":17,"concept":"M4-1-u3-C3","difficulty":3,"kind":"mc","stem":"지유가 786 × 93을 이렇게 계산해 3388이라고 했어요. 바르게 계산하면 얼마인가요?","options":[{"t":"73098","correct":true},{"t":"3388","mis":"M4-1-u3-X04"},{"t":"9432","mis":"M4-1-u3-X02"},{"t":"70740","mis":"M4-1-u3-X03"}],"explanation":["지유 — 올림한 수를 더하지 않았어요.","786 × 3 = 2358, 786 × 90 = 70740.","2358 + 70740 = 73098이에요."],"asset":{"type":"expr_grid","rows":[["","","","7","8","6"],["×","","","","9","3"],["","","","1","4","8"],["","","3","2","4",""],["","","3","3","8","8"]]},"variant_rule":{"alt":[{"stem":"건우가 392 × 39를 이렇게 계산해 4704라고 했어요. 바르게 계산하면 얼마인가요?","options":[{"t":"15288","correct":true},{"t":"4704","mis":"M4-1-u3-X02"},{"t":"11760","mis":"M4-1-u3-X03"},{"t":"3528","mis":"M4-1-u3-X03"}],"explanation":["건우 — 넷째 줄을 한 칸 밀어 쓰지 않았어요.","392 × 9 = 3528, 392 × 30 = 11760.","3528 + 11760 = 15288이에요."],"asset":{"type":"expr_grid","rows":[["","","","3","9","2"],["×","","","","3","9"],["","","3","5","2","8"],["","","1","1","7","6"],["","","4","7","0","4"]]}},{"stem":"하린이 476 × 26을 이렇게 계산해 12406이라고 했어요. 바르게 계산하면 얼마인가요?","options":[{"t":"12376","correct":true},{"t":"12406","mis":"M4-1-u3-X05"},{"t":"3808","mis":"M4-1-u3-X02"},{"t":"9520","mis":"M4-1-u3-X03"}],"explanation":["하린 — 셋째 줄의 올림을 넷째 줄에 다시 더했어요.","476 × 6 = 2856, 476 × 20 = 9520.","2856 + 9520 = 12376이에요."],"asset":{"type":"expr_grid","rows":[["","","","4","7","6"],["×","","","","2","6"],["","","2","8","5","6"],["","","9","5","5",""],["","1","2","4","0","6"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.di