INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_b#18','math',4,1,'u3','','g4_1_math_u3_review_b','unit_review','M4-1-u3-C4',3,'mc','auto','하린이 847 × 46을 계산해 33880이라고 했어요. 어림해 보면 어떤가요?',ARRAY['M4-1-u3-X17','M4-1-u3-X14']::text[],true,'{"seq":18,"concept":"M4-1-u3-C4","difficulty":3,"kind":"mc","stem":"하린이 847 × 46을 계산해 33880이라고 했어요. 어림해 보면 어떤가요?","options":[{"t":"40000쯤인데 33880은 너무 작아요 — 잘못 계산했어요","correct":true},{"t":"어림값과 비슷하니 맞게 계산했어요","mis":"M4-1-u3-X17"},{"t":"어림으로는 맞았는지 알 수 없어요","mis":"M4-1-u3-X17"},{"t":"40000쯤인데 33880은 너무 커요 — 잘못 계산했어요","mis":"M4-1-u3-X14"}],"explanation":["847 × 46 — 약 800 × 50 = 40000.","33880은 어림값보다 훨씬 작아요.","바른 곱은 38962예요."],"variant_rule":{"alt":[{"stem":"하린이 957 × 34를 계산해 28710이라고 했어요. 어림해 보면 어떤가요?","options":[{"t":"30000쯤인데 28710은 너무 작아요 — 잘못 계산했어요","correct":true},{"t":"어림값과 비슷하니 맞게 계산했어요","mis":"M4-1-u3-X17"},{"t":"어림으로는 맞았는지 알 수 없어요","mis":"M4-1-u3-X17"},{"t":"30000쯤인데 28710은 너무 커요 — 잘못 계산했어요","mis":"M4-1-u3-X14"}],"explanation":["957 × 34 — 약 1000 × 30 = 30000.","28710은 어림값보다 훨씬 작아요.","바른 곱은 32538이에요."],"asset":null},{"stem":"도윤이 663 × 35를 계산해 5304라고 했어요. 어림해 보면 어떤가요?","options":[{"t":"28000쯤인데 5304는 너무 작아요 — 잘못 계산했어요","correct":true},{"t":"어림값과 비슷하니 맞게 계산했어요","mis":"M4-1-u3-X17"},{"t":"어림으로는 맞았는지 알 수 없어요","mis":"M4-1-u3-X17"},{"t":"28000쯤인데 5304는 너무 커요 — 잘못 계산했어요","mis":"M4-1-u3-X14"}],"explanation":["663 × 35 — 약 700 × 40 = 28000.","5304는 어림값보다 훨씬 작아요.","바른 곱은 23205예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_b#19','math',4,1,'u3','','g4_1_math_u3_review_b','unit_review','M4-1-u3-C5',3,'error','auto','친구들이 나눗셈을 했어요. 잘못 계산한 친구는 누구인가요?',ARRAY['M4-1-u3-X09','M4-1-u3-X14']::text[],true,'{"seq":19,"concept":"M4-1-u3-C5","difficulty":3,"kind":"error","stem":"친구들이 나눗셈을 했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"지유 — 699 ÷ 90 = 7 … 6","correct":true,"mis_target":"M4-1-u3-X09"},{"t":"도윤 — 145 ÷ 40 = 3 … 25","mis":"M4-1-u3-X14"},{"t":"하린 — 121 ÷ 40 = 3 … 1","mis":"M4-1-u3-X14"}],"explanation":["699 ÷ 90 — 90 × 7 = 630.","699 − 630 = 69예요 — 나머지예요.","지유가 0을 지우고 69 ÷ 9를 계산해 나머지를 6으로 썼어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 친구들이 나눗셈을 했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"도윤 — 885 ÷ 90 = 9 … 7","correct":true,"mis_target":"M4-1-u3-X09"},{"t":"서준 — 541 ÷ 70 = 7 … 51","mis":"M4-1-u3-X14"},{"t":"하린 — 223 ÷ 30 = 7 … 13","mis":"M4-1-u3-X14"}],"explanation":["885 ÷ 90 — 90 × 9 = 810.","885 − 810 = 75예요 — 나머지예요.","도윤이 0을 지우고 88 ÷ 9를 계산해 나머지를 7로 썼어요."],"asset":null},{"stem":"이번에는 다른 수예요. 친구들이 나눗셈을 했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"서준 — 249 ÷ 30 = 8 … 0","correct":true,"mis_target":"M4-1-u3-X09"},{"t":"도윤 — 123 ÷ 20 = 6 … 3","mis":"M4-1-u3-X14"},{"t":"태오 — 733 ÷ 80 = 9 … 13","mis":"M4-1-u3-X14"}],"explanation":["249 ÷ 30 — 30 × 8 = 240.","249 − 240 = 9예요 — 나머지예요.","서준이 0을 지우고 24 ÷ 3을 계산해 나머지를 0으로 썼어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_b#20','math',4,1,'u3','','g4_1_math_u3_review_b','unit_review','M4-1-u3-C9',3,'error','auto','지유가 947 ÷ 46 = 2 … 27이라고 계산했어요. 무엇이 잘못됐나요?',ARRAY['M4-1-u3-X11','M4-1-u3-X07','M4-1-u3-X08']::text[],true,'{"seq":20,"concept":"M4-1-u3-C9","difficulty":3,"kind":"error","stem":"지유가 947 ÷ 46 = 2 … 27이라고 계산했어요. 무엇이 잘못됐나요?","options":[{"t":"몫의 일의 자리에 0을 쓰지 않았어요","correct":true,"mis_target":"M4-1-u3-X11"},{"t":"나머지가 나누는 수보다 커요","mis":"M4-1-u3-X07"},{"t":"몫을 1 크게 해야 해요","mis":"M4-1-u3-X08"}],"explanation":["46 × 20 = 920 — 몫의 십의 자리 2.","남은 27이 46보다 작아 일의 자리 몫은 0.","바르게: 947 ÷ 46 = 20 … 27이에요."],"asset":{"type":"ldiv","a":947,"b":46},"variant_rule":{"alt":[{"stem":"서준이 966 ÷ 19 = 5 … 16이라고 계산했어요. 무엇이 잘못됐나요?","options":[{"t":"몫의 일의 자리에 0을 쓰지 않았어요","correct":true,"mis_target":"M4-1-u3-X11"},{"t":"나머지가 나누는 수보다 커요","mis":"M4-1-u3-X07"},{"t":"몫을 1 크게 해야 해요","mis":"M4-1-u3-X08"}],"explanation":["19 × 50 = 950 — 몫의 십의 자리 5.","남은 16이 19보다 작아 일의 자리 몫은 0.","바르게: 966 ÷ 19 = 50 … 16이에요."],"asset":{"type":"ldiv","a":966,"b":19}},{"stem":"시아가 164 ÷ 16 = 1 … 4라고 계산했어요. 무엇이 잘못됐나요?","options":[{"t":"몫의 일의 자리에 0을 쓰지 않았어요","correct":true,"mis_target":"M4-1-u3-X11"},{"t":"나머지가 나누는 수보다 커요","mis":"M4-1-u3-X07"},{"t":"몫을 1 크게 해야 해요","mis":"M4-1-u3-X08"}],"explanation":["16 × 10 = 160 — 몫의 십의 자리 1.","남은 4가 16보다 작아 일의 자리 몫은 0.","바르게: 164 ÷ 16 = 10 … 4예요."],"asset":{"type":"ldiv","a":164,"b":16}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_b#21','math',4,1,'u3','','g4_1_math_u3_review_b','unit_review','M4-1-u3-C10',3,'mc','auto','학생 767명이 한 대에 84명씩 타는 버스를 타려고 해요. 모두 타려면 버스는 적어도 몇 대 필요한가요?',ARRAY['M4-1-u3-X13','M4-1-u3-X14','M4-1-u3-X15']::text[],true,'{"seq":21,"concept":"M4-1-u3-C10","difficulty":3,"kind":"mc","stem":"학생 767명이 한 대에 84명씩 타는 버스를 타려고 해요. 모두 타려면 버스는 적어도 몇 대 필요한가요?","options":[{"t":"10대","correct":true},{"t":"9대","mis":"M4-1-u3-X13"},{"t":"11대","mis":"M4-1-u3-X14"},{"t":"20대","mis":"M4-1-u3-X15"}],"explanation":["767 ÷ 84 = 9 … 11.","남은 11도 태워야 하니 하나 더 — 9 + 1 = 10.","답은 10대예요."],"variant_rule":{"alt":[{"stem":"사과 396개를 한 상자에 59개씩 남김없이 모두 담으려고 해요. 상자는 적어도 몇 개 필요한가요?","options":[{"t":"7개","correct":true},{"t":"6개","mis":"M4-1-u3-X13"},{"t":"42개","mis":"M4-1-u3-X14"},{"t":"48개","mis":"M4-1-u3-X15"}],"explanation":["396 ÷ 59 = 6 … 42.","남은 42도 담아야 하니 하나 더 — 6 + 1 = 7.","답은 7개예요."],"asset":null},{"stem":"사과 179개를 한 상자에 21개씩 남김없이 모두 담으려고 해요. 상자는 적어도 몇 개 필요한가요?","options":[{"t":"9개","correct":true},{"t":"8개","mis":"M4-1-u3-X13"},{"t":"11개","mis":"M4-1-u3-X14"},{"t":"19개","mis":"M4-1-u3-X15"}],"explanation":["179 ÷ 21 = 8 … 11.","남은 11도 담아야 하니 하나 더 — 8 + 1 = 9.","답은 9개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_b#22','math',4,1,'u3','','g4_1_math_u3_review_b','unit_review','M4-1-u3-C6',3,'sa','auto','어떤 수를 47로 나누었더니 몫이 7, 나머지가 16이 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":22,"concept":"M4-1-u3-C6","difficulty":3,"kind":"sa","stem":"어떤 수를 47로 나누었더니 몫이 7, 나머지가 16이 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["345"],"explanation":["나누어지는 수 = (나누는 수) × (몫) + (나머지).","47 × 7 = 329.","329 + 16 = 345 — 어떤 수는 345예요."],"asset":{"type":"expr_grid","rows":[["47 × 7","=","329"],["329 + 16","=",null]]},"variant_rule":{"alt":[{"stem":"어떤 수를 76으로 나누었더니 몫이 6, 나머지가 19가 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["475"],"explanation":["나누어지는 수 = (나누는 수) × (몫) + (나머지).","76 × 6 = 456.","456 + 19 = 475 — 어떤 수는 475예요."],"asset":{"type":"expr_grid","rows":[["76 × 6","=","456"],["456 + 19","=",null]]}},{"stem":"어떤 수를 85로 나누었더니 몫이 4, 나머지가 15가 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["355"],"explanation":["나누어지는 수 = (나누는 수) × (몫) + (나머지).","85 × 4 = 340.","340 + 15 = 355 — 어떤 수는 355예요."],"asset":{"type":"expr_grid","rows":[["85 × 4","=","340"],["340 + 15","=",null]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_b#23','math',4,1,'u3','','g4_1_math_u3_review_b','unit_review','M4-1-u3-C3',4,'mc','auto','수 카드 4, 7, 6, 9, 5를 한 번씩 모두 써서 (세 자리 수) × (두 자리 수)를 만들려고 해요. 가장 큰 곱은 얼마인가요?',ARRAY['M4-1-u3-X14','M4-1-u3-X16']::text[],true,'{"seq":23,"concept":"M4-1-u3-C3","difficulty":4,"kind":"mc","stem":"수 카드 4, 7, 6, 9, 5를 한 번씩 모두 써서 (세 자리 수) × (두 자리 수)를 만들려고 해요. 가장 큰 곱은 얼마인가요?","options":[{"t":"72580","correct":true},{"t":"52704","mis":"M4-1-u3-X14"},{"t":"72300","mis":"M4-1-u3-X14"},{"t":"7258","mis":"M4-1-u3-X16"}],"explanation":["가장 큰 두 숫자를 두 수의 맨 앞(백의 자리·십의 자리)에 나누어 놓아요.","여러 가지로 놓아 곱을 견주면 764 × 95가 가장 커요.","764 × 95 = 72580이에요."],"variant_rule":{"alt":[{"stem":"수 카드 9, 6, 4, 2, 8을 한 번씩 모두 써서 (세 자리 수) × (두 자리 수)를 만들려고 해요. 가장 큰 곱은 얼마인가요?","options":[{"t":"81028","correct":true},{"t":"41412","mis":"M4-1-u3-X14"},{"t":"80808","mis":"M4-1-u3-X14"},{"t":"8102","mis":"M4-1-u3-X16"}],"explanation":["가장 큰 두 숫자를 두 수의 맨 앞(백의 자리·십의 자리)에 나누어 놓아요.","여러 가지로 놓아 곱을 견주면 862 × 94가 가장 커요.","862 × 94 = 81028이에요."],"asset":null},{"stem":"수 카드 5, 1, 4, 2, 9를 한 번씩 모두 써서 (세 자리 수) × (두 자리 수)를 만들려고 해요. 가장 큰 곱은 얼마인가요?","options":[{"t":"49772","correct":true},{"t":"20034","mis":"M4-1-u3-X14"},{"t":"48932","mis":"M4-1-u3-X14"},{"t":"4977","mis":"M4-1-u3-X16"}],"explanation":["가장 큰 두 숫자를 두 수의 맨 앞(백의 자리·십의 자리)에 나누어 놓아요.","여러 가지로 놓아 곱을 견주면 541 × 92가 가장 커요.","541 × 92 = 49772예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_b#24','math',4,1,'u3','','g4_1_math_u3_review_b','unit_review','M4-1-u3-C10',4,'mc','auto','오늘 반찬은 한 사람에 708 g, 내일 반찬은 한 사람에 436 g이에요. 28명이 먹을 때 내일은 오늘보다 탄소 발자국이 몇 g 줄어드나요?',ARRAY['M4-1-u3-X18','M4-1-u3-X15']::text[],true,'{"seq":24,"concept":"M4-1-u3-C10","difficulty":4,"kind":"mc","stem":"오늘 반찬은 한 사람에 708 g, 내일 반찬은 한 사람에 436 g이에요. 28명이 먹을 때 내일은 오늘보다 탄소 발자국이 몇 g 줄어드나요?","options":[{"t":"7616 g","correct":true},{"t":"272 g","mis":"M4-1-u3-X18"},{"t":"32032 g","mis":"M4-1-u3-X15"},{"t":"12208 g","mis":"M4-1-u3-X18"}],"explanation":["오늘 708 × 28 = 19824 g.","내일 436 × 28 = 12208 g.","19824 − 12208 = 7616 g 줄어요."],"variant_rule":{"alt":[{"stem":"오늘 반찬은 한 사람에 616 g, 내일 반찬은 한 사람에 346 g이에요. 25명이 먹을 때 내일은 오늘보다 탄소 발자국이 몇 g 줄어드나요?","options":[{"t":"6750 g","correct":true},{"t":"270 g","mis":"M4-1-u3-X18"},{"t":"24050 g","mis":"M4-1-u3-X15"},{"t":"8650 g","mis":"M4-1-u3-X18"}],"explanation":["오늘 616 × 25 = 15400 g.","내일 346 × 25 = 8650 g.","15400 − 8650 = 6750 g 줄어요."],"asset":null},{"stem":"오늘 반찬은 한 사람에 717 g, 내일 반찬은 한 사람에 378 g이에요. 28명이 먹을 때 내일은 오늘보다 탄소 발자국이 몇 g 줄어드나요?","options":[{"t":"9492 g","correct":true},{"t":"339 g","mis":"M4-1-u3-X18"},{"t":"30660 g","mis":"M4-1-u3-X15"},{"t":"10584 g","mis":"M4-1-u3-X18"}],"explanation":["오늘 717 × 28 = 20076 g.","내일 378 × 28 = 10584 g.","20076 − 10584 = 9492 g 줄어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_b#25','math',4,1,'u3','','g4_1_math_u3_review_b','unit_review','M4-1-u3-C6',4,'essay','teacher','729 ÷ 31 = 23 … 16이 맞는지 확인하는 방법을 설명하고, 확인해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M4-1-u3-C6","difficulty":4,"kind":"essay","stem":"729 ÷ 31 = 23 … 16이 맞는지 확인하는 방법을 설명하고, 확인해 보세요.","answer_guide":{"answer":"예: (나누는 수) × (몫) + (나머지)가 나누어지는 수와 같은지 본다. 31 × 23 = 713, 713 + 16 = 729이고 16은 31보다 작으므로 바르게 계산했다.","scoring_points":["확인 식 (나누는 수) × (몫) + (나머지)를 썼는가","31 × 23 = 713, 713 + 16 = 729를 구했는가","나머지가 나누는 수보다 작은지도 보았는가"]},"explanation":["31 × 23 = 713.","713 + 16 = 729.","16 < 31 — 바르게 계산했어요."],"asset":{"type":"expr_grid","rows":[["31 × 23","=","713"],["713 + 16","=","729"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_c#1','math',4,1,'u3','','g4_1_math_u3_review_c','unit_review','M4-1-u3-C2',1,'sa','auto','126 × 70은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-1-u3-C2","difficulty":1,"kind":"sa","stem":"126 × 70은 얼마인가요? 숫자로 쓰세요.","answer":["8820"],"explanation":["126 × 7 = 882 — 먼저 몇을 곱해요.","곱하는 수가 10배(7 → 70)라서 곱도 10배예요.","126 × 70 = 8820이에요."],"variant_rule":{"alt":[{"stem":"252 × 30은 얼마인가요? 숫자로 쓰세요.","answer":["7560"],"explanation":["252 × 3 = 756 — 먼저 몇을 곱해요.","곱하는 수가 10배(3 → 30)라서 곱도 10배예요.","252 × 30 = 7560이에요."],"asset":null},{"stem":"189 × 30은 얼마인가요? 숫자로 쓰세요.","answer":["5670"],"explanation":["189 × 3 = 567 — 먼저 몇을 곱해요.","곱하는 수가 10배(3 → 30)라서 곱도 10배예요.","189 × 30 = 5670이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_c#2','math',4,1,'u3','','g4_1_math_u3_review_c','unit_review','M4-1-u3-C1',1,'sa','auto','393 × 53을 아는 계산으로 쪼갰어요. 393 × 53 = 393 × 50 + 393 × □에서 □ 안에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-1-u3-C1","difficulty":1,"kind":"sa","stem":"393 × 53을 아는 계산으로 쪼갰어요. 393 × 53 = 393 × 50 + 393 × □에서 □ 안에 알맞은 수를 쓰세요.","answer":["3"],"explanation":["53은 50과 3의 합이에요.","53번 더한 것 = 50번 더하고 3번 더 더한 것.","□ = 3이에요."],"asset":{"type":"expr_grid","rows":[["393 × 50","=","19650"],["393 × 3","=","1179"],["19650 + 1179","=","20829"]]},"variant_rule":{"alt":[{"stem":"412 × 83을 아는 계산으로 쪼갰어요. 412 × 83 = 412 × 80 + 412 × □에서 □ 안에 알맞은 수를 쓰세요.","answer":["3"],"explanation":["83은 80과 3의 합이에요.","83번 더한 것 = 80번 더하고 3번 더 더한 것.","□ = 3이에요."],"asset":{"type":"expr_grid","rows":[["412 × 80","=","32960"],["412 × 3","=","1236"],["32960 + 1236","=","34196"]]}},{"stem":"203 × 65를 아는 계산으로 쪼갰어요. 203 × 65 = 203 × 60 + 203 × □에서 □ 안에 알맞은 수를 쓰세요.","answer":["5"],"explanation":["65는 60과 5의 합이에요.","65번 더한 것 = 60번 더하고 5번 더 더한 것.","□ = 5예요."],"asset":{"type":"expr_grid","rows":[["203 × 60","=","12180"],["203 × 5","=","1015"],["12180 + 1015","=","13195"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_c#3','math',4,1,'u3','','g4_1_math_u3_review_c','unit_review','M4-1-u3-C3',1,'sa','auto','344 × 13의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-1-u3-C3","difficulty":1,"kind":"sa","stem":"344 × 13의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["2"],"explanation":["일의 자리 3을 먼저 곱하고, 십의 자리 1을 곱한 값은 한 칸 밀어 써요.","셋째 줄은 344 × 3 = 1032예요.","?는 일의 자리 숫자 2예요."],"asset":{"type":"expr_grid","rows":[["","","","3","4","4"],["×","","","","1","3"],["","","1","0","3",null],["","","3","4","4",""],["","","4","4","7","2"]]},"variant_rule":{"alt":[{"stem":"173 × 13의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["1"],"explanation":["일의 자리 3을 먼저 곱하고, 십의 자리 1을 곱한 값은 한 칸 밀어 써요.","넷째 줄은 173 × 1 = 173 — 한 칸 밀어 써서 1730을 나타내요.","?는 천의 자리 숫자 1이에요."],"asset":{"type":"expr_grid","rows":[["","","","1","7","3"],["×","","","","1","3"],["","","","5","1","9"],["","",null,"7","3",""],["","","2","2","4","9"]]}},{"stem":"345 × 27의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["5"],"explanation":["일의 자리 7을 먼저 곱하고, 십의 자리 2를 곱한 값은 한 칸 밀어 써요.","셋째 줄은 345 × 7 = 2415예요.","?는 일의 자리 숫자 5예요."],"asset":{"type":"expr_grid","rows":[["","","","3","4","5"],["×","","","","2","7"],["","","2","4","1",null],["","","6","9","0",""],["","","9","3","1","5"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_c#4','math',4,1,'u3','','g4_1_math_u3_review_c','unit_review','M4-1-u3-C5',1,'sa','auto','615 ÷ 80의 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-1-u3-C5","difficulty":1,"kind":"sa","stem":"615 ÷ 80의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["615 ÷ 80 — 610은 십 모형 61개, 80은 십 모형 8개로 보면 61 ÷ 8과 같아요.","615 − 560 = 55 — 55는 80보다 작아요.","615 ÷ 80 = 7 … 55예요."],"asset":{"type":"ldiv","a":615,"b":80,"upto":0},"variant_rule":{"alt":[{"stem":"338 ÷ 50의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["338 ÷ 50 — 330은 십 모형 33개, 50은 십 모형 5개로 보면 33 ÷ 5와 같아요.","338 − 300 = 38 — 38은 50보다 작아요.","338 ÷ 50 = 6 … 38이에요."],"asset":{"type":"ldiv","a":338,"b":50,"upto":0}},{"stem":"206 ÷ 40의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["206 ÷ 40 — 200은 십 모형 20개, 40은 십 모형 4개로 보면 20 ÷ 4와 같아요.","206 − 200 = 6 — 6은 40보다 작아요.","206 ÷ 40 = 5 … 6이에요."],"asset":{"type":"ldiv","a":206,"b":40,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_c#5','math',4,1,'u3','','g4_1_math_u3_review_c','unit_review','M4-1-u3-C7',1,'sa','auto','35 ÷ 14의 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-1-u3-C7","difficulty":1,"kind":"sa","stem":"35 ÷ 14의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["14 × 2 = 28, 14 × 3 = 42 — 35를 넘지 않으면서 가장 가까운 곱을 찾아요.","35 − 28 = 7 — 7은 14보다 작아요.","35 ÷ 14 = 2 … 7이에요."],"asset":{"type":"ldiv","a":35,"b":14,"upto":0},"variant_rule":{"alt":[{"stem":"58 ÷ 27의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["27 × 2 = 54, 27 × 3 = 81 — 58을 넘지 않으면서 가장 가까운 곱을 찾아요.","58 − 54 = 4 — 4는 27보다 작아요.","58 ÷ 27 = 2 … 4예요."],"asset":{"type":"ldiv","a":58,"b":27,"upto":0}},{"stem":"59 ÷ 21의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["21 × 2 = 42, 21 × 3 = 63 — 59를 넘지 않으면서 가장 가까운 곱을 찾아요.","59 − 42 = 17 — 17은 21보다 작아요.","59 ÷ 21 = 2 … 17이에요."],"asset":{"type":"ldiv","a":59,"b":21,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_c#6','math',4,1,'u3','','g4_1_math_u3_review_c','unit_review','M4-1-u3-C8',1,'sa','auto','271 ÷ 45의 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M4-1-u3-C8","difficulty":1,"kind":"sa","stem":"271 ÷ 45의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["45 × 6 = 270, 45 × 7 = 315 — 271을 넘지 않으면서 가장 가까운 곱을 찾아요.","271 − 270 = 1 — 1은 45보다 작아요.","271 ÷ 45 = 6 … 1이에요."],"asset":{"type":"ldiv","a":271,"b":45,"upto":0},"variant_rule":{"alt":[{"stem":"156 ÷ 35의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["35 × 4 = 140, 35 × 5 = 175 — 156을 넘지 않으면서 가장 가까운 곱을 찾아요.","156 − 140 = 16 — 16은 35보다 작아요.","156 ÷ 35 = 4 … 16이에요."],"asset":{"type":"ldiv","a":156,"b":35,"upto":0}},{"stem":"354 ÷ 57의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["57 × 6 = 342, 57 × 7 = 399 — 354를 넘지 않으면서 가장 가까운 곱을 찾아요.","354 − 342 = 12 — 12는 57보다 작아요.","354 ÷ 57 = 6 … 12예요."],"asset":{"type":"ldiv","a":354,"b":57,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_c#7','math',4,1,'u3','','g4_1_math_u3_review_c','unit_review','M4-1-u3-C9',1,'sa','auto','736 ÷ 21의 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M4-1-u3-C9","difficulty":1,"kind":"sa","stem":"736 ÷ 21의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["35"],"explanation":["먼저 몇십 번: 21 × 30 = 630 → 106이 남아요.","736 − 735 = 1 — 1은 21보다 작아요.","736 ÷ 21 = 35 … 1이에요."],"asset":{"type":"ldiv","a":736,"b":21,"upto":0},"variant_rule":{"alt":[{"stem":"489 ÷ 11의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["44"],"explanation":["먼저 몇십 번: 11 × 40 = 440 → 49가 남아요.","489 − 484 = 5 — 5는 11보다 작아요.","489 ÷ 11 = 44 … 5예요."],"asset":{"type":"ldiv","a":489,"b":11,"upto":0}},{"stem":"427 ÷ 12의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["35"],"explanation":["먼저 몇십 번: 12 × 30 = 360 → 67이 남아요.","427 − 420 = 7 — 7은 12보다 작아요.","427 ÷ 12 = 35 … 7이에요."],"asset":{"type":"ldiv","a":427,"b":12,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_c#8','math',4,1,'u3','','g4_1_math_u3_review_c','unit_review','M4-1-u3-C10',1,'sa','auto','반찬 한 사람 몫의 탄소 발자국이에요 — 배추김치 76 g, 미역국 92 g, 고등어조림 245 g. 세 반찬의 탄소 발자국을 모두 더하면 몇 g인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M4-1-u3-C10","difficulty":1,"kind":"sa","stem":"반찬 한 사람 몫의 탄소 발자국이에요 — 배추김치 76 g, 미역국 92 g, 고등어조림 245 g. 세 반찬의 탄소 발자국을 모두 더하면 몇 g인가요? 숫자로 쓰세요.","answer":["413"],"explanation":["세 값을 차례로 더해요.","76 + 92 + 245 = 413.","한 사람 몫은 413 g이에요."],"variant_rule":{"alt":[{"stem":"반찬 한 사람 몫의 탄소 발자국이에요 — 잡곡밥 136 g, 미역국 92 g, 고등어조림 245 g. 세 반찬의 탄소 발자국을 모두 더하면 몇 g인가요? 숫자로 쓰세요.","answer":["473"],"explanation":["세 값을 차례로 더해요.","136 + 92 + 245 = 473.","한 사람 몫은 473 g이에요."],"asset":null},{"stem":"반찬 한 사람 몫의 탄소 발자국이에요 — 고등어조림 245 g, 콩나물무침 58 g, 달걀말이 118 g. 세 반찬의 탄소 발자국을 모두 더하면 몇 g인가요? 숫자로 쓰세요.","answer":["421"],"explanation":["세 값을 차례로 더해요.","245 + 58 + 118 = 421.","한 사람 몫은 421 g이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_c#9','math',4,1,'u3','','g4_1_math_u3_review_c','unit_review','M4-1-u3-C3',2,'mc','auto','445 × 32는 얼마인가요?',ARRAY['M4-1-u3-X02','M4-1-u3-X03']::text[],true,'{"seq":9,"concept":"M4-1-u3-C3","difficulty":2,"kind":"mc","stem":"445 × 32는 얼마인가요?","options":[{"t":"14240","correct":true},{"t":"2225","mis":"M4-1-u3-X02"},{"t":"13350","mis":"M4-1-u3-X03"},{"t":"890","mis":"M4-1-u3-X03"}],"explanation":["32를 30과 2로 쪼개요.","445 × 30 = 13350, 445 × 2 = 890.","13350 + 890 = 14240이에요."],"variant_rule":{"alt":[{"stem":"866 × 24는 얼마인가요?","options":[{"t":"20784","correct":true},{"t":"5196","mis":"M4-1-u3-X02"},{"t":"17320","mis":"M4-1-u3-X03"},{"t":"3464","mis":"M4-1-u3-X03"}],"explanation":["24를 20과 4로 쪼개요.","866 × 20 = 17320, 866 × 4 = 3464.","17320 + 3464 = 20784예요."],"asset":null},{"stem":"292 × 94는 얼마인가요?","options":[{"t":"27448","correct":true},{"t":"3796","mis":"M4-1-u3-X02"},{"t":"26280","mis":"M4-1-u3-X03"},{"t":"1168","mis":"M4-1-u3-X03"}],"explanation":["94를 90과 4로 쪼개요.","292 × 90 = 26280, 292 × 4 = 1168.","26280 + 1168 = 27448이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_c#10','math',4,1,'u3','','g4_1_math_u3_review_c','unit_review','M4-1-u3-C4',2,'mc','auto','421 × 64를 몇백과 몇십으로 어림하면 약 얼마인가요?',ARRAY['M4-1-u3-X16','M4-1-u3-X15']::text[],true,'{"seq":10,"concept":"M4-1-u3-C4","difficulty":2,"kind":"mc","stem":"421 × 64를 몇백과 몇십으로 어림하면 약 얼마인가요?","options":[{"t":"약 24000","correct":true},{"t":"약 240000","mis":"M4-1-u3-X16"},{"t":"약 2400","mis":"M4-1-u3-X16"},{"t":"약 460","mis":"M4-1-u3-X15"}],"explanation":["421은 약 400, 64는 약 60이에요.","400 × 60 = 24000이에요 — 0의 개수를 세어 붙여요.","실제 곱 26944는 어림값 24000에 가까워요."],"variant_rule":{"alt":[{"stem":"513 × 32를 몇백과 몇십으로 어림하면 약 얼마인가요?","options":[{"t":"약 15000","correct":true},{"t":"약 150000","mis":"M4-1-u3-X16"},{"t":"약 1500","mis":"M4-1-u3-X16"},{"t":"약 530","mis":"M4-1-u3-X15"}],"explanation":["513은 약 500, 32는 약 30이에요.","500 × 30 = 15000이에요 — 0의 개수를 세어 붙여요.","실제 곱 16416은 어림값 15000에 가까워요."],"asset":null},{"stem":"846 × 45를 몇백과 몇십으로 어림하면 약 얼마인가요?","options":[{"t":"약 40000","correct":true},{"t":"약 400000","mis":"M4-1-u3-X16"},{"t":"약 4000","mis":"M4-1-u3-X16"},{"t":"약 850","mis":"M4-1-u3-X15"}],"explanation":["846은 약 800, 45는 약 50이에요.","800 × 50 = 40000이에요 — 0의 개수를 세어 붙여요.","실제 곱 38070은 어림값 40000에 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_c#11','math',4,1,'u3','','g4_1_math_u3_review_c','unit_review','M4-1-u3-C6',2,'mc','auto','737 ÷ 86 = 8 … 49가 맞는지 확인하는 식은 어느 것인가요?',ARRAY['M4-1-u3-X10','M4-1-u3-X15']::text[],true,'{"seq":11,"concept":"M4-1-u3-C6","difficulty":2,"kind":"mc","stem":"737 ÷ 86 = 8 … 49가 맞는지 확인하는 식은 어느 것인가요?","options":[{"t":"86 × 8 + 49 = 737","correct":true},{"t":"86 × 8 − 49 = 639","mis":"M4-1-u3-X10"},{"t":"737 × 86 + 49","mis":"M4-1-u3-X10"},{"t":"86 + 8 + 49 = 143","mis":"M4-1-u3-X15"}],"explanation":["확인은 (나누는 수) × (몫) + (나머지).","86 × 8 = 688, 688 + 49 = 737이에요.","나누어지는 수 737과 같으니 바르게 계산했어요."],"asset":{"type":"expr_grid","rows":[["86 × 8","=","688"],["688 + 49","=","737"]]},"variant_rule":{"alt":[{"stem":"610 ÷ 94 = 6 … 46이 맞는지 확인하는 식은 어느 것인가요?","options":[{"t":"94 × 6 + 46 = 610","correct":true},{"t":"94 × 6 − 46 = 518","mis":"M4-1-u3-X10"},{"t":"610 × 94 + 46","mis":"M4-1-u3-X10"},{"t":"94 + 6 + 46 = 146","mis":"M4-1-u3-X15"}],"explanation":["확인은 (나누는 수) × (몫) + (나머지).","94 × 6 = 564, 564 + 46 = 610이에요.","나누어지는 수 610과 같으니 바르게 계산했어요."],"asset":{"type":"expr_grid","rows":[["94 × 6","=","564"],["564 + 46","=","610"]]}},{"stem":"100 ÷ 31 = 3 … 7이 맞는지 확인하는 식은 어느 것인가요?","options":[{"t":"31 × 3 + 7 = 100","correct":true},{"t":"31 × 3 − 7 = 86","mis":"M4-1-u3-X10"},{"t":"100 × 31 + 7","mis":"M4-1-u3-X10"},{"t":"31 + 3 + 7 = 41","mis":"M4-1-u3-X15"}],"explanation":["확인은 (나누는 수) × (몫) + (나머지).","31 × 3 = 93, 93 + 7 = 100이에요.","나누어지는 수 100과 같으니 바르게 계산했어요."],"asset":{"type":"expr_grid","rows":[["31 × 3","=","93"],["93 + 7","=","100"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_c#12','math',4,1,'u3','','g4_1_math_u3_review_c','unit_review','M4-1-u3-C5',2,'mc','auto','294 ÷ 80을 계산하여 몫과 나머지를 바르게 구한 것은 어느 것인가요?',ARRAY['M4-1-u3-X07','M4-1-u3-X08','M4-1-u3-X09']::text[],true,'{"seq":12,"concept":"M4-1-u3-C5","difficulty":2,"kind":"mc","stem":"294 ÷ 80을 계산하여 몫과 나머지를 바르게 구한 것은 어느 것인가요?","options":[{"t":"몫 3, 나머지 54","correct":true},{"t":"몫 2, 나머지 134","mis":"M4-1-u3-X07"},{"t":"몫 4, 나머지 없음","mis":"M4-1-u3-X08"},{"t":"몫 3, 나머지 5","mis":"M4-1-u3-X09"}],"explanation":["294 ÷ 80 — 290은 십 모형 29개, 80은 십 모형 8개로 보면 29 ÷ 8과 같아요.","294 − 240 = 54 — 54는 80보다 작아요.","294 ÷ 80 = 3 … 54예요."],"asset":{"type":"ldiv","a":294,"b":80,"upto":0},"variant_rule":{"alt":[{"stem":"361 ÷ 50을 계산하여 몫과 나머지를 바르게 구한 것은 어느 것인가요?","options":[{"t":"몫 7, 나머지 11","correct":true},{"t":"몫 6, 나머지 61","mis":"M4-1-u3-X07"},{"t":"몫 8, 나머지 없음","mis":"M4-1-u3-X08"},{"t":"몫 7, 나머지 1","mis":"M4-1-u3-X09"}],"explanation":["361 ÷ 50 — 360은 십 모형 36개, 50은 십 모형 5개로 보면 36 ÷ 5와 같아요.","361 − 350 = 11 — 11은 50보다 작아요.","361 ÷ 50 = 7 … 11이에요."],"asset":{"type":"ldiv","a":361,"b":50,"upto":0}},{"stem":"255 ÷ 40을 계산하여 몫과 나머지를 바르게 구한 것은 어느 것인가요?","options":[{"t":"몫 6, 나머지 15","correct":true},{"t":"몫 5, 나머지 55","mis":"M4-1-u3-X07"},{"t":"몫 7, 나머지 없음","mis":"M4-1-u3-X08"},{"t":"몫 6, 나머지 1","mis":"M4-1-u3-X09"}],"explanation":["255 ÷ 40 — 250은 십 모형 25개, 40은 십 모형 4개로 보면 25 ÷ 4와 같아요.","255 − 240 = 15 — 15는 40보다 작아요.","255 ÷ 40 = 6 … 15예요."],"asset":{"type":"ldiv","a":255,"b":40,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_c#13','math',4,1,'u3','','g4_1_math_u3_review_c','unit_review','M4-1-u3-C7',2,'sa','auto','74 ÷ 13의 몫을 6으로 어림했더니 13 × 6 = 78이 74보다 커요. 알맞은 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":13,"concept":"M4-1-u3-C7","difficulty":2,"kind":"sa","stem":"74 ÷ 13의 몫을 6으로 어림했더니 13 × 6 = 78이 74보다 커요. 알맞은 몫은 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["곱 78이 74보다 커서 6은 너무 큰 몫이에요.","몫을 1 작게: 13 × 5 = 65.","알맞은 몫은 5예요."],"variant_rule":{"alt":[{"stem":"93 ÷ 13의 몫을 8로 어림했더니 13 × 8 = 104가 93보다 커요. 알맞은 몫은 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["곱 104가 93보다 커서 8은 너무 큰 몫이에요.","몫을 1 작게: 13 × 7 = 91.","알맞은 몫은 7이에요."],"asset":null},{"stem":"49 ÷ 11의 몫을 3으로 어림해 11 × 3 = 33을 빼니 16이 남았어요. 알맞은 몫은 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["남은 16이 나누는 수 11보다 커요.","한 번 더 나눌 수 있으니 몫을 1 크게: 4.","알맞은 몫은 4예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_c#14','math',4,1,'u3','','g4_1_math_u3_review_c','unit_review','M4-1-u3-C8',2,'mc','auto','526 ÷ 55를 계산하여 몫과 나머지를 바르게 구한 것은 어느 것인가요?',ARRAY['M4-1-u3-X07','M4-1-u3-X08','M4-1-u3-X14']::text[],true,'{"seq":14,"concept":"M4-1-u3-C8","difficulty":2,"kind":"mc","stem":"526 ÷ 55를 계산하여 몫과 나머지를 바르게 구한 것은 어느 것인가요?","options":[{"t":"몫 9, 나머지 31","correct":true},{"t":"몫 8, 나머지 86","mis":"M4-1-u3-X07"},{"t":"몫 10, 나머지 없음","mis":"M4-1-u3-X08"},{"t":"몫 31, 나머지 9","mis":"M4-1-u3-X14"}],"explanation":["55 × 9 = 495, 55 × 10 = 550 — 526을 넘지 않으면서 가장 가까운 곱을 찾아요.","526 − 495 = 31 — 31은 55보다 작아요.","526 ÷ 55 = 9 … 31이에요."],"asset":{"type":"ldiv","a":526,"b":55,"upto":0},"variant_rule":{"alt":[{"stem":"316 ÷ 43을 계산하여 몫과 나머지를 바르게 구한 것은 어느 것인가요?","options":[{"t":"몫 7, 나머지 15","correct":true},{"t":"몫 6, 나머지 58","mis":"M4-1-u3-X07"},{"t":"몫 8, 나머지 없음","mis":"M4-1-u3-X08"},{"t":"몫 15, 나머지 7","mis":"M4-1-u3-X14"}],"explanation":["43 × 7 = 301, 43 × 8 = 344 — 316을 넘지 않으면서 가장 가까운 곱을 찾아요.","316 − 301 = 15 — 15는 43보다 작아요.","316 ÷ 43 = 7 … 15예요."],"asset":{"type":"ldiv","a":316,"b":43,"upto":0}},{"stem":"239 ÷ 38을 계산하여 몫과 나머지를 바르게 구한 것은 어느 것인가요?","options":[{"t":"몫 6, 나머지 11","correct":true},{"t":"몫 5, 나머지 49","mis":"M4-1-u3-X07"},{"t":"몫 7, 나머지 없음","mis":"M4-1-u3-X08"},{"t":"몫 11, 나머지 6","mis":"M4-1-u3-X14"}],"explanation":["38 × 6 = 228, 38 × 7 = 266 — 239를 넘지 않으면서 가장 가까운 곱을 찾아요.","239 − 228 = 11 — 11은 38보다 작아요.","239 ÷ 38 = 6 … 11이에요."],"asset":{"type":"ldiv","a":239,"b":38,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_c#15','math',4,1,'u3','','g4_1_math_u3_review_c','unit_review','M4-1-u3-C9',2,'sa','auto','363 ÷ 14에서 먼저 14 × 20 = 280을 뺐어요. 남은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":15,"concept":"M4-1-u3-C9","difficulty":2,"kind":"sa","stem":"363 ÷ 14에서 먼저 14 × 20 = 280을 뺐어요. 남은 수는 얼마인가요? 숫자로 쓰세요.","answer":["83"],"explanation":["363 − 280 = 83이에요.","남은 83에 14가 5번 더 들어가요.","그래서 몫은 20 + 5 = 25예요."],"asset":{"type":"ldiv","a":363,"b":14,"upto":1},"variant_rule":{"alt":[{"stem":"546 ÷ 43에서 먼저 43 × 10 = 430을 뺐어요. 남은 수는 얼마인가요? 숫자로 쓰세요.","answer":["116"],"explanation":["546 − 430 = 116이에요.","남은 116에 43이 2번 더 들어가요.","그래서 몫은 10 + 2 = 12예요."],"asset":{"type":"ldiv","a":546,"b":43,"upto":1}},{"stem":"781 ÷ 27에서 먼저 27 × 20 = 540을 뺐어요. 남은 수는 얼마인가요? 숫자로 쓰세요.","answer":["241"],"explanation":["781 − 540 = 241이에요.","남은 241에 27이 8번 더 들어가요.","그래서 몫은 20 + 8 = 28이에요."],"asset":{"type":"ldiv","a":781,"b":27,"upto":1}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_c#16','math',4,1,'u3','','g4_1_math_u3_review_c','unit_review','M4-1-u3-C10',2,'sa','auto','빈 병 한 개를 돌려주면 80원을 받아요. 3040원을 받았다면 돌려준 빈 병은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":16,"concept":"M4-1-u3-C10","difficulty":2,"kind":"sa","stem":"빈 병 한 개를 돌려주면 80원을 받아요. 3040원을 받았다면 돌려준 빈 병은 몇 개인가요? 숫자로 쓰세요.","answer":["38"],"explanation":["받은 돈 ÷ 한 개에 받는 돈.","3040 ÷ 80 = 38이에요.","빈 병 38개를 돌려줬어요."],"asset":{"type":"ldiv","a":3040,"b":80,"upto":0},"variant_rule":{"alt":[{"stem":"빈 병 한 개를 돌려주면 80원을 받아요. 1200원을 받았다면 돌려준 빈 병은 몇 개인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["받은 돈 ÷ 한 개에 받는 돈.","1200 ÷ 80 = 15예요.","빈 병 15개를 돌려줬어요."],"asset":{"type":"ldiv","a":1200,"b":80,"upto":0}},{"stem":"빈 병 한 개를 돌려주면 40원을 받아요. 1120원을 받았다면 돌려준 빈 병은 몇 개인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["받은 돈 ÷ 한 개에 받는 돈.","1120 ÷ 40 = 28이에요.","빈 병 28개를 돌려줬어요."],"asset":{"type":"ldiv","a":1120,"b":40,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
