INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_c#18','math',4,1,'u3','','g4_1_math_u3_review_c','unit_review','M4-1-u3-C4',3,'mc','auto','도윤이 433 × 43을 계산해 3031이라고 했어요. 어림해 보면 어떤가요?',ARRAY['M4-1-u3-X17','M4-1-u3-X14']::text[],true,'{"seq":18,"concept":"M4-1-u3-C4","difficulty":3,"kind":"mc","stem":"도윤이 433 × 43을 계산해 3031이라고 했어요. 어림해 보면 어떤가요?","options":[{"t":"16000쯤인데 3031은 너무 작아요 — 잘못 계산했어요","correct":true},{"t":"어림값과 비슷하니 맞게 계산했어요","mis":"M4-1-u3-X17"},{"t":"어림으로는 맞았는지 알 수 없어요","mis":"M4-1-u3-X17"},{"t":"16000쯤인데 3031은 너무 커요 — 잘못 계산했어요","mis":"M4-1-u3-X14"}],"explanation":["433 × 43 — 약 400 × 40 = 16000.","3031은 어림값보다 훨씬 작아요.","바른 곱은 18619예요."],"variant_rule":{"alt":[{"stem":"하린이 648 × 16을 계산해 6480이라고 했어요. 어림해 보면 어떤가요?","options":[{"t":"12000쯤인데 6480은 너무 작아요 — 잘못 계산했어요","correct":true},{"t":"어림값과 비슷하니 맞게 계산했어요","mis":"M4-1-u3-X17"},{"t":"어림으로는 맞았는지 알 수 없어요","mis":"M4-1-u3-X17"},{"t":"12000쯤인데 6480은 너무 커요 — 잘못 계산했어요","mis":"M4-1-u3-X14"}],"explanation":["648 × 16 — 약 600 × 20 = 12000.","6480은 어림값보다 훨씬 작아요.","바른 곱은 10368이에요."],"asset":null},{"stem":"하린이 718 × 86을 계산해 57440이라고 했어요. 어림해 보면 어떤가요?","options":[{"t":"63000쯤인데 57440은 너무 작아요 — 잘못 계산했어요","correct":true},{"t":"어림값과 비슷하니 맞게 계산했어요","mis":"M4-1-u3-X17"},{"t":"어림으로는 맞았는지 알 수 없어요","mis":"M4-1-u3-X17"},{"t":"63000쯤인데 57440은 너무 커요 — 잘못 계산했어요","mis":"M4-1-u3-X14"}],"explanation":["718 × 86 — 약 700 × 90 = 63000.","57440은 어림값보다 훨씬 작아요.","바른 곱은 61748이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_c#19','math',4,1,'u3','','g4_1_math_u3_review_c','unit_review','M4-1-u3-C5',3,'error','auto','친구들이 나눗셈을 했어요. 잘못 계산한 친구는 누구인가요?',ARRAY['M4-1-u3-X09','M4-1-u3-X14']::text[],true,'{"seq":19,"concept":"M4-1-u3-C5","difficulty":3,"kind":"error","stem":"친구들이 나눗셈을 했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"지유 — 119 ÷ 40 = 2 … 3","correct":true,"mis_target":"M4-1-u3-X09"},{"t":"서준 — 559 ÷ 90 = 6 … 19","mis":"M4-1-u3-X14"},{"t":"도윤 — 683 ÷ 80 = 8 … 43","mis":"M4-1-u3-X14"}],"explanation":["119 ÷ 40 — 40 × 2 = 80.","119 − 80 = 39예요 — 나머지예요.","지유가 0을 지우고 11 ÷ 4를 계산해 나머지를 3으로 썼어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 친구들이 나눗셈을 했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"시아 — 177 ÷ 50 = 3 … 2","correct":true,"mis_target":"M4-1-u3-X09"},{"t":"서준 — 567 ÷ 70 = 8 … 7","mis":"M4-1-u3-X14"},{"t":"지유 — 112 ÷ 30 = 3 … 22","mis":"M4-1-u3-X14"}],"explanation":["177 ÷ 50 — 50 × 3 = 150.","177 − 150 = 27이에요 — 나머지예요.","시아가 0을 지우고 17 ÷ 5를 계산해 나머지를 2로 썼어요."],"asset":null},{"stem":"이번에는 다른 수예요. 친구들이 나눗셈을 했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"시아 — 301 ÷ 70 = 4 … 2","correct":true,"mis_target":"M4-1-u3-X09"},{"t":"서준 — 567 ÷ 70 = 8 … 7","mis":"M4-1-u3-X14"},{"t":"지유 — 112 ÷ 30 = 3 … 22","mis":"M4-1-u3-X14"}],"explanation":["301 ÷ 70 — 70 × 4 = 280.","301 − 280 = 21이에요 — 나머지예요.","시아가 0을 지우고 30 ÷ 7을 계산해 나머지를 2로 썼어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_c#20','math',4,1,'u3','','g4_1_math_u3_review_c','unit_review','M4-1-u3-C9',3,'error','auto','하린이 477 ÷ 44 = 1 … 37이라고 계산했어요. 무엇이 잘못됐나요?',ARRAY['M4-1-u3-X11','M4-1-u3-X07','M4-1-u3-X08']::text[],true,'{"seq":20,"concept":"M4-1-u3-C9","difficulty":3,"kind":"error","stem":"하린이 477 ÷ 44 = 1 … 37이라고 계산했어요. 무엇이 잘못됐나요?","options":[{"t":"몫의 일의 자리에 0을 쓰지 않았어요","correct":true,"mis_target":"M4-1-u3-X11"},{"t":"나머지가 나누는 수보다 커요","mis":"M4-1-u3-X07"},{"t":"몫을 1 크게 해야 해요","mis":"M4-1-u3-X08"}],"explanation":["44 × 10 = 440 — 몫의 십의 자리 1.","남은 37이 44보다 작아 일의 자리 몫은 0.","바르게: 477 ÷ 44 = 10 … 37이에요."],"asset":{"type":"ldiv","a":477,"b":44},"variant_rule":{"alt":[{"stem":"은우가 823 ÷ 27 = 3 … 13이라고 계산했어요. 무엇이 잘못됐나요?","options":[{"t":"몫의 일의 자리에 0을 쓰지 않았어요","correct":true,"mis_target":"M4-1-u3-X11"},{"t":"나머지가 나누는 수보다 커요","mis":"M4-1-u3-X07"},{"t":"몫을 1 크게 해야 해요","mis":"M4-1-u3-X08"}],"explanation":["27 × 30 = 810 — 몫의 십의 자리 3.","남은 13이 27보다 작아 일의 자리 몫은 0.","바르게: 823 ÷ 27 = 30 … 13이에요."],"asset":{"type":"ldiv","a":823,"b":27}},{"stem":"시아가 177 ÷ 17 = 1 … 7이라고 계산했어요. 무엇이 잘못됐나요?","options":[{"t":"몫의 일의 자리에 0을 쓰지 않았어요","correct":true,"mis_target":"M4-1-u3-X11"},{"t":"나머지가 나누는 수보다 커요","mis":"M4-1-u3-X07"},{"t":"몫을 1 크게 해야 해요","mis":"M4-1-u3-X08"}],"explanation":["17 × 10 = 170 — 몫의 십의 자리 1.","남은 7이 17보다 작아 일의 자리 몫은 0.","바르게: 177 ÷ 17 = 10 … 7이에요."],"asset":{"type":"ldiv","a":177,"b":17}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_c#21','math',4,1,'u3','','g4_1_math_u3_review_c','unit_review','M4-1-u3-C10',3,'mc','auto','달걀 159개를 한 판에 39개씩 담으려고 해요. 가득 채운 판은 몇 판인가요?',ARRAY['M4-1-u3-X13','M4-1-u3-X14','M4-1-u3-X15']::text[],true,'{"seq":21,"concept":"M4-1-u3-C10","difficulty":3,"kind":"mc","stem":"달걀 159개를 한 판에 39개씩 담으려고 해요. 가득 채운 판은 몇 판인가요?","options":[{"t":"4판","correct":true},{"t":"5판","mis":"M4-1-u3-X13"},{"t":"3판","mis":"M4-1-u3-X14"},{"t":"7판","mis":"M4-1-u3-X15"}],"explanation":["159 ÷ 39 = 4 … 3.","남은 3은 하나를 다 채우지 못해요.","답은 4판이에요."],"variant_rule":{"alt":[{"stem":"사과 567개를 한 상자에 59개씩 남김없이 모두 담으려고 해요. 상자는 적어도 몇 개 필요한가요?","options":[{"t":"10개","correct":true},{"t":"9개","mis":"M4-1-u3-X13"},{"t":"36개","mis":"M4-1-u3-X14"},{"t":"45개","mis":"M4-1-u3-X15"}],"explanation":["567 ÷ 59 = 9 … 36.","남은 36도 담아야 하니 하나 더 — 9 + 1 = 10.","답은 10개예요."],"asset":null},{"stem":"책 259쪽을 하루에 51쪽씩 읽으려고 해요. 책을 다 읽으려면 적어도 며칠이 걸리나요?","options":[{"t":"6일","correct":true},{"t":"5일","mis":"M4-1-u3-X13"},{"t":"4일","mis":"M4-1-u3-X14"},{"t":"9일","mis":"M4-1-u3-X15"}],"explanation":["259 ÷ 51 = 5 … 4.","남은 4도 읽어야 하니 하나 더 — 5 + 1 = 6.","답은 6일이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_c#22','math',4,1,'u3','','g4_1_math_u3_review_c','unit_review','M4-1-u3-C6',3,'sa','auto','어떤 수를 23으로 나누었더니 몫이 4, 나머지가 2가 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":22,"concept":"M4-1-u3-C6","difficulty":3,"kind":"sa","stem":"어떤 수를 23으로 나누었더니 몫이 4, 나머지가 2가 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["94"],"explanation":["나누어지는 수 = (나누는 수) × (몫) + (나머지).","23 × 4 = 92.","92 + 2 = 94 — 어떤 수는 94예요."],"asset":{"type":"expr_grid","rows":[["23 × 4","=","92"],["92 + 2","=",null]]},"variant_rule":{"alt":[{"stem":"어떤 수를 40으로 나누었더니 몫이 3, 나머지가 18이 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["138"],"explanation":["나누어지는 수 = (나누는 수) × (몫) + (나머지).","40 × 3 = 120.","120 + 18 = 138 — 어떤 수는 138이에요."],"asset":{"type":"expr_grid","rows":[["40 × 3","=","120"],["120 + 18","=",null]]}},{"stem":"어떤 수를 85로 나누었더니 몫이 8, 나머지가 5가 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["685"],"explanation":["나누어지는 수 = (나누는 수) × (몫) + (나머지).","85 × 8 = 680.","680 + 5 = 685 — 어떤 수는 685예요."],"asset":{"type":"expr_grid","rows":[["85 × 8","=","680"],["680 + 5","=",null]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_c#23','math',4,1,'u3','','g4_1_math_u3_review_c','unit_review','M4-1-u3-C3',4,'mc','auto','수 카드 7, 8, 4, 3, 6을 한 번씩 모두 써서 (세 자리 수) × (두 자리 수)를 만들려고 해요. 가장 큰 곱은 얼마인가요?',ARRAY['M4-1-u3-X14','M4-1-u3-X16']::text[],true,'{"seq":23,"concept":"M4-1-u3-C3","difficulty":4,"kind":"mc","stem":"수 카드 7, 8, 4, 3, 6을 한 번씩 모두 써서 (세 자리 수) × (두 자리 수)를 만들려고 해요. 가장 큰 곱은 얼마인가요?","options":[{"t":"64092","correct":true},{"t":"37668","mis":"M4-1-u3-X14"},{"t":"63862","mis":"M4-1-u3-X14"},{"t":"6409","mis":"M4-1-u3-X16"}],"explanation":["가장 큰 두 숫자를 두 수의 맨 앞(백의 자리·십의 자리)에 나누어 놓아요.","여러 가지로 놓아 곱을 견주면 763 × 84가 가장 커요.","763 × 84 = 64092예요."],"variant_rule":{"alt":[{"stem":"수 카드 6, 2, 3, 8, 9를 한 번씩 모두 써서 (세 자리 수) × (두 자리 수)를 만들려고 해요. 가장 큰 곱은 얼마인가요?","options":[{"t":"80166","correct":true},{"t":"31552","mis":"M4-1-u3-X14"},{"t":"79846","mis":"M4-1-u3-X14"},{"t":"8016","mis":"M4-1-u3-X16"}],"explanation":["가장 큰 두 숫자를 두 수의 맨 앞(백의 자리·십의 자리)에 나누어 놓아요.","여러 가지로 놓아 곱을 견주면 862 × 93이 가장 커요.","862 × 93 = 80166이에요."],"asset":null},{"stem":"수 카드 7, 8, 1, 3, 6을 한 번씩 모두 써서 (세 자리 수) × (두 자리 수)를 만들려고 해요. 가장 큰 곱은 얼마인가요?","options":[{"t":"63163","correct":true},{"t":"27156","mis":"M4-1-u3-X14"},{"t":"62853","mis":"M4-1-u3-X14"},{"t":"6316","mis":"M4-1-u3-X16"}],"explanation":["가장 큰 두 숫자를 두 수의 맨 앞(백의 자리·십의 자리)에 나누어 놓아요.","여러 가지로 놓아 곱을 견주면 761 × 83이 가장 커요.","761 × 83 = 63163이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_c#24','math',4,1,'u3','','g4_1_math_u3_review_c','unit_review','M4-1-u3-C10',4,'mc','auto','오늘 반찬은 한 사람에 668 g, 내일 반찬은 한 사람에 444 g이에요. 21명이 먹을 때 내일은 오늘보다 탄소 발자국이 몇 g 줄어드나요?',ARRAY['M4-1-u3-X18','M4-1-u3-X15']::text[],true,'{"seq":24,"concept":"M4-1-u3-C10","difficulty":4,"kind":"mc","stem":"오늘 반찬은 한 사람에 668 g, 내일 반찬은 한 사람에 444 g이에요. 21명이 먹을 때 내일은 오늘보다 탄소 발자국이 몇 g 줄어드나요?","options":[{"t":"4704 g","correct":true},{"t":"224 g","mis":"M4-1-u3-X18"},{"t":"23352 g","mis":"M4-1-u3-X15"},{"t":"9324 g","mis":"M4-1-u3-X18"}],"explanation":["오늘 668 × 21 = 14028 g.","내일 444 × 21 = 9324 g.","14028 − 9324 = 4704 g 줄어요."],"variant_rule":{"alt":[{"stem":"오늘 반찬은 한 사람에 643 g, 내일 반찬은 한 사람에 442 g이에요. 24명이 먹을 때 내일은 오늘보다 탄소 발자국이 몇 g 줄어드나요?","options":[{"t":"4824 g","correct":true},{"t":"201 g","mis":"M4-1-u3-X18"},{"t":"26040 g","mis":"M4-1-u3-X15"},{"t":"10608 g","mis":"M4-1-u3-X18"}],"explanation":["오늘 643 × 24 = 15432 g.","내일 442 × 24 = 10608 g.","15432 − 10608 = 4824 g 줄어요."],"asset":null},{"stem":"오늘 반찬은 한 사람에 628 g, 내일 반찬은 한 사람에 321 g이에요. 30명이 먹을 때 내일은 오늘보다 탄소 발자국이 몇 g 줄어드나요?","options":[{"t":"9210 g","correct":true},{"t":"307 g","mis":"M4-1-u3-X18"},{"t":"28470 g","mis":"M4-1-u3-X15"},{"t":"9630 g","mis":"M4-1-u3-X18"}],"explanation":["오늘 628 × 30 = 18840 g.","내일 321 × 30 = 9630 g.","18840 − 9630 = 9210 g 줄어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_c#25','math',4,1,'u3','','g4_1_math_u3_review_c','unit_review','M4-1-u3-C10',4,'essay','teacher','122쪽짜리 책을 하루에 16쪽씩 읽어요. 책을 다 읽는 데 며칠이 걸리는지 구하고, 그렇게 답한 까닭을 나머지를 들어 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M4-1-u3-C10","difficulty":4,"kind":"essay","stem":"122쪽짜리 책을 하루에 16쪽씩 읽어요. 책을 다 읽는 데 며칠이 걸리는지 구하고, 그렇게 답한 까닭을 나머지를 들어 설명해 보세요.","answer_guide":{"answer":"예: 122 ÷ 16 = 7 … 10이다. 7일 동안 112쪽을 읽고 10쪽이 남는데, 남은 10쪽도 읽어야 하므로 하루가 더 필요하다. 그래서 8일이 걸린다.","scoring_points":["122 ÷ 16 = 7 … 10을 구했는가","남은 10쪽도 읽어야 한다고 설명했는가","8일이라고 답했는가"]},"explanation":["122 ÷ 16 = 7 … 10.","남은 10쪽도 읽어야 해요.","7 + 1 = 8일."],"asset":{"type":"ldiv","a":122,"b":16,"upto":0}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_d#1','math',4,1,'u3','','g4_1_math_u3_review_d','unit_review','M4-1-u3-C2',1,'sa','auto','399 × 20은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-1-u3-C2","difficulty":1,"kind":"sa","stem":"399 × 20은 얼마인가요? 숫자로 쓰세요.","answer":["7980"],"explanation":["399 × 2 = 798 — 먼저 몇을 곱해요.","곱하는 수가 10배(2 → 20)라서 곱도 10배예요.","399 × 20 = 7980이에요."],"variant_rule":{"alt":[{"stem":"115 × 60은 얼마인가요? 숫자로 쓰세요.","answer":["6900"],"explanation":["115 × 6 = 690 — 먼저 몇을 곱해요.","곱하는 수가 10배(6 → 60)라서 곱도 10배예요.","115 × 60 = 6900이에요."],"asset":null},{"stem":"352 × 20은 얼마인가요? 숫자로 쓰세요.","answer":["7040"],"explanation":["352 × 2 = 704 — 먼저 몇을 곱해요.","곱하는 수가 10배(2 → 20)라서 곱도 10배예요.","352 × 20 = 7040이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_d#2','math',4,1,'u3','','g4_1_math_u3_review_d','unit_review','M4-1-u3-C1',1,'sa','auto','294 × 41을 아는 계산으로 쪼갰어요. 294 × 41 = 294 × 40 + 294 × □에서 □ 안에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-1-u3-C1","difficulty":1,"kind":"sa","stem":"294 × 41을 아는 계산으로 쪼갰어요. 294 × 41 = 294 × 40 + 294 × □에서 □ 안에 알맞은 수를 쓰세요.","answer":["1"],"explanation":["41은 40과 1의 합이에요.","41번 더한 것 = 40번 더하고 1번 더 더한 것.","□ = 1이에요."],"asset":{"type":"expr_grid","rows":[["294 × 40","=","11760"],["294 × 1","=","294"],["11760 + 294","=","12054"]]},"variant_rule":{"alt":[{"stem":"974 × 51을 아는 계산으로 쪼갰어요. 974 × 51 = 974 × 50 + 974 × □에서 □ 안에 알맞은 수를 쓰세요.","answer":["1"],"explanation":["51은 50과 1의 합이에요.","51번 더한 것 = 50번 더하고 1번 더 더한 것.","□ = 1이에요."],"asset":{"type":"expr_grid","rows":[["974 × 50","=","48700"],["974 × 1","=","974"],["48700 + 974","=","49674"]]}},{"stem":"872 × 23을 아는 계산으로 쪼갰어요. 872 × 23 = 872 × 20 + 872 × □에서 □ 안에 알맞은 수를 쓰세요.","answer":["3"],"explanation":["23은 20과 3의 합이에요.","23번 더한 것 = 20번 더하고 3번 더 더한 것.","□ = 3이에요."],"asset":{"type":"expr_grid","rows":[["872 × 20","=","17440"],["872 × 3","=","2616"],["17440 + 2616","=","20056"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_d#3','math',4,1,'u3','','g4_1_math_u3_review_d','unit_review','M4-1-u3-C3',1,'sa','auto','182 × 42의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-1-u3-C3","difficulty":1,"kind":"sa","stem":"182 × 42의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["8"],"explanation":["일의 자리 2를 먼저 곱하고, 십의 자리 4를 곱한 값은 한 칸 밀어 써요.","넷째 줄은 182 × 4 = 728 — 한 칸 밀어 써서 7280을 나타내요.","?는 십의 자리 숫자 8이에요."],"asset":{"type":"expr_grid","rows":[["","","","1","8","2"],["×","","","","4","2"],["","","","3","6","4"],["","","7","2",null,""],["","","7","6","4","4"]]},"variant_rule":{"alt":[{"stem":"632 × 15의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["1"],"explanation":["일의 자리 5를 먼저 곱하고, 십의 자리 1을 곱한 값은 한 칸 밀어 써요.","셋째 줄은 632 × 5 = 3160이에요.","?는 백의 자리 숫자 1이에요."],"asset":{"type":"expr_grid","rows":[["","","","6","3","2"],["×","","","","1","5"],["","","3",null,"6","0"],["","","6","3","2",""],["","","9","4","8","0"]]}},{"stem":"245 × 35의 세로셈이에요. ?에 알맞은 숫자를 쓰세요.","answer":["2"],"explanation":["일의 자리 5를 먼저 곱하고, 십의 자리 3을 곱한 값은 한 칸 밀어 써요.","셋째 줄은 245 × 5 = 1225예요.","?는 백의 자리 숫자 2예요."],"asset":{"type":"expr_grid","rows":[["","","","2","4","5"],["×","","","","3","5"],["","","1",null,"2","5"],["","","7","3","5",""],["","","8","5","7","5"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_d#4','math',4,1,'u3','','g4_1_math_u3_review_d','unit_review','M4-1-u3-C5',1,'sa','auto','866 ÷ 90의 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-1-u3-C5","difficulty":1,"kind":"sa","stem":"866 ÷ 90의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["866 ÷ 90 — 860은 십 모형 86개, 90은 십 모형 9개로 보면 86 ÷ 9와 같아요.","866 − 810 = 56 — 56은 90보다 작아요.","866 ÷ 90 = 9 … 56이에요."],"asset":{"type":"ldiv","a":866,"b":90,"upto":0},"variant_rule":{"alt":[{"stem":"576 ÷ 60의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["576 ÷ 60 — 570은 십 모형 57개, 60은 십 모형 6개로 보면 57 ÷ 6과 같아요.","576 − 540 = 36 — 36은 60보다 작아요.","576 ÷ 60 = 9 … 36이에요."],"asset":{"type":"ldiv","a":576,"b":60,"upto":0}},{"stem":"182 ÷ 30의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["182 ÷ 30 — 180은 십 모형 18개, 30은 십 모형 3개로 보면 18 ÷ 3과 같아요.","182 − 180 = 2 — 2는 30보다 작아요.","182 ÷ 30 = 6 … 2예요."],"asset":{"type":"ldiv","a":182,"b":30,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_d#5','math',4,1,'u3','','g4_1_math_u3_review_d','unit_review','M4-1-u3-C7',1,'sa','auto','72 ÷ 14의 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-1-u3-C7","difficulty":1,"kind":"sa","stem":"72 ÷ 14의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["14 × 5 = 70, 14 × 6 = 84 — 72를 넘지 않으면서 가장 가까운 곱을 찾아요.","72 − 70 = 2 — 2는 14보다 작아요.","72 ÷ 14 = 5 … 2예요."],"asset":{"type":"ldiv","a":72,"b":14,"upto":0},"variant_rule":{"alt":[{"stem":"35 ÷ 17의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["17 × 2 = 34, 17 × 3 = 51 — 35를 넘지 않으면서 가장 가까운 곱을 찾아요.","35 − 34 = 1 — 1은 17보다 작아요.","35 ÷ 17 = 2 … 1이에요."],"asset":{"type":"ldiv","a":35,"b":17,"upto":0}},{"stem":"84 ÷ 19의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["19 × 4 = 76, 19 × 5 = 95 — 84를 넘지 않으면서 가장 가까운 곱을 찾아요.","84 − 76 = 8 — 8은 19보다 작아요.","84 ÷ 19 = 4 … 8이에요."],"asset":{"type":"ldiv","a":84,"b":19,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_d#6','math',4,1,'u3','','g4_1_math_u3_review_d','unit_review','M4-1-u3-C8',1,'sa','auto','784 ÷ 82의 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M4-1-u3-C8","difficulty":1,"kind":"sa","stem":"784 ÷ 82의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["82 × 9 = 738, 82 × 10 = 820 — 784를 넘지 않으면서 가장 가까운 곱을 찾아요.","784 − 738 = 46 — 46은 82보다 작아요.","784 ÷ 82 = 9 … 46이에요."],"asset":{"type":"ldiv","a":784,"b":82,"upto":0},"variant_rule":{"alt":[{"stem":"299 ÷ 31의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["31 × 9 = 279, 31 × 10 = 310 — 299를 넘지 않으면서 가장 가까운 곱을 찾아요.","299 − 279 = 20 — 20은 31보다 작아요.","299 ÷ 31 = 9 … 20이에요."],"asset":{"type":"ldiv","a":299,"b":31,"upto":0}},{"stem":"552 ÷ 78의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["78 × 7 = 546, 78 × 8 = 624 — 552를 넘지 않으면서 가장 가까운 곱을 찾아요.","552 − 546 = 6 — 6은 78보다 작아요.","552 ÷ 78 = 7 … 6이에요."],"asset":{"type":"ldiv","a":552,"b":78,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_d#7','math',4,1,'u3','','g4_1_math_u3_review_d','unit_review','M4-1-u3-C9',1,'sa','auto','243 ÷ 22의 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M4-1-u3-C9","difficulty":1,"kind":"sa","stem":"243 ÷ 22의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["먼저 몇십 번: 22 × 10 = 220 → 23이 남아요.","243 − 242 = 1 — 1은 22보다 작아요.","243 ÷ 22 = 11 … 1이에요."],"asset":{"type":"ldiv","a":243,"b":22,"upto":0},"variant_rule":{"alt":[{"stem":"292 ÷ 15의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["19"],"explanation":["먼저 몇십 번: 15 × 10 = 150 → 142가 남아요.","292 − 285 = 7 — 7은 15보다 작아요.","292 ÷ 15 = 19 … 7이에요."],"asset":{"type":"ldiv","a":292,"b":15,"upto":0}},{"stem":"913 ÷ 17의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["53"],"explanation":["먼저 몇십 번: 17 × 50 = 850 → 63이 남아요.","913 − 901 = 12 — 12는 17보다 작아요.","913 ÷ 17 = 53 … 12예요."],"asset":{"type":"ldiv","a":913,"b":17,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_d#8','math',4,1,'u3','','g4_1_math_u3_review_d','unit_review','M4-1-u3-C10',1,'sa','auto','반찬 한 사람 몫의 탄소 발자국이에요 — 깍두기 58 g, 닭볶음 312 g, 잡곡밥 136 g. 세 반찬의 탄소 발자국을 모두 더하면 몇 g인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M4-1-u3-C10","difficulty":1,"kind":"sa","stem":"반찬 한 사람 몫의 탄소 발자국이에요 — 깍두기 58 g, 닭볶음 312 g, 잡곡밥 136 g. 세 반찬의 탄소 발자국을 모두 더하면 몇 g인가요? 숫자로 쓰세요.","answer":["506"],"explanation":["세 값을 차례로 더해요.","58 + 312 + 136 = 506.","한 사람 몫은 506 g이에요."],"variant_rule":{"alt":[{"stem":"반찬 한 사람 몫의 탄소 발자국이에요 — 깍두기 58 g, 불고기 460 g, 배추김치 76 g. 세 반찬의 탄소 발자국을 모두 더하면 몇 g인가요? 숫자로 쓰세요.","answer":["594"],"explanation":["세 값을 차례로 더해요.","58 + 460 + 76 = 594.","한 사람 몫은 594 g이에요."],"asset":null},{"stem":"반찬 한 사람 몫의 탄소 발자국이에요 — 고등어조림 245 g, 배추김치 76 g, 닭볶음 312 g. 세 반찬의 탄소 발자국을 모두 더하면 몇 g인가요? 숫자로 쓰세요.","answer":["633"],"explanation":["세 값을 차례로 더해요.","245 + 76 + 312 = 633.","한 사람 몫은 633 g이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_d#9','math',4,1,'u3','','g4_1_math_u3_review_d','unit_review','M4-1-u3-C3',2,'mc','auto','593 × 54는 얼마인가요?',ARRAY['M4-1-u3-X02','M4-1-u3-X03']::text[],true,'{"seq":9,"concept":"M4-1-u3-C3","difficulty":2,"kind":"mc","stem":"593 × 54는 얼마인가요?","options":[{"t":"32022","correct":true},{"t":"5337","mis":"M4-1-u3-X02"},{"t":"29650","mis":"M4-1-u3-X03"},{"t":"2372","mis":"M4-1-u3-X03"}],"explanation":["54를 50과 4로 쪼개요.","593 × 50 = 29650, 593 × 4 = 2372.","29650 + 2372 = 32022예요."],"variant_rule":{"alt":[{"stem":"906 × 34는 얼마인가요?","options":[{"t":"30804","correct":true},{"t":"6342","mis":"M4-1-u3-X02"},{"t":"27180","mis":"M4-1-u3-X03"},{"t":"3624","mis":"M4-1-u3-X03"}],"explanation":["34를 30과 4로 쪼개요.","906 × 30 = 27180, 906 × 4 = 3624.","27180 + 3624 = 30804예요."],"asset":null},{"stem":"671 × 45는 얼마인가요?","options":[{"t":"30195","correct":true},{"t":"6039","mis":"M4-1-u3-X02"},{"t":"26840","mis":"M4-1-u3-X03"},{"t":"3355","mis":"M4-1-u3-X03"}],"explanation":["45를 40과 5로 쪼개요.","671 × 40 = 26840, 671 × 5 = 3355.","26840 + 3355 = 30195예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_d#10','math',4,1,'u3','','g4_1_math_u3_review_d','unit_review','M4-1-u3-C4',2,'mc','auto','969 × 84를 몇백과 몇십으로 어림하면 약 얼마인가요?',ARRAY['M4-1-u3-X16','M4-1-u3-X15']::text[],true,'{"seq":10,"concept":"M4-1-u3-C4","difficulty":2,"kind":"mc","stem":"969 × 84를 몇백과 몇십으로 어림하면 약 얼마인가요?","options":[{"t":"약 80000","correct":true},{"t":"약 800000","mis":"M4-1-u3-X16"},{"t":"약 8000","mis":"M4-1-u3-X16"},{"t":"약 1080","mis":"M4-1-u3-X15"}],"explanation":["969는 약 1000, 84는 약 80이에요.","1000 × 80 = 80000이에요 — 0의 개수를 세어 붙여요.","실제 곱 81396은 어림값 80000에 가까워요."],"variant_rule":{"alt":[{"stem":"633 × 17을 몇백과 몇십으로 어림하면 약 얼마인가요?","options":[{"t":"약 12000","correct":true},{"t":"약 120000","mis":"M4-1-u3-X16"},{"t":"약 1200","mis":"M4-1-u3-X16"},{"t":"약 620","mis":"M4-1-u3-X15"}],"explanation":["633은 약 600, 17은 약 20이에요.","600 × 20 = 12000이에요 — 0의 개수를 세어 붙여요.","실제 곱 10761은 어림값 12000에 가까워요."],"asset":null},{"stem":"862 × 18을 몇백과 몇십으로 어림하면 약 얼마인가요?","options":[{"t":"약 18000","correct":true},{"t":"약 180000","mis":"M4-1-u3-X16"},{"t":"약 1800","mis":"M4-1-u3-X16"},{"t":"약 920","mis":"M4-1-u3-X15"}],"explanation":["862는 약 900, 18은 약 20이에요.","900 × 20 = 18000이에요 — 0의 개수를 세어 붙여요.","실제 곱 15516은 어림값 18000에 가까워요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_d#11','math',4,1,'u3','','g4_1_math_u3_review_d','unit_review','M4-1-u3-C6',2,'mc','auto','893 ÷ 97 = 9 … 20이 맞는지 확인하는 식은 어느 것인가요?',ARRAY['M4-1-u3-X10','M4-1-u3-X15']::text[],true,'{"seq":11,"concept":"M4-1-u3-C6","difficulty":2,"kind":"mc","stem":"893 ÷ 97 = 9 … 20이 맞는지 확인하는 식은 어느 것인가요?","options":[{"t":"97 × 9 + 20 = 893","correct":true},{"t":"97 × 9 − 20 = 853","mis":"M4-1-u3-X10"},{"t":"893 × 97 + 20","mis":"M4-1-u3-X10"},{"t":"97 + 9 + 20 = 126","mis":"M4-1-u3-X15"}],"explanation":["확인은 (나누는 수) × (몫) + (나머지).","97 × 9 = 873, 873 + 20 = 893이에요.","나누어지는 수 893과 같으니 바르게 계산했어요."],"asset":{"type":"expr_grid","rows":[["97 × 9","=","873"],["873 + 20","=","893"]]},"variant_rule":{"alt":[{"stem":"302 ÷ 39 = 7 … 29가 맞는지 확인하는 식은 어느 것인가요?","options":[{"t":"39 × 7 + 29 = 302","correct":true},{"t":"39 × 7 − 29 = 244","mis":"M4-1-u3-X10"},{"t":"302 × 39 + 29","mis":"M4-1-u3-X10"},{"t":"39 + 7 + 29 = 75","mis":"M4-1-u3-X15"}],"explanation":["확인은 (나누는 수) × (몫) + (나머지).","39 × 7 = 273, 273 + 29 = 302예요.","나누어지는 수 302와 같으니 바르게 계산했어요."],"asset":{"type":"expr_grid","rows":[["39 × 7","=","273"],["273 + 29","=","302"]]}},{"stem":"290 ÷ 89 = 3 … 23이 맞는지 확인하는 식은 어느 것인가요?","options":[{"t":"89 × 3 + 23 = 290","correct":true},{"t":"89 × 3 − 23 = 244","mis":"M4-1-u3-X10"},{"t":"290 × 89 + 23","mis":"M4-1-u3-X10"},{"t":"89 + 3 + 23 = 115","mis":"M4-1-u3-X15"}],"explanation":["확인은 (나누는 수) × (몫) + (나머지).","89 × 3 = 267, 267 + 23 = 290이에요.","나누어지는 수 290과 같으니 바르게 계산했어요."],"asset":{"type":"expr_grid","rows":[["89 × 3","=","267"],["267 + 23","=","290"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_d#12','math',4,1,'u3','','g4_1_math_u3_review_d','unit_review','M4-1-u3-C5',2,'mc','auto','202 ÷ 60을 계산하여 몫과 나머지를 바르게 구한 것은 어느 것인가요?',ARRAY['M4-1-u3-X07','M4-1-u3-X08','M4-1-u3-X09']::text[],true,'{"seq":12,"concept":"M4-1-u3-C5","difficulty":2,"kind":"mc","stem":"202 ÷ 60을 계산하여 몫과 나머지를 바르게 구한 것은 어느 것인가요?","options":[{"t":"몫 3, 나머지 22","correct":true},{"t":"몫 2, 나머지 82","mis":"M4-1-u3-X07"},{"t":"몫 4, 나머지 없음","mis":"M4-1-u3-X08"},{"t":"몫 3, 나머지 2","mis":"M4-1-u3-X09"}],"explanation":["202 ÷ 60 — 200은 십 모형 20개, 60은 십 모형 6개로 보면 20 ÷ 6과 같아요.","202 − 180 = 22 — 22는 60보다 작아요.","202 ÷ 60 = 3 … 22예요."],"asset":{"type":"ldiv","a":202,"b":60,"upto":0},"variant_rule":{"alt":[{"stem":"179 ÷ 40을 계산하여 몫과 나머지를 바르게 구한 것은 어느 것인가요?","options":[{"t":"몫 4, 나머지 19","correct":true},{"t":"몫 3, 나머지 59","mis":"M4-1-u3-X07"},{"t":"몫 5, 나머지 없음","mis":"M4-1-u3-X08"},{"t":"몫 4, 나머지 1","mis":"M4-1-u3-X09"}],"explanation":["179 ÷ 40 — 170은 십 모형 17개, 40은 십 모형 4개로 보면 17 ÷ 4와 같아요.","179 − 160 = 19 — 19는 40보다 작아요.","179 ÷ 40 = 4 … 19예요."],"asset":{"type":"ldiv","a":179,"b":40,"upto":0}},{"stem":"544 ÷ 90을 계산하여 몫과 나머지를 바르게 구한 것은 어느 것인가요?","options":[{"t":"몫 6, 나머지 4","correct":true},{"t":"몫 5, 나머지 94","mis":"M4-1-u3-X07"},{"t":"몫 7, 나머지 없음","mis":"M4-1-u3-X08"},{"t":"몫 4, 나머지 6","mis":"M4-1-u3-X14"}],"explanation":["544 ÷ 90 — 540은 십 모형 54개, 90은 십 모형 9개로 보면 54 ÷ 9와 같아요.","544 − 540 = 4 — 4는 90보다 작아요.","544 ÷ 90 = 6 … 4예요."],"asset":{"type":"ldiv","a":544,"b":90,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_d#13','math',4,1,'u3','','g4_1_math_u3_review_d','unit_review','M4-1-u3-C7',2,'sa','auto','95 ÷ 38의 몫을 3으로 어림했더니 38 × 3 = 114가 95보다 커요. 알맞은 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":13,"concept":"M4-1-u3-C7","difficulty":2,"kind":"sa","stem":"95 ÷ 38의 몫을 3으로 어림했더니 38 × 3 = 114가 95보다 커요. 알맞은 몫은 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["곱 114가 95보다 커서 3은 너무 큰 몫이에요.","몫을 1 작게: 38 × 2 = 76.","알맞은 몫은 2예요."],"variant_rule":{"alt":[{"stem":"99 ÷ 24의 몫을 5로 어림했더니 24 × 5 = 120이 99보다 커요. 알맞은 몫은 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["곱 120이 99보다 커서 5는 너무 큰 몫이에요.","몫을 1 작게: 24 × 4 = 96.","알맞은 몫은 4예요."],"asset":null},{"stem":"83 ÷ 23의 몫을 2로 어림해 23 × 2 = 46을 빼니 37이 남았어요. 알맞은 몫은 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["남은 37이 나누는 수 23보다 커요.","한 번 더 나눌 수 있으니 몫을 1 크게: 3.","알맞은 몫은 3이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_d#14','math',4,1,'u3','','g4_1_math_u3_review_d','unit_review','M4-1-u3-C8',2,'mc','auto','291 ÷ 55를 계산하여 몫과 나머지를 바르게 구한 것은 어느 것인가요?',ARRAY['M4-1-u3-X07','M4-1-u3-X08','M4-1-u3-X14']::text[],true,'{"seq":14,"concept":"M4-1-u3-C8","difficulty":2,"kind":"mc","stem":"291 ÷ 55를 계산하여 몫과 나머지를 바르게 구한 것은 어느 것인가요?","options":[{"t":"몫 5, 나머지 16","correct":true},{"t":"몫 4, 나머지 71","mis":"M4-1-u3-X07"},{"t":"몫 6, 나머지 없음","mis":"M4-1-u3-X08"},{"t":"몫 16, 나머지 5","mis":"M4-1-u3-X14"}],"explanation":["55 × 5 = 275, 55 × 6 = 330 — 291을 넘지 않으면서 가장 가까운 곱을 찾아요.","291 − 275 = 16 — 16은 55보다 작아요.","291 ÷ 55 = 5 … 16이에요."],"asset":{"type":"ldiv","a":291,"b":55,"upto":0},"variant_rule":{"alt":[{"stem":"132 ÷ 49를 계산하여 몫과 나머지를 바르게 구한 것은 어느 것인가요?","options":[{"t":"몫 2, 나머지 34","correct":true},{"t":"몫 1, 나머지 83","mis":"M4-1-u3-X07"},{"t":"몫 3, 나머지 없음","mis":"M4-1-u3-X08"},{"t":"몫 34, 나머지 2","mis":"M4-1-u3-X14"}],"explanation":["49 × 2 = 98, 49 × 3 = 147 — 132를 넘지 않으면서 가장 가까운 곱을 찾아요.","132 − 98 = 34 — 34는 49보다 작아요.","132 ÷ 49 = 2 … 34예요."],"asset":{"type":"ldiv","a":132,"b":49,"upto":0}},{"stem":"153 ÷ 34를 계산하여 몫과 나머지를 바르게 구한 것은 어느 것인가요?","options":[{"t":"몫 4, 나머지 17","correct":true},{"t":"몫 3, 나머지 51","mis":"M4-1-u3-X07"},{"t":"몫 5, 나머지 없음","mis":"M4-1-u3-X08"},{"t":"몫 17, 나머지 4","mis":"M4-1-u3-X14"}],"explanation":["34 × 4 = 136, 34 × 5 = 170 — 153을 넘지 않으면서 가장 가까운 곱을 찾아요.","153 − 136 = 17 — 17은 34보다 작아요.","153 ÷ 34 = 4 … 17이에요."],"asset":{"type":"ldiv","a":153,"b":34,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_d#15','math',4,1,'u3','','g4_1_math_u3_review_d','unit_review','M4-1-u3-C9',2,'sa','auto','794 ÷ 47에서 먼저 47 × 10 = 470을 뺐어요. 남은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":15,"concept":"M4-1-u3-C9","difficulty":2,"kind":"sa","stem":"794 ÷ 47에서 먼저 47 × 10 = 470을 뺐어요. 남은 수는 얼마인가요? 숫자로 쓰세요.","answer":["324"],"explanation":["794 − 470 = 324예요.","남은 324에 47이 6번 더 들어가요.","그래서 몫은 10 + 6 = 16이에요."],"asset":{"type":"ldiv","a":794,"b":47,"upto":1},"variant_rule":{"alt":[{"stem":"488 ÷ 37에서 먼저 37 × 10 = 370을 뺐어요. 남은 수는 얼마인가요? 숫자로 쓰세요.","answer":["118"],"explanation":["488 − 370 = 118이에요.","남은 118에 37이 3번 더 들어가요.","그래서 몫은 10 + 3 = 13이에요."],"asset":{"type":"ldiv","a":488,"b":37,"upto":1}},{"stem":"581 ÷ 26에서 먼저 26 × 20 = 520을 뺐어요. 남은 수는 얼마인가요? 숫자로 쓰세요.","answer":["61"],"explanation":["581 − 520 = 61이에요.","남은 61에 26이 2번 더 들어가요.","그래서 몫은 20 + 2 = 22예요."],"asset":{"type":"ldiv","a":581,"b":26,"upto":1}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_d#16','math',4,1,'u3','','g4_1_math_u3_review_d','unit_review','M4-1-u3-C10',2,'sa','auto','빈 병 한 개를 돌려주면 80원을 받아요. 2560원을 받았다면 돌려준 빈 병은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":16,"concept":"M4-1-u3-C10","difficulty":2,"kind":"sa","stem":"빈 병 한 개를 돌려주면 80원을 받아요. 2560원을 받았다면 돌려준 빈 병은 몇 개인가요? 숫자로 쓰세요.","answer":["32"],"explanation":["받은 돈 ÷ 한 개에 받는 돈.","2560 ÷ 80 = 32예요.","빈 병 32개를 돌려줬어요."],"asset":{"type":"ldiv","a":2560,"b":80,"upto":0},"variant_rule":{"alt":[{"stem":"빈 병 한 개를 돌려주면 80원을 받아요. 3440원을 받았다면 돌려준 빈 병은 몇 개인가요? 숫자로 쓰세요.","answer":["43"],"explanation":["받은 돈 ÷ 한 개에 받는 돈.","3440 ÷ 80 = 43이에요.","빈 병 43개를 돌려줬어요."],"asset":{"type":"ldiv","a":3440,"b":80,"upto":0}},{"stem":"빈 병 한 개를 돌려주면 70원을 받아요. 1890원을 받았다면 돌려준 빈 병은 몇 개인가요? 숫자로 쓰세요.","answer":["27"],"explanation":["받은 돈 ÷ 한 개에 받는 돈.","1890 ÷ 70 = 27이에요.","빈 병 27개를 돌려줬어요."],"asset":{"type":"ldiv","a":1890,"b":70,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_d#17','math',4,1,'u3','','g4_1_math_u3_review_d','unit_review','M4-1-u3-C3',3,'mc','auto','시아가 519 × 56을 이렇게 계산해 5709라고 했어요. 바르게 계산하면 얼마인가요?',ARRAY['M4-1-u3-X02','M4-1-u3-X03']::text[],true,'{"seq":17,"concept":"M4-1-u3-C3","difficulty":3,"kind":"mc","stem":"시아가 519 × 56을 이렇게 계산해 5709라고 했어요. 바르게 계산하면 얼마인가요?","options":[{"t":"29064","correct":true},{"t":"5709","mis":"M4-1-u3-X02"},{"t":"25950","mis":"M4-1-u3-X03"},{"t":"3114","mis":"M4-1-u3-X03"}],"explanation":["시아 — 넷째 줄을 한 칸 밀어 쓰지 않았어요.","519 × 6 = 3114, 519 × 50 = 25950.","3114 + 25950 = 29064예요."],"asset":{"type":"expr_grid","rows":[["","","","5","1","9"],["×","","","","5","6"],["","","3","1","1","4"],["","","2","5","9","5"],["","","5","7","0","9"]]},"variant_rule":{"alt":[{"stem":"서준이 607 × 47을 이렇게 계산해 6677이라고 했어요. 바르게 계산하면 얼마인가요?","options":[{"t":"28529","correct":true},{"t":"6677","mis":"M4-1-u3-X02"},{"t":"24280","mis":"M4-1-u3-X03"},{"t":"4249","mis":"M4-1-u3-X03"}],"explanation":["서준 — 넷째 줄을 한 칸 밀어 쓰지 않았어요.","607 × 7 = 4249, 607 × 40 = 24280.","4249 + 24280 = 28529예요."],"asset":{"type":"expr_grid","rows":[["","","","6","0","7"],["×","","","","4","7"],["","","4","2","4","9"],["","","2","4","2","8"],["","","6","6","7","7"]]}},{"stem":"시아가 617 × 69를 이렇게 계산해 7113이라고 했어요. 바르게 계산하면 얼마인가요?","options":[{"t":"42573","correct":true},{"t":"7113","mis":"M4-1-u3-X04"},{"t":"9255","mis":"M4-1-u3-X02"},{"t":"37020","mis":"M4-1-u3-X03"}],"explanation":["시아 — 올림한 수를 더하지 않았어요.","617 × 9 = 5553, 617 × 60 = 37020.","5553 + 37020 = 42573이에요."],"asset":{"type":"expr_grid","rows":[["","","","6","1","7"],["×","","","","6","9"],["","","","4","9","3"],["","","6","6","2",""],["","","7","1","1","3"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXC