INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_d#18','math',4,1,'u3','','g4_1_math_u3_review_d','unit_review','M4-1-u3-C4',3,'mc','auto','도윤이 473 × 34를 계산해 3311이라고 했어요. 어림해 보면 어떤가요?',ARRAY['M4-1-u3-X17','M4-1-u3-X14']::text[],true,'{"seq":18,"concept":"M4-1-u3-C4","difficulty":3,"kind":"mc","stem":"도윤이 473 × 34를 계산해 3311이라고 했어요. 어림해 보면 어떤가요?","options":[{"t":"15000쯤인데 3311은 너무 작아요 — 잘못 계산했어요","correct":true},{"t":"어림값과 비슷하니 맞게 계산했어요","mis":"M4-1-u3-X17"},{"t":"어림으로는 맞았는지 알 수 없어요","mis":"M4-1-u3-X17"},{"t":"15000쯤인데 3311은 너무 커요 — 잘못 계산했어요","mis":"M4-1-u3-X14"}],"explanation":["473 × 34 — 약 500 × 30 = 15000.","3311은 어림값보다 훨씬 작아요.","바른 곱은 16082예요."],"variant_rule":{"alt":[{"stem":"도윤이 962 × 79를 계산해 15392라고 했어요. 어림해 보면 어떤가요?","options":[{"t":"80000쯤인데 15392는 너무 작아요 — 잘못 계산했어요","correct":true},{"t":"어림값과 비슷하니 맞게 계산했어요","mis":"M4-1-u3-X17"},{"t":"어림으로는 맞았는지 알 수 없어요","mis":"M4-1-u3-X17"},{"t":"80000쯤인데 15392는 너무 커요 — 잘못 계산했어요","mis":"M4-1-u3-X14"}],"explanation":["962 × 79 — 약 1000 × 80 = 80000.","15392는 어림값보다 훨씬 작아요.","바른 곱은 75998이에요."],"asset":null},{"stem":"도윤이 573 × 96을 계산해 8595라고 했어요. 어림해 보면 어떤가요?","options":[{"t":"60000쯤인데 8595는 너무 작아요 — 잘못 계산했어요","correct":true},{"t":"어림값과 비슷하니 맞게 계산했어요","mis":"M4-1-u3-X17"},{"t":"어림으로는 맞았는지 알 수 없어요","mis":"M4-1-u3-X17"},{"t":"60000쯤인데 8595는 너무 커요 — 잘못 계산했어요","mis":"M4-1-u3-X14"}],"explanation":["573 × 96 — 약 600 × 100 = 60000.","8595는 어림값보다 훨씬 작아요.","바른 곱은 55008이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_d#19','math',4,1,'u3','','g4_1_math_u3_review_d','unit_review','M4-1-u3-C5',3,'error','auto','친구들이 나눗셈을 했어요. 잘못 계산한 친구는 누구인가요?',ARRAY['M4-1-u3-X09','M4-1-u3-X14']::text[],true,'{"seq":19,"concept":"M4-1-u3-C5","difficulty":3,"kind":"error","stem":"친구들이 나눗셈을 했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"도윤 — 287 ÷ 60 = 4 … 4","correct":true,"mis_target":"M4-1-u3-X09"},{"t":"서준 — 848 ÷ 90 = 9 … 38","mis":"M4-1-u3-X14"},{"t":"지유 — 211 ÷ 70 = 3 … 1","mis":"M4-1-u3-X14"}],"explanation":["287 ÷ 60 — 60 × 4 = 240.","287 − 240 = 47이에요 — 나머지예요.","도윤이 0을 지우고 28 ÷ 6을 계산해 나머지를 4로 썼어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 친구들이 나눗셈을 했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"시아 — 624 ÷ 90 = 6 … 8","correct":true,"mis_target":"M4-1-u3-X09"},{"t":"하린 — 134 ÷ 50 = 2 … 34","mis":"M4-1-u3-X14"},{"t":"지유 — 188 ÷ 80 = 2 … 28","mis":"M4-1-u3-X14"}],"explanation":["624 ÷ 90 — 90 × 6 = 540.","624 − 540 = 84예요 — 나머지예요.","시아가 0을 지우고 62 ÷ 9를 계산해 나머지를 8로 썼어요."],"asset":null},{"stem":"이번에는 다른 수예요. 친구들이 나눗셈을 했어요. 잘못 계산한 친구는 누구인가요?","options":[{"t":"도윤 — 406 ÷ 90 = 4 … 4","correct":true,"mis_target":"M4-1-u3-X09"},{"t":"하린 — 202 ÷ 50 = 4 … 2","mis":"M4-1-u3-X14"},{"t":"은우 — 131 ÷ 60 = 2 … 11","mis":"M4-1-u3-X14"}],"explanation":["406 ÷ 90 — 90 × 4 = 360.","406 − 360 = 46이에요 — 나머지예요.","도윤이 0을 지우고 40 ÷ 9를 계산해 나머지를 4로 썼어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_d#20','math',4,1,'u3','','g4_1_math_u3_review_d','unit_review','M4-1-u3-C9',3,'error','auto','건우가 996 ÷ 11 = 9 … 6이라고 계산했어요. 무엇이 잘못됐나요?',ARRAY['M4-1-u3-X11','M4-1-u3-X07','M4-1-u3-X08']::text[],true,'{"seq":20,"concept":"M4-1-u3-C9","difficulty":3,"kind":"error","stem":"건우가 996 ÷ 11 = 9 … 6이라고 계산했어요. 무엇이 잘못됐나요?","options":[{"t":"몫의 일의 자리에 0을 쓰지 않았어요","correct":true,"mis_target":"M4-1-u3-X11"},{"t":"나머지가 나누는 수보다 커요","mis":"M4-1-u3-X07"},{"t":"몫을 1 크게 해야 해요","mis":"M4-1-u3-X08"}],"explanation":["11 × 90 = 990 — 몫의 십의 자리 9.","남은 6이 11보다 작아 일의 자리 몫은 0.","바르게: 996 ÷ 11 = 90 … 6이에요."],"asset":{"type":"ldiv","a":996,"b":11},"variant_rule":{"alt":[{"stem":"시아가 493 ÷ 48 = 1 … 13이라고 계산했어요. 무엇이 잘못됐나요?","options":[{"t":"몫의 일의 자리에 0을 쓰지 않았어요","correct":true,"mis_target":"M4-1-u3-X11"},{"t":"나머지가 나누는 수보다 커요","mis":"M4-1-u3-X07"},{"t":"몫을 1 크게 해야 해요","mis":"M4-1-u3-X08"}],"explanation":["48 × 10 = 480 — 몫의 십의 자리 1.","남은 13이 48보다 작아 일의 자리 몫은 0.","바르게: 493 ÷ 48 = 10 … 13이에요."],"asset":{"type":"ldiv","a":493,"b":48}},{"stem":"하린이 682 ÷ 17 = 4 … 2라고 계산했어요. 무엇이 잘못됐나요?","options":[{"t":"몫의 일의 자리에 0을 쓰지 않았어요","correct":true,"mis_target":"M4-1-u3-X11"},{"t":"나머지가 나누는 수보다 커요","mis":"M4-1-u3-X07"},{"t":"몫을 1 크게 해야 해요","mis":"M4-1-u3-X08"}],"explanation":["17 × 40 = 680 — 몫의 십의 자리 4.","남은 2가 17보다 작아 일의 자리 몫은 0.","바르게: 682 ÷ 17 = 40 … 2예요."],"asset":{"type":"ldiv","a":682,"b":17}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_d#21','math',4,1,'u3','','g4_1_math_u3_review_d','unit_review','M4-1-u3-C10',3,'mc','auto','사과 106개를 한 상자에 12개씩 남김없이 모두 담으려고 해요. 상자는 적어도 몇 개 필요한가요?',ARRAY['M4-1-u3-X13','M4-1-u3-X14','M4-1-u3-X15']::text[],true,'{"seq":21,"concept":"M4-1-u3-C10","difficulty":3,"kind":"mc","stem":"사과 106개를 한 상자에 12개씩 남김없이 모두 담으려고 해요. 상자는 적어도 몇 개 필요한가요?","options":[{"t":"9개","correct":true},{"t":"8개","mis":"M4-1-u3-X13"},{"t":"10개","mis":"M4-1-u3-X14"},{"t":"18개","mis":"M4-1-u3-X15"}],"explanation":["106 ÷ 12 = 8 … 10.","남은 10도 담아야 하니 하나 더 — 8 + 1 = 9.","답은 9개예요."],"variant_rule":{"alt":[{"stem":"돈 537원으로 89원짜리 지우개를 사려고 해요. 지우개를 몇 개까지 살 수 있나요?","options":[{"t":"6개","correct":true},{"t":"7개","mis":"M4-1-u3-X13"},{"t":"3개","mis":"M4-1-u3-X14"},{"t":"9개","mis":"M4-1-u3-X15"}],"explanation":["537 ÷ 89 = 6 … 3.","남은 3은 하나를 다 채우지 못해요.","답은 6개예요."],"asset":null},{"stem":"책 489쪽을 하루에 76쪽씩 읽으려고 해요. 책을 다 읽으려면 적어도 며칠이 걸리나요?","options":[{"t":"7일","correct":true},{"t":"6일","mis":"M4-1-u3-X13"},{"t":"33일","mis":"M4-1-u3-X14"},{"t":"39일","mis":"M4-1-u3-X15"}],"explanation":["489 ÷ 76 = 6 … 33.","남은 33도 읽어야 하니 하나 더 — 6 + 1 = 7.","답은 7일이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_d#22','math',4,1,'u3','','g4_1_math_u3_review_d','unit_review','M4-1-u3-C6',3,'sa','auto','어떤 수를 23으로 나누었더니 몫이 5, 나머지가 15가 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":22,"concept":"M4-1-u3-C6","difficulty":3,"kind":"sa","stem":"어떤 수를 23으로 나누었더니 몫이 5, 나머지가 15가 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["130"],"explanation":["나누어지는 수 = (나누는 수) × (몫) + (나머지).","23 × 5 = 115.","115 + 15 = 130 — 어떤 수는 130이에요."],"asset":{"type":"expr_grid","rows":[["23 × 5","=","115"],["115 + 15","=",null]]},"variant_rule":{"alt":[{"stem":"어떤 수를 30으로 나누었더니 몫이 5, 나머지가 13이 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["163"],"explanation":["나누어지는 수 = (나누는 수) × (몫) + (나머지).","30 × 5 = 150.","150 + 13 = 163 — 어떤 수는 163이에요."],"asset":{"type":"expr_grid","rows":[["30 × 5","=","150"],["150 + 13","=",null]]}},{"stem":"어떤 수를 34로 나누었더니 몫이 9, 나머지가 2가 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["308"],"explanation":["나누어지는 수 = (나누는 수) × (몫) + (나머지).","34 × 9 = 306.","306 + 2 = 308 — 어떤 수는 308이에요."],"asset":{"type":"expr_grid","rows":[["34 × 9","=","306"],["306 + 2","=",null]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_d#23','math',4,1,'u3','','g4_1_math_u3_review_d','unit_review','M4-1-u3-C3',4,'mc','auto','수 카드 9, 1, 3, 5, 6을 한 번씩 모두 써서 (세 자리 수) × (두 자리 수)를 만들려고 해요. 가장 큰 곱은 얼마인가요?',ARRAY['M4-1-u3-X14','M4-1-u3-X16']::text[],true,'{"seq":23,"concept":"M4-1-u3-C3","difficulty":4,"kind":"mc","stem":"수 카드 9, 1, 3, 5, 6을 한 번씩 모두 써서 (세 자리 수) × (두 자리 수)를 만들려고 해요. 가장 큰 곱은 얼마인가요?","options":[{"t":"60543","correct":true},{"t":"29915","mis":"M4-1-u3-X14"},{"t":"59913","mis":"M4-1-u3-X14"},{"t":"6054","mis":"M4-1-u3-X16"}],"explanation":["가장 큰 두 숫자를 두 수의 맨 앞(백의 자리·십의 자리)에 나누어 놓아요.","여러 가지로 놓아 곱을 견주면 651 × 93이 가장 커요.","651 × 93 = 60543이에요."],"variant_rule":{"alt":[{"stem":"수 카드 8, 2, 5, 3, 1을 한 번씩 모두 써서 (세 자리 수) × (두 자리 수)를 만들려고 해요. 가장 큰 곱은 얼마인가요?","options":[{"t":"43542","correct":true},{"t":"17913","mis":"M4-1-u3-X14"},{"t":"43212","mis":"M4-1-u3-X14"},{"t":"4354","mis":"M4-1-u3-X16"}],"explanation":["가장 큰 두 숫자를 두 수의 맨 앞(백의 자리·십의 자리)에 나누어 놓아요.","여러 가지로 놓아 곱을 견주면 531 × 82가 가장 커요.","531 × 82 = 43542예요."],"asset":null},{"stem":"수 카드 1, 4, 3, 8, 9를 한 번씩 모두 써서 (세 자리 수) × (두 자리 수)를 만들려고 해요. 가장 큰 곱은 얼마인가요?","options":[{"t":"78213","correct":true},{"t":"30504","mis":"M4-1-u3-X14"},{"t":"78103","mis":"M4-1-u3-X14"},{"t":"7821","mis":"M4-1-u3-X16"}],"explanation":["가장 큰 두 숫자를 두 수의 맨 앞(백의 자리·십의 자리)에 나누어 놓아요.","여러 가지로 놓아 곱을 견주면 841 × 93이 가장 커요.","841 × 93 = 78213이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_d#24','math',4,1,'u3','','g4_1_math_u3_review_d','unit_review','M4-1-u3-C10',4,'mc','auto','오늘 반찬은 한 사람에 681 g, 내일 반찬은 한 사람에 424 g이에요. 24명이 먹을 때 내일은 오늘보다 탄소 발자국이 몇 g 줄어드나요?',ARRAY['M4-1-u3-X18','M4-1-u3-X15']::text[],true,'{"seq":24,"concept":"M4-1-u3-C10","difficulty":4,"kind":"mc","stem":"오늘 반찬은 한 사람에 681 g, 내일 반찬은 한 사람에 424 g이에요. 24명이 먹을 때 내일은 오늘보다 탄소 발자국이 몇 g 줄어드나요?","options":[{"t":"6168 g","correct":true},{"t":"257 g","mis":"M4-1-u3-X18"},{"t":"26520 g","mis":"M4-1-u3-X15"},{"t":"10176 g","mis":"M4-1-u3-X18"}],"explanation":["오늘 681 × 24 = 16344 g.","내일 424 × 24 = 10176 g.","16344 − 10176 = 6168 g 줄어요."],"variant_rule":{"alt":[{"stem":"오늘 반찬은 한 사람에 635 g, 내일 반찬은 한 사람에 374 g이에요. 22명이 먹을 때 내일은 오늘보다 탄소 발자국이 몇 g 줄어드나요?","options":[{"t":"5742 g","correct":true},{"t":"261 g","mis":"M4-1-u3-X18"},{"t":"22198 g","mis":"M4-1-u3-X15"},{"t":"8228 g","mis":"M4-1-u3-X18"}],"explanation":["오늘 635 × 22 = 13970 g.","내일 374 × 22 = 8228 g.","13970 − 8228 = 5742 g 줄어요."],"asset":null},{"stem":"오늘 반찬은 한 사람에 570 g, 내일 반찬은 한 사람에 314 g이에요. 29명이 먹을 때 내일은 오늘보다 탄소 발자국이 몇 g 줄어드나요?","options":[{"t":"7424 g","correct":true},{"t":"256 g","mis":"M4-1-u3-X18"},{"t":"25636 g","mis":"M4-1-u3-X15"},{"t":"9106 g","mis":"M4-1-u3-X18"}],"explanation":["오늘 570 × 29 = 16530 g.","내일 314 × 29 = 9106 g.","16530 − 9106 = 7424 g 줄어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u3_review_d#25','math',4,1,'u3','','g4_1_math_u3_review_d','unit_review','M4-1-u3-C4',4,'essay','teacher','586 × 47을 몇백과 몇십으로 어림하여 약 얼마인지 쓰고, 실제 곱을 구해 어림값과 견주어 보세요.','{}'::text[],false,'{"seq":25,"concept":"M4-1-u3-C4","difficulty":4,"kind":"essay","stem":"586 × 47을 몇백과 몇십으로 어림하여 약 얼마인지 쓰고, 실제 곱을 구해 어림값과 견주어 보세요.","answer_guide":{"answer":"예: 586은 약 600, 47은 약 50이므로 600 × 50 = 30000쯤이다. 실제로 계산하면 586 × 47 = 27542이고, 어림값 30000과 가까우므로 계산이 알맞다고 볼 수 있다.","scoring_points":["600 × 50 = 30000으로 어림했는가","586 × 47 = 27542를 구했는가","어림값과 견주어 알맞은지 말했는가"]},"explanation":["586 → 600, 47 → 50.","600 × 50 = 30000, 586 × 47 = 27542.","어림값과 가까워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
